INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('1.  だ  /  です  (Da / Desu) Là', 'N5', 'Dùng ở cuối câu khẳng định.  です  lịch sự,  だ  thông thường.', 'Danh từ / Tính từ đuôi  な +  だ (Thể thông thường)   Danh từ / Tính từ đuôi  な / Tính từ đuôi  い +  です (Thể lịch sự)', '[{"ja":"私は学生です。","romaji":"(Watashi wa gakusei desu.)","vi":"→ Tôi là học sinh."},{"ja":"これは本だ。","romaji":"(Kore wa hon da.)","vi":"→ Đây là quyển sách."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('2.  だけ  (Dake) Chỉ; chỉ có', 'N5', 'Diễn tả sự giới hạn.', 'Danh từ / Động từ +  だけ', '[{"ja":"５分だけ待ってください。","romaji":"(Go-fun dake matte kudasai.)","vi":"→ Xin hãy đợi chỉ 5 phút."},{"ja":"これだけあります。","romaji":"(Kore dake arimasu.)","vi":"→ Chỉ có cái này thôi."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('3.  で  (De) Ở; tại (nơi xảy ra hành động); bằng (phương tiện); với (công cụ)', 'N5', 'Đang cập nhật nội dung...', 'Danh từ +  で', '[]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('4.  が  (Ga) Trợ từ chủ ngữ', 'N5', 'Nhấn mạnh chủ ngữ, giới thiệu thông tin mới, đi với các từ chỉ khả năng/sở thích (好き,  います,  あります...).', 'Danh từ +  が + Động từ / Tính từ', '[{"ja":"雨が降っています。","romaji":"(Ame ga futte imasu.)","vi":"→ Trời đang mưa."},{"ja":"猫が好きです。","romaji":"(Neko ga suki desu.)","vi":"→ Tôi thích mèo."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('5.  があります  /  がいます  (Ga arimasu / Ga imasu) Có (sự tồn tại)', 'N5', 'あります  cho đồ vật,  います  cho người và động vật.', 'Danh từ +  が +  あります /  います', '[{"ja":"机の上に本があります。","romaji":"(Tsukue no ue ni hon ga arimasu.)","vi":"→ Trên bàn có sách."},{"ja":"公園に子供がいます。","romaji":"(Kouen ni kodomo ga imasu.)","vi":"→ Ở công viên có trẻ em."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('6.  がほしい  (Ga hoshii) Muốn (cái gì đó)', 'N5', 'Diễn tả mong muốn sở hữu một vật gì đó (ngôi thứ nhất).', 'Danh từ +  が +  ほしいです', '[{"ja":"新しい車がほしいです。","romaji":"(Atarashii kuruma ga hoshii desu.)","vi":"→ Tôi muốn có một chiếc ô tô mới."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('7.  ほうがいい  (Hou ga ii) Nên ~; tốt hơn là nên ~', 'N5', 'Đưa ra lời khuyên.', 'V-た / V-ない +  ほうがいい', '[{"ja":"薬を飲んだほうがいいですよ。","romaji":"(Kusuri o nonda hou ga ii desu yo.)","vi":"→ Bạn nên uống thuốc đi."},{"ja":"タバコは吸わないほうがいいです。","romaji":"(Tabako wa suwanai hou ga ii desu.)","vi":"→ Không nên hút thuốc lá."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('8.  一番  (Ichiban) Nhất', 'N5', 'Diễn tả sự so sánh cao nhất.', '[Phạm vi] +  で + [Danh từ] +  が +  一番 + [Tính từ] +  です。', '[{"ja":"スポーツでサッカーが一番面白いです。","romaji":"(Supootsu de sakkaa ga ichiban omoshiroi desu.)","vi":"→ Trong các môn thể thao, bóng đá là thú vị nhất."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('9.  か  (Ka) Trợ từ nghi vấn (dấu chấm hỏi)', 'N5', 'Thêm vào cuối câu để tạo câu hỏi.', 'Câu +  か', '[{"ja":"これはあなたの傘ですか。","romaji":"(Kore wa anata no kasa desu ka?)","vi":"→ Đây là ô của bạn phải không?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('10.  から  (Kara) Từ; Bởi vì', 'N5', 'Chỉ điểm bắt đầu hoặc nguyên nhân.', 'N +  から (Từ); Câu 1 +  から + Câu 2 (Bởi vì)', '[{"ja":"９時から働きます。","romaji":"(Ku-ji kara hatarakimasu.)","vi":"→ Tôi làm việc từ 9 giờ."},{"ja":"時間がないから、急ぎます。","romaji":"(Jikan ga nai kara, isogimasu.)","vi":"→ Vì không có thời gian nên tôi sẽ khẩn trương."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('11.  方  (Kata) Cách làm ~', 'N5', 'Biến động từ thành danh từ chỉ "cách thức thực hiện hành động".', 'V-ます (bỏ  ます) +  方 (かた)', '[{"ja":"この漢字の読み方が分かりません。","romaji":"(Kono kanji no yomikata ga wakarimasen.)","vi":"→ Tôi không biết cách đọc chữ Hán này."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('12.  まで  (Made) Cho đến khi; đến', 'N5', 'Chỉ điểm kết thúc về thời gian hoặc không gian.', 'N +  まで', '[{"ja":"５時まで働きます。","romaji":"(Go-ji made hatarakimasu.)","vi":"→ Tôi làm việc đến 5 giờ."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('13.  前に  (Mae ni) Trước khi; ở phía trước', 'N5', 'Diễn tả hành động xảy ra trước một hành động khác hoặc một thời điểm.', 'V-る / N +  の +  前に', '[{"ja":"寝る前に、本を読みます。","romaji":"(Neru mae ni, hon o yomimasu.)","vi":"→ Trước khi ngủ, tôi đọc sách."},{"ja":"食事の前に、手を洗います。","romaji":"(Shokuji no mae ni, te o araimasu.)","vi":"→ Trước bữa ăn, tôi rửa tay."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('14.  ませんか  (Masen ka) Bạn có muốn ~ không? (Lời mời/rủ rê)', 'N5', 'Mời ai đó cùng làm gì một cách lịch sự.', 'V-ます (bỏ  ます) +  ませんか', '[{"ja":"一緒に映画を見ませんか。","romaji":"(Issho ni eiga o mimasen ka?)","vi":"→ Cùng đi xem phim không?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('15.  ましょう  (Mashou) Chúng ta hãy ~', 'N5', 'Đề nghị, rủ rê cùng làm gì (mang tính chủ động hơn  ませんか).', 'V-ます (bỏ  ます) +  ましょう', '[{"ja":"昼ご飯を食べましょう。","romaji":"(Hirugohan o tabemashou.)","vi":"→ Chúng ta hãy ăn trưa nào."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('16.  も  (Mo) Cũng; nữa', 'N5', 'Diễn tả sự tương đồng, lặp lại.', 'Thay thế  は,  が,  を bằng  も. Với các trợ từ khác thì thêm  も sau trợ từ (にも,  でも,  へも...).', '[{"ja":"私も学生です。","romaji":"(Watashi mo gakusei desu.)","vi":"→ Tôi cũng là học sinh."},{"ja":"コーヒーも飲みます。","romaji":"(Koohii mo nomimasu.)","vi":"→ Tôi cũng uống cà phê."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('17.  もう  (Mou) Đã; không còn nữa', 'N5', 'Diễn tả hành động đã hoàn thành hoặc không còn tiếp diễn.', 'もう + V-ました (Đã);  もう + V-ません / V-ない (Không còn nữa).', '[{"ja":"もう昼ご飯を食べましたか。","romaji":"(Mou hirugohan o tabemashita ka?)","vi":"→ Bạn đã ăn trưa chưa?"},{"ja":"もうタバコは吸いません。","romaji":"(Mou tabako wa suimasen.)","vi":"→ Tôi không còn hút thuốc lá nữa."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('18.  ないでください  (Naide kudasai) Xin đừng làm ~', 'N5', 'Yêu cầu ai đó đừng làm một việc gì đó.', 'V-ない +  でください', '[{"ja":"ここで写真を撮らないでください。","romaji":"(Koko de shashin o toranaide kudasai.)","vi":"→ Xin đừng chụp ảnh ở đây."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('19.  なる  (Naru) Trở thành', 'N5', 'Diễn tả sự thay đổi, biến đổi trạng thái.', 'N +  に +  なる   A-na +  に +  なる   A-i (bỏ  い) +  く +  なる', '[{"ja":"医者になりたいです。","romaji":"(Isha ni naritai desu.)","vi":"→ Tôi muốn trở thành bác sĩ."},{"ja":"部屋がきれいになりました。","romaji":"(Heya ga kirei ni narimashita.)","vi":"→ Căn phòng đã trở nên sạch sẽ."},{"ja":"寒くなりました。","romaji":"(Samuku narimashita.)","vi":"→ Trời đã trở lạnh."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('20.  に  (Ni) Trợ từ chỉ điểm đến; ở; tại; vào (thời gian); cho (đối tượng)', 'N5', 'Đang cập nhật nội dung...', 'N +  に', '[]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('21.  に行く  (Ni iku) Đi để làm ~', 'N5', 'Diễn tả mục đích của việc di chuyển.', 'V-ます (bỏ  ます) / Danh động từ +  に +  行く /  来る /  帰る', '[{"ja":"日本へ働きに来ました。","romaji":"(Nihon e hataraki ni kimashita.)","vi":"→ Tôi đến Nhật để làm việc."},{"ja":"買い物に行きます。","romaji":"(Kaimono ni ikimasu.)","vi":"→ Tôi đi mua sắm."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('22.  の  (No) Trợ từ sở hữu (của); bổ nghĩa', 'N5', 'Nối hai danh từ, chỉ sự sở hữu, thuộc tính, vị trí...', 'N1 +  の + N2', '[{"ja":"これは私の本です。","romaji":"(Kore wa watashi no hon desu.)","vi":"→ Đây là sách của tôi."},{"ja":"日本語の先生。","romaji":"(Nihongo no sensei.)","vi":"→ Giáo viên tiếng Nhật."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('23.  ので  (Node) Bởi vì; do đó; vì ~', 'N5', 'Chỉ nguyên nhân, lý do (mang tính khách quan và nhẹ nhàng hơn  から).', 'V-thường / A-i / A-na / N +  な +  ので + Câu 2', '[{"ja":"雨が降っているので、行きません。","romaji":"(Ame ga futte iru node, ikimasen.)","vi":"→ Vì trời đang mưa nên tôi không đi."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('24.  を  (O) Trợ từ chỉ đối tượng (tân ngữ)', 'N5', 'Đánh dấu đối tượng trực tiếp của hành động.', 'N +  を + Tha động từ', '[{"ja":"ご飯を食べます。","romaji":"(Gohan o tabemasu.)","vi":"→ Tôi ăn cơm."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('25.  たことがある  (Ta koto ga aru) Đã từng làm gì đó', 'N5', 'Diễn tả kinh nghiệm, trải nghiệm trong quá khứ.', 'V-た +  ことがある', '[{"ja":"富士山に登ったことがあります。","romaji":"(Fuji-san ni nobotta koto ga arimasu.)","vi":"→ Tôi đã từng leo núi Phú Sĩ."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('26.  たい  (Tai) Muốn làm gì đó', 'N5', 'Diễn tả mong muốn làm gì đó (ngôi thứ nhất).', 'V-ます (bỏ  ます) +  たいです', '[{"ja":"日本へ行きたいです。","romaji":"(Nihon e ikitai desu.)","vi":"→ Tôi muốn đi Nhật."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('27.  たり～たり  (Tari ~ tari) Làm những việc như A và B', 'N5', 'Liệt kê một vài hành động tiêu biểu, không theo thứ tự.', 'V1-た +  り + V2-た +  り +  する', '[{"ja":"日曜日は本を読んだり、映画を見たりします。","romaji":"(Nichiyoubi wa hon o yondari, eiga o mitari shimasu.)","vi":"→ Vào Chủ nhật, tôi làm những việc như đọc sách, xem phim..."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('28.  ている  (Te iru) Hành động đang diễn ra hoặc trạng thái', 'N5', 'Diễn tả hành động đang diễn ra:  雨が降っています。 (Ame ga futte imasu.)  → Trời đang mưa.   Diễn tả trạng thái kết quả:  結婚しています。 (Kekkon shite imasu.)  → Tôi đã kết hôn (và đang trong trạng thái đó).   Diễn tả thói quen, nghề nghiệp:  銀行で働いています。 (Ginkou de hataraite imasu.)  → Tôi đang làm việc ở ngân hàng.', 'V-て +  いる', '[{"ja":"今、音楽を聞いています。","romaji":"(Ima, ongaku o kiite imasu.)","vi":"→ Bây giờ tôi đang nghe nhạc."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('29.  てください  (Te kudasai) Vui lòng làm ~', 'N5', 'Đưa ra yêu cầu, nhờ vả một cách lịch sự.', 'V-て +  ください', '[{"ja":"ちょっと待ってください。","romaji":"(Chotto matte kudasai.)","vi":"→ Xin vui lòng đợi một chút."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('30.  てもいいです  (Te mo ii desu) ~ cũng được; ~ cũng không sao; tôi có thể ~ không?', 'N5', 'Diễn tả sự cho phép.', 'V-て +  もいいです', '[{"ja":"写真を撮ってもいいですか。","romaji":"(Shashin o totte mo ii desu ka?)","vi":"→ Tôi chụp ảnh có được không?"},{"ja":"はい、撮ってもいいですよ。","romaji":"(Hai, totte mo ii desu yo.)","vi":"→ Vâng, bạn chụp cũng được."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('31.  と  (To) Và; với', 'N5', 'Đang cập nhật nội dung...', 'N1 +  と + N2', '[]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('32.  や  (Ya) Và; hoặc', 'N5', 'Liệt kê không đầy đủ, chỉ nêu vài ví dụ tiêu biểu. Thường đi kèm với  など  (nado  → vân vân).', 'N1 +  や + N2 + (など)', '[{"ja":"かばんの中に本やノートなどがあります。","romaji":"(Kaban no naka ni hon ya nooto nado ga arimasu.)","vi":"→ Trong cặp có sách, vở, vân vân."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('33.  じゃない  /  ではない  (Janai / Dewa nai) Không phải là', 'N5', 'Dạng phủ định của  だ  / です.  ではない  / ではありません  trang trọng hơn  じゃない  / じゃありません.', 'Danh từ / Tính từ đuôi  な +  じゃない /  ではない (hoặc  じゃありません /  ではありません)', '[{"ja":"彼は学生ではありません。","romaji":"(Kare wa gakusei dewa arimasen.)","vi":"→ Anh ấy không phải là học sinh."},{"ja":"ここは静かじゃないです。","romaji":"(Koko wa shizuka ja nai desu.)","vi":"→ Nơi đây không yên tĩnh."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('34.  か～か  (Ka ~ ka) Hoặc', 'N5', 'Dùng để đưa ra lựa chọn giữa hai hoặc nhiều danh từ, hoặc trong câu hỏi lựa chọn.', 'N1 +  か + N2 +  か', '[{"ja":"コーヒーかお茶、どちらがいいですか。","romaji":"(Koohii ka ocha, dochira ga ii desu ka?)","vi":"→ Cà phê hay trà, bạn thích cái nào hơn?"},{"ja":"行くか行かないか、決めてください。","romaji":"(Iku ka ikanai ka, kimete kudasai.)","vi":"→ Hãy quyết định đi hay không đi."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('35.  けど  /  けれども  (Kedo / Keredomo) Nhưng; tuy nhiên', 'N5', 'Nối hai mệnh đề có ý nghĩa tương phản hoặc đối lập.  けれども  trang trọng hơn  けど.', 'Câu 1 +  けど /  けれども + Câu 2', '[{"ja":"このレストランは高いけど、おいしいです。","romaji":"(Kono resutoran wa takai kedo, oishii desu.)","vi":"→ Nhà hàng này đắt nhưng ngon."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('36.  まだ  (Mada) Vẫn; chưa', 'N5', 'Diễn tả hành động vẫn còn đang tiếp diễn hoặc chưa xảy ra.', 'まだ + V-ています (Vẫn);  まだ + V-ていません (Chưa).', '[{"ja":"雨はまだ降っています。","romaji":"(Ame wa mada futte imasu.)","vi":"→ Trời vẫn đang mưa."},{"ja":"彼はまだ来ていません。","romaji":"(Kare wa mada kite imasen.)","vi":"→ Anh ấy vẫn chưa đến."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('37.  ましょうか  (Mashou ka) Tôi sẽ ~ nhé?; Dùng để đề nghị giúp đỡ', 'N5', 'Đề nghị làm gì đó cho người nghe một cách lịch sự.', 'V-ます (bỏ  ます) +  ましょうか', '[{"ja":"荷物を持ちましょうか。","romaji":"(Nimotsu o mochimashou ka?)","vi":"→ Tôi mang hành lý giúp bạn nhé?"},{"ja":"窓を開けましょうか。","romaji":"(Mado o akemashou ka?)","vi":"→ Tôi mở cửa sổ nhé?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('38.  ないでください  (Naide kudasai) Xin đừng làm ~', 'N5', 'Yêu cầu ai đó đừng làm gì một cách lịch sự.', 'V-ない +  でください', '[{"ja":"心配しないでください。","romaji":"(Shinpai shinaide kudasai.)","vi":"→ Xin đừng lo lắng."},{"ja":"走らないでください。","romaji":"(Hashiranaide kudasai.)","vi":"→ Xin đừng chạy."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('39.  ないといけない  /  なくてはいけない  (Nai to ikenai / Nakute wa ikenai) Phải làm ~', 'N5', 'Diễn tả sự bắt buộc, nghĩa vụ phải làm gì đó.', 'V-ない (bỏ  い) +  ければいけない /  くてはいけない', '[{"ja":"薬を飲まないといけません。","romaji":"(Kusuri o nomanai to ikemasen.)","vi":"→ Phải uống thuốc."},{"ja":"早く起きなくてはいけません。","romaji":"(Hayaku okinakute wa ikemasen.)","vi":"→ Phải dậy sớm."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('40.  なくてもいい  (Nakute mo ii) Không cần phải ~', 'N5', 'Diễn tả sự không cần thiết phải làm gì đó.', 'V-ない (bỏ  い) +  くてもいいです', '[{"ja":"来なくてもいいです。","romaji":"(Konakute mo ii desu.)","vi":"→ Bạn không cần đến cũng được."},{"ja":"名前を書かなくてもいいです。","romaji":"(Namae o kakanakute mo ii desu.)","vi":"→ Không cần viết tên cũng được."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('41.  んです  /  のです  (N desu / No desu) Dùng để giải thích, nhấn mạnh, hoặc hỏi lý do', 'N5', 'Làm cho câu nói có sắc thái mềm mại hơn, như đang giải thích hoặc muốn biết thêm thông tin.', 'V-thường / A-i / A-na / N +  な +  んです /  のです', '[{"ja":"どうしたんですか。","romaji":"(Doushitan desu ka?)","vi":"→ Bạn bị sao vậy? (Hỏi lý do)"},{"ja":"頭が痛いんです。","romaji":"(Atama ga itain desu.)","vi":"→ (Là vì) tôi bị đau đầu. (Giải thích)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('42.  ね  (Ne) Phải không? nhỉ? nhé?', 'N5', 'Đặt cuối câu để tìm sự đồng tình, xác nhận, hoặc làm mềm câu.', 'Câu +  ね', '[{"ja":"いい天気ですね。","romaji":"(Ii tenki desu ne.)","vi":"→ Thời tiết đẹp nhỉ?"},{"ja":"そうですね。","romaji":"(Sou desu ne.)","vi":"→ Đúng vậy nhỉ."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('43.  にする  (Ni suru) Quyết định ~', 'N5', 'Diễn tả quyết định lựa chọn một cái gì đó.', 'Danh từ +  にする', '[{"ja":"飲み物は何にしますか。","romaji":"(Nomimono wa nani ni shimasu ka?)","vi":"→ Đồ uống bạn chọn gì?"},{"ja":"コーヒーにします。","romaji":"(Koohii ni shimasu.)","vi":"→ Tôi chọn cà phê."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('44.  のが下手  /  上手  /  好き  (No ga heta / Jouzu / Suki) Kém / Giỏi / Thích làm gì đó', 'N5', 'Dùng  の  để danh từ hóa động từ, sau đó kết hợp với các tính từ chỉ khả năng, sở thích.', 'V-る +  の +  が +  下手 /  上手 /  好き +  です', '[{"ja":"私は歌うのが好きです。","romaji":"(Watashi wa utau no ga suki desu.)","vi":"→ Tôi thích hát."},{"ja":"彼は料理を作るのが上手です。","romaji":"(Kare wa ryouri o tsukuru no ga jouzu desu.)","vi":"→ Anh ấy giỏi nấu ăn."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('45.  をください  (O kudasai) Vui lòng cho tôi ~', 'N5', 'Dùng khi gọi món, mua hàng hoặc yêu cầu ai đó đưa cho mình thứ gì.', 'Danh từ +  を +  ください', '[{"ja":"水をください。","romaji":"(Mizu o kudasai.)","vi":"→ Vui lòng cho tôi nước."},{"ja":"これをください。","romaji":"(Kore o kudasai.)","vi":"→ Vui lòng cho tôi cái này."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('46.  すぎる  (Sugiru) Quá nhiều; quá ~', 'N5', 'Diễn tả sự vượt quá mức độ bình thường, thường mang ý nghĩa tiêu cực.', 'V-ます (bỏ  ます) / A-i (bỏ  い) / A-na +  すぎる', '[{"ja":"食べすぎました。","romaji":"(Tabesugimashita.)","vi":"→ Tôi đã ăn quá nhiều."},{"ja":"この服は大きすぎます。","romaji":"(Kono fuku wa ookisugimasu.)","vi":"→ Cái áo này quá lớn."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('47.  てから  (Te kara) Sau khi làm ~', 'N5', 'Diễn tả hành động V2 xảy ra sau khi V1 kết thúc.', 'V1-て +  から、V2', '[{"ja":"宿題をしてから、遊びます。","romaji":"(Shukudai o shite kara, asobimasu.)","vi":"→ Sau khi làm bài tập, tôi sẽ đi chơi."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('48.  てはいけない  (Te wa ikenai) Không được; không thể; không được phép', 'N5', 'Diễn tả sự cấm đoán. Trong văn nói thường dùng  ちゃいけない  /  じゃいけない.', 'V-て +  は +  いけない', '[{"ja":"ここで泳いではいけません。","romaji":"(Koko de oyoide wa ikemasen.)","vi":"→ Không được bơi ở đây."},{"ja":"寝ちゃいけない！(Necha ikenai!)","romaji":"→ Không được ngủ! (Văn nói)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('49.  とき  (Toki) Khi; vào lúc này', 'N5', 'Chỉ thời điểm xảy ra hành động/trạng thái.', 'V-thường / A-i / A-na / N +  の +  とき', '[{"ja":"子供のとき、よく公園で遊びました。","romaji":"(Kodomo no toki, yoku kouen de asobimashita.)","vi":"→ Khi còn nhỏ, tôi thường chơi ở công viên."},{"ja":"困ったとき、相談してください。","romaji":"(Komatta toki, soudan shite kudasai.)","vi":"→ Khi gặp khó khăn, hãy trao đổi nhé."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('50.  とても  (Totemo) Rất; vô cùng', 'N5', 'Nhấn mạnh mức độ.', 'とても + Tính từ / Phó từ', '[{"ja":"このケーキはとてもおいしいです。","romaji":"(Kono keeki wa totemo oishii desu.)","vi":"→ Cái bánh này rất ngon."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('51.  つもり  (Tsumori) Dự định ~; có ý định ~', 'N5', 'Thể hiện ý định, kế hoạch của người nói.', 'V-る / V-ない +  つもりです', '[{"ja":"大学に入るつもりです。","romaji":"(Daigaku ni hairu tsumori desu.)","vi":"→ Tôi dự định vào đại học."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('52.  は  (Wa) Trợ từ chủ đề', 'N5', 'Đánh dấu chủ đề chính của câu.', 'Danh từ +  は', '[{"ja":"私は医者です。","romaji":"(Watashi wa isha desu.)","vi":"→ Tôi là bác sĩ."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('53.  よ  (Yo) Nhấn mạnh; thông báo', 'N5', 'Đặt cuối câu để nhấn mạnh thông tin, hoặc nói cho người nghe biết điều họ chưa biết.', 'Câu +  よ', '[{"ja":"危ないですよ！(Abunai desu yo!)","romaji":"→ Nguy hiểm đấy!","vi":""},{"ja":"この映画は面白いですよ。","romaji":"(Kono eiga wa omoshiroi desu yo.)","vi":"→ Bộ phim này hay đấy (bạn chưa biết nên tôi nói cho)."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('54.  でしょう  (Deshou) Có lẽ; phải không?', 'N5', 'Dùng để diễn tả sự phỏng đoán, suy luận của người nói, hoặc dùng để hỏi xác nhận một cách lịch sự, mềm mại hơn  ～ですか.', 'V-thường / A-i / A-na / N +  でしょう', '[{"ja":"明日は雨が降るでしょう。","romaji":"(Ashita wa ame ga furu deshou.)","vi":"→ Có lẽ ngày mai trời sẽ mưa."},{"ja":"これは山田さんの傘でしょう？","romaji":"→ (Kore wa Yamada-san no kasa deshou?)","vi":"→ Đây là ô của anh Yamada phải không ạ?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('55.  どんな  (Donna) Loại ~ nào; kiểu ~ nào', 'N5', 'Là một từ để hỏi, dùng khi muốn hỏi về tính chất, đặc điểm, hoặc thể loại của một danh từ.', 'どんな + Danh từ + ...', '[{"ja":"どんなスポーツが好きですか。","romaji":"(Donna supootsu ga suki desu ka?)","vi":"→ Bạn thích loại thể thao nào?"},{"ja":"田中さんはどんな人ですか。","romaji":"(Tanaka-san wa donna hito desu ka?)","vi":"→ Anh Tanaka là người như thế nào?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('56.  どうして  (Doushite) Tại sao; vì lý do gì', 'N5', 'Là từ để hỏi về nguyên nhân, lý do. Thường dùng trong văn nói. Tương đương với  なぜ  (naze) nhưng  なぜ  trang trọng hơn.', 'どうして + Câu hỏi?', '[{"ja":"どうして日本語を勉強していますか。","romaji":"(Doushite Nihongo o benkyou shite imasu ka?)","vi":"→ Tại sao bạn học tiếng Nhật?"},{"ja":"どうして遅れましたか。","romaji":"(Doushite okuremashita ka?)","vi":"→ Tại sao bạn đến muộn?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('57.  どうやって  (Douyatte) Làm thế nào; bằng cách nào', 'N5', 'Là từ để hỏi về phương pháp, cách thức thực hiện một hành động.', 'どうやって + Động từ +  か?', '[{"ja":"駅までどうやって行きますか。","romaji":"(Eki made douyatte ikimasu ka?)","vi":"→ Đi đến nhà ga bằng cách nào?"},{"ja":"この漢字はどうやって読みますか。","romaji":"(Kono kanji wa douyatte yomimasu ka?)","vi":"→ Chữ Hán này đọc như thế nào?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('58.  一緒に  (Issho ni) Cùng nhau', 'N5', 'Diễn tả hành động được thực hiện cùng với một ai đó.', '(Danh từ chỉ người) +  と +  一緒に + Động từ', '[{"ja":"週末、友達と一緒に買い物に行きます。","romaji":"(Shuumatsu, tomodachi to issho ni kaimono ni ikimasu.)","vi":"→ Cuối tuần, tôi đi mua sắm cùng với bạn."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('59.  いつも  (Itsumo) Luôn luôn; thường xuyên', 'N5', 'Là một phó từ chỉ tần suất, diễn tả một hành động hay thói quen lặp đi lặp lại.', 'いつも + Động từ', '[{"ja":"父はいつも朝早く起きます。","romaji":"(Chichi wa itsumo asa hayaku okimasu.)","vi":"→ Bố tôi luôn luôn dậy sớm vào buổi sáng."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('60.  なくちゃ  (Nakucha) Phải làm (văn nói)', 'N5', 'Là dạng nói tắt, thân mật của  なくてはいけない  (phải làm). Thường dùng trong hội thoại hàng ngày.', 'V-ない (bỏ  い) +  くちゃ', '[{"ja":"もう帰らなくちゃ。","romaji":"(Mou kaeranakucha.)","vi":"→ Phải về thôi."},{"ja":"宿題をしなくちゃ。","romaji":"(Shukudai o shinakucha.)","vi":"→ Phải làm bài tập thôi."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('61.  お  /  ご  (O / Go) Kính ngữ; tiền tố kính ngữ', 'N5', 'Thêm vào trước danh từ để thể hiện sự lịch sự, tôn kính.', 'お + Danh từ (gốc Nhật);  ご + Danh từ (gốc Hán)', '[{"ja":"お名前 (O-namae)","romaji":"→ Tên (lịch sự)","vi":""},{"ja":"お仕事 (O-shigoto)","romaji":"→ Công việc (lịch sự)","vi":""},{"ja":"ご連絡 (Go-renraku)","romaji":"→ Liên lạc (lịch sự)","vi":""},{"ja":"ご飯 (Go-han)","romaji":"→ Cơm","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('62.  しかし  (Shikashi) Nhưng; tuy nhiên', 'N5', 'Dùng để nối hai câu có ý nghĩa trái ngược. Mang tính trang trọng, thường dùng trong văn viết hơn là văn nói.', 'Câu 1.  しかし、Câu 2.', '[{"ja":"彼は努力しました。","romaji":"しかし、失敗しました。","vi":"(Kare wa doryoku shimashita. Shikashi, shippai shimashita.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('63.  それから  (Sorekara) Và; và sau đó; sau đó', 'N5', 'Dùng để nối các hành động theo trình tự thời gian hoặc để bổ sung thêm thông tin.', 'Câu 1.  それから、Câu 2.', '[{"ja":"朝ご飯を食べて、歯を磨きます。","romaji":"それから、会社へ行きます。","vi":"(Asagohan o tabete, ha o migakimasu. Sorekara, kaisha e ikimasu.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('64.  そして  (Soshite) Và; và sau đó', 'N5', 'Dùng để nối hai câu theo trình tự hoặc bổ sung thông tin, tương tự  それから  nhưng ít nhấn mạnh vào trình tự thời gian hơn, có thể dùng để nối các ý song song.', 'Câu 1.  そして、Câu 2.', '[{"ja":"彼は親切です。","romaji":"そして、頭もいいです。","vi":"(Kare wa shinsetsu desu. Soshite, atama mo ii desu.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('65.  はどうですか  (Wa dou desu ka) ~ thì thế nào; ~ ra sao?', 'N5', 'Dùng để hỏi ý kiến, cảm nhận hoặc đưa ra lời gợi ý, đề nghị.', 'Danh từ +  は +  どうですか', '[{"ja":"新しい先生はどうですか。","romaji":"(Atarashii sensei wa dou desu ka?)","vi":"→ Thầy giáo mới thế nào?"},{"ja":"お茶はどうですか。","romaji":"(Ocha wa dou desu ka?)","vi":"→ Bạn dùng trà nhé?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('66.  より～ほうが  (~ Yori ~ hou ga) [B] thì ~ hơn [A]', 'N5', 'Dùng để so sánh, nhấn mạnh vào N1 tốt hơn/kém hơn... so với N2.', 'N2 +  より + N1 +  の +  ほうが + Tính từ +  です', '[{"ja":"バスより電車のほうが速いです。","romaji":"(Basu yori densha no hou ga hayai desu.)","vi":"→ So với xe buýt thì tàu điện nhanh hơn."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('67.  でも  (Demo) Nhưng / Hoặc là; chẳng hạn như', 'N5', 'Đứng đầu câu để nối hai vế trái nghĩa (thường dùng trong văn nói).   Đứng sau danh từ để đưa ra ví dụ, gợi ý.', 'Câu 1.  でも、Câu 2. / Danh từ +  でも', '[{"ja":"行きたいです。","romaji":"でも、時間がありません。","vi":"(Ikitai desu. Demo, jikan ga arimasen.)"},{"ja":"お茶でも飲みませんか。","romaji":"(Ocha demo nomimasen ka?)","vi":"→ Uống trà hay gì đó không?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('68.  ちゃいけない  /  じゃいけない  (Chaikenai / Jaikenai) Không được làm (văn nói)', 'N5', 'Là dạng nói tắt, thân mật và suồng sã của  ～てはいけない. Được sử dụng rất phổ biến trong hội thoại hàng ngày, đặc biệt là giữa bạn bè, người thân.', 'V-て (bỏ  て) +  ちゃ', '[{"ja":"食べて →  食べちゃいけない)","romaji":"","vi":""},{"ja":"V-で (bỏ  で) +  じゃ","romaji":"──────────","vi":"Ví dụ:  飲んで →  飲んじゃいけない)"},{"ja":"V-して →  しちゃいけない","romaji":"──────────","vi":"Cách dùng: Là dạng nói tắt, thân mật và suồng sã của  ～てはいけない. Được sử dụng rất phổ biến trong hội thoại hàng ngày, đặc biệt là giữa bạn bè, người thân."},{"ja":"そんなに飲んじゃいけない。","romaji":"(Sonna ni nonja ikenai.)","vi":"→ Không được uống nhiều như thế."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('6.  だろう  (Darou) Có lẽ; chắc là; phải không? (Thể thông thường)', 'N5', 'Là thể thông thường của  でしょう. Dùng để diễn tả sự phỏng đoán hoặc tìm kiếm sự đồng tình một cách thân mật. Trong văn nói, thường được nam giới sử dụng nhiều hơn.', 'V-thường / A-i / A-na (bỏ  な) / N +  だろう', '[{"ja":"彼はもうすぐ来るだろう。","romaji":"(Kare wa mousugu kuru darou.)","vi":"→ Chắc là anh ấy sắp đến rồi."},{"ja":"これでいいだろう？","romaji":"→ (Kore de ii darou?)","vi":"→ Thế này là được rồi phải không?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('70.  まだ～ていません  (Mada ~te imasen) Vẫn chưa ~', 'N5', 'Nhấn mạnh rằng một hành động được mong đợi hoặc nên xảy ra nhưng tại thời điểm nói vẫn chưa xảy ra.', 'まだ + V-て +  いません (Thể lịch sự) /  いない (Thể thông thường)', '[{"ja":"昼ご飯はまだ食べていません。","romaji":"(Hirugohan wa mada tabete imasen.)","vi":"→ Tôi vẫn chưa ăn trưa."},{"ja":"レポートはまだ書いていない。","romaji":"(Repooto wa mada kaite inai.)","vi":"→ Tôi vẫn chưa viết báo cáo."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('71.  へ  (E) Đến; về phía (chỉ hướng)', 'N5', 'Chỉ phương hướng của hành động di chuyển. So với  に,  へ  (đọc là "e") nhấn mạnh hướng đi hơn là điểm đến cụ thể. Trong nhiều trường hợp, có thể dùng thay  に, nhưng  へ  gợi cảm giác di chuyển về phía đó.', 'Danh từ (Địa điểm) +  へ + Động từ di chuyển (行く,  来る,  帰る...)', '[{"ja":"駅へ行きます。","romaji":"(Eki e ikimasu.)","vi":"→ Tôi đi về phía nhà ga."},{"ja":"大阪へ出張します。","romaji":"(Oosaka e shucchou shimasu.)","vi":"→ Tôi đi công tác (về phía) Osaka."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('72.  なあ  (Naa) Trợ từ cuối câu (biểu cảm)', 'N5', 'Đặt ở cuối câu để thể hiện cảm xúc mạnh như cảm thán, ngưỡng mộ, mong muốn, hoặc tự nhủ. Thường mang sắc thái thân mật, có phần nam tính.', 'Câu +  なあ', '[{"ja":"きれいだなあ。","romaji":"(Kirei da naa.)","vi":"→ Đẹp ghê ha!"},{"ja":"疲れたなあ。","romaji":"(Tsukareta naa.)","vi":"→ Mệt quá đi~."},{"ja":"早く夏休みにならないかなあ。","romaji":"(Hayaku natsuyasumi ni naranai ka naa.)","vi":"→ Mong hè đến nhanh ghê~."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('73.  でも  (Demo) Nhưng; tuy nhiên / Hoặc là; ví dụ như', 'N5', 'Nối hai câu trái nghĩa (thông dụng trong văn nói).   Đưa ra một ví dụ không cụ thể, hoặc gợi ý một lựa chọn ("uống trà hay gì đó không?").', 'Câu 1.  でも、Câu 2. (Nhưng)   Danh từ +  でも + V. (Ví dụ như/Hoặc là)', '[{"ja":"勉強は嫌いです。","romaji":"でも、テストのために頑張ります。","vi":"(Benkyou wa kirai desu. Demo, tesuto no tame ni ganbarimasu.)"},{"ja":"休みの日は、映画でも見ますか。","romaji":"(Yasumi no hi wa, eiga demo mimasu ka?)","vi":"→ Ngày nghỉ, xem phim hay gì đó không?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('74.  ～か～か  (~ka ~ka) Hoặc là A, hoặc là B', 'N5', 'Dùng để đưa ra các lựa chọn, thường trong câu hỏi hoặc khi không chắc chắn.', '[Lựa chọn 1] +  か + [Lựa chọn 2] +  か', '[{"ja":"バスで行くか、電車で行くか、迷っています。","romaji":"(Basu de iku ka, densha de iku ka, mayotte imasu.)","vi":"→ Tôi đang phân vân không biết nên đi bằng xe buýt hay tàu điện."},{"ja":"彼が来るか来ないか、分かりません。","romaji":"(Kare ga kuru ka konai ka, wakarimasen.)","vi":"→ Tôi không biết anh ấy có đến hay không."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('75.  ないで  (Naide) Mà không làm ~; Làm [B] mà không làm [A]', 'N5', 'Dùng để diễn tả việc thực hiện hành động V2 trong khi không thực hiện hành động V1 (V1 thường là hành động được cho là nên làm hoặc thường làm trước V2). Nó chỉ cách thức hoặc hoàn cảnh thực hiện V2.', 'V1-ない (bỏ  い) +  ないで, V2.', '[{"ja":"傘を持たないで、出かけました。","romaji":"(Kasa o motanai de, dekakemashita.)","vi":"→ Tôi đã ra ngoài mà không mang ô."},{"ja":"何も食べないで、寝ました。","romaji":"(Nani mo tabenai de, nemashita.)","vi":"→ Tôi đã đi ngủ mà không ăn gì cả."},{"ja":"Chú ý: Phân biệt với  ないでください  (xin đừng làm) và  なくて  (dạng TE của V-nai, thường chỉ nguyên nhân:  時間がなくて、行きませんでした","romaji":"→ Vì không có thời gian nên tôi đã không đi).","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('76.  てある  (Te aru) Đã được làm (nhấn mạnh trạng thái kết quả của hành động có chủ ý)', 'N5', 'Diễn tả một trạng thái là kết quả của một hành động được ai đó thực hiện có chủ đích (thường là để chuẩn bị cho việc gì đó), và trạng thái đó vẫn còn tồn tại. Trợ từ thường đi kèm là  が.', 'V-て +  あります /  ある (Thường dùng với Tha động từ  → động từ có tân ngữ).', '[{"ja":"壁にポスターが貼ってあります。","romaji":"(Kabe ni posutaa ga hatte arimasu.)","vi":"→ Trên tường có tấm áp phích (đã được ai đó) dán (và nó vẫn ở đó)."},{"ja":"テーブルの上に料理が並べてあります。","romaji":"(Teeburu no ue ni ryouri ga narabete arimasu.)","vi":"→ Trên bàn có đồ ăn (đã được ai đó) bày sẵn."},{"ja":"エアコンがつけてあります。","romaji":"(Eakon ga tsukete arimasu.)","vi":"→ Máy lạnh (đã được ai đó) bật (và giờ nó đang chạy)."},{"ja":"So sánh: Với  ～ている,  ～ている  thường dùng với Tự động từ để chỉ trạng thái tự nhiên (窓が開いています","romaji":"→ Cửa sổ đang mở), hoặc với Tha động từ để chỉ hành động đang diễn ra.  ～てある  nhấn mạnh vào kết quả của hành động có chủ ý.","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('77.  ちゃいけない・じゃいけない  (Chaikenai / Jaikenai) Không được làm (văn nói)', 'N5', 'Là dạng nói tắt, thân mật của  ～てはいけない. Rất phổ biến trong hội thoại.', 'V-て →  ちゃ / V-で →  じゃ +  いけない.', '[{"ja":"嘘をついちゃいけないよ。","romaji":"(Uso o tsuicha ikenai yo.)","vi":"→ Không được nói dối đâu!"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('78.  なくちゃ  (Nakucha) Phải làm (văn nói)', 'N5', 'Là dạng nói tắt, thân mật của  ～なくてはいけない.', 'V-ない (bỏ  い) +  くちゃ.', '[{"ja":"もう行かなくちゃ。","romaji":"(Mou ikanakucha.)","vi":"→ Phải đi thôi."}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('1.  間  (あいだ) Trong khi; trong suốt; giữa ~', 'N4', 'Đang cập nhật nội dung...', 'N  の 間 / V-る/ている 間', '[{"ja":"夏休みの間、ずっと田舎にいました。","romaji":"→ (Trong suốt kỳ nghỉ hè, tôi đã ở quê.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('2.  間に  (あいだに) Trong khi; trong suốt~ (một điều gì đó đã xảy ra)', 'N4', 'Đang cập nhật nội dung...', 'N  の 間に / V-る/ている/ない 間に', '[{"ja":"留守の間に、友達が来ました。","romaji":"→ (Trong lúc tôi vắng nhà, bạn tôi đã đến.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('3.  あまり～ない  Không ~ lắm', 'N4', 'Đang cập nhật nội dung...', 'あまり + V-ない / A-くない / Na  じゃない / N  じゃない', '[{"ja":"この映画はあまり面白くないです。","romaji":"→ (Bộ phim này không thú vị lắm.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('4.  後で  (あとで) Sau khi~; lát nữa', 'N4', 'Đang cập nhật nội dung...', 'N  の 後で / V-た 後で', '[{"ja":"映画を見た後で、食事をしましょう。","romaji":"→ (Sau khi xem phim xong, chúng ta cùng đi ăn nhé.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('5.  ば  Thể điều kiện; Nếu [A] thì [B]', 'N4', 'Đang cập nhật nội dung...', 'V-えば / A-ければ / Na/N +  なら(ば)', '[{"ja":"春になれば、桜が咲きます。","romaji":"→ (Nếu mùa xuân đến, hoa anh đào sẽ nở.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('6.  場合は  (ばあいは) Trong trường hợp ~', 'N4', 'Đang cập nhật nội dung...', 'N  の / V-る/た/ない / A-い / Na  な +  場合は', '[{"ja":"火事の場合は、エレベーターを使わないでください。","romaji":"→ (Trong trường hợp có hỏa hoạn, đừng dùng thang máy.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('7.  ばかり  Chỉ; toàn là ~', 'N4', 'Đang cập nhật nội dung...', 'N +  ばかり / V-て +  ばかりいる', '[{"ja":"彼は遊んでばかりいる。","romaji":"→ (Anh ta chỉ toàn chơi.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('8.  だけで  Chỉ bằng cách; chỉ cần làm ~', 'N4', 'Đang cập nhật nội dung...', 'N +  だけで / V-る +  だけで', '[{"ja":"このボタンを押すだけで、ドアが開きます。","romaji":"→ (Chỉ cần ấn nút này là cửa sẽ mở.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('9.  出す  (だす) Bắt đầu; ... ra', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  出す', '[{"ja":"急に雨が降り出した。","romaji":"→ (Đột nhiên trời bắt đầu mưa.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('10.  でございます  Là (kính ngữ)', 'N4', 'Đang cập nhật nội dung...', 'N +  でございます', '[{"ja":"こちらは受付でございます。","romaji":"→ (Đây là quầy lễ tân ạ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('11.  でも  ... hoặc cái gì đó; ~ thì sao nhỉ', 'N4', 'Đang cập nhật nội dung...', 'N +  でも', '[{"ja":"お茶でも飲みませんか。","romaji":"→ (Uống trà hay gì đó không?)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('12.  ではないか  /  じゃないか  Phải không?; chẳng phải là ~ sao?', 'N4', 'Đang cập nhật nội dung...', 'V-thể thông thường / A-い / Na/N +  ではないか (じゃないか)', '[{"ja":"ほら、雨が降ってきたじゃないか。","romaji":"→ (Kìa, chẳng phải mưa rồi sao?)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('13.  が必要  (がひつよう) Cần; cần thiết', 'N4', 'Đang cập nhật nội dung...', 'N +  が必要だ / V-ること +  が必要だ', '[{"ja":"練習が必要です。","romaji":"→ (Cần phải luyện tập.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('14.  がする  Có mùi; nghe thấy; có vị', 'N4', 'Đang cập nhật nội dung...', 'N (cảm giác) +  がする', '[{"ja":"変な匂いがしますね。","romaji":"→ (Có mùi lạ nhỉ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('15.  がり  Tính cách (hay ~)', 'N4', 'Đang cập nhật nội dung...', 'A-い (bỏ  い) / Na +  がり', '[{"ja":"彼は暑がりです。","romaji":"→ (Anh ấy là người sợ nóng.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('16.  がる  /  がっている  Tỏ ra; có vẻ; cảm thấy, nghĩ rằng ~', 'N4', 'Đang cập nhật nội dung...', 'A-い (bỏ  い) / Na +  がる /  がっている', '[{"ja":"子供がそのおもちゃを欲しがっている。","romaji":"→ (Đứa bé có vẻ muốn món đồ chơi đó.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('17.  ございます  Là, tồn tại (thể lịch sự của  いる/ある)', 'N4', 'Đang cập nhật nội dung...', 'N +  でございます / N +  がございます', '[{"ja":"何かご用件がございますか。","romaji":"→ (Ngài có việc gì cần ạ?)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('18.  始める  (はじめる) Bắt đầu ~', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  始める', '[{"ja":"日本語の勉強を始めました。","romaji":"→ (Tôi đã bắt đầu học tiếng Nhật.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('19.  はずだ  Chắc chắn là; đáng lẽ ra', 'N4', 'Đang cập nhật nội dung...', 'V-thể thông thường / A-い / Na  な / N  の +  はずだ', '[{"ja":"彼は来るはずだ。","romaji":"→ (Chắc chắn anh ấy sẽ đến.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('20.  はずがない  Không thể nào', 'N4', 'Đang cập nhật nội dung...', 'V-thể thông thường / A-い / Na  な / N  の +  はずがない', '[{"ja":"彼がそんなことをするはずがない。","romaji":"→ (Không thể nào anh ta lại làm chuyện đó.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('21.  必要がある  (ひつようがある) Cần phải; cần thiết phải ~', 'N4', 'Đang cập nhật nội dung...', 'V-る +  必要がある / N +  が必要だ', '[{"ja":"もっと練習する必要があります。","romaji":"→ Cần phải luyện tập nhiều hơn nữa.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('22.  意向形  (いこうけい) Thể ý chí; chúng ta hãy làm ~', 'N4', 'Đang cập nhật nội dung...', 'V1: -u → -おう (書く→書こう)  V2: -る → -よう (食べる→食べよう)  V3:  する→しよう,  来る→来よう', '[{"ja":"映画を見に行こう。","romaji":"→ Chúng ta hãy đi xem phim đi.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('23.  いらっしゃる  Là; đến; đi (kính ngữ)', 'N4', 'Đang cập nhật nội dung...', 'Là kính ngữ của  いる,  来る,  行く.', '[{"ja":"社長はもういらっしゃいましたか。","romaji":"→ (Shachō wa mō irasshaimashita ka.)","vi":"→ Nghĩa: Giám đốc đã đến rồi phải không ạ?"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('24.  いたします  Làm (thể khiêm nhường của  する)', 'N4', 'Đang cập nhật nội dung...', 'Là khiêm nhường ngữ của  する.', '[{"ja":"私がご説明いたします。","romaji":"→ Tôi xin phép được giải thích ạ.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('25.  じゃないか  Phải không?; chẳng phải là ~ sao?', 'N4', 'Đang cập nhật nội dung...', 'Giống  ではないか nhưng thân mật hơn.', '[{"ja":"いい天気じゃないか！","romaji":"→ Trời đẹp quá còn gì!","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('26.  かどうか  Có ~ hay không', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  かどうか', '[{"ja":"明日、彼が来るかどうか分かりません。","romaji":"→ Tôi không biết ngày mai anh ấy có đến hay không.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('27.  かしら  Tôi tự hỏi (nữ giới dùng)', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  かしら', '[{"ja":"明日は晴れるかしら。","romaji":"→ Mai trời có nắng không nhỉ?","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('28.  かい  Biến câu thành câu hỏi có/không (thân mật, nam giới)', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  かい', '[{"ja":"もう宿題をしたかい？","romaji":"→ Làm bài tập xong chưa con?","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('29.  かもしれない  Có lẽ; có thể', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  かもしれない (Lịch sự:  ～かもしれません)', '[{"ja":"約束の時間に間に合わないかもしれない。","romaji":"→ Có lẽ tôi sẽ không kịp giờ hẹn.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('30.  かな  Tôi tự hỏi; có nên không nhỉ?', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  かな', '[{"ja":"この服、似合うかな。","romaji":"→ Bộ đồ này có hợp với mình không nhỉ?","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('31.  から作る  Được làm từ (nguyên liệu bị biến đổi)', 'N4', 'Đang cập nhật nội dung...', 'N (nguyên liệu) +  から +  作る/できる', '[{"ja":"ワインはぶどうから作られます。","romaji":"→ Rượu vang được làm từ nho.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('32.  きっと  Chắc chắn', 'N4', 'Đang cập nhật nội dung...', 'Trạng từ.', '[{"ja":"彼はきっと来ます。","romaji":"→ Anh ấy chắc chắn sẽ đến.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('33.  頃  (ころ  /  ごろ) Khoảng; vào khoảng; khi', 'N4', 'Đang cập nhật nội dung...', 'N (thời điểm) +  ごろ / V-る/た +  ころ', '[{"ja":"３時ごろ会いましょう。","romaji":"→ Gặp nhau vào khoảng 3 giờ nhé.","vi":"→  子供のころ、よく川で遊びました。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('34.  こと  Việc; danh từ hóa động từ', 'N4', 'Đang cập nhật nội dung...', 'V-る/た/ない +  こと', '[{"ja":"私の趣味は映画を見ることです。","romaji":"→ Sở thích của tôi là việc xem phim.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('35.  ことがある  Thỉnh thoảng; đôi khi ~', 'N4', 'Đang cập nhật nội dung...', 'V-る/ない +  ことがある', '[{"ja":"時々、朝ごはんを食べないことがあります。","romaji":"→ Thỉnh thoảng tôi không ăn sáng.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('36.  ことができる  Có thể ~', 'N4', 'Đang cập nhật nội dung...', 'V-る +  ことができる', '[{"ja":"私は漢字を読むことができます。","romaji":"→ Tôi có thể đọc chữ Hán.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('37.  ことになる  Được quyết định là..; hóa ra là..', 'N4', 'Đang cập nhật nội dung...', 'V-る/ない +  ことになる', '[{"ja":"来月、転勤することになりました。","romaji":"→ Đã được quyết định là tháng sau tôi sẽ chuyển công tác.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('38.  ことにする  Quyết định ~', 'N4', 'Đang cập nhật nội dung...', 'V-る/ない +  ことにする', '[{"ja":"これから、毎日運動することにします。","romaji":"→ Từ giờ tôi quyết định sẽ vận động mỗi ngày.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('39.  くする  /  にする  Làm cho ~ trở nên ~', 'N4', 'Đang cập nhật nội dung...', 'A-い (bỏ  い) +  く +  する / Na +  に +  する', '[{"ja":"音を大きくしてください。","romaji":"→ Hãy làm cho âm thanh to lên.","vi":"→  部屋をきれいにしてください。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('40.  急に  (きゅうに) Đột ngột; bất ngờ', 'N4', 'Đang cập nhật nội dung...', 'Trạng từ.', '[{"ja":"急に空が暗くなった。","romaji":"→ Đột nhiên trời tối sầm lại.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('41.  までに  Trước; cho đến (chỉ giới hạn thời gian)', 'N4', 'Đang cập nhật nội dung...', 'Danh từ (thời gian) / V-る +  までに', '[{"ja":"レポートは金曜日までに提出してください。","romaji":"→ (Hãy nộp báo cáo trước thứ Sáu.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('42.  まま  Cứ để nguyên; trạng thái hiện tại', 'N4', 'Đang cập nhật nội dung...', 'V-た / V-ない / N  の / A-い / Na  な +  まま', '[{"ja":"窓を開けたまま寝てしまった。","romaji":"→ (Tôi đã ngủ quên mà cứ để cửa sổ mở.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('43.  または  Hoặc; hoặc là', 'N4', 'Đang cập nhật nội dung...', 'N1 +  または + N2', '[{"ja":"住所または電話番号を書いてください。","romaji":"→ (Hãy viết địa chỉ hoặc số điện thoại.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('44.  みたいだ  Giống như; tương tự; trông giống ~', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  みたいだ', '[{"ja":"あの雲は犬みたいだ。","romaji":"→ (Đám mây kia trông giống như con chó.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('45.  みたいな  Giống như, tương tự ~ (dùng như tính từ  な)', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  みたいな + N', '[{"ja":"夢みたいな話ですね。","romaji":"→ (Đó là câu chuyện giống như giấc mơ nhỉ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('46.  みたいに  Giống như; tương tự ~ (dùng như trạng từ)', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  みたいに + V/A', '[{"ja":"子供みたいに笑っている。","romaji":"→ (Đang cười như một đứa trẻ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('47.  も  Đến mức; nhiều đến', 'N4', 'Đang cập nhật nội dung...', 'Danh từ (số lượng) +  も', '[{"ja":"パーティーには１００人も来ました。","romaji":"→ (Có đến 100 người đã đến bữa tiệc.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('48.  な  Đừng ~ (mệnh lệnh thân mật)', 'N4', 'Đang cập nhật nội dung...', 'V-る +  な', '[{"ja":"ここでタバコを吸うな。","romaji":"→ (Đừng hút thuốc ở đây!)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('49.  など  Như là; những thứ như ~', 'N4', 'Đang cập nhật nội dung...', 'N1  や N2 +  など', '[{"ja":"机の上には、本やペンなどがあります。","romaji":"→ (Trên bàn có những thứ như sách và bút.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('50.  ながら  Vừa... vừa...', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  ながら', '[{"ja":"音楽を聞きながら、勉強します。","romaji":"→ (Tôi vừa nghe nhạc vừa học bài.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('51.  なかなか～ない  Khó mà ~; mãi mà không ~', 'N4', 'Đang cập nhật nội dung...', 'なかなか + V-ない / A-くない / Na  じゃない', '[{"ja":"バスがなかなか来ない。","romaji":"→ (Xe buýt mãi mà không đến.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('52.  なければいけない  Phải làm gì đó', 'N4', 'Đang cập nhật nội dung...', 'V-ない (bỏ  い) +  ければいけない', '[{"ja":"薬を飲まなければいけません。","romaji":"→ (Phải uống thuốc.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('53.  なければならない  Phải làm gì đó', 'N4', 'Đang cập nhật nội dung...', 'V-ない (bỏ  い) +  ければならない', '[{"ja":"明日、早く起きなければならない。","romaji":"→ (Ngày mai tôi phải dậy sớm.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('54.  なら  Nếu; trong trường hợp ~', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  なら', '[{"ja":"日本へ行くなら、京都がいいですよ。","romaji":"→ (Nếu (nói về việc) đi Nhật thì Kyoto là hay đấy.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('55.  なさい  Hãy làm đi', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  なさい', '[{"ja":"早く寝なさい。","romaji":"→ (Hãy ngủ sớm đi.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('56.  なさる  Làm (kính ngữ)', 'N4', 'Đang cập nhật nội dung...', 'Kính ngữ của  する.', '[{"ja":"社長は何をなさっていますか。","romaji":"→ (Giám đốc đang làm gì đấy ạ?)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('57.  に気がつく  Nhận thấy; nhận ra', 'N4', 'Đang cập nhật nội dung...', 'N / V-こと +  に気がつく', '[{"ja":"財布がないことに気がついた。","romaji":"→ (Tôi nhận ra là mình không có ví.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('58.  に見える  Trông có vẻ; dường như', 'N4', 'Đang cập nhật nội dung...', 'N / A-く / Na  に +  見える', '[{"ja":"彼女は幸せに見える。","romaji":"→ (Cô ấy trông có vẻ hạnh phúc.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('59.  にする  Quyết định chọn ~', 'N4', 'Đang cập nhật nội dung...', 'N +  にする', '[{"ja":"飲み物は何にしますか。","romaji":"→ コーヒーにします。","vi":"→ (Đồ uống bạn chọn gì? Tôi chọn cà phê.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('60.  にくい  Khó làm ~', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  にくい', '[{"ja":"この字は小さくて読みにくい。","romaji":"→ (Chữ này nhỏ nên khó đọc.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('61.  の中で  Trong; giữa ~', 'N4', 'Đang cập nhật nội dung...', 'Danh từ (phạm vi) +  の中で', '[{"ja":"果物の中で、りんごが一番好きです。","romaji":"→ (Trong các loại hoa quả, tôi thích táo nhất.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('62.  のに  Mặc dù; dù cho ~ (bất ngờ, trái dự đoán)', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na  な/N  な +  のに', '[{"ja":"約束したのに、彼は来ませんでした。","romaji":"→ (Mặc dù đã hứa, anh ấy đã không đến.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('63.  のに  Để (làm gì đó); dùng cho việc ~ (chỉ mục đích)', 'N4', 'Đang cập nhật nội dung...', 'V-る +  のに', '[{"ja":"この道具は木を切るのに便利です。","romaji":"→ (Dụng cụ này tiện lợi cho việc cắt gỗ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('64.  のは〜だ  [A] là [B] (Nhấn mạnh)', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na  な/N  な +  のは + N/A/V +  だ', '[{"ja":"私が生まれたのは東京です。","romaji":"→ (Nơi tôi sinh ra là Tokyo.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('65.  お～ください  Xin hãy ~ (kính ngữ)', 'N4', 'Đang cập nhật nội dung...', 'お + V-ます (bỏ  ます) +  ください', '[{"ja":"こちらでお待ちください。","romaji":"→ (Xin vui lòng đợi ở đây ạ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('66.  お～になる  Làm (kính ngữ)', 'N4', 'Đang cập nhật nội dung...', 'お + V-ます (bỏ  ます) +  になる', '[{"ja":"社長はもうお帰りになりました。","romaji":"→ (Giám đốc đã về rồi ạ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('67.  おきに  Cách quãng; cứ mỗi ~', 'N4', 'Đang cập nhật nội dung...', 'Từ chỉ số lượng (thời gian/không gian) +  おきに', '[{"ja":"このバスは１０分おきに来ます。","romaji":"→ (Xe buýt này cứ 10 phút lại đến một chuyến.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('68.  終わる  (おわる) Kết thúc ~', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  終わる', '[{"ja":"この本を読み終わったら、貸してください。","romaji":"→ (Khi nào đọc xong cuốn sách này thì cho tôi mượn nhé.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('69.  られる  Thể khả năng; có thể ~', 'N4', 'Đang cập nhật nội dung...', 'V1: -u → -eru; V2: -る → -られる; V3:  できる,  来られる', '[{"ja":"私は納豆が食べられます。","romaji":"→ (Tôi có thể ăn được natto.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('70.  らしい  Có vẻ như; nghe nói; hình như ~', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể thông thường) +  らしい', '[{"ja":"天気予報によると、明日は雨らしい。","romaji":"→ (Theo dự báo thời tiết, nghe nói ngày mai trời mưa.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('71.  さ  Danh từ hóa tính từ', 'N4', 'Đang cập nhật nội dung...', 'A-い (bỏ  い) +  さ / Na +  さ', '[{"ja":"この川の深さはどのぐらいですか。","romaji":"→ (Độ sâu của con sông này là bao nhiêu?)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('72.  さっき  Lúc nãy; vừa mới', 'N4', 'Đang cập nhật nội dung...', 'Trạng từ.', '[{"ja":"さっき、田中さんに会いました。","romaji":"→ (Lúc nãy tôi đã gặp anh Tanaka.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('73.  させられる  Thể bị động sai khiến; bị bắt làm ~', 'N4', 'Đang cập nhật nội dung...', 'V1: -a +  せられる; V2: -させられる; V3:  させられる,  来させられる .', '[{"ja":"子供の時、母にピアノを習わせられました。","romaji":"→ (Hồi nhỏ, tôi bị mẹ bắt học piano.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('74.  させる  Thể sai khiến; bắt/cho phép ~', 'N4', 'Đang cập nhật nội dung...', 'V1: -a +  せる; V2: -させる; V3:  させる,  来させる.', '[{"ja":"先生は生徒に本を読ませた。","romaji":"→ (Thầy giáo đã cho/bắt học sinh đọc sách.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('75.  させてください  Xin hãy cho phép tôi làm ~', 'N4', 'Đang cập nhật nội dung...', 'V-(thể sai khiến)  て +  ください (V-させてください).', '[{"ja":"今日は早く帰らせてください。","romaji":"→ (Xin hãy cho phép tôi về sớm hôm nay.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('76.  さすが  Quả đúng là; như mong đợi', 'N4', 'Đang cập nhật nội dung...', 'Trạng từ /  さすが + N.', '[{"ja":"さすがですね。","romaji":"→ こんな難しい問題もできるなんて。","vi":"→ (Quả đúng là anh/chị. Vấn đề khó thế này mà cũng làm được.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('77.  し  Và; hơn nữa ~ (liệt kê lý do)', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na  だ/N  だ +  し', '[{"ja":"この店は安いし、おいしいし、いつも混んでいます。","romaji":"→ (Quán này vừa rẻ vừa ngon nên lúc nào cũng đông.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('78.  そんなに  Đến mức đó; như thế', 'N4', 'Đang cập nhật nội dung...', 'Trạng từ (thường đi với phủ định).', '[{"ja":"日本語はそんなに難しくないですよ。","romaji":"→ (Tiếng Nhật không khó đến mức đó đâu.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('79.  それでも  Nhưng mà; tuy nhiên; dù vậy ~', 'N4', 'Đang cập nhật nội dung...', 'Từ nối.', '[{"ja":"大雨が降っています。","romaji":"→ それでも、試合は続きます。","vi":"→ (Trời đang mưa to. Dù vậy, trận đấu vẫn tiếp tục.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('80.  それに  Bên cạnh đó; thêm vào đó; hơn nữa ~', 'N4', 'Đang cập nhật nội dung...', 'Từ nối.', '[{"ja":"このアパートは駅から近いし、それに、家賃も安いです。","romaji":"→ (Căn hộ này vừa gần ga, thêm vào đó, tiền thuê nhà cũng rẻ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('81.  そうだ  Nghe nói là; người ta nói rằng ~', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na  だ/N  だ (thể thông thường) +  そうだ', '[{"ja":"天気予報によると、明日は雪が降るそうです。","romaji":"→ (Theo dự báo thời tiết, nghe nói ngày mai tuyết sẽ rơi.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('82.  そうだ  Trông có vẻ; có vẻ như; dường như ~', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) / A-い (bỏ  い) / Na +  そうだ', '[{"ja":"このケーキはおいしそうだ。","romaji":"→ (Cái bánh này trông có vẻ ngon.)","vi":"→  雨が降り そうです。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('83.  そうに  /  そうな  Trông có vẻ; giống như ~', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) / A-い (bỏ  い) / Na +  そうに + V /  そうな + N', '[{"ja":"彼女は楽しそうに歌っています。","romaji":"→ (Cô ấy đang hát trông có vẻ vui.)","vi":"→  彼は 眠そうな顔をしています。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('84.  たばかり  Vừa mới; vừa mới xảy ra', 'N4', 'Đang cập nhật nội dung...', 'V-た +  ばかりだ', '[{"ja":"日本に来たばかりです。","romaji":"→ (Tôi vừa mới đến Nhật.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('85.  たところ  Vừa mới làm xong', 'N4', 'Đang cập nhật nội dung...', 'V-た +  ところだ', '[{"ja":"ちょうど今、宿題が終わったところです。","romaji":"→ (Đúng lúc này tôi vừa làm xong bài tập.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('86.  他動詞  &  自動詞  Tha động từ & Tự động từ', 'N4', 'Đang cập nhật nội dung...', 'Tha động từ (N  を V) / Tự động từ (N  が V)', '[{"ja":"ドアを開ける。","romaji":"→ (Mở cửa - Tha)","vi":"→  ドアが開く。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('87.  たがる  Muốn làm ~ (ngôi thứ ba)', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  たがる /  たがっている', '[{"ja":"妹は留学したがっています。","romaji":"→ (Em gái tôi muốn đi du học.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('88.  たら  Nếu; sau khi; khi ~', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na/N (thể  た) +  ら', '[{"ja":"お金があったら、旅行したい。","romaji":"→ (Nếu có tiền, tôi muốn đi du lịch.)","vi":"→  家に帰ったら、手紙が来ていた。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('89.  たらどう  Tại sao bạn không ~; ~ thì sao?', 'N4', 'Đang cập nhật nội dung...', 'V-たら +  どうですか /  どう？', '[{"ja":"疲れているなら、少し休んだらどうですか。","romaji":"→ (Nếu mệt thì sao bạn không nghỉ một chút?)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G0.  たらいいですか  Tôi nên làm gì?', 'N4', 'Đang cập nhật nội dung...', 'V-たら +  いいですか', '[{"ja":"道に迷ったんですが、どうしたらいいですか。","romaji":"→ (Tôi bị lạc đường rồi, tôi nên làm thế nào?)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G1.  て  /  で  Liên từ; nên; vì [A], [B]... (chỉ nguyên nhân)', 'N4', 'Đang cập nhật nội dung...', 'V-て / A-くて / Na  で / N  で', '[{"ja":"病気で学校を休みました。","romaji":"→ (Vì bị ốm nên tôi đã nghỉ học.)","vi":"→  試験に合格し て、嬉しいです。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G2.  てあげる  Làm cho (ai đó)', 'N4', 'Đang cập nhật nội dung...', 'V-て +  あげる', '[{"ja":"私は妹に本を読んであげた。","romaji":"→ (Tôi đã đọc sách cho em gái.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G3.  てほしい  Tôi muốn bạn ~', 'N4', 'Đang cập nhật nội dung...', 'V-て +  ほしい', '[{"ja":"あなたに手伝ってほしい。","romaji":"→ (Tôi muốn bạn giúp tôi.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G4.  ていく  Bắt đầu; tiếp tục; đi tiếp', 'N4', 'Đang cập nhật nội dung...', 'V-て +  いく', '[{"ja":"これから暖かくなっていきます。","romaji":"→ (Từ giờ trời sẽ dần ấm lên.)","vi":"→  彼は歩い ていった。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G5.  ていた  Đang làm gì đó (quá khứ tiếp diễn)', 'N4', 'Đang cập nhật nội dung...', 'V-て +  いた', '[{"ja":"昨日、私が電話した時、彼はテレビを見ていました。","romaji":"→ (Hôm qua, lúc tôi gọi điện, anh ấy đang xem TV.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G6.  ていただけませんか  Bạn có thể vui lòng ~?', 'N4', 'Đang cập nhật nội dung...', 'V-て +  いただけませんか', '[{"ja":"この書類をチェックしていただけませんか。","romaji":"→ (Bạn có thể vui lòng kiểm tra tài liệu này cho tôi được không ạ?)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G7.  てくれる  Làm cho tôi/phía tôi', 'N4', 'Đang cập nhật nội dung...', 'V-て +  くれる', '[{"ja":"友達が私にプレゼントをくれた。","romaji":"→ (Bạn tôi đã tặng quà cho tôi.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G8.  てくる  Làm... rồi quay lại; trở nên; bắt đầu ~', 'N4', 'Đang cập nhật nội dung...', 'V-て +  くる', '[{"ja":"ちょっと牛乳を買ってくる。","romaji":"→ (Tôi đi mua sữa rồi về ngay.)","vi":"→  だんだん寒 くなってきた。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('GG.  てみる  Thử làm ~', 'N4', 'Đang cập nhật nội dung...', 'V-て +  みる', '[{"ja":"この新しいレストランで食べてみましょう。","romaji":"→ (Chúng ta hãy ăn thử ở nhà hàng mới này xem sao.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('100.  てもらう  Được ai đó làm cho ~', 'N4', 'Đang cập nhật nội dung...', 'V-て +  もらう', '[{"ja":"私は医者に診てもらった。","romaji":"→ (Tôi đã được bác sĩ khám cho.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('101.  ておく  Làm sẵn; làm trước ~', 'N4', 'Đang cập nhật nội dung...', 'V-て +  おく (Nói tắt:  ～とく /  ～どく)', '[{"ja":"旅行の前に、切符を買っておきます。","romaji":"→ (Trước chuyến du lịch, tôi mua sẵn vé.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('102.  てしまう  /  ちゃう  Lỡ làm gì đó; làm xong hoàn toàn', 'N4', 'Đang cập nhật nội dung...', 'V-て +  しまう (Nói tắt:  ～ちゃう /  ～じゃう)', '[{"ja":"大切なコップを割ってしまった。","romaji":"→ (Tôi đã lỡ làm vỡ cái cốc quan trọng.) / 宿題はもうやってしまいました。","vi":"→ (Bài tập tôi đã làm xong hết rồi.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('103.  てすみません  Tôi xin lỗi vì đã ~', 'N4', 'Đang cập nhật nội dung...', 'V-て +  すみません /  すみませんでした', '[{"ja":"返事が遅れてすみませんでした。","romaji":"→ (Xin lỗi vì đã trả lời muộn.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('104.  てやる  Làm cho (người dưới, động vật, thực vật)', 'N4', 'Đang cập nhật nội dung...', 'V-て +  やる', '[{"ja":"弟に宿題を手伝ってやった。","romaji":"→ (Tôi đã giúp em trai làm bài tập.)","vi":"→  花に水を やりました。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('105.  てよかった  Tôi mừng vì đã ~', 'N4', 'Đang cập nhật nội dung...', 'V-て / V-なくて +  よかった', '[{"ja":"あなたに会えてよかったです。","romaji":"→ (Tôi mừng vì đã có thể gặp bạn.)","vi":"→  雨が降 らなくてよかった。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('106.  ているところ  Đang trong quá trình làm ~', 'N4', 'Đang cập nhật nội dung...', 'V-て +  いる +  ところだ', '[{"ja":"今、レポートを書いているところです。","romaji":"→ (Bây giờ tôi đang viết báo cáo.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('107.  ても  Dù; ngay cả khi; mặc dù ~', 'N4', 'Đang cập nhật nội dung...', 'V-て / A-くて / Na  で / N  で +  も', '[{"ja":"高くても、買いたいです。","romaji":"→ (Dù đắt tôi vẫn muốn mua.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('108.  と  Hễ mà [A] xảy ra, thì [B] cũng xảy ra', 'N4', 'Đang cập nhật nội dung...', 'V-る / A-い / Na  だ / N  だ +  と', '[{"ja":"春になると、桜が咲きます。","romaji":"→ (Hễ mùa xuân đến thì hoa anh đào nở.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('109.  と言ってもいい  Có thể nói là ~', 'N4', 'Đang cập nhật nội dung...', '(Cụm từ/Câu) +  と言ってもいい (でしょう)', '[{"ja":"彼は現代の英雄と言ってもいいでしょう。","romaji":"→ (Có thể nói anh ấy là người hùng thời hiện đại.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('110.  という  Được gọi là; tên là; rằng ~', 'N4', 'Đang cập nhật nội dung...', 'N1 +  という + N2 / (Trích dẫn/Nội dung) +  という + N', '[{"ja":"これは「納豆」という食べ物です。","romaji":"→ (Đây là món ăn gọi là \"Natto\".)","vi":"→  彼が 結婚するという噂を聞きました。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('111.  ということ  Việc ~; danh từ hóa cụm từ', 'N4', 'Đang cập nhật nội dung...', '(Câu) +  ということ', '[{"ja":"時間を守るということは大切です。","romaji":"→ (Việc giữ đúng giờ là quan trọng.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('112.  と言われている  Người ta nói rằng ~', 'N4', 'Đang cập nhật nội dung...', '(Sự thật/Niềm tin) +  と言われている', '[{"ja":"昔、ここには大きな寺があったと言われています。","romaji":"→ (Người ta nói rằng ngày xưa ở đây có một ngôi chùa lớn.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('113.  と聞いた  Tôi nghe nói...', 'N4', 'Đang cập nhật nội dung...', '(Thông tin) +  と聞いた /  と聞きました', '[{"ja":"山田さんは来月転勤すると聞きました。","romaji":"→ (Tôi nghe nói anh Yamada tháng sau sẽ chuyển công tác.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('114.  と思う  Nghĩ rằng...', 'N4', 'Đang cập nhật nội dung...', '(Nội dung suy nghĩ) +  と思う /  と思います', '[{"ja":"彼はきっと合格すると思います。","romaji":"→ (Tôi nghĩ anh ấy chắc chắn sẽ đỗ.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('115.  とか～とか  Nào là... nào là...; như là ~', 'N4', 'Đang cập nhật nội dung...', 'N1  とか N2  とか / V1  とか V2  とか', '[{"ja":"休みの日には、映画を見るとか、本を読むとかしています。","romaji":"→ (Vào ngày nghỉ, tôi thường làm những việc như là xem phim, hay là đọc sách.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('116.  ところ  Sắp sửa; đang chuẩn bị làm ~', 'N4', 'Đang cập nhật nội dung...', 'V-る +  ところだ', '[{"ja":"これから出かけるところです。","romaji":"→ (Bây giờ tôi sắp ra ngoài đây.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('117.  続ける  (つづける) Tiếp tục ~', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  続ける', '[{"ja":"雨が一日中降り続けた。","romaji":"→ (Mưa đã rơi liên tục suốt cả ngày.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('118.  って  Tên là; gọi là ~; rằng ~ (thân mật)', 'N4', 'Đang cập nhật nội dung...', 'Thay thế ch は,  と,  という... trong văn nói.', '[{"ja":"田中さんって、どんな人？(Anh Tanaka ấy, là người thế nào?)","romaji":"→  彼は来な いって言ってたよ。","vi":"→ (Anh ấy nói là không đến đâu.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('119.  受身形  (うけみけい) Thể bị động', 'N4', 'Đang cập nhật nội dung...', 'V1: -a +  れる; V2: -られる; V3:  される,  来られる.', '[{"ja":"私は犬に手を噛まれました。","romaji":"→ (Tôi bị chó cắn vào tay.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('120.  は〜が…  は  [A] thì [B]; tuy nhiên; so sánh', 'N4', 'Đang cập nhật nội dung...', 'N1  は ～ が、N2  は ～', '[{"ja":"英語は得意ですが、数学は苦手です。","romaji":"→ (Tiếng Anh thì tôi giỏi, nhưng toán thì tôi kém.)","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('121.  やすい  Dễ ~; có khả năng ~; có xu hướng ~', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  やすい', '[{"ja":"この薬は飲みやすいです。","romaji":"→ (Thuốc này dễ uống.)","vi":"→  このコップは壊れや すいので、気をつけてください。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('122.  やっと  Cuối cùng thì; mãi mới; vừa đủ ~', 'N4', 'Đang cập nhật nội dung...', 'Trạng từ.', '[{"ja":"やっとバスに乗れました。","romaji":"→ (Mãi mới lên được xe buýt.)","vi":"→  やっと宿題が終 わった。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('123.  より  Hơn; hơn là; hơn ~', 'N4', 'Đang cập nhật nội dung...', 'N1  は N2  より A  です', '[{"ja":"中国は日本より大きいです。","romaji":"→ (Trung Quốc thì lớn hơn Nhật Bản.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('124.  予定だ  (よていだ) Dự định; có kế hoạch ~', 'N4', 'Đang cập nhật nội dung...', 'V-る / N  の +  予定だ', '[{"ja":"午後、会議の予定です。","romaji":"→ (Buổi chiều tôi có kế hoạch họp.)","vi":"→  来年、結婚する予定です。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('125.  ようだ  Có vẻ; dường như; trông như là ~', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na  な/N  の +  ようだ', '[{"ja":"外は雨が降っているようです。","romaji":"→ (Bên ngoài có vẻ như đang mưa.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('126.  ように  /  ような  Giống như; như là; tương tự ~', 'N4', 'Đang cập nhật nội dung...', 'V/A/Na  な/N  の +  ように + V/A /  ような + N', '[{"ja":"雪のような肌。","romaji":"→ (Làn da (trắng) như tuyết.)","vi":"→  日本語が話せるように、毎日勉強しています。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('127.  ようになる  Trở nên; đến mức mà ~', 'N4', 'Đang cập nhật nội dung...', 'V-る (thể khả năng) / V-ない +  ようになる', '[{"ja":"練習して、泳げるようになりました。","romaji":"→ (Nhờ luyện tập, tôi đã biết bơi.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('128.  ようにする  Cố gắng ~; đảm bảo rằng ~', 'N4', 'Đang cập nhật nội dung...', 'V-る / V-ない +  ようにする', '[{"ja":"甘いものを食べないようにしています。","romaji":"→ (Tôi đang cố gắng không ăn đồ ngọt.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('129.  ようと思う  Định làm; dự định làm ~', 'N4', 'Đang cập nhật nội dung...', 'V-意向形 +  と思う', '[{"ja":"週末は、家でゆっくり休もうと思います。","romaji":"→ (Cuối tuần tôi định sẽ nghỉ ngơi thong thả ở nhà.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('130.  ぜひ  Nhất định; chắc chắn ~', 'N4', 'Đang cập nhật nội dung...', 'Trạng từ.', '[{"ja":"ぜひ日本へ遊びに来てください。","romaji":"→ (Nhất định hãy đến Nhật chơi nhé.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('131.  全然～ない  Hoàn toàn không ~', 'N4', 'Đang cập nhật nội dung...', '全然 + V-ない / A-くない / Na  じゃない / N  じゃない', '[{"ja":"お金が全然ありません。","romaji":"→ (Tôi hoàn toàn không có tiền.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('132.  づらい  Khó làm ~ (tâm lý)', 'N4', 'Đang cập nhật nội dung...', 'V-ます (bỏ  ます) +  づらい', '[{"ja":"人前で話しづらい。","romaji":"→ (Tôi thấy khó nói chuyện trước đám đông.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('1.  上げる  (あげる) /  上がる  (あがる) - Hoàn thành việc ~', 'N3', 'Diễn tả sự hoàn thành, kết thúc trọn vẹn của một hành động, thường là những hành động đòi hỏi nỗ lực hoặc có kết quả cụ thể.', 'V-ます (bỏ  ます) +  上げる (Tha động từ)   V-ます (bỏ  ます) +  上がる (Tự động từ)', '[{"ja":"やっとレポートを書き上げた。","romaji":"→ (Cuối cùng tôi cũng đã viết xong bản báo cáo.)","vi":""},{"ja":"ケーキが焼き上がりました。","romaji":"→ (Bánh đã nướng xong rồi.)","vi":"──────────"},{"ja":"～切る (N3): Nhấn mạnh việc làm xong toàn bộ, hết sạch.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('2.  あまり  - Quá... đến nỗi', 'N3', 'Diễn tả một kết quả (thường bất thường/tiêu cực) xảy ra do một trạng thái hoặc cảm xúc ở mức độ quá cao.', 'N +  の +  あまり   V-る / V-た +  あまり   Adj-な +  な +  あまり   Adj-い →  さ +  の +  あまり', '[{"ja":"嬉しさのあまり、涙が出ました。","romaji":"→ (Vì quá vui sướng, tôi đã bật khóc.)","vi":""},{"ja":"心配するあまり、彼は病気になってしまった。","romaji":"→ (Vì quá lo lắng, anh ấy đã đổ bệnh.)","vi":"──────────"},{"ja":"～て/で (N5/N4): Diễn tả nguyên nhân - kết quả thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('3.  あまりにも  - Quá nhiều; quá mức; quá ~', 'N3', 'Là một trạng từ dùng để nhấn mạnh mức độ "quá", "vượt quá bình thường". Mạnh hơn  とても.', 'あまりにも + Adj / Adv / V', '[{"ja":"あまりにも難しい問題で、誰も解けなかった。","romaji":"→ (Vì là một vấn đề quá khó nên không ai giải được.)","vi":""},{"ja":"彼の態度はあまりにも失礼だ。","romaji":"→ (Thái độ của anh ta thật quá bất lịch sự.)","vi":"──────────"},{"ja":"非常に (N3): Cực kỳ (tương đối trang trọng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('4.  合う  (あう) - Cùng nhau làm gì đó', 'N3', 'Ghép vào sau động từ để diễn tả hành động được thực hiện bởi hai hoặc nhiều người/nhóm, hướng về phía nhau hoặc cùng nhau.', 'V-ます (bỏ  ます) +  合う', '[{"ja":"困った時は、助け合いましょう。","romaji":"→ (Khi gặp khó khăn, chúng ta hãy cùng giúp đỡ lẫn nhau.)","vi":""},{"ja":"もっとよく話し合ってから決めたほうがいい。","romaji":"→ (Nên thảo luận cùng nhau kỹ hơn rồi hãy quyết định.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('5.  ばいい  - Nên ~; có thể ~; sẽ tốt nếu ~', 'N3', 'Đưa ra lời khuyên nhẹ nhàng; thể hiện mong muốn; hỏi lời khuyên.', 'V-ば +  いい   Adj-い →  ければ +  いい   Adj-な / N +  なら(ば) +  いい', '[{"ja":"分からなかったら、先生に聞けばいい。","romaji":"→ (Nếu không hiểu thì nên hỏi giáo viên.)","vi":""},{"ja":"どうすればいいか分かりません。","romaji":"→ (Tôi không biết nên làm thế nào.)","vi":"──────────"},{"ja":"～ほうがいい (N4): Lời khuyên mạnh hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('6.  ばよかった  - Lẽ ra nên ~; sẽ tốt hơn nếu ~', 'N3', 'Diễn tả sự hối tiếc về một việc đã làm hoặc đã không làm trong quá khứ.', 'V-ば +  よかった   V-ない →  なければ +  よかった', '[{"ja":"もっと勉強すればよかった。","romaji":"→ (Lẽ ra tôi nên học hành chăm chỉ hơn.)","vi":""},{"ja":"あんなことを言わなければよかった。","romaji":"→ (Lẽ ra tôi không nên nói những lời như vậy.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('7.  ば～ほど  - Càng... càng ~', 'N3', 'Diễn tả mối quan hệ tỷ lệ thuận: khi mức độ vế trước tăng thì vế sau cũng tăng.', 'V-ば + V-る +  ほど   Adj-い →  ければ + Adj-い +  ほど   Adj-な →  なら + Adj-な +  な +  ほど', '[{"ja":"日本語は勉強すれば勉強するほど面白くなる。","romaji":"→ (Tiếng Nhật càng học thì càng thấy thú vị.)","vi":""},{"ja":"荷物は少なければ少ないほどいい。","romaji":"→ (Hành lý càng ít thì càng tốt.)","vi":"──────────"},{"ja":"～にしたがって (N3): Cũng diễn tả sự thay đổi song song, thường dùng với thay đổi tự nhiên.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('8.  ば～のに  - Lẽ ra ~; nên ~; giá mà ~', 'N3', 'Diễn tả sự tiếc nuối, thất vọng về một kết quả không như mong đợi, dù điều kiện đã có thể dẫn đến kết quả tốt hơn.', 'V-ば +  ～のに   Adj-い →  ければ +  ～のに   Adj-な →  なら +  ～のに', '[{"ja":"もっと早く起きれば、電車に間に合ったのに。","romaji":"→ (Giá mà dậy sớm hơn thì đã kịp chuyến tàu rồi.)","vi":""},{"ja":"お金があれば、そのカメラを買ったのに。","romaji":"→ (Nếu có tiền thì tôi đã mua cái máy ảnh đó rồi.)","vi":"──────────"},{"ja":"～たら～のに (N4): Gần như tương đương.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('9.  ばかりで  - Chỉ; toàn là ~ (mô tả tiêu cực)', 'N3', 'Diễn tả sự tồn tại của một thứ gì đó với số lượng lớn, chiếm đa số, thường mang hàm ý tiêu cực, phàn nàn.', 'N +  ばかりで', '[{"ja":"このクラスは男子ばかりで、女子は３人しかいない。","romaji":"→ (Lớp này toàn là con trai, con gái chỉ có 3 người.)","vi":""},{"ja":"会議では文句ばかりで、建設的な意見は出なかった。","romaji":"→ (Trong cuộc họp toàn là phàn nàn, chẳng có ý kiến xây dựng nào được đưa ra.)","vi":"──────────"},{"ja":"だけ (N5): Chỉ (trung tính).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('10.  ばかりでなく  - Không chỉ... mà còn; cũng như ~', 'N3', 'Dùng để liệt kê, nhấn mạnh rằng không chỉ có A mà còn có cả B.', 'N / V-thể thường / Adj-い / Adj-な +  ばかりでなく、～も', '[{"ja":"彼は日本語ばかりでなく、英語も話せる。","romaji":"→ (Anh ấy không chỉ nói được tiếng Nhật mà còn cả tiếng Anh nữa.)","vi":""},{"ja":"このレストランは料理がおいしいばかりでなく、雰囲気もいい。","romaji":"→ (Nhà hàng này không chỉ đồ ăn ngon mà không khí cũng rất tuyệt.)","vi":"──────────"},{"ja":"～上に (N3): Hơn nữa, thêm vào đó.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('11.  べきだ  - Nên làm; phải làm ~', 'N3', 'Diễn tả một hành động/trạng thái được coi là đúng đắn, hợp lý, là nghĩa vụ nên làm theo lẽ thường hoặc đạo đức. Mạnh hơn  ～ほうがいい.', 'V-る +  べきだ /  べきです   Adj-な →  である +  べきだ   Adj-い →  くある +  べきだ (Ít dùng)   Lưu ý:  する →  すべきだ', '[{"ja":"学生はもっと勉強すべきだ。","romaji":"→ (Học sinh nên học hành chăm chỉ hơn.)","vi":""},{"ja":"約束は守るべきだ。","romaji":"→ (Lời hứa thì nên giữ.)","vi":"──────────"},{"ja":"～なければならない (N4): Phải làm (nghĩa vụ, sự cần thiết).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('12.  べきではない  - Không nên làm; không được làm ~', 'N3', 'Diễn tả một hành động được coi là sai trái, không hợp lý, không nên làm theo lẽ thường hoặc đạo đức.', 'V-る +  べきではない /  べきじゃありません', '[{"ja":"人の悪口を言うべきではない。","romaji":"→ (Không nên nói xấu người khác.)","vi":""},{"ja":"簡単に諦めるべきではない。","romaji":"→ (Không nên dễ dàng bỏ cuộc.)","vi":"──────────"},{"ja":"～てはいけない (N5): Không được làm (cấm đoán).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('13.  別に～ない  (べつに～ない) - Không hẳn là, không đặc biệt ~', 'N3', 'Dùng để phủ định nhẹ nhàng, hàm ý không có gì đặc biệt, không quan trọng. Thường dùng trong văn nói.', '別に + V-ない / Adj-くない / Adj-じゃない / N +  ではない', '[{"ja":"A:  何か怒ってる？ (Cậu đang giận à?)","romaji":"B:  ううん、別に怒ってないよ。 (Ừm, không, tớ có giận gì đâu.)","vi":""},{"ja":"別に難しい問題ではありません。","romaji":"→ (Đó không phải là vấn đề gì đặc biệt khó cả.)","vi":"──────────"},{"ja":"あまり～ない (N5): Không... lắm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('14.  ぶりに  - Lần đầu tiên sau (khoảng thời gian)', 'N3', 'Diễn tả một hành động/sự kiện xảy ra lần đầu tiên sau một khoảng thời gian dài.', 'Khoảng thời gian +  ぶりに /  ぶりだ', '[{"ja":"10 年ぶりに高校時代の友達に会った。","romaji":"→ (Sau 10 năm tôi mới gặp lại bạn thời cấp ba.)","vi":""},{"ja":"久しぶりに映画を見に行った。","romaji":"→ (Đã lâu rồi tôi mới đi xem phim.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('15.  中  (ちゅう  /  じゅう) - Đang; trong lúc; trong suốt ~', 'N3', '～中  (ちゅう): Đang trong quá trình (会議中).   ～中  (じゅう): Trong suốt / Khắp (一日中).   ～中  (ちゅう): Trong vòng / Trước khi kết thúc (午前中).', 'N +  中 (ちゅう /  じゅう)', '[{"ja":"ただ今、話し中です。","romaji":"→ (Bây giờ máy đang bận.)","vi":""},{"ja":"昨日、一日中寝ていました。","romaji":"→ (Hôm qua tôi đã ngủ suốt cả ngày.)","vi":""},{"ja":"今日中にレポートを出してください。","romaji":"→ (Hãy nộp báo cáo trong ngày hôm nay.)","vi":"──────────"},{"ja":"～うちに (N3): Trong khi... (nhấn mạnh sự thay đổi hoặc cần làm trước khi thay đổi).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('16.  だけ  - Đến mức ~ / Chừng nào mà ~', 'N3', 'Diễn tả giới hạn, phạm vi hoặc mức độ tối đa của một hành động/trạng thái.', 'V-る / V-たい / Adj-い / Adj-な +  だけ', '[{"ja":"食べたいだけ食べてください。","romaji":"→ (Hãy ăn bao nhiêu tùy thích.)","vi":""},{"ja":"できるだけ早く来てください。","romaji":"→ (Hãy đến sớm nhất có thể.)","vi":"──────────"},{"ja":"～くらい /  ぐらい (N4): Khoảng, đến mức.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('17.  だけでなく  - Không chỉ… mà còn ~', 'N3', 'Dùng để liệt kê, nhấn mạnh không chỉ có A mà còn có cả B.', 'N / V-thể thường / Adj-い / Adj-な +  だけでなく、～も', '[{"ja":"この映画は面白いだけでなく、感動的でもある。","romaji":"→ (Bộ phim này không chỉ thú vị mà còn cảm động nữa.)","vi":""},{"ja":"彼はサッカーが上手なだけでなく、勉強もよくできる。","romaji":"→ (Cậu ấy không chỉ chơi đá bóng giỏi mà học cũng rất tốt.)","vi":"──────────"},{"ja":"～上に (N3): Hơn nữa, thêm vào đó.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('18.  だけど  - Nhưng; tuy nhiên; mặc dù ~', 'N3', 'Liên từ nối dùng trong văn nói, nối hai vế câu tương phản.', 'Câu 1 +  だけど + Câu 2', '[{"ja":"今日は天気がいいね。だけど、少し暑いね。","romaji":"→ (Hôm nay thời tiết đẹp nhỉ. Nhưng mà hơi nóng nhỉ.)","vi":""},{"ja":"行きたいだけど、時間がないんだ。","romaji":"→ (Tôi muốn đi nhưng không có thời gian.)","vi":"──────────"},{"ja":"しかし (N4): Tuy nhiên (trang trọng hơn).","romaji":"","vi":""},{"ja":"けど /  けれども (N4): Nhưng (phổ biến).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('19.  だらけ  - Đầy; phủ đầy; rất nhiều (thứ không mong muốn)', 'N3', 'Diễn tả rằng một thứ gì đó bị bao phủ/chứa đầy những thứ không mong muốn, gây cảm giác khó chịu, tiêu cực.', 'N +  だらけ', '[{"ja":"靴が泥だらけになった。","romaji":"→ (Giày dính đầy bùn.)","vi":""},{"ja":"この作文は間違いだらけだ。","romaji":"→ (Bài văn này đầy lỗi sai.)","vi":"──────────"},{"ja":"～いっぱい (N5): Đầy (thường trung tính hoặc tích cực).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('20.  どんなに～ても  - Dù ~ đến đâu (thế nào)', 'N3', 'Diễn tả rằng dù điều kiện có xảy ra ở mức độ cao/cực đoan, kết quả vẫn không thay đổi.', 'どんなに + V-ても / Adj-くても / Adj-な/N +  でも', '[{"ja":"どんなに反対されても、私は留学します。","romaji":"→ (Dù bị phản đối thế nào đi nữa, tôi vẫn sẽ đi du học.)","vi":""},{"ja":"どんなに高くても、このバッグが欲しい。","romaji":"→ (Dù đắt đến mấy, tôi vẫn muốn cái túi này.)","vi":"──────────"},{"ja":"たとえ～ても (N3): Ngay cả khi... (mang tính giả định mạnh hơn).","romaji":"","vi":""},{"ja":"～ても /  ～でも (N4): Dù... thì cũng (cơ bản nhất).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('21.  どうしても  - Dù thế nào cũng; bằng mọi giá; rốt cuộc ~', 'N3', 'Diễn tả ý chí mạnh mẽ, quyết tâm "bằng mọi giá".   Diễn tả tình huống không thể tránh khỏi hoặc không thể làm được "dù thế nào cũng không...".', 'どうしても + V / V-たい / V-ない', '[{"ja":"どうしてもこの大学に入りたい。","romaji":"→ (Tôi muốn vào trường đại học này bằng mọi giá.)","vi":""},{"ja":"どうしても思い出せない。","romaji":"→ (Dù cố thế nào tôi cũng không thể nhớ ra được.)","vi":"──────────"},{"ja":"絶対に (N4): Tuyệt đối.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('22.  ふりをする  - Giả vờ; hành động như thể ~', 'N3', 'Diễn tả hành động giả vờ, tỏ ra như thể mình đang ở trong một trạng thái/làm gì đó, trong khi thực tế không phải vậy.', 'V-thể thường / Adj-い / Adj-な +  な / N +  の +  ふりをする', '[{"ja":"彼は知らないふりをした。","romaji":"→ (Anh ta giả vờ không biết.)","vi":""},{"ja":"寝たふりをしないでください。","romaji":"→ (Đừng giả vờ ngủ nữa.)","vi":"──────────"},{"ja":"～よう (N4/N3): Dường như là.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('23.  ふと  - Đột nhiên; tình cờ; bất ngờ; vô tình ~', 'N3', 'Trạng từ, diễn tả hành động/suy nghĩ nảy sinh đột ngột, không chủ ý.', 'ふと + V', '[{"ja":"道を歩いていて、ふと昔のことを思い出した。","romaji":"→ (Đang đi trên đường, tôi chợt nhớ về chuyện ngày xưa.)","vi":""},{"ja":"ふと窓の外を見ると、雪が降っていた。","romaji":"→ (Bất chợt nhìn ra ngoài cửa sổ, tôi thấy tuyết đang rơi.)","vi":"──────────"},{"ja":"突然 (N4): Đột nhiên, bất thình lình.","romaji":"","vi":""},{"ja":"いきなり (N3): Đột ngột, ngay lập tức.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('24.  がち  - Có xu hướng; thường; hay; dễ làm gì đó', 'N3', 'Diễn tả khuynh hướng, thói quen thường xảy ra, hoặc trạng thái dễ rơi vào, thường mang sắc thái tiêu cực.', 'V-ます (bỏ  ます) / N +  がち', '[{"ja":"彼は子供の時から病気がちだった。","romaji":"→ (Anh ấy từ nhỏ đã hay ốm.)","vi":""},{"ja":"雨の日は、電車が遅れがちだ。","romaji":"→ (Vào những ngày mưa, tàu điện thường hay bị trễ.)","vi":"──────────"},{"ja":"～気味 (N3): Có vẻ hơi... (chỉ mức độ nhẹ).","romaji":"","vi":""},{"ja":"～っぽい (N3): Trông có vẻ..., ra vẻ...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('25.  がたい  - Rất khó để ~; khó ~', 'N3', 'Diễn tả hành động khó thực hiện, thường do yếu tố tâm lý, cảm xúc.', 'V-ます (bỏ  ます) +  がたい', '[{"ja":"それは信じがたい話だ。","romaji":"→ (Đó là một câu chuyện khó tin.)","vi":""},{"ja":"彼がしたことは、許しがたい。","romaji":"→ (Việc anh ta đã làm thật khó tha thứ.)","vi":"──────────"},{"ja":"～づらい (N3): Khó... (thường chỉ khó khăn về tâm lý/phiền phức).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('26.  気味  (ぎみ) - Có vẻ ~; trông như ~; có xu hướng ~', 'N3', 'Diễn tả cảm giác có một chút dấu hiệu, khuynh hướng của một trạng thái nào đó, thường là tiêu cực.', 'V-ます (bỏ  ます) / N +  気味', '[{"ja":"最近、ちょっと疲れ気味だ。","romaji":"→ (Gần đây, tôi cảm thấy hơi mệt.)","vi":""},{"ja":"彼は少し緊張気味に見えた。","romaji":"→ (Anh ấy trông có vẻ hơi căng thẳng.)","vi":"──────────"},{"ja":"～っぽい (N3): Giống như là..., có vẻ...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('27.  ごとに  - Mỗi; mọi; cách khoảng ~', 'N3', 'Diễn tả sự lặp lại đều đặn theo từng khoảng hoặc từng đối tượng.', 'N (khoảng thời gian/số lượng/danh từ) +  ごとに', '[{"ja":"このバスは 10 分ごとに来ます。","romaji":"→ (Xe buýt này cứ 10 phút lại đến một chuyến.)","vi":""},{"ja":"オリンピックは４年ごとに開かれます。","romaji":"→ (Thế vận hội Olympic được tổ chức 4 năm một lần.)","vi":"──────────"},{"ja":"～ずつ (N4): Từng... (nhấn mạnh sự phân chia).","romaji":"","vi":""},{"ja":"毎～ (N5): Mỗi... (毎朝 - mỗi sáng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('28.  ほど  - Mức độ; phạm vi; giới hạn; khoảng ~', 'N3', 'Chỉ mức độ của hành động/trạng thái (thường là cao), hoặc dùng để so sánh.', 'N / V-る / V-ない / Adj-い / Adj-な +  ほど', '[{"ja":"死ぬほど疲れた。","romaji":"→ (Tôi mệt đến chết đi được.)","vi":""},{"ja":"彼ほど親切な人はいない。","romaji":"→ (Không có ai tốt bụng như anh ấy.)","vi":"──────────"},{"ja":"～だけ (N5/N3): Chỉ / Đến mức.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('29.  ほど～ない  - Không... bằng ~', 'N3', 'Dùng trong câu so sánh phủ định, nói rằng N1 không đạt đến mức độ của N2.', 'N1  は N2 +  ほど + Adj / V +  ない', '[{"ja":"今年の夏は去年ほど暑くない。","romaji":"→ (Mùa hè năm nay không nóng bằng năm ngoái.)","vi":""},{"ja":"私は彼ほど日本語が上手ではない。","romaji":"→ (Tiếng Nhật của tôi không giỏi bằng anh ấy.)","vi":"──────────"},{"ja":"～に比べて (N3): So với... (chỉ sự so sánh).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('30.  一度に  (いちどに) - Cùng một lúc', 'N3', 'Trạng từ, diễn tả nhiều thứ xảy ra/được làm cùng lúc, hoặc số lượng lớn trong một lần.', '一度に + V', '[{"ja":"一度にたくさんのことを言われても、覚えられない。","romaji":"→ (Dù có bị nói nhiều thứ cùng một lúc thì tôi cũng không thể nhớ được.)","vi":""},{"ja":"荷物を一度に運びましょう。","romaji":"→ (Hãy cùng vận chuyển hành lý một lần luôn.)","vi":"──────────"},{"ja":"一緒に (N5): Cùng nhau (nhấn mạnh sự hợp tác).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('31.  いくら～ても  - Dù ~ bao nhiêu đi nữa', 'N3', 'Dùng để nhấn mạnh rằng dù cho mức độ (thường là số lượng, giá cả, mức độ nỗ lực) có lớn đến đâu đi chăng nữa, thì kết quả ở vế sau vẫn không thay đổi.', 'いくら + V-ても / Adj-くても / Adj-な/N +  でも', '[{"ja":"いくら高くても、私はそれを買います。","romaji":"→ (Dù đắt bao nhiêu đi nữa, tôi cũng sẽ mua nó.)","vi":""},{"ja":"いくら説明しても、彼は分かってくれない。","romaji":"→ (Dù tôi giải thích bao nhiêu, anh ấy cũng không hiểu cho.)","vi":"──────────"},{"ja":"たとえ～ても (N3): Ngay cả khi... (mang tính giả định mạnh hơn).","romaji":"","vi":""},{"ja":"～ても /  ～でも (N4): Dù... thì cũng (cơ bản).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('32.  一方だ  (いっぽうだ) - Ngày càng; tiếp tục ~', 'N3', 'Diễn tả một sự thay đổi đang diễn ra liên tục theo một chiều hướng nhất định (tăng hoặc giảm). Thường dùng cho những thay đổi không mong muốn hoặc không thể kiểm soát.', 'V-る +  一方だ', '[{"ja":"最近、物価は上がる一方だ。","romaji":"→ (Gần đây, giá cả ngày càng tăng.)","vi":""},{"ja":"祖母の病気は悪くなる一方だ。","romaji":"→ (Bệnh tình của bà tôi ngày càng xấu đi.)","vi":"──────────"},{"ja":"～ていく (N4): Diễn tả sự thay đổi hướng về tương lai.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('33.  一体  (いったい) - Nhấn mạnh; rốt cuộc là; quái gì ~', 'N3', 'Dùng trong câu hỏi để nhấn mạnh sự ngạc nhiên, nghi ngờ, thắc mắc mạnh mẽ hoặc sự khó hiểu của người nói.', '一体 + Từ để hỏi (何,  誰,  どこ,  どうして...) +  ～か /  ～だろう /  ～んだ', '[{"ja":"一体何があったんですか。","romaji":"→ (Rốt cuộc là đã có chuyện gì xảy ra vậy?)","vi":""},{"ja":"一体彼は誰なんだ。","romaji":"→ (Không hiểu anh ta là ai nữa?)","vi":""},{"ja":"一体どうしてこんなことになったのだろう。","romaji":"→ (Rốt cuộc tại sao lại ra nông nỗi này?)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('34.  じゃない  /  じゃないか  - Có lẽ; rất có thể; xác nhận thông tin; bày tỏ sự ngạc nhiên', 'N3', 'Xác nhận điều gì đó mà mình nghĩ người nghe cũng biết ("Chẳng phải là... sao?").   Bày tỏ sự ngạc nhiên hoặc phát hiện ra điều gì đó ("Ồ, ... kìa!").   Đưa ra lời đề nghị, rủ rê ("Chúng ta hãy... đi!").   Thể hiện sự phán đoán, có lẽ ("Hình như là...").', 'V/Adj/N-thể thường +  じゃない /  じゃないか', '[{"ja":"あ、雨が降ってるじゃないか。","romaji":"→ (A, trời đang mưa kìa!)","vi":""},{"ja":"これ、おいしいじゃない。","romaji":"→ (Cái này ngon đấy chứ!)","vi":""},{"ja":"そろそろ行こうじゃないか。","romaji":"→ (Chúng ta đi thôi nào!)","vi":"──────────"},{"ja":"～かもしれない (N4): Có lẽ là, có thể là.","romaji":"","vi":""},{"ja":"～ね (N5): ... nhỉ? (xác nhận nhẹ nhàng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('35.  か何か  (かなにか) - Hay gì đó ~', 'N3', 'Dùng khi muốn đưa ra một ví dụ nhưng không chắc chắn hoặc không muốn nói cụ thể, mang ý "hoặc một thứ gì đó tương tự".', 'N +  か何か', '[{"ja":"喉が渇いたから、ジュースか何か飲みたい。","romaji":"→ (Vì khát nước nên tôi muốn uống nước trái cây hay gì đó.)","vi":""},{"ja":"机の上に、本か何かが置いてある。","romaji":"→ (Trên bàn có đặt sách hay thứ gì đó.)","vi":"──────────"},{"ja":"～など (N4): ... vân vân..., như là... (liệt kê ví dụ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('36.  かける  - Dở; chưa xong; đang làm ~', 'N3', 'Diễn tả một hành động đã được bắt đầu nhưng chưa kết thúc, đang còn dang dở.', 'V-ます (bỏ  ます) +  かける /  かけの + N', '[{"ja":"この本はまだ読みかけだ。","romaji":"→ (Quyển sách này tôi vẫn đang đọc dở.)","vi":""},{"ja":"彼女は何か言いかけたが、やめた。","romaji":"→ (Cô ấy định nói gì đó nhưng lại thôi.)","vi":""},{"ja":"テーブルの上に食べかけのパンがある。","romaji":"→ (Trên bàn có mẩu bánh mì đang ăn dở.)","vi":"──────────"},{"ja":"～途中だ (N3): Đang giữa chừng...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('37.  から〜にかけて  - Suốt; từ [A] đến [B] (khoảng)', 'N3', 'Chỉ một khoảng không gian hoặc thời gian giữa hai điểm A và B, nhưng không xác định chính xác điểm bắt đầu và kết thúc như  から～まで.', 'N1 (Thời gian/Địa điểm) +  から + N2 (Thời gian/Địa điểm) +  にかけて', '[{"ja":"今夜から明日の朝にかけて、雨が降るでしょう。","romaji":"→ (Từ đêm nay đến sáng mai, có lẽ trời sẽ mưa.)","vi":""},{"ja":"関東地方から東北地方にかけて、大きな地震があった。","romaji":"→ (Đã có một trận động đất lớn xảy ra ở khu vực từ Kanto đến Tohoku.)","vi":"──────────"},{"ja":"～ごろ (N5): Khoảng (dùng cho mốc thời gian).","romaji":"","vi":""},{"ja":"～あいだ (N4): Trong khoảng (chỉ một khoảng thời gian liên tục).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('38.  代わりに  (かわりに) - Thay vì; thay thế cho; đổi lại; để đáp lại', 'N3', 'Diễn tả sự thay thế: làm B thay cho A, dùng B thay cho A.   Diễn tả sự bù đắp, đổi lại: có mặt lợi này thì cũng có mặt hại kia, hoặc làm gì đó để đổi lại.', 'N +  の +  代わりに   V-る / V-た +  代わりに', '[{"ja":"父の代わりに、私が会議に出席しました。","romaji":"→ (Tôi đã đi họp thay cho bố.)","vi":""},{"ja":"映画を見に行く代わりに、家で DVD を見よう。","romaji":"→ (Thay vì đi xem phim, hãy xem DVD ở nhà đi.)","vi":""},{"ja":"この部屋は狭い代わりに、家賃が安い。","romaji":"→ (Căn phòng này nhỏ, bù lại thì tiền thuê nhà rẻ.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('39.  結果  (けっか) - Kết quả là; sau khi ~', 'N3', 'Diễn tả kết quả phát sinh từ một hành động, sự kiện hoặc quá trình đã xảy ra trước đó.', 'V-た / N +  の +  結果', '[{"ja":"色々考えた結果、留学することに決めた。","romaji":"→ (Sau khi suy nghĩ rất nhiều, kết quả là tôi đã quyết định đi du học.)","vi":""},{"ja":"検査の結果、異常はありませんでした。","romaji":"→ (Kết quả kiểm tra là không có gì bất thường.)","vi":"──────────"},{"ja":"～ため (N4): Vì... nên... (chỉ nguyên nhân).","romaji":"","vi":""},{"ja":"～おかげで /  ～せいで (N3): Nhờ... / Tại... (chỉ nguyên nhân với sắc thái tích cực/tiêu cực).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('40.  結局  (けっきょく) - Rốt cuộc; cuối cùng; sau cùng ~', 'N3', 'Là một trạng từ, dùng để nêu lên kết luận cuối cùng sau một quá trình (suy nghĩ, thảo luận, diễn biến sự việc...), thường là một kết quả không có gì thay đổi hoặc không như mong đợi ban đầu.', '結局、+ Câu.', '[{"ja":"色々迷ったが、結局何も買わなかった。","romaji":"→ (Đã phân vân rất nhiều, nhưng rốt cuộc tôi chẳng mua gì cả.)","vi":""},{"ja":"彼らは長い間話し合ったが、結局意見が合わなかった。","romaji":"→ (Họ đã thảo luận rất lâu, nhưng cuối cùng ý kiến vẫn không thống nhất.)","vi":"──────────"},{"ja":"ついに (N3): Cuối cùng thì (chỉ một kết quả quan trọng, sau thời gian dài).","romaji":"","vi":""},{"ja":"最後は (N4): Cuối cùng thì (chỉ thứ tự).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('41.  決して～ない  (けっして～ない) - Không bao giờ; tuyệt đối không ~', 'N3', 'Dùng để phủ định một cách mạnh mẽ, diễn tả ý chí hoặc sự cam kết rằng sẽ không bao giờ làm điều gì đó hoặc điều gì đó tuyệt đối không phải là sự thật.', '決して + V-ない / Adj-くない / Adj-じゃない / N +  ではない', '[{"ja":"私は決してあなたを忘れません。","romaji":"→ (Tôi sẽ không bao giờ quên bạn.)","vi":""},{"ja":"彼の言うことは決して信じてはいけない。","romaji":"→ (Tuyệt đối không được tin những lời anh ta nói.)","vi":""},{"ja":"それは決して簡単なことではない。","romaji":"→ (Đó tuyệt đối không phải là việc đơn giản.)","vi":"──────────"},{"ja":"全然～ない (N5): Hoàn toàn không.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('42.  切れない  (きれない) - Không thể làm; quá nhiều để hoàn thành', 'N3', 'Diễn tả rằng một hành động không thể được hoàn thành trọn vẹn, thường là do số lượng quá lớn hoặc quá khó khăn để làm hết.', 'V-ます (bỏ  ます) +  切れない (きれない)', '[{"ja":"ご飯が多くて、一人では食べ切れない。","romaji":"→ (Cơm nhiều quá, một mình tôi không thể ăn hết được.)","vi":""},{"ja":"こんなにたくさんの仕事は、一日ではやり切れない。","romaji":"→ (Nhiều công việc thế này thì một ngày không thể làm hết được.)","vi":"──────────"},{"ja":"～終わらない (N4): Không kết thúc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('43.  きり  /  っきり  - Chỉ; kể từ khi; sau khi ~', 'N3', 'Nghĩa 1 (Chỉ): Giống với  だけ, nhưng thường nhấn mạnh số lượng ít ỏi. (Vd: 二人きり - chỉ có hai người).   Nghĩa 2 (Kể từ khi): Diễn tả một hành động xảy ra và sau đó trạng thái đó cứ kéo dài, không có sự thay đổi hoặc hành động tiếp theo như mong đợi.', 'N +  きり /  っきり (Chỉ)   V-た +  きり /  っきり (Kể từ khi)', '[{"ja":"彼とは一度会ったきり、それから連絡がない。","romaji":"→ (Tôi chỉ gặp anh ta một lần, kể từ đó không có liên lạc gì.)","vi":""},{"ja":"息子は部屋に入ったきり、出てこない。","romaji":"→ (Con trai tôi vào phòng rồi cứ ở trong đó, không ra ngoài.)","vi":""},{"ja":"今朝コーヒーを一杯飲んだきり、何も食べていない。","romaji":"→ (Sáng nay chỉ uống một cốc cà phê, từ đó chưa ăn gì cả.)","vi":"──────────"},{"ja":"しか～ない (N4): Chỉ (nghĩa 1, luôn đi với phủ định).","romaji":"","vi":""},{"ja":"～てから (N5): Sau khi (nghĩa 2, không có hàm ý \"không thay đổi\").","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('44.  切る  (きる) - Làm gì đó hoàn toàn đến cuối cùng', 'N3', 'Diễn tả việc hoàn thành một hành động một cách trọn vẹn, hoàn toàn, không còn sót lại; hoặc làm gì đó một cách dứt khoát.', 'V-ます (bỏ  ます) +  切る (きる)', '[{"ja":"長い小説を３日間で読み切った。","romaji":"→ (Tôi đã đọc hết cuốn tiểu thuyết dài trong 3 ngày.)","vi":""},{"ja":"彼は決心して、彼女との関係を断ち切った。","romaji":"→ (Anh ấy đã quyết tâm và cắt đứt quan hệ với cô ấy.)","vi":""},{"ja":"もう疲れ切った。","romaji":"→ (Tôi đã hoàn toàn kiệt sức rồi.)","vi":"──────────"},{"ja":"～終わる (N4): Làm xong.","romaji":"","vi":""},{"ja":"～上げる (N3): Làm xong (nhấn mạnh sự hoàn chỉnh).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('45.  っけ  - (Xác nhận điều đang cố nhớ)', 'N3', 'Là một hậu tố dùng trong văn nói thân mật, khi người nói đang cố gắng nhớ lại một thông tin nào đó và muốn tự xác nhận hoặc hỏi người nghe để xác nhận.', 'V-た / Adj-かった / N/Adj-な +  だった +  っけ', '[{"ja":"明日の会議は何時からだっけ？(Cuộc họp ngày mai bắt đầu từ mấy giờ nhỉ?)","romaji":"","vi":""},{"ja":"あの人の名前、何て言ったっけ。","romaji":"→ (Tên người kia là gì nhỉ?)","vi":""},{"ja":"子供のころ、よくここで遊んだっけ。","romaji":"→ (Hồi nhỏ, hình như mình hay chơi ở đây thì phải.)","vi":"──────────"},{"ja":"～でしょう (N4): Phải không? / Chắc là... (phỏng đoán, xác nhận).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('46.  込む  (こむ) - Làm gì đó sâu / Đi vào trong', 'N3', 'Nghĩa 1: Diễn tả hành động đi vào bên trong một không gian nào đó (飛び込 む - nhảy vào,  駆け込む - chạy vào).   Nghĩa 2: Diễn tả hành động được thực hiện một cách kỹ lưỡng, sâu sắc, hoặc trong một thời gian dài (考え込む - suy nghĩ đăm chiêu,  話し込む - mải nói chuyện).', 'V-ます (bỏ  ます) +  込む', '[{"ja":"子供たちが川に飛び込んだ。","romaji":"→ (Lũ trẻ nhảy ùm xuống sông.)","vi":""},{"ja":"電車に駆け込んだ。","romaji":"→ (Tôi chạy vội vào tàu điện.)","vi":""},{"ja":"彼は深く考え込んでいるようだ。","romaji":"→ (Anh ấy có vẻ đang chìm sâu trong suy nghĩ.)","vi":"──────────"},{"ja":"中に入る (N5): Đi vào trong (nghĩa 1).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('47.  こそ  - Chính; chính vì ~', 'N3', 'Dùng để nhấn mạnh danh từ hoặc cụm từ đứng trước nó, hàm ý "chính là cái này/người này/lúc này... chứ không phải cái khác".', 'N / Cụm từ +  こそ', '[{"ja":"あなたこそ、私が探していた人です。","romaji":"→ (Chính bạn là người mà tôi đang tìm kiếm.)","vi":""},{"ja":"今年こそ、日本語能力試験 N1 に合格したい。","romaji":"→ (Chính năm nay tôi muốn đỗ N1.)","vi":""},{"ja":"愛情があるからこそ、厳しく叱るのです。","romaji":"→ (Chính vì có tình yêu thương nên mới la mắng nghiêm khắc.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('48.  こと  - (Phải) làm / (Không được) làm', 'N3', 'Dùng để đưa ra mệnh lệnh, quy tắc, hướng dẫn hoặc lời khuyên mạnh mẽ, thường xuất hiện trong các văn bản quy định, nội quy, hoặc lời dặn dò.', 'V-る / V-ない +  こと', '[{"ja":"図書館では静かにすること。","romaji":"→ (Ở thư viện phải giữ yên lặng.)","vi":""},{"ja":"廊下を走らないこと。","romaji":"→ (Không được chạy trên hành lang.)","vi":""},{"ja":"明日８時までに来ること。","romaji":"→ (Ngày mai phải đến trước 8 giờ.)","vi":"──────────"},{"ja":"～てください (N5): Xin hãy... (yêu cầu lịch sự).","romaji":"","vi":""},{"ja":"～なければならない (N4): Phải làm... (nghĩa vụ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('49.  ことから  - Từ sự thật là ~; Vì ~', 'N3', 'Dùng để giải thích nguồn gốc, lý do hoặc căn cứ của một sự việc, tên gọi, hoặc phán đoán, dựa trên một sự thật hoặc một sự kiện nào đó.', 'V/Adj/N-thể thường +  ことから', '[{"ja":"富士山が見えることから、この町は富士見町と名付けられた。","romaji":"→ (Vì có thể nhìn thấy núi Phú Sĩ nên thị trấn này được đặt tên là Fujimichou.)","vi":""},{"ja":"彼がいつも遅刻することから、信用できないと思われている。","romaji":"→ (Từ việc anh ta luôn đi trễ, anh ta bị cho là không đáng tin.)","vi":"──────────"},{"ja":"～から (N5): Bởi vì (chỉ nguyên nhân chủ quan/khách quan).","romaji":"","vi":""},{"ja":"～ため (N4): Bởi vì (chỉ nguyên nhân, hơi trang trọng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('50.  ことになっている  - Được quy định là; dự kiến là ~', 'N3', 'Diễn tả một quy tắc, quy định, lịch trình, kế hoạch hoặc một sự việc đã được quyết định (thường là bởi người khác hoặc một tổ chức) và mọi người được mong đợi sẽ tuân theo.', 'V-る / V-ない +  ことになっている', '[{"ja":"この寮では、１２時までに帰らなければならないことになっている。 (Ở ký túc xá này, có quy định là phải về trước 12 giờ.)","romaji":"","vi":""},{"ja":"明日、ここで会議が行われることになっている。","romaji":"→ (Theo kế hoạch, ngày mai sẽ có một cuộc họp được tổ chức ở đây.)","vi":""},{"ja":"法律で、２０歳未満はお酒を飲んではいけないことになっている。 (Theo luật, người dưới 20 tuổi không được uống rượu.)","romaji":"──────────","vi":"Ngữ pháp tương tự:"},{"ja":"～予定だ (N4): Dự định là... (chỉ kế hoạch).","romaji":"","vi":""},{"ja":"～決まり (N3/N2): Quy định, quyết định.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('51.  ことはない  - Không cần phải ~; không có khả năng ~', 'N3', 'Nghĩa 1: Diễn tả rằng không có sự cần thiết phải làm một việc gì đó. (Tương đương  ～なくてもいい nhưng mạnh hơn).   Nghĩa 2: Diễn tả rằng không có khả năng, không thể xảy ra một việc gì đó.', 'V-る +  ことはない', '[{"ja":"心配することはない。きっとうまくいくよ。","romaji":"→ (Không cần phải lo lắng đâu. Chắc chắn sẽ ổn cả thôi.)","vi":""},{"ja":"ただの風邪だから、そんなに心配することはない。","romaji":"→ (Chỉ là cảm cúm thông thường thôi, không cần phải lo lắng đến thế.)","vi":""},{"ja":"彼が約束を破ることはないと思う。","romaji":"→ (Tôi nghĩ không có khả năng anh ấy thất hứa đâu.)","vi":"──────────"},{"ja":"～はずがない (N3): Chắc chắn không... (nghĩa 2).","romaji":"","vi":""},{"ja":"～わけがない (N3): Lẽ nào lại... (nghĩa 2).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('52.  ことは～が  - Mặc dù; nhưng ~', 'N3', 'Dùng để thừa nhận một sự thật nào đó (thường lặp lại động từ/tính từ) nhưng ngay sau đó đưa ra một ý kiến, sự thật trái ngược hoặc một vấn đề khác liên quan.', 'V/Adj-thể thường +  ことは + (V/Adj-thể thường) +  が /  けど', '[{"ja":"このギターは、高いことは高いが、とてもいい音がする。","romaji":"→ (Cây đàn ghi- ta này đắt thì đắt thật, nhưng âm thanh rất hay.)","vi":""},{"ja":"日本語が話せることは話せるが、まだ自信がない。","romaji":"→ (Nói tiếng Nhật thì tôi nói được đấy, nhưng vẫn chưa tự tin lắm.)","vi":"──────────"},{"ja":"～が (N5): Nhưng...","romaji":"","vi":""},{"ja":"～ものの (N2): Mặc dù... (N2, trang trọng hơn).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('53.  くらい  /  ぐらい  - Khoảng; xấp xỉ; đến mức ~', 'N3', 'Nghĩa 1: Biểu thị sự ước lượng, xấp xỉ về số lượng, thời gian, mức độ.   Nghĩa 2: Biểu thị mức độ (cao hoặc thấp) của một hành động, trạng thái.   Nghĩa 3: Biểu thị sự coi nhẹ, xem thường ("chỉ cỡ...").', 'N / V-thể thường / Adj +  くらい /  ぐらい', '[{"ja":"ここから駅まで 10 分くらいです。","romaji":"→ (Từ đây đến ga mất khoảng 10 phút.)","vi":""},{"ja":"疲れてもう一歩も歩けないくらいだ。","romaji":"→ (Tôi mệt đến mức không thể bước thêm một bước nào nữa.)","vi":""},{"ja":"これくらいの傷なら、大丈夫だ。","romaji":"→ (Vết thương cỡ này thì không sao đâu.)","vi":"──────────"},{"ja":"約 (やく) (N4/N3): Khoảng (dùng với số lượng).","romaji":"","vi":""},{"ja":"～だけ (N5/N3): Chỉ / Đến mức.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('54.  くせに  - Vậy mà; dù; mặc dù; bất chấp ~', 'N3', 'Dùng để biểu thị sự đối lập giữa hai vế câu, đồng thời thể hiện thái độ chỉ trích, bất mãn, khinh thường hoặc coi nhẹ của người nói đối với đối tượng được nói đến.', 'V/Adj/N-thể thường +  くせに', '[{"ja":"知っているくせに、教えてくれない。","romaji":"→ (Biết vậy mà không chỉ cho.)","vi":""},{"ja":"子供のくせに、生意気なことを言うな。","romaji":"→ (Chỉ là con nít vậy mà đừng nói những lời xấc xược.)","vi":""},{"ja":"お金がないくせに、高いものを買おうとする。","romaji":"→ (Không có tiền vậy mà cứ định mua đồ đắt tiền.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('55.  まるで  - Như thể; như là; giống hệt như ~', 'N3', 'Dùng để nhấn mạnh sự giống nhau giữa hai sự vật, sự việc, thường là so sánh ví von, đôi khi mang tính cường điệu.', 'まるで + N +  の +  ようだ / V +  ようだ /  みたいだ', '[{"ja":"合格した！まるで夢のようだ。","romaji":"→ (Đậu rồi! Cứ như là một giấc mơ vậy.)","vi":""},{"ja":"あの雲はまるで犬のような形をしている。","romaji":"→ (Đám mây kia có hình dạng giống hệt như một chú chó.)","vi":""},{"ja":"彼はまるで何でも知っているかのように話す。","romaji":"→ (Anh ta nói chuyện cứ như thể là biết tuốt mọi thứ.)","vi":"──────────"},{"ja":"～みたいだ (N4): Trông có vẻ, giống như (thân mật hơn).","romaji":"","vi":""},{"ja":"～かのようだ (N3): Cứ như thể là (nhấn mạnh sự ví von).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('56.  まさか  - Không đời nào; không thể nào; bạn đùa à', 'N3', 'Là một trạng từ, dùng để diễn tả sự ngạc nhiên tột độ, sự không tin hoặc sự phủ nhận mạnh mẽ trước một sự việc nào đó.', 'まさか + Câu (thường có  ～とは /  ～だろうか /  ～ないだろう)', '[{"ja":"まさか彼が試験に落ちるとは思わなかった。","romaji":"→ (Không ngờ anh ấy lại trượt kỳ thi.)","vi":""},{"ja":"まさか、宝くじに当たるとは！(Không thể nào, tôi lại trúng số ư!)","romaji":"","vi":""},{"ja":"まさか、こんな所であなたに会えるなんて。","romaji":"→ (Không thể tin được lại có thể gặp bạn ở một nơi như thế này.)","vi":"──────────"},{"ja":"～はずがない (N3): Chắc chắn không thể...","romaji":"","vi":""},{"ja":"～わけがない (N3): Lẽ nào lại...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('57.  めったに～ない  - Hầu như không; hiếm khi', 'N3', 'Dùng để diễn tả tần suất xảy ra của một hành động, sự việc là rất thấp, rất hiếm.', 'めったに + V-ない', '[{"ja":"彼はめったに遅刻しない。","romaji":"→ (Anh ấy hiếm khi đi muộn.)","vi":""},{"ja":"私はめったに外食しない。","romaji":"→ (Tôi hầu như không ăn ngoài.)","vi":""},{"ja":"こんな機会はめったにないから、大切にしよう。","romaji":"→ (Cơ hội như thế này hiếm có lắm, nên hãy trân trọng nó.)","vi":"──────────"},{"ja":"ほとんど～ない (N4): Hầu như không (có thể dùng cho cả tần suất và số lượng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('58.  も～ば～も  - Cả ~ và ~; cũng; hoặc/hoặc', 'N3', 'Dùng để liệt kê hai (hoặc nhiều hơn) sự vật, sự việc, trạng thái, nhấn mạnh rằng cả hai đều tồn tại hoặc có tính chất đó.', 'N1 +  も + V-ば/Adj-ければ/N/Adj-な +  なら + N2 +  も + V/Adj/N.', '[{"ja":"彼は勉強もできれば、スポーツもできる。","romaji":"→ (Anh ấy vừa học giỏi mà chơi thể thao cũng giỏi.)","vi":""},{"ja":"この店は値段も安ければ、味もいい。","romaji":"→ (Quán này giá vừa rẻ mà vị cũng ngon.)","vi":""},{"ja":"雨も降っていれば、風も吹いている。","romaji":"→ (Trời vừa mưa mà gió cũng thổi.)","vi":"──────────"},{"ja":"～し～し (N4): Vừa... vừa... (liệt kê lý do/sự thật).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('59.  もしかしたら  - Có lẽ; có thể; biết đâu; có khả năng ~', 'N3', 'Là một trạng từ, dùng để diễn tả một khả năng hoặc sự phỏng đoán, nhưng với mức độ chắc chắn không cao.', 'もしかしたら + Câu +  かもしれない', '[{"ja":"もしかしたら、彼はもう帰ったかもしれない。","romaji":"→ (Biết đâu anh ấy đã về rồi cũng nên.)","vi":""},{"ja":"連絡がないけど、もしかしたら何かあったのかもしれない。","romaji":"→ (Không thấy liên lạc gì, có lẽ đã xảy ra chuyện gì đó chăng.)","vi":"──────────"},{"ja":"きっと (N4): Chắc chắn là (mức độ chắc chắn cao nhất).","romaji":"","vi":""},{"ja":"～かもしれない (N4): Có lẽ là... (kết hợp với  もしかしたら).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('60.  もしも〜たら  /  〜ば  - Nếu; trong trường hợp; giả sử ~', 'N3', 'Dùng để nhấn mạnh một tình huống giả định hoặc điều kiện. Mạnh hơn và mang tính giả định cao hơn so với chỉ dùng  ～たら hoặc  ～ば.', 'もしも + V-たら / Adj-かったら / N/Adj-な +  だったら / V-ば / Adj-ければ / N/Adj-な +  なら', '[{"ja":"もしも１億円あったら、何をしますか。","romaji":"→ (Nếu có 100 triệu yên, bạn sẽ làm gì?)","vi":""},{"ja":"もしもあなたが鳥だったら、どこへ飛んでいきたいですか。","romaji":"→ (Nếu bạn là một chú chim, bạn muốn bay đi đâu?)","vi":"──────────"},{"ja":"～たら (N4): Nếu...","romaji":"","vi":""},{"ja":"～ば (N4): Nếu...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('61.  向け  (むけ) - Dành cho; nhắm đến ~', 'N3', 'Chỉ ra đối tượng hoặc mục đích cụ thể mà một sản phẩm, chương trình, hoặc thông tin được tạo ra để hướng tới.', 'N +  向けだ /  向けの + N', '[{"ja":"この本は子供向けに書かれています。","romaji":"→ (Quyển sách này được viết dành cho trẻ em.)","vi":""},{"ja":"これは初心者向けのパソコン教室です。","romaji":"→ (Đây là lớp học máy tính dành cho người mới bắt đầu.)","vi":"──────────"},{"ja":"～のために (N4): Vì..., cho... (chỉ mục đích/lợi ích).","romaji":"","vi":""},{"ja":"～用 (よう) (N3): Dùng cho... (chỉ công dụng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('62.  向き  (むき) - Phù hợp với ~', 'N3', 'Chỉ ra rằng một cái gì đó phù hợp hoặc thích hợp với một đối tượng, mục đích, hoặc tình huống cụ thể, dựa trên đặc tính vốn có của nó.', 'N +  向きだ /  向きの + N', '[{"ja":"この仕事は体力がある人向きだ。","romaji":"→ (Công việc này phù hợp với người có thể lực.)","vi":""},{"ja":"このデザインは若い人向きですね。","romaji":"→ (Thiết kế này hợp với người trẻ nhỉ.)","vi":"──────────"},{"ja":"～に合う (N4): Hợp với..., vừa với...","romaji":"","vi":""},{"ja":"～にいい (N5): Tốt cho...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('63.  むしろ  - Đúng hơn; thay vào đó; tốt hơn ~', 'N3', 'Là một trạng từ, dùng khi so sánh hai lựa chọn (A và B), và muốn nhấn mạnh rằng B là lựa chọn thích hợp hơn, chính xác hơn, hoặc tốt hơn A.', 'むしろ + B (Thường dùng trong cấu trúc A  より B)', '[{"ja":"難しいと言うより、むしろ面倒くさい。","romaji":"→ (Nói là khó thì đúng hơn là phiền phức.)","vi":""},{"ja":"私は暑いのより、むしろ寒いほうが好きだ。","romaji":"→ (Tôi thích lạnh còn hơn là nóng.)","vi":"──────────"},{"ja":"代わりに (N3): Thay vào đó.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('64.  ながらも  - Nhưng; mặc dù; bất chấp ~', 'N3', 'Dùng để nối hai vế câu có ý nghĩa tương phản, đối lập, tương tự như  ～のに hay  ～けれども. Thường mang sắc thái trang trọng hoặc văn viết hơn một chút.', 'V-ます (bỏ  ます) / N / Adj-い / Adj-な +  ながらも', '[{"ja":"残念ながらも、試合に負けてしまった。","romaji":"→ (Mặc dù rất tiếc nhưng chúng tôi đã thua trận đấu.)","vi":""},{"ja":"彼は学生でありながらも、会社を経営している。","romaji":"→ (Anh ấy dù là sinh viên nhưng vẫn đang kinh doanh công ty.)","vi":""},{"ja":"狭いながらも、楽しい我が家。","romaji":"→ (Dù chật hẹp nhưng đây là ngôi nhà vui vẻ của tôi.)","vi":"──────────"},{"ja":"～けれど /  ～けど (N4): Nhưng.","romaji":"","vi":""},{"ja":"～が (N5): Nhưng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('65.  ないことはない  - Có thể làm; không phải là không thể ~', 'N3', 'Là một dạng phủ định kép, dùng để khẳng định một cách yếu ớt hoặc dè dặt. Nó ngụ ý rằng "không phải là không thể", tức là "có thể" nhưng có thể là khó, không muốn, hoặc không chắc chắn lắm.', 'V-ない (bỏ  ない) +  ないことはない', '[{"ja":"納豆は、食べられないことはないが、あまり好きじゃない。","romaji":"→ (Natto thì không phải là không ăn được, nhưng tôi không thích lắm.)","vi":""},{"ja":"今から行けば、間に合わないことはないだろう。","romaji":"→ (Nếu đi bây giờ thì có lẽ không phải là không kịp.)","vi":"──────────"},{"ja":"～可能性がある (N3): Có khả năng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('66.  ないと  - Phải làm; trừ khi/nếu bạn không ~', 'N3', 'Là dạng nói tắt, thân mật của  ～ないといけない hoặc  ～なければならない, diễn tả ý nghĩa "phải làm" một việc gì đó.', 'V-ない +  と', '[{"ja":"もう寝ないと。","romaji":"→ (Phải ngủ thôi.)","vi":""},{"ja":"明日早く起きないと。","romaji":"→ (Mai phải dậy sớm.)","vi":""},{"ja":"宿題をしないと。","romaji":"→ (Phải làm bài tập.)","vi":"──────────"},{"ja":"～なくてはいけない (N4): Phải làm (đầy đủ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('67.  なかなか  - Rất; khá; mãi mà không ~', 'N3', 'Nghĩa 1 (Đi với khẳng định): Diễn tả mức độ "khá, rất", thường là cao hơn so với dự kiến.   Nghĩa 2 (Đi với phủ định): Diễn tả một việc gì đó khó xảy ra, tốn thời gian, hoặc không diễn ra một cách dễ dàng.', 'なかなか + Adj / Adv (Khá, rất)   なかなか + V-ない (Mãi mà không)', '[{"ja":"このレストランはなかなかおいしい。","romaji":"→ (Nhà hàng này khá là ngon đấy.)","vi":""},{"ja":"バスがなかなか来ない。","romaji":"→ (Xe buýt mãi mà không đến.)","vi":""},{"ja":"彼はなかなかやるね。","romaji":"→ (Anh ta cũng khá cừ đấy nhỉ.)","vi":"──────────"},{"ja":"かなり (N4): Khá (nghĩa 1).","romaji":"","vi":""},{"ja":"ぜんぜん～ない (N5): Hoàn toàn không (nghĩa 2, nhưng  なかなか～ない ngụ ý sự khó khăn/tốn thời gian).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('68.  なんか  /  なんて  /  など  - Đưa ra ví dụ; thể hiện sự khiêm tốn; xem nhẹ ~', 'N3', 'など  (N4): Dùng để liệt kê ví dụ ("...vân vân", "... như là"). Trang trọng hơn.   なんか  /  なんて: Dùng trong văn nói, có nhiều sắc thái:       Liệt kê ví dụ (giống  など nhưng thân mật hơn).       Thể hiện sự khiêm tốn (私なんか - người như tôi thì...).       Thể hiện sự xem nhẹ, coi thường (あいつなんか - hạng như hắn ta thì...).       なんて: Còn dùng để thể hiện sự ngạc nhiên hoặc trích dẫn.', 'N +  なんか /  なんて /  など', '[{"ja":"ケーキなんかどうですか。","romaji":"→ (Bánh ngọt hay gì đó thì sao?)","vi":""},{"ja":"私なんかに、そんなことはできません。","romaji":"→ (Người như tôi thì không thể làm việc đó được đâu.)","vi":""},{"ja":"試験なんて大嫌いだ。","romaji":"→ (Tôi ghét cay ghét đắng cái thứ gọi là thi cử.)","vi":"──────────"},{"ja":"～や～など (N5): ... và ... vân vân...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('69.  直す  (なおす) - Làm lại; làm lại từ đầu', 'N3', 'Ghép vào sau động từ để diễn tả việc thực hiện lại hành động đó một lần nữa, thường là để sửa chữa, cải thiện hoặc làm cho đúng.', 'V-ます (bỏ  ます) +  直す', '[{"ja":"作文に間違いが多かったので、書き直した。","romaji":"→ (Vì bài văn có nhiều lỗi nên tôi đã viết lại.)","vi":""},{"ja":"この部分は分かりにくいので、言い直してください。","romaji":"→ (Phần này khó hiểu nên xin hãy nói lại.)","vi":""},{"ja":"もう一度考え直します。","romaji":"→ (Tôi sẽ suy nghĩ lại một lần nữa.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('70.  なるべく  - Càng nhiều càng tốt / Cố gắng hết sức', 'N3', 'Là một trạng từ, diễn tả sự cố gắng làm một việc gì đó ở mức độ tốt nhất, nhiều nhất, hoặc sớm nhất có thể trong phạm vi cho phép.', 'なるべく + V / Adj / Adv', '[{"ja":"なるべく早く来てください。","romaji":"→ (Xin hãy đến sớm nhất có thể.)","vi":""},{"ja":"なるべく多くの人に参加してほしい。","romaji":"→ (Tôi muốn càng nhiều người tham gia càng tốt.)","vi":""},{"ja":"なるべく野菜を食べるようにしています。","romaji":"→ (Tôi đang cố gắng ăn rau nhiều nhất có thể.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('71.  なぜなら  - Bởi vì; lý do là; nếu bạn muốn biết tại sao', 'N3', 'Dùng để đưa ra lý do hoặc nguyên nhân cho một sự việc đã được nêu ở câu trước. Thường mang tính trang trọng hoặc dùng trong văn viết, giải thích.', 'Câu 1.  なぜなら、Câu 2 (lý do) +  からだ /  ためだ.', '[{"ja":"来週、私は学校を休みます。なぜなら、国へ帰るからです。","romaji":"→ (Tuần sau tôi sẽ nghỉ học. Bởi vì tôi sẽ về nước.)","vi":""},{"ja":"彼は人気がある。なぜなら、親切で正直だからだ。","romaji":"→ (Anh ấy được yêu mến. Lý do là vì anh ấy tốt bụng và trung thực.)","vi":"──────────"},{"ja":"～ので (N4): Vì... (khách quan hơn  から).","romaji":"","vi":""},{"ja":"どうしてかというと (N3): Nếu hỏi tại sao thì là vì... (tương tự, nhấn mạnh sự giải thích).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('72.  んだって  - Tôi nghe nói rằng; nghe nói ~', 'N3', 'Dùng trong văn nói thân mật để truyền đạt lại thông tin đã nghe được từ người khác. Tương tự  ～そうだ (truyền 聞).', 'V/Adj/N-thể thường +  んだって', '[{"ja":"田中さん、結婚するんだって。","romaji":"→ (Tớ nghe nói anh Tanaka sắp cưới đấy.)","vi":""},{"ja":"明日は雨が降るんだって。","romaji":"→ (Nghe nói mai trời mưa đấy.)","vi":""},{"ja":"あの店のケーキ、美味しいんだって。","romaji":"→ (Nghe nói bánh ngọt ở quán kia ngon lắm.)","vi":"──────────"},{"ja":"～ということだ (N3): Nghe nói là... / Có nghĩa là... (trang trọng hơn).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('73.  に違いない  (にちがいない) - Chắc chắn là; không nghi ngờ gì ~', 'N3', 'Diễn tả sự phán đoán chắc chắn của người nói dựa trên một căn cứ nào đó. Mức độ chắc chắn cao.', 'V/Adj/N-thể thường +  に違いない', '[{"ja":"窓が開いている。誰かが部屋に入ったに違いない。","romaji":"→ (Cửa sổ đang mở. Chắc chắn là có ai đó đã vào phòng.)","vi":""},{"ja":"彼は一日中勉強しているから、試験に合格するに違いない。","romaji":"→ (Vì anh ấy học cả ngày nên chắc chắn sẽ đỗ kỳ thi.)","vi":"──────────"},{"ja":"～はずだ (N4): Chắc chắn là... (dựa trên logic, quy luật).","romaji":"","vi":""},{"ja":"きっと (N4): Chắc chắn là... (trạng từ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('74.  に反して  (にはんして) - Chống lại; trái với; ngược lại với ~', 'N3', 'Diễn tả một sự việc, hành động xảy ra trái ngược với dự đoán, kỳ vọng, mong muốn, quy tắc hoặc ý chí.', 'N +  に反して /  に反する + N', '[{"ja":"私の予想に反して、試合は簡単に終わった。","romaji":"→ (Trái với dự đoán của tôi, trận đấu đã kết thúc một cách dễ dàng.)","vi":""},{"ja":"親の期待に反して、彼は大学に行かなかった。","romaji":"→ (Trái với kỳ vọng của bố mẹ, anh ấy đã không vào đại học.)","vi":"──────────"},{"ja":"～と違って (N4): Khác với...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('75.  にかけて  /  にかけては  - Về (lĩnh vực); Xét về (mặt); Giỏi về ~', 'N3', 'Dùng để chỉ một lĩnh vực, phương diện cụ thể mà ai đó hoặc cái gì đó đặc biệt giỏi, vượt trội.', 'N (Lĩnh vực/Kỹ năng) +  にかけては + (N2 +  は/も) +  ～', '[{"ja":"数学にかけては、彼に勝てる人はいない。","romaji":"→ (Xét về môn Toán thì không ai thắng nổi cậu ấy.)","vi":""},{"ja":"足の速さにかけては、彼女がクラスで一番だ。","romaji":"→ (Nói về tốc độ chạy thì cô ấy là số một trong lớp.)","vi":"──────────"},{"ja":"～に関しては (N3): Liên quan đến... (trang trọng hơn).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('76.  に関する  /  に関して  (にかんする  /  にかんして) - Về; liên quan đến ~', 'N3', 'Dùng để chỉ chủ đề, đối tượng được nói đến, đề cập đến. Trang trọng hơn  ～について.', 'N +  に関して /  に関する + N', '[{"ja":"この問題に関して、何か意見がありますか。","romaji":"→ (Về vấn đề này, có ai có ý kiến gì không?)","vi":""},{"ja":"環境問題に関するレポートを書いた。","romaji":"→ (Tôi đã viết một bản báo cáo liên quan đến vấn đề môi trường.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('77.  にかわって  /  にかわり  - Thay vì; thay thế; thay mặt ~', 'N3', 'Diễn tả sự thay thế: người này làm thay người kia, vật này được dùng thay vật kia.', 'N +  にかわって /  にかわり', '[{"ja":"今日は父にかわって、私が店番をします。","romaji":"→ (Hôm nay tôi sẽ trông cửa hàng thay cho bố.)","vi":""},{"ja":"社長にかわり、ご挨拶申し上げます。","romaji":"→ (Thay mặt giám đốc, tôi xin có đôi lời phát biểu.)","vi":""},{"ja":"今は、電話にかわってメールが主な連絡手段になった。","romaji":"→ (Bây giờ, email đã trở thành phương tiện liên lạc chính thay cho điện thoại.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('78.  に比べて  (にくらべて) - So với; so sánh với ~', 'N3', 'Dùng để đưa ra một đối tượng làm tiêu chuẩn để so sánh với một đối tượng khác.', 'N +  に比べて /  に比べると', '[{"ja":"去年に比べて、今年は雨が多い。","romaji":"→ (So với năm ngoái thì năm nay mưa nhiều.)","vi":""},{"ja":"電話はメールに比べて、早く連絡が取れる。","romaji":"→ (So với email thì điện thoại có thể liên lạc nhanh hơn.)","vi":"──────────"},{"ja":"～ほど～ない (N3): Không... bằng...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('79.  に慣れる  (になれる) - Quen với ~', 'N3', 'Diễn tả trạng thái đã trở nên quen thuộc, thích nghi được với một môi trường, công việc, hoặc thói quen nào đó.', 'N +  に慣れる / V-る +  の +  に慣れる', '[{"ja":"日本の生活に慣れましたか。","romaji":"→ (Bạn đã quen với cuộc sống ở Nhật chưa?)","vi":""},{"ja":"新しい仕事になかなか慣れない。","romaji":"→ (Tôi mãi mà không quen được với công việc mới.)","vi":""},{"ja":"毎日早く起きるのに慣れた。","romaji":"→ (Tôi đã quen với việc dậy sớm mỗi ngày.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('80.  において  /  における  - Ở; tại (nơi); về; đối với; liên quan đến ~', 'N3', 'Là cách nói trang trọng của  ～で hoặc  ～に, dùng để chỉ địa điểm, thời gian hoặc lĩnh vực mà một sự việc xảy ra hoặc tồn tại.', 'N (Nơi chốn/Thời gian/Lĩnh vực) +  において /  における + N', '[{"ja":"会議は第一会議室において行われます。","romaji":"→ (Cuộc họp sẽ được tổ chức tại phòng họp số 1.)","vi":""},{"ja":"現代社会における問題について話し合った。","romaji":"→ (Chúng tôi đã thảo luận về các vấn đề trong xã hội hiện đại.)","vi":"──────────"},{"ja":"～に (N5): Vào, ở (chỉ thời gian, địa điểm tồn tại).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('81.  にしたがって  /  にしたがい  - Theo; cùng với; do đó ~', 'N3', 'Nghĩa 1: Diễn tả sự thay đổi song song: Khi một sự việc thay đổi (vế trước), thì một sự việc khác cũng thay đổi theo (vế sau). (Tương tự  ～につれて).   Nghĩa 2: Diễn tả sự tuân theo một chỉ thị, quy tắc, hoặc lời khuyên nào đó.', 'N / V-る +  にしたがって /  にしたがい', '[{"ja":"北へ行くにしたがって、紅葉は早くなる。","romaji":"→ (Càng đi về phía Bắc, lá đỏ càng đến sớm.)","vi":""},{"ja":"予定表にしたがい、旅行の準備をします。","romaji":"→ (Tôi sẽ chuẩn bị cho chuyến đi theo như lịch trình.)","vi":""},{"ja":"指示にしたがって、動いてください。","romaji":"→ (Hãy hành động theo chỉ thị.)","vi":"──────────"},{"ja":"～どおりに (N4): Theo như (Chỉ dùng cho nghĩa 2).","romaji":"","vi":""},{"ja":"～ば～ほど (N3): Càng... càng... (Nghĩa 1).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('82.  にしても  - Ngay cả khi; mặc dù; bất kể ~', 'N3', 'Nghĩa 1: Diễn tả ý "ngay cả khi/dù là" (Tương tự  ～ても).   Nghĩa 2: Dùng để đưa ra một ví dụ cực đoan hoặc một trường hợp, và khẳng định rằng dù ở trường hợp đó thì vế sau vẫn đúng.   Nghĩa 3: A にしても B にしても: Dù là A hay B thì...', 'V/Adj/N-thể thường +  にしても', '[{"ja":"行くにしても、行かないにしても、早く決めてください。","romaji":"→ (Dù đi hay không đi thì cũng hãy quyết định sớm đi.)","vi":""},{"ja":"いくら好きだにしても、毎日食べると飽きる。","romaji":"→ (Dù thích đến mấy đi nữa, ăn mỗi ngày cũng chán.)","vi":"──────────"},{"ja":"～たって (N3): Dù... thì cũng... (văn nói).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('83.  にしては  - Đối với; xét đến việc ~', 'N3', 'Dùng khi muốn nói rằng một sự việc nào đó khác biệt (tốt hơn hoặc kém hơn) so với những gì người ta thường mong đợi từ một tiêu chuẩn hoặc sự thật được nêu ở vế trước.', 'V/Adj/N-thể thường +  にしては', '[{"ja":"初めてにしては、上手にできましたね。","romaji":"→ (Xét việc lần đầu làm thì cậu đã làm rất giỏi đấy nhỉ.)","vi":""},{"ja":"彼は外国人にしては、日本語がぺらぺらだ。","romaji":"→ (Đối với một người nước ngoài thì anh ấy nói tiếng Nhật rất trôi chảy.)","vi":""},{"ja":"子供にしては、難しいことをよく知っている。","romaji":"→ (Đối với một đứa trẻ thì nó biết khá nhiều chuyện khó.)","vi":"──────────"},{"ja":"～のに (N4): Mặc dù... (chỉ sự tương phản đơn thuần).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('84.  に対して  (にたいして) - Đối với; chống lại; về; trái ngược với ~', 'N3', 'Nghĩa 1: Chỉ đối tượng mà hành động hoặc thái độ hướng đến.   Nghĩa 2: Chỉ sự đối lập, tương phản rõ rệt giữa hai sự vật, sự việc.', 'N +  に対して /  に対する + N', '[{"ja":"目上の人に対しては、丁寧な言葉を使いなさい。","romaji":"→ (Đối với người trên, hãy dùng lời lẽ lịch sự.)","vi":""},{"ja":"父の意見に対して、私は反対です。","romaji":"→ (Tôi phản đối ý kiến của bố.)","vi":""},{"ja":"大阪はにぎやかなのに対して、私の故郷は静かだ。","romaji":"→ (Osaka náo nhiệt, trái lại quê tôi thì yên tĩnh.)","vi":"──────────"},{"ja":"～に (N5): Đến/Với (nghĩa 1).","romaji":"","vi":""},{"ja":"～は～が、～は～ (N5/N4): Cấu trúc so sánh (nghĩa 2).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('85.  にとって  - Đối với; cho; về; theo như... thì; về ~', 'N3', 'Dùng để chỉ ra quan điểm, góc nhìn hoặc sự đánh giá từ phía một người hoặc một sự vật nào đó.', 'N +  にとって', '[{"ja":"私にとって、家族は一番大切です。","romaji":"→ (Đối với tôi, gia đình là quan trọng nhất.)","vi":""},{"ja":"この問題は子供にとっては難しすぎる。","romaji":"→ (Vấn đề này quá khó đối với trẻ con.)","vi":"──────────"},{"ja":"～に対して (N3): Đối với (hành động/thái độ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('86.  について  - Về; liên quan đến; về; trên ~', 'N3', 'Dùng để chỉ chủ đề hoặc nội dung của một hành động như nói chuyện, suy nghĩ, điều tra, viết lách... Đây là cách nói cơ bản và phổ biến nhất.', 'N +  について /  についての + N', '[{"ja":"日本の文化について勉強したいです。","romaji":"→ (Tôi muốn học về văn hóa Nhật Bản.)","vi":""},{"ja":"この件について、詳しく説明してください。","romaji":"→ (Xin hãy giải thích chi tiết về vụ việc này.)","vi":""},{"ja":"経済についての本を読んでいます。","romaji":"→ (Tôi đang đọc sách về kinh tế.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('87.  につれて  - Cùng với; tỷ lệ thuận với; với; khi… thì ~', 'N3', 'Diễn tả sự thay đổi của vế sau diễn ra một cách tự nhiên, song song và cùng chiều hướng với sự thay đổi của vế trước.', 'N / V-る +  につれて', '[{"ja":"年を取るにつれて、体が弱くなってきた。","romaji":"→ (Càng lớn tuổi, cơ thể càng yếu đi.)","vi":""},{"ja":"台風が近づくにつれて、雨や風が強くなってきた。","romaji":"→ (Cùng với việc bão đến gần, mưa và gió càng mạnh lên.)","vi":"──────────"},{"ja":"～ば～ほど (N3): Càng... càng... (nhấn mạnh sự lặp lại hoặc mức độ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('88.  には  - Với mục đích; để ~', 'N3', 'Dùng để chỉ mục đích hoặc mục tiêu của hành động, và vế sau thường nêu lên phương pháp, điều kiện cần thiết, hoặc sự đánh giá để đạt được mục đích đó.', 'V-る +  には', '[{"ja":"日本語が上手になるには、毎日練習することが大切だ。","romaji":"→ (Để giỏi tiếng Nhật thì việc luyện tập mỗi ngày là rất quan trọng.)","vi":""},{"ja":"駅へ行くには、どのバスに乗ればいいですか。","romaji":"→ (Để đi đến ga thì nên đi chuyến xe buýt nào ạ?)","vi":"──────────"},{"ja":"V-る +  のに (N4): Để... (chỉ sự hữu ích/cần thiết).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('89.  によると  /  によれば  - Theo ~', 'N3', 'Dùng để chỉ nguồn gốc của thông tin mà người nói nghe được hoặc đọc được.', 'N (Nguồn thông tin) +  によると /  によれば', '[{"ja":"天気予報によると、明日は晴れるそうだ。","romaji":"→ (Theo dự báo thời tiết thì nghe nói ngày mai trời sẽ nắng.)","vi":""},{"ja":"新聞によれば、事故の原因はまだ分かっていないということだ。","romaji":"→ (Theo báo chí thì nghe nói nguyên nhân vụ tai nạn vẫn chưa được làm rõ.)","vi":"──────────"},{"ja":"～そうだ (N4): Nghe nói là...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('90.  によって  /  による  - Bằng cách; do; vì; bởi vì ~', 'N3', 'Là một cấu trúc rất đa năng, có thể diễn tả:   Phương tiện, cách thức: Bằng... (手段)   Nguyên nhân, lý do: Do..., Vì... (原因・理由)   Tác nhân trong câu bị động: Bởi... (受け身)   Sự khác biệt tùy thuộc vào: Tùy vào... (場合)   Người tạo ra: Bởi... (Tác giả, người phát minh...)', 'N +  によって /  による + N', '[{"ja":"インターネットによって、世界中の情報を得られる。","romaji":"→ (Bằng internet, chúng ta có thể có được thông tin trên toàn thế giới.)","vi":""},{"ja":"地震によって、多くの家が壊れた。","romaji":"→ (Do động đất, nhiều nhà cửa đã bị phá hủy.)","vi":""},{"ja":"この本は有名な作家によって書かれた。","romaji":"→ (Quyển sách này được viết bởi một tác giả nổi tiếng.)","vi":""},{"ja":"人によって、考え方が違う。","romaji":"→ (Tùy vào mỗi người mà cách suy nghĩ khác nhau.)","vi":"──────────"},{"ja":"～から /  ～ので (N5/N4): Vì (nguyên nhân).","romaji":"","vi":""},{"ja":"Câu bị động (N4): Bị/Được... bởi...","romaji":"","vi":""},{"ja":"～場合は (N4): Trong trường hợp...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('91.  のでしょうか  - (Dùng để hỏi một cách lịch sự)', 'N3', 'Là một cách hỏi rất lịch sự và mềm mại, thường được dùng khi muốn hỏi xin lời giải thích, ý kiến, hoặc khi muốn hỏi một cách gián tiếp, đặc biệt là với người trên hoặc trong tình huống cần sự lịch sự.', 'V/Adj/N-thể thường +  のでしょうか', '[{"ja":"この問題について、どう考えたらいいのでしょうか。","romaji":"→ (Về vấn đề này, tôi nên suy nghĩ như thế nào ạ?)","vi":""},{"ja":"会場にはどうやって行くのが一番早いのでしょうか。","romaji":"→ (Để đến hội trường thì đi bằng cách nào là nhanh nhất ạ?)","vi":"──────────"},{"ja":"～ですか (N5): ... à? (câu hỏi cơ bản).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('92.  を中心に  (をちゅうしんに) - Tập trung vào; lấy làm trung tâm', 'N3', 'Diễn tả rằng danh từ đứng trước là trung tâm, là điểm chính hoặc là đối tượng tập trung của một hành động, sự việc hoặc một khu vực nào đó.', 'N +  を中心に /  を中心として /  を中心にした + N', '[{"ja":"東京を中心に、関東地方は人口が多い。","romaji":"→ (Lấy Tokyo làm trung tâm, vùng Kanto có dân số đông đúc.)","vi":""},{"ja":"この会議は環境問題を中心にして、話し合います。","romaji":"→ (Cuộc họp này sẽ thảo luận tập trung vào vấn đề môi trường.)","vi":"──────────"},{"ja":"～に関して (N3): Liên quan đến...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('93.  をはじめ  /  をはじめとして  - Ví dụ; bắt đầu với ~', 'N3', 'Dùng để đưa ra một ví dụ tiêu biểu, quan trọng nhất khi muốn liệt kê nhiều thứ khác nhau.', 'N +  をはじめ /  をはじめとして /  をはじめとする + N', '[{"ja":"日本には富士山をはじめ、美しい山がたくさんあります。","romaji":"→ (Ở Nhật Bản, tiêu biểu là núi Phú Sĩ, có rất nhiều ngọn núi đẹp.)","vi":""},{"ja":"会議には、田中さんをはじめとして、多くの専門家が出席した。","romaji":"→ (Trong cuộc họp, bắt đầu với ông Tanaka, có rất nhiều chuyên gia đã tham dự.)","vi":"──────────"},{"ja":"～など (N4): ... vân vân..., như là...","romaji":"","vi":""},{"ja":"～や～など (N5): ... và ... vân vân...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('94.  を込めて  (をこめて) - Tràn đầy; chứa đựng ~', 'N3', 'Diễn tả một hành động được thực hiện với tất cả tình cảm, tâm tư, hoặc nỗ lực được dồn vào trong đó.', 'N (Chỉ cảm xúc) +  を込めて', '[{"ja":"感謝の気持ちを込めて、プレゼントを贈ります。","romaji":"→ (Tôi gửi món quà này với tất cả lòng biết ơn.)","vi":""},{"ja":"彼女は心を込めて、手紙を書いた。","romaji":"→ (Cô ấy đã viết lá thư với tất cả tấm lòng.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('G5.  を通じて  /  を通して  (をつうじて  /  をとおして) - Thông qua; qua; trong suốt; bằng ~', 'N3', 'Nghĩa 1: Diễn tả một phương tiện, một cách thức, hoặc một người trung gian mà thông qua đó một hành động được thực hiện hoặc thông tin được truyền đạt.   Nghĩa 2: Diễn tả một khoảng thời gian kéo dài "trong suốt".', 'N +  を通じて /  を通して', '[{"ja":"インターネットを通じて、世界中の友達ができた。","romaji":"→ (Thông qua internet, tôi đã kết bạn được với bạn bè trên khắp thế giới.)","vi":""},{"ja":"友人を通して、彼と知り合った。","romaji":"→ (Tôi quen anh ấy qua một người bạn.)","vi":""},{"ja":"この地域は一年を通じて暖かい。","romaji":"→ (Vùng này ấm áp suốt cả năm.)","vi":"──────────"},{"ja":"～中 (じゅう) (N3): Suốt... (nghĩa 2).","romaji":"","vi":""},{"ja":"～あいだずっと (N4): Suốt trong khoảng... (nghĩa 2).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('96.  おかげで  - Nhờ có; do; bởi vì ~', 'N3', 'Dùng để chỉ nguyên nhân dẫn đến một kết quả tốt, tích cực, đồng thời thể hiện lòng biết ơn hoặc sự đánh giá cao đối với nguyên nhân đó.', 'V/Adj/N-thể thường +  おかげで', '[{"ja":"先生のおかげで、試験に合格できました。","romaji":"→ (Nhờ có thầy cô mà em đã đỗ kỳ thi.)","vi":""},{"ja":"あなたが手伝ってくれたおかげで、仕事が早く終わった。","romaji":"→ (Nhờ bạn giúp mà công việc đã xong sớm.)","vi":"──────────"},{"ja":"～ので (N4): Vì... (trung tính).","romaji":"","vi":""},{"ja":"～せいで (N3): Tại vì... (kết quả xấu).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('97.  っぱなし  - Để (cái gì đó) nguyên; để suốt ~', 'N3', 'Diễn tả một trạng thái cứ tiếp diễn mà không được xử lý hoặc kết thúc như bình thường, thường mang hàm ý tiêu cực, chỉ sự bỏ mặc, bất cẩn hoặc phàn nàn.', 'V-ます (bỏ  ます) +  っぱなし', '[{"ja":"テレビをつけっぱなしで寝てしまった。","romaji":"→ (Tôi đã để tivi bật suốt và ngủ quên mất.)","vi":""},{"ja":"ドアを開けっぱなしにしないでください。","romaji":"→ (Xin đừng để cửa mở suốt như vậy.)","vi":""},{"ja":"電気を消し忘れて、つけっぱなしだった。","romaji":"→ (Tôi quên tắt điện, cứ để nó bật suốt.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('98.  っぽい  - Giống như; hơi; có vẻ; dễ làm; thường làm ~', 'N3', 'Nghĩa 1: Diễn tả cảm giác "giống như", "có vẻ như" N, thường dùng cho màu sắc, đặc tính (đôi khi mang nghĩa không tốt hoặc trẻ con). (子供っぽい - như trẻ con,  安っぽい - trông rẻ tiền).   Nghĩa 2: Diễn tả xu hướng "dễ", "hay" làm gì đó. (忘れっぽい - hay quên, 怒りっぽい - hay nổi giận).', 'N / V-ます (bỏ  ます) / Adj-い (bỏ  い) +  っぽい', '[{"ja":"あの黒っぽい服を取ってください。","romaji":"→ (Hãy lấy cho tôi cái bộ quần áo trông hơi đen kia.)","vi":""},{"ja":"彼は怒りっぽい人だ。","romaji":"→ (Anh ta là người hay nổi giận.)","vi":""},{"ja":"年を取ると忘れっぽくなる。","romaji":"→ (Khi có tuổi thì trở nên hay quên.)","vi":"──────────"},{"ja":"～らしい (N4): Đúng kiểu..., ra dáng...","romaji":"","vi":""},{"ja":"～がち (N3): Hay... (thường chỉ thói quen xấu).","romaji":"","vi":""},{"ja":"～気味 (N3): Hơi... (chỉ mức độ nhẹ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('99.  さえ  - Ngay cả; đến mức; thậm chí ~', 'N3', 'Dùng để đưa ra một ví dụ cực đoan, nhằm nhấn mạnh rằng đến cả trường hợp đó cũng như vậy (thì những trường hợp khác là đương nhiên).', 'N (+ Trợ từ) +  さえ', '[{"ja":"ひらがなさえ書けないのに、漢字は無理だ。","romaji":"→ (Ngay cả Hiragana còn không viết được thì Kanji là không thể.)","vi":""},{"ja":"自分の名前さえ忘れました。","romaji":"→ (Tôi thậm chí quên cả tên mình.)","vi":""},{"ja":"子供でさえ知っている。","romaji":"→ (Ngay cả trẻ con cũng biết.)","vi":"──────────"},{"ja":"～だって (N4): Ngay cả (văn nói).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('100.  さえ～ば  - Chỉ cần; miễn là ~', 'N3', 'Dùng để chỉ ra một điều kiện tối thiểu và duy nhất, nếu điều kiện đó được đáp ứng thì vế sau sẽ xảy ra.', 'N +  さえ + V-ば / Adj-ければ / Adj-な +  なら / N +  なら   V-ます (bỏ  ます) +  さえ +  すれば', '[{"ja":"あなたさえいれば、何もいらない。","romaji":"→ (Chỉ cần có anh thì em không cần gì cả.)","vi":""},{"ja":"体さえ丈夫なら、どんな仕事もできる。","romaji":"→ (Chỉ cần cơ thể khỏe mạnh thì việc gì cũng có thể làm được.)","vi":""},{"ja":"薬を飲みさえすれば、治りますよ。","romaji":"→ (Chỉ cần uống thuốc là sẽ khỏi thôi.)","vi":"──────────"},{"ja":"～ば /  ～たら (N4): Nếu...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('101.  際に  (さいに) - Khi; vào lúc; trong trường hợp ~', 'N3', 'Là cách nói trang trọng của  ～とき, dùng để chỉ thời điểm hoặc trường hợp một hành động nào đó diễn ra. Thường dùng trong các thông báo, hướng dẫn, văn bản trang trọng.', 'N +  の +  際に / V-る / V-た +  際に', '[{"ja":"お申し込みの際には、印鑑が必要です。","romaji":"→ (Khi đăng ký, cần có con dấu.)","vi":""},{"ja":"図書館を利用する際には、カードを提示してください。","romaji":"→ (Khi sử dụng thư viện, xin hãy xuất trình thẻ.)","vi":""},{"ja":"緊急の際には、このボタンを押してください。","romaji":"→ (Trong trường hợp khẩn cấp, hãy nhấn nút này.)","vi":"──────────"},{"ja":"～場合 (N4): Trong trường hợp (nhấn mạnh tình huống giả định).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('102.  最中に  (さいちゅうに) - Trong khi; trong lúc; giữa lúc ~', 'N3', 'Diễn tả một hành động hoặc sự việc khác xảy ra đúng vào lúc cao điểm, giữa lúc một hành động/sự việc khác đang diễn ra. Thường là những hành động chen ngang, bất ngờ hoặc gây cản trở.', 'N +  の +  最中に / V-ている +  最中に', '[{"ja":"食事の最中に、電話が鳴った。","romaji":"→ (Đúng lúc đang ăn cơm thì điện thoại reo.)","vi":""},{"ja":"会議をしている最中に、停電になった。","romaji":"→ (Đang giữa lúc họp thì mất điện.)","vi":"──────────"},{"ja":"～うちに (N3): Trong khi (nhấn mạnh sự thay đổi hoặc làm trước khi thay đổi).","romaji":"","vi":""},{"ja":"～ているところだ (N4): Đang đúng lúc làm...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('103.  さらに  - Hơn nữa; lại; ngày càng nhiều ~', 'N3', 'Là một trạng từ, dùng để bổ sung thêm thông tin, hoặc chỉ mức độ tăng tiến, mạnh hơn nữa.', 'さらに + Câu / Adj / Adv', '[{"ja":"彼は英語が話せる。さらに、フランス語も話せる。","romaji":"→ (Anh ấy nói được tiếng Anh. Hơn nữa, còn nói được cả tiếng Pháp.)","vi":""},{"ja":"雨が降り出し、さらに風も強くなった。","romaji":"→ (Trời bắt đầu mưa, và gió lại càng mạnh hơn.)","vi":"──────────"},{"ja":"その上 (N3): Thêm vào đó.","romaji":"","vi":""},{"ja":"しかも (N3): Hơn nữa, vả lại.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('104.  さて  - Nào; bây giờ; vậy thì ~', 'N3', 'Là một liên từ, dùng để bắt đầu một câu chuyện, chuyển sang một chủ đề mới, hoặc thu hút sự chú ý trước khi nói điều gì đó quan trọng hoặc đặt câu hỏi.', 'さて、+ Câu.', '[{"ja":"さて、次の問題に移りましょう。","romaji":"→ (Nào, chúng ta hãy chuyển sang vấn đề tiếp theo.)","vi":""},{"ja":"さて、今日の会議を始めます。","romaji":"→ (Bây giờ, chúng ta sẽ bắt đầu cuộc họp hôm nay.)","vi":"──────────"},{"ja":"それでは (N5): Vậy thì... (lịch sự hơn).","romaji":"","vi":""},{"ja":"ところで (N3): Nhân tiện (dùng để chuyển chủ đề đột ngột).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('105.  せいで  - Vì; do; kết quả của ~', 'N3', 'Dùng để chỉ nguyên nhân dẫn đến một kết quả xấu, tiêu cực. Thường mang sắc thái đổ lỗi, trách móc.  ～せいか dùng khi không chắc chắn về nguyên nhân.', 'V/Adj/N-thể thường +  せいで /  せいだ /  せいか', '[{"ja":"あなたのせいで、私は遅刻しました。","romaji":"→ (Tại bạn mà tôi đã đi muộn.)","vi":""},{"ja":"寝不足のせいか、頭が痛い。","romaji":"→ (Có lẽ tại vì thiếu ngủ nên tôi bị đau đầu.)","vi":"──────────"},{"ja":"～ので (N4): Vì... (trung tính).","romaji":"","vi":""},{"ja":"～おかげで (N3): Nhờ... (kết quả tốt).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('106.  せいぜい  - Nhiều nhất; tốt nhất; hết mức ~', 'N3', 'Là một trạng từ, dùng để chỉ mức độ tối đa có thể đạt được, nhưng thường mang hàm ý rằng mức đó không cao lắm, ít hơn so với mong đợi.', 'せいぜい + Số lượng / Mức độ', '[{"ja":"ここから駅まで歩いても、せいぜい１０分だろう。","romaji":"→ (Từ đây đi bộ đến ga thì nhiều nhất cũng chỉ mất 10 phút thôi.)","vi":""},{"ja":"この仕事はせいぜい３日で終わる。","romaji":"→ (Công việc này nhiều nhất 3 ngày là xong.)","vi":"──────────"},{"ja":"最大 (さいだい) (N3): Tối đa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('107.  しばらく  - Một lát; một lúc; trong lúc này', 'N3', 'Là một trạng từ, chỉ một khoảng thời gian tương đối (không quá ngắn cũng không quá dài).', 'しばらく + V /  しばらくです', '[{"ja":"しばらくお待ちください。","romaji":"→ (Xin vui lòng đợi một lát.)","vi":""},{"ja":"彼はしばらく黙っていた。","romaji":"→ (Anh ấy đã im lặng một lúc.)","vi":""},{"ja":"ご無沙汰しております。しばらくですね。","romaji":"→ (Lâu rồi không liên lạc. Cũng một thời gian rồi nhỉ.)","vi":"──────────"},{"ja":"しばらくぶり (N3): Lâu rồi mới...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('108.  しかない  - Không còn cách nào khác ngoài ~', 'N3', 'Diễn tả rằng không có lựa chọn nào khác, chỉ có một cách duy nhất là phải làm V.', 'V-る +  しかない', '[{"ja":"バスがないから、歩くしかない。","romaji":"→ (Vì không có xe buýt nên chỉ còn cách đi bộ.)","vi":""},{"ja":"もう時間がない。急ぐしかない。","romaji":"→ (Không còn thời gian nữa. Chỉ còn cách khẩn trương thôi.)","vi":""},{"ja":"やってみるしかないだろう。","romaji":"→ (Chắc là chỉ còn cách làm thử thôi.)","vi":"──────────"},{"ja":"～なければならない (N4): Phải làm...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('109.  そのために  - Do đó; vì lý do đó; bởi vì ~', 'N3', 'Là một liên từ, dùng để nối hai câu, chỉ ra rằng Câu 1 là nguyên nhân hoặc mục đích dẫn đến kết quả hoặc hành động ở Câu 2.', 'Câu 1.  そのために、Câu 2.', '[{"ja":"彼は一生懸命勉強した。そのため（に）、試験に合格した。","romaji":"→ (Anh ấy đã học rất chăm chỉ. Do đó, anh ấy đã đỗ kỳ thi.)","vi":""},{"ja":"来年留学したい。そのために、今から貯金している。","romaji":"→ (Tôi muốn đi du học vào năm tới. Vì vậy, tôi đang tiết kiệm tiền từ bây giờ.)","vi":"──────────"},{"ja":"それで (N4): Do đó, vậy nên.","romaji":"","vi":""},{"ja":"～ために (N4): Vì, để.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('110.  それとも  - Hoặc; hoặc là ~', 'N3', 'Là một liên từ, dùng để nối hai câu hỏi, đưa ra hai hoặc nhiều lựa chọn để người nghe chọn một.', 'Câu hỏi 1  か。それとも Câu hỏi 2  か。', '[{"ja":"コーヒーにしますか。それとも紅茶にしますか。","romaji":"→ (Bạn dùng cà phê hay là dùng trà?)","vi":""},{"ja":"バスで行きますか。それとも電車で行きますか。","romaji":"→ (Bạn đi bằng xe buýt hay là đi bằng tàu điện?)","vi":"──────────"},{"ja":"～か～か (N5): ... hay ... (cách nối cơ bản).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('111.  そうもない  /  そうにない  - Rất khó có thể; không có dấu hiệu ~', 'N3', 'Dùng để diễn tả khả năng xảy ra một việc gì đó là rất thấp, gần như không thể, dựa trên tình hình hiện tại. Đây là dạng phủ định mạnh của  ～そうだ (trông có vẻ).', 'V-ます (bỏ  ます) +  そうもない /  そうにない', '[{"ja":"今日中にこの仕事は終わりそうもない。","romaji":"→ (Trong hôm nay, công việc này khó mà xong được.)","vi":""},{"ja":"空はまだ暗い。雨はまだやみそうにない。","romaji":"→ (Trời vẫn còn tối. Mưa trông không có vẻ gì là tạnh.)","vi":"──────────"},{"ja":"～そうだ (N4 - Dạng khẳng định): Trông có vẻ...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('112.  すでに  - Đã làm/xảy ra; đã là trường hợp ~', 'N3', 'Là một trạng từ, diễn tả một hành động hoặc trạng thái đã xảy ra hoặc đã tồn tại trước một thời điểm nhất định. Trang trọng hơn  もう.', 'すでに + V-た / V-ている / N', '[{"ja":"私が駅に着いた時、電車はすでに出てしまった。","romaji":"→ (Khi tôi đến ga thì tàu đã chạy mất rồi.)","vi":""},{"ja":"この件については、すでに報告しました。","romaji":"→ (Về vụ việc này, tôi đã báo cáo rồi.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('113.  すなわち  - Nói cách khác; cụ thể là ~', 'N3', 'Là một liên từ, dùng để nối hai vế, trong đó vế sau (B) giải thích, định nghĩa, hoặc nói lại vế trước (A) bằng một cách khác, rõ ràng hơn. Thường dùng trong văn viết, giải thích trang trọng.', 'A  すなわち B', '[{"ja":"母の兄、すなわち私の伯父は、医者です。","romaji":"→ (Anh trai của mẹ tôi, tức là bác tôi, là bác sĩ.)","vi":""},{"ja":"日本の首都、すなわち東京は、世界でも有数の大都市だ。","romaji":"→ (Thủ đô của Nhật Bản, tức là Tokyo, là một trong những thành phố lớn hàng đầu thế giới.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('114.  数量  +  は  (すうりょう  +  は) - Ít nhất ~', 'N3', 'Dùng sau một từ chỉ số lượng để nhấn mạnh rằng đó là mức tối thiểu, có thể còn nhiều hơn nữa.', 'Số lượng +  は', '[{"ja":"パーティーには３０人は来るだろう。","romaji":"→ (Bữa tiệc chắc sẽ có ít nhất 30 người đến.)","vi":""},{"ja":"このプロジェクトを完成させるには、１年はかかる。","romaji":"→ (Để hoàn thành dự án này, cần ít nhất 1 năm.)","vi":"──────────"},{"ja":"～以上 (N4): ... trở lên, ít nhất là...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('115.  たものだ  - Đã từng làm; thường làm ~', 'N3', 'Dùng để hồi tưởng lại những thói quen, hành động thường xuyên xảy ra trong quá khứ, thường mang theo một chút cảm xúc hoài niệm.', 'V-た +  ものだ', '[{"ja":"子供のころ、よくこの川で泳いだものだ。","romaji":"→ (Hồi nhỏ, tôi thường hay bơi ở con sông này.)","vi":""},{"ja":"学生時代は、毎晩遅くまで勉強したものだ。","romaji":"→ (Thời sinh viên, tôi thường học đến khuya mỗi tối.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('116.  たとたん  /  たとたんに  - Ngay sau khi; vừa mới ~', 'N3', 'Diễn tả rằng ngay sau khi hành động 1 vừa kết thúc thì hành động 2 xảy ra gần như đồng thời. Vế 2 thường là một sự việc bất ngờ, không có chủ ý của người nói.', 'V-た +  とたん /  とたんに', '[{"ja":"ドアを開けたとたん、猫が飛び出してきた。","romaji":"→ (Vừa mới mở cửa ra thì con mèo phóng ra.)","vi":""},{"ja":"彼は椅子に座ったとたん、寝てしまった。","romaji":"→ (Anh ta vừa mới ngồi xuống ghế thì ngủ thiếp đi.)","vi":"──────────"},{"ja":"～てすぐ (N4): Ngay sau khi (không nhất thiết phải bất ngờ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('117.  たびに  - Mỗi khi; mỗi lần ~', 'N3', 'Diễn tả rằng cứ mỗi lần hành động V hoặc sự việc N xảy ra, thì một hành động hoặc sự việc khác cũng lặp lại theo.', 'N +  の +  たびに / V-る +  たびに', '[{"ja":"この歌を聞くたびに、故郷を思い出す。","romaji":"→ (Mỗi lần nghe bài hát này, tôi lại nhớ về quê hương.)","vi":""},{"ja":"旅行のたびに、お土産をたくさん買ってしまう。","romaji":"→ (Cứ mỗi lần đi du lịch, tôi lại lỡ mua rất nhiều quà.)","vi":"──────────"},{"ja":"いつも (N5): Luôn luôn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('118.  ために  - Cho; để; vì lợi ích của; bởi vì; kết quả của ~', 'N3', 'Nghĩa 1 (Mục đích): Diễn tả mục đích, mục tiêu của hành động.   Nghĩa 2 (Nguyên nhân): Diễn tả nguyên nhân, lý do (thường dùng trong văn viết hoặc tình huống trang trọng, có thể là kết quả tốt hoặc xấu).', 'N +  の +  ために / V-る +  ために (Mục đích)   V-thể thường / Adj-い / Adj-な / N +  の +  ために (Nguyên nhân)', '[{"ja":"家族のために、毎日働いています。","romaji":"→ (Tôi làm việc mỗi ngày vì gia đình.) - Mục đích","vi":""},{"ja":"日本へ留学するために、日本語を勉強しています。","romaji":"→ (Tôi học tiếng Nhật để đi du học Nhật Bản.) - Mục đích","vi":""},{"ja":"大雪のために、電車が遅れた。","romaji":"→ (Vì tuyết lớn nên tàu đã bị trễ.) - Nguyên nhân","vi":"──────────"},{"ja":"～には (N3): Để... (chỉ mục đích và phương pháp).","romaji":"","vi":""},{"ja":"～から /  ～ので (N5/N4): Vì... (nguyên nhân).","romaji":"","vi":""},{"ja":"～おかげで /  ～せいで (N3): Nhờ... / Tại... (nguyên nhân).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('119.  確かに  (たしかに) - Chắc chắn; nhất định ~ / Quả thật là ~', 'N3', 'Nghĩa 1: Diễn tả sự chắc chắn, tin tưởng vào điều gì đó.   Nghĩa 2: Dùng để thừa nhận một sự thật nào đó ("Đúng là..."), thường để làm đệm trước khi nói một ý kiến khác hoặc phản bác nhẹ.', '確かに + Câu / Adj / Adv', '[{"ja":"彼は確かにそう言いました。","romaji":"→ (Anh ấy chắc chắn đã nói như vậy.)","vi":""},{"ja":"確かにこのレストランは高いけれど、とても美味しい。","romaji":"→ (Đúng là nhà hàng này đắt thật, nhưng rất ngon.)","vi":"──────────"},{"ja":"もちろん (N4): Dĩ nhiên là...","romaji":"","vi":""},{"ja":"～が (N5): Nhưng...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('120.  たて  - Vừa mới làm xong; mới làm ~', 'N3', 'Diễn tả một hành động vừa mới được hoàn thành, nhấn mạnh sự tươi mới, nóng hổi, hoặc vừa mới ra lò.', 'V-ます (bỏ  ます) +  たて +  だ /  の + N', '[{"ja":"焼きたてのパンは美味しい。","romaji":"→ (Bánh mì mới nướng rất ngon.)","vi":""},{"ja":"ペンキ塗りたて。触らないでください。","romaji":"→ (Mới sơn. Xin đừng chạm vào.)","vi":"──────────"},{"ja":"～たところだ (N4): Vừa mới... (nhấn mạnh thời điểm ngay sau khi kết thúc).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('121.  たとえ～ても  - Ngay cả khi ~; Dù cho ~', 'N3', 'Dùng để nhấn mạnh một tình huống giả định (dù là khó xảy ra hoặc cực đoan), và khẳng định rằng dù tình huống đó có xảy ra đi nữa thì kết quả ở vế sau vẫn không thay đổi.', 'たとえ + V-ても / Adj-くても / N/Adj-な +  でも', '[{"ja":"たとえ両親に反対されても、私は彼と結婚します。","romaji":"→ (Dù cho bố mẹ có phản đối, tôi vẫn sẽ kết hôn với anh ấy.)","vi":""},{"ja":"たとえどんなに難しくても、諦めません。","romaji":"→ (Dù cho có khó khăn đến mấy, tôi cũng sẽ không bỏ cuộc.)","vi":"──────────"},{"ja":"どんなに～ても (N3): Dù... đến đâu...","romaji":"","vi":""},{"ja":"いくら～ても (N3): Dù... bao nhiêu...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('122.  例えば  (たとえば) - Ví dụ; chẳng hạn ~', 'N3', 'Là một trạng từ, dùng để đưa ra một ví dụ cụ thể để minh họa cho điều đang nói.', '例えば + Câu / N', '[{"ja":"日本には美しい都市がたくさんあります。例えば、京都や奈良などです。","romaji":"→ (Nhật Bản có rất nhiều thành phố đẹp. Ví dụ như Kyoto hay Nara.)","vi":""},{"ja":"好きな果物はたくさんあります。例えば、りんご、バナナ、みかんです。","romaji":"→ (Tôi thích rất nhiều loại trái cây. Chẳng hạn như táo, chuối, quýt.)","vi":"──────────"},{"ja":"～とか (N4): Hoặc là..., như là...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('123.  たって  - Ngay cả khi; mặc dù; dù thế nào đi nữa ~', 'N3', 'Là dạng văn nói, thân mật của  ～ても /  ～でも. Diễn tả ý nghĩa "dù... thì cũng...".', 'V-たって / Adj-くたって / N/Adj-な +  だって', '[{"ja":"今から急いだって、もう間に合わないよ。","romaji":"→ (Bây giờ dù có vội thì cũng không kịp nữa đâu.)","vi":""},{"ja":"嫌いだったって、食べなければならない。","romaji":"→ (Dù ghét thì cũng phải ăn.)","vi":"──────────"},{"ja":"～にしても (N3): Dù... thì cũng...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('124.  てばかりいる  - Chỉ; không gì khác ngoài ~', 'N3', 'Diễn tả rằng ai đó chỉ làm đi làm lại một hành động nào đó, thường mang sắc thái phàn nàn, chỉ trích hoặc không hài lòng.', 'V-て +  ばかりいる', '[{"ja":"彼は寝てばかりいる。","romaji":"→ (Anh ta cứ ngủ suốt.)","vi":""},{"ja":"ゲームをしてばかりいないで、勉強しなさい。","romaji":"→ (Đừng có chơi game suốt nữa, học đi!)","vi":"──────────"},{"ja":"～だけ (N5): Chỉ...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('125.  てごらん  /  てごらんなさい  - (Hãy) thử; (hãy) nhìn', 'N3', 'Là một dạng mệnh lệnh hoặc gợi ý nhẹ nhàng, thường được dùng bởi người lớn (bố mẹ, thầy cô) nói với trẻ em hoặc người dưới, có nghĩa là "hãy thử làm...".', 'V-て +  ごらん /  ごらんなさい', '[{"ja":"分からなかったら、先生に聞いてごらん。","romaji":"→ (Nếu không hiểu thì hãy thử hỏi thầy xem.)","vi":""},{"ja":"ほら、きれいな花が咲いてごらん。","romaji":"→ (Này, nhìn hoa đẹp nở kìa.)","vi":"──────────"},{"ja":"～てみてください (N4): Xin hãy thử làm xem (lịch sự).","romaji":"","vi":""},{"ja":"～てください (N5): Xin hãy...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('126.  てはじめて  - Mãi cho đến khi; chỉ sau khi [x] tôi mới ~', 'N3', 'Nhấn mạnh rằng chỉ sau khi trải qua hành động V, người nói mới nhận ra, hiểu ra hoặc có được một kinh nghiệm nào đó lần đầu tiên.', 'V-て +  はじめて', '[{"ja":"日本に来てはじめて、寿司を食べました。","romaji":"→ (Chỉ sau khi đến Nhật tôi mới ăn sushi lần đầu.)","vi":""},{"ja":"病気になってはじめて、健康のありがたみが分かった。","romaji":"→ (Chỉ sau khi bị bệnh tôi mới hiểu được sự quý giá của sức khỏe.)","vi":"──────────"},{"ja":"～後で (N5): Sau khi...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('127.  てからでないと  /  てからでなければ  - Phải làm trước; không thể làm nếu không làm trước ~', 'N3', 'Diễn tả rằng hành động ở vế sau không thể thực hiện được nếu hành động ở vế trước chưa được hoàn thành.', 'V-て +  からでないと /  からでなければ + V-ない /  できない /  難 しい...', '[{"ja":"宿題をしてからでないと、遊びに行けません。","romaji":"→ (Nếu chưa làm xong bài tập thì không thể đi chơi được.)","vi":""},{"ja":"よく考えてからでなければ、返事はできない。","romaji":"→ (Nếu chưa suy nghĩ kỹ thì không thể trả lời được.)","vi":"──────────"},{"ja":"～ないと (N3): Phải...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('128.  てしょうがない・てしかたがない  - Không thể không; rất; cực kỳ ~', 'N3', 'Dùng để diễn tả một cảm xúc, trạng thái hoặc mong muốn mạnh mẽ đến mức không thể kiềm chế hay kiểm soát được.', 'V-て / Adj-くて / Adj-な +  で +  しょうがない /  しかたがない', '[{"ja":"嬉しくてしょうがない。","romaji":"→ (Tôi vui không chịu được.)","vi":""},{"ja":"眠くてしかたがない。","romaji":"→ (Tôi buồn ngủ không chịu được.)","vi":""},{"ja":"会いたくてしょうがない。","romaji":"→ (Tôi muốn gặp không chịu được.)","vi":"──────────"},{"ja":"とても (N5): Rất.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('129.  て済む  (てすむ) - Đủ bằng cách ~; giải quyết bằng cách ~', 'N3', 'Diễn tả rằng một vấn đề có thể được giải quyết hoặc chỉ cần/đủ bằng cách làm V hoặc chỉ cần N, không cần đến những biện pháp phức tạp hay tốn kém hơn. Thường dùng ở dạng phủ định (～ないで済む - không cần làm cũng xong) hoặc với  だけ (～だけで済む - chỉ cần... là xong).', 'V-て +  済む / N +  で +  済む', '[{"ja":"謝るだけで済む問題ではない。","romaji":"→ (Đây không phải là vấn đề chỉ cần xin lỗi là xong.)","vi":""},{"ja":"軽い怪我だったので、病院に行かないで済んだ。","romaji":"→ (Vì là vết thương nhẹ nên không cần đến bệnh viện cũng xong.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('130.  てはいけないから  - Để không ~; Vì không được ~', 'N3', 'Dùng để giải thích lý do cho một hành động hoặc một lời khuyên, trong đó lý do là "vì không được phép" hoặc "vì sẽ gây ra hậu quả xấu" nếu làm V.', 'V-ては +  いけない /  ならない +  から', '[{"ja":"危ないから、入ってはいけないから、柵があります。","romaji":"→ (Vì nguy hiểm, và vì không được vào, nên có hàng rào.)","vi":""},{"ja":"大事な試験だから、遅刻してはいけないから、早く寝ます。","romaji":"→ (Vì là kỳ thi quan trọng, và vì không được đi muộn, nên tôi sẽ ngủ sớm.)","vi":"──────────"},{"ja":"～てはいけない (N5): Không được...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('131.  ている場合じゃない  (ているばあいじゃない) - Đây không phải là lúc để làm ~', 'N3', 'Diễn tả rằng tình hình hiện tại đang rất cấp bách, nghiêm trọng hoặc không phù hợp để thực hiện hành động V.', 'V-ている +  場合ではない /  場合じゃない', '[{"ja":"地震だ！のんびりしている場合じゃない。早く逃げろ！(Động đất kìa! Đây không phải là lúc để thong thả. Nhanh chạy đi!)","romaji":"","vi":""},{"ja":"もうすぐ試験なのに、遊んでいる場合じゃないよ。","romaji":"→ (Sắp thi đến nơi rồi, đây không phải là lúc để chơi đâu.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('132.  的  (てき) - Mang tính ~; Thuộc về ~', 'N3', 'Là một hậu tố, thêm vào sau danh từ (thường là danh từ gốc Hán) để biến danh từ đó thành:   Tính từ  な: Khi đi với  な, nó bổ nghĩa cho danh từ, mang ý nghĩa "mang tính chất...", "thuộc về...".   Trạng từ: Khi đi với  に, nó bổ nghĩa cho động từ/tính từ, mang ý nghĩa "về mặt...", "một cách...".', 'N +  的 (てき) +  な + N / N +  的 (てき) +  に + V/Adj', '[{"ja":"彼は科学的な方法で問題を解決した。","romaji":"→ (Anh ấy đã giải quyết vấn đề bằng phương pháp mang tính khoa học.)","vi":""},{"ja":"国際的に有名な歌手。","romaji":"→ (Ca sĩ nổi tiếng mang tầm quốc tế.)","vi":""},{"ja":"個人的には、私はその意見に賛成です。","romaji":"→ (Về mặt cá nhân thì tôi đồng ý với ý kiến đó.)","vi":"──────────"},{"ja":"～っぽい (N3): Trông như..., có vẻ...","romaji":"","vi":""},{"ja":"～のような (N4): Giống như...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('133.  ても始まらない  (てもはじまらない) - Dù có ~ cũng vô ích; không có ích gì ~', 'N3', 'Diễn tả rằng dù có làm hành động V (thường là than vãn, hối tiếc, lo lắng), thì cũng chẳng giải quyết được gì, chẳng có gì bắt đầu hay thay đổi được, tức là vô ích.', 'V-ても +  始まらない (はじまらない)', '[{"ja":"終わったことを今さら悔やんでも始まらない。","romaji":"→ (Việc đã qua rồi, bây giờ có hối hận cũng chẳng được gì.)","vi":""},{"ja":"心配しても始まらない。まずは行動しよう。","romaji":"→ (Có lo lắng cũng vô ích. Trước hết hãy hành động đi.)","vi":"──────────"},{"ja":"～てもしょうがない (N3): Dù có... cũng chẳng làm được gì.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('134.  ても構わない  (てもかまわない) - Không sao nếu ~; Không phiền nếu ~', 'N3', 'Dùng để cho phép ai đó làm gì, diễn tả rằng việc đó không thành vấn đề, không gây phiền hà. Lịch sự và mềm mại hơn  ～てもいい.', 'V-ても / Adj-くても / N/Adj-な +  でも +  構わない (かまわない)', '[{"ja":"もし都合が悪ければ、明日来ても構いません。","romaji":"→ (Nếu không tiện thì ngày mai bạn đến cũng không sao ạ.)","vi":""},{"ja":"ここに座っても構いませんか。","romaji":"→ (Tôi ngồi đây có được không ạ?)","vi":"──────────"},{"ja":"～ても大丈夫だ (N4): ... cũng không sao.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('135.  てもしょうがない  /  てもしかたがない  - Vô ích ~; không có ích gì ~; không thể làm gì khác', 'N3', 'Tương tự  ～ても始まらない, diễn tả rằng dù có làm V thì cũng vô ích, không mang lại kết quả gì, hoặc không thể thay đổi được tình hình.', 'V-ても +  しょうがない /  しかたがない', '[{"ja":"今更急いでもしょうがない。もう間に合わない。","romaji":"→ (Bây giờ có vội cũng chẳng được gì. Đã không kịp nữa rồi.)","vi":""},{"ja":"済んでしまったことは、悔やんでもしかたがない。","romaji":"→ (Việc đã qua rồi, có hối tiếc cũng đành chịu.)","vi":"──────────"},{"ja":"～ても始まらない (N3): Dù có... cũng chẳng được gì.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('136.  と言えば  (といえば) - Nói đến; khi bạn nói về; nếu là trường hợp ~', 'N3', 'Dùng để lấy một từ hoặc chủ đề vừa được nhắc đến trong cuộc hội thoại để đưa ra một ý nghĩ, liên tưởng hoặc thông tin liên quan.', 'N / V/Adj/N-thể thường +  と言えば', '[{"ja":"A:  来週、京都へ行きます。","romaji":"→ (Tuần sau tôi đi Kyoto.)","vi":"B:  京都と言えば、 紅葉の季節ですね。"},{"ja":"日本料理と言えば、やはり寿司でしょう。","romaji":"→ (Nói về món ăn Nhật thì chắc chắn là sushi rồi.)","vi":"──────────"},{"ja":"～について (N4): Về...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('137.  といい  /  たらいい  - Sẽ tốt nếu; nên; tôi hy vọng ~', 'N3', 'Dùng để diễn tả mong muốn, hy vọng của người nói (cho bản thân hoặc người khác). Cũng có thể dùng để đưa ra gợi ý nhẹ nhàng.', 'V-thể thường +  といい (のに /  なあ) / V-たら +  いい (のに /  なあ)', '[{"ja":"明日、晴れるといいな。","romaji":"→ (Ước gì ngày mai trời nắng nhỉ.)","vi":""},{"ja":"もっと早く着いたらいいのに。","romaji":"→ (Giá mà đến sớm hơn thì tốt.)","vi":""},{"ja":"疲れたら、少し休むといい。","romaji":"→ (Nếu mệt thì nên nghỉ một chút.)","vi":"──────────"},{"ja":"～たい (N5): Muốn...","romaji":"","vi":""},{"ja":"～てほしい (N4): Muốn ai đó làm...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('138.  といっても  - Mặc dù nói là; tuy nói là ~', 'N3', 'Dùng để bổ sung, điều chỉnh hoặc làm rõ một phát biểu đã đưa ra trước đó, thường là để nói rằng mức độ không cao hoặc phạm vi không rộng như người nghe có thể hình dung.', 'N / V/Adj-thể thường +  といっても', '[{"ja":"日本料理が好きだといっても、寿司しか食べられません。","romaji":"→ (Tuy nói là thích món Nhật nhưng tôi chỉ ăn được sushi thôi.)","vi":""},{"ja":"彼は社長だといっても、社員は３人だけです。","romaji":"→ (Tuy nói anh ấy là giám đốc nhưng nhân viên chỉ có 3 người.)","vi":"──────────"},{"ja":"～のに (N4): Mặc dù...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('139.  ということだ  - Tôi nghe nói; có nghĩa là; nói cách khác ~', 'N3', 'Nghĩa 1 (Truyền đạt): Dùng để truyền đạt lại thông tin nghe được. (Tương tự ～そうだ).   Nghĩa 2 (Giải thích/Kết luận): Dùng để giải thích ý nghĩa hoặc đưa ra kết luận từ một sự việc. (Tương tự  つまり).', 'V/Adj/N-thể thường +  ということだ', '[{"ja":"天気予報によると、明日は雨が降るということだ。","romaji":"→ (Theo dự báo thời tiết, nghe nói ngày mai trời sẽ mưa.)","vi":""},{"ja":"試験の結果が悪いということは、もっと勉強しなければならないということだ。","romaji":"→ (Kết quả thi kém, điều đó có nghĩa là phải học nhiều hơn nữa.)","vi":"──────────"},{"ja":"～んだって (N3): Nghe nói là... (văn nói).","romaji":"","vi":""},{"ja":"つまり (N3): Tức là...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('140.  というのは  - Điều này có nghĩa là; ý nghĩa của… là; bởi vì; tức là ~', 'N3', 'Dùng để đưa ra một định nghĩa, giải thích ý nghĩa của một từ ngữ hoặc một sự việc.', 'N / Cụm từ +  というのは + Định nghĩa / Giải thích +  ということだ / からだ.', '[{"ja":"「立ち入り禁止」というのは、入ってはいけないという意味です。 (“Tachi-iri kinshi” có nghĩa là không được vào.)","romaji":"","vi":""},{"ja":"彼が来ないというのは、何か理由があるのだろう。","romaji":"→ (Việc anh ấy không đến, tức là có lý do gì đó chăng.)","vi":"──────────"},{"ja":"つまり (N3): Tức là...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('141.  と言うと  (というと) - Nói đến; khi bạn nói về ~', 'N3', 'Tương tự  ～と言えば, dùng để lấy một từ/chủ đề làm điểm xuất phát:   Đưa ra liên tưởng tức thì, phổ biến nhất.   Hỏi lại để xác nhận ý người nói.', 'N / Cụm từ +  と言うと', '[{"ja":"日本の食べ物と言うと、まず寿司が思い浮かびます。","romaji":"→ (Nói đến đồ ăn Nhật thì trước hết tôi nghĩ đến sushi.)","vi":""},{"ja":"A:  明日、山田さんが来ます。","romaji":"→ (Mai anh Yamada sẽ đến.)","vi":"B:  山田さんというと、あの背が高い人ですか。"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('142.  というより  - Hơn là ~', 'N3', 'Dùng khi muốn nói rằng cách diễn đạt B phù hợp hơn, chính xác hơn so với cách diễn đạt A.', 'A +  というより + B', '[{"ja":"この部屋は涼しいというより寒いくらいだ。","romaji":"→ (Căn phòng này nói là mát thì đúng hơn là lạnh.)","vi":""},{"ja":"彼は学者というより、むしろ小説家だ。","romaji":"→ (Anh ta nói là học giả thì đúng hơn là một tiểu thuyết gia.)","vi":"──────────"},{"ja":"～より (N5): Hơn là (so sánh cơ bản).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('143.  とみえる  /  とみえて  - Có vẻ như ~', 'N3', 'Dùng để diễn tả sự phán đoán của người nói dựa trên những gì quan sát được từ bên ngoài (hành động, dáng vẻ, tình hình).', 'V/Adj/N-thể thường +  とみえる /  とみえて', '[{"ja":"彼は疲れているとみえる。顔色が悪い。","romaji":"→ (Anh ấy trông có vẻ mệt. Sắc mặt kém.)","vi":""},{"ja":"雨が降ったとみえて、道が濡れている。","romaji":"→ (Trông có vẻ như trời đã mưa, đường sá ướt hết.)","vi":"──────────"},{"ja":"～そうだ (N4): Trông có vẻ (dựa trên quan sát trực tiếp).","romaji":"","vi":""},{"ja":"～らしい (N4): Có vẻ là (dựa trên thông tin nghe được hoặc đặc tính).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('144.  とすれば・としたら・とすると  - Trong trường hợp ~; giả sử ~; nếu A thì B', 'N3', 'Dùng để đưa ra một giả định hoặc một tình huống giả định, rồi dựa vào đó để suy luận, phán đoán hoặc nêu lên hành động tiếp theo.', 'V/Adj/N-thể thường +  とすれば /  としたら /  とすると', '[{"ja":"もし留学するとしたら、どの国へ行きたいですか。","romaji":"→ (Nếu giả sử đi du học thì bạn muốn đi nước nào?)","vi":""},{"ja":"それが本当だとすれば、大変なことになる。","romaji":"→ (Nếu đó là sự thật thì sẽ thành chuyện lớn đấy.)","vi":"──────────"},{"ja":"～たら (N4): Nếu...","romaji":"","vi":""},{"ja":"～なら (N4): Nếu... (dựa trên thông tin có sẵn).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('145.  と共に  (とともに) - Cùng với; đồng thời với; cũng như ~', 'N3', 'Nghĩa 1: Cùng với... (Tương tự  と一緒に).   Nghĩa 2: Cùng lúc với..., đồng thời với... (Khi A thay đổi thì B cũng thay đổi theo).', 'N +  と共に / V-る +  と共に', '[{"ja":"家族と共に日本へ来た。","romaji":"→ (Tôi đã đến Nhật cùng với gia đình.) - Nghĩa 1","vi":""},{"ja":"年を取ると共に、記憶力が悪くなる。","romaji":"→ (Cùng với việc có tuổi, trí nhớ cũng kém đi.) - Nghĩa 2","vi":"──────────"},{"ja":"～につれて (N3): Cùng với (Nghĩa 2).","romaji":"","vi":""},{"ja":"～にしたがって (N3): Cùng với (Nghĩa 2).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('146.  途中で  /  途中に  (とちゅうで  /  とちゅうに) - Trên đường; giữa chừng ~', 'N3', 'Diễn tả một địa điểm hoặc thời điểm "đang trên đường" đi đâu đó hoặc "đang giữa chừng" làm việc gì đó.   途中で: Thường chỉ hành động xảy ra tại điểm đó.   途中に: Thường chỉ sự tồn tại tại điểm đó.', 'N +  の +  途中で /  途中に; V-る +  途中で /  途中に', '[{"ja":"学校へ来る途中で、友達に会いました。","romaji":"→ (Trên đường đến trường, tôi đã gặp bạn.)","vi":""},{"ja":"マラソンの途中で、気分が悪くなった。","romaji":"→ (Giữa chừng cuộc thi marathon, tôi cảm thấy không khỏe.)","vi":""},{"ja":"駅へ行く途中に、コンビニがあります。","romaji":"→ (Trên đường đến ga có cửa hàng tiện lợi.)","vi":"──────────"},{"ja":"～間に (N4): Trong lúc...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('147.  ところで  - Nhân tiện ~', 'N3', 'Là một liên từ, dùng để chuyển chủ đề câu chuyện một cách đột ngột sang một chủ đề khác không liên quan hoặc ít liên quan.', 'ところで、+ Câu.', '[{"ja":"今日の会議はこれで終わります。ところで、来週のパーティーはどうしますか。","romaji":"→ (Cuộc họp hôm nay kết thúc ở đây. Nhân tiện, bữa tiệc tuần sau thì sao nhỉ?)","vi":""},{"ja":"彼は元気そうだね。ところで、山田さんは最近どうしてる？(Anh ấy trông khỏe nhỉ. À này, dạo này anh Yamada thế nào?)","romaji":"──────────","vi":"Ngữ pháp tương tự:"},{"ja":"では (N5): Vậy thì.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('148.  ところが  - Mặc dù vậy; tuy nhiên; mặc dù ~', 'N3', 'Là một liên từ, dùng để nối hai câu, trong đó vế sau (Câu 2) thể hiện một kết quả hoặc sự việc bất ngờ, trái ngược hoàn toàn với những gì được dự đoán hoặc mong đợi từ vế trước (Câu 1).', 'Câu 1 +  ところが + Câu 2', '[{"ja":"彼は勉強しなかった。ところが、試験に合格した。","romaji":"→ (Cậu ta chẳng học hành gì. Thế nhưng lại đỗ kỳ thi.)","vi":""},{"ja":"絶対に間に合うと思った。ところが、電車が遅れて遅刻してしまった 。","romaji":"→ (Tôi đã nghĩ là tuyệt đối sẽ kịp. Tuy nhiên, tàu bị trễ nên tôi đã đi muộn.)","vi":"──────────"},{"ja":"～けれど (N4): Nhưng...","romaji":"","vi":""},{"ja":"しかし (N4): Tuy nhiên (trang trọng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('149.  とおりに  - Theo cách ~; như ~', 'N3', 'Diễn tả rằng một hành động được thực hiện đúng y như, theo đúng như một chỉ thị, kế hoạch, suy nghĩ, hoặc một hành động khác đã diễn ra.', 'N +  の +  とおりに / V-る / V-た +  とおりに', '[{"ja":"私が言ったとおりに、書いてください。","romaji":"→ (Hãy viết theo đúng như những gì tôi đã nói.)","vi":""},{"ja":"説明書のとおりに、組み立てた。","romaji":"→ (Tôi đã lắp ráp theo đúng như sách hướng dẫn.)","vi":""},{"ja":"予想したとおりに、彼は来た。","romaji":"→ (Đúng như tôi dự đoán, anh ấy đã đến.)","vi":"──────────"},{"ja":"～ままに (N4): Cứ để nguyên như...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('150.  通す  (とおす) - Làm cho đến cuối; tiếp tục làm; qua ~', 'N3', 'Nghĩa 1: Diễn tả việc làm một hành động từ đầu đến cuối một cách trọn vẹn.   Nghĩa 2: Diễn tả việc giữ vững, tiếp tục một hành động hoặc trạng thái mà không bỏ cuộc.', 'V-ます (bỏ  ます) +  通す', '[{"ja":"彼はその本を一日で読み通した。","romaji":"→ (Anh ấy đã đọc suốt quyển sách đó trong một ngày.) - Nghĩa 1","vi":""},{"ja":"困難があっても、最後までやり通すつもりだ。","romaji":"→ (Dù có khó khăn, tôi vẫn định sẽ làm cho đến cùng.) - Nghĩa 2","vi":"──────────"},{"ja":"～続ける (N4): Tiếp tục làm...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('151.  として  - Như là; với vai trò là ~', 'N3', 'Dùng để chỉ tư cách, vai trò, lập trường, hoặc danh nghĩa của một người hoặc vật.', 'N +  として', '[{"ja":"彼は留学生として日本へ来た。","romaji":"→ (Anh ấy đến Nhật với tư cách là một du học sinh.)","vi":""},{"ja":"これは薬として使われる。","romaji":"→ (Cái này được dùng như là thuốc.)","vi":""},{"ja":"一人の人間として、彼の行動は許せない。","romaji":"→ (Với tư cách là một con người, tôi không thể tha thứ cho hành động của anh ta.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('152.  とても～ない  - Không thể nào; hầu như không ~', 'N3', 'Dùng để nhấn mạnh rằng một hành động nào đó là hoàn toàn không thể thực hiện được, vượt quá khả năng.', 'とても + V-ない / V-れない (Thể khả năng phủ định)', '[{"ja":"こんなにたくさんの料理は、一人ではとても食べられない。","romaji":"→ (Nhiều món ăn thế này thì một mình tôi không tài nào ăn hết được.)","vi":""},{"ja":"1 時間でこのレポートを書くのはとてもできない。","romaji":"→ (Viết bản báo cáo này trong 1 tiếng là không thể nào làm được.)","vi":"──────────"},{"ja":"決して～ない (N3): Tuyệt đối không.","romaji":"","vi":""},{"ja":"できない (N5): Không thể.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('153.  とは限らない  (とはかぎらない) - Không nhất thiết là vậy; không phải lúc nào cũng đúng', 'N3', 'Diễn tả rằng một điều gì đó được cho là đúng, phổ biến hoặc là quy luật chung nhưng không phải lúc nào cũng áp dụng, vẫn có ngoại lệ.', 'V/Adj/N-thể thường +  とは限らない', '[{"ja":"日本人だからといって、みんな寿司が好きだとは限らない。","romaji":"→ (Dù nói là người Nhật nhưng không hẳn là ai cũng thích sushi.)","vi":""},{"ja":"お金持ちが必ずしも幸せだとは限らない。","romaji":"→ (Người giàu không nhất thiết lúc nào cũng hạnh phúc.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('154.  つい  - Vô tình; không cố ý; lỡ ~', 'N3', 'Là một trạng từ, diễn tả một hành động được thực hiện một cách vô thức, không có chủ ý, thường là do thói quen, sự hấp dẫn hoặc sơ suất. Thường đi kèm với ～てしまう.', 'つい + V-てしまう / V-る', '[{"ja":"ダイエット中なのに、ついケーキを食べてしまった。","romaji":"→ (Đang ăn kiêng vậy mà tôi lại lỡ ăn bánh kem mất rồi.)","vi":""},{"ja":"秘密だと知っていたのに、つい話してしまった。","romaji":"→ (Dù biết là bí mật nhưng tôi lại lỡ nói ra mất.)","vi":"──────────"},{"ja":"思わず (N3): Bất giác, không kìm được.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('155.  ついに  - Cuối cùng; rốt cuộc ~', 'N3', 'Dùng để chỉ kết quả cuối cùng sau một quá trình dài chờ đợi, nỗ lực hoặc biến đổi. Có thể là kết quả tích cực hoặc tiêu cực.', 'ついに + V-た / V-なかった', '[{"ja":"長年の夢だった自分の店をついに持つことができた。","romaji":"→ (Cuối cùng tôi cũng đã có được cửa hàng của riêng mình, là ước mơ bao năm qua.)","vi":""},{"ja":"彼は何度も挑戦したが、ついに成功しなかった。","romaji":"→ (Anh ấy đã thử thách nhiều lần nhưng cuối cùng đã không thành công.)","vi":"──────────"},{"ja":"結局 (N3): Rốt cuộc thì (thường chỉ kết quả sau khi cân nhắc, đôi khi không như ý).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('156.  ついでに  - Nhân tiện; đồng thời; trên đường ~', 'N3', 'Diễn tả việc tận dụng cơ hội khi thực hiện một hành động chính (A) để làm thêm một hành động phụ (B).', 'N +  の +  ついでに / V-る / V-た +  ついでに', '[{"ja":"コンビニへ行くついでに、手紙を出してくれませんか。","romaji":"→ (Nhân tiện đi cửa hàng tiện lợi, bạn gửi giúp tôi lá thư được không?)","vi":""},{"ja":"散歩のついでに、牛乳を買ってきた。","romaji":"→ (Nhân tiện đi dạo, tôi đã mua sữa về.)","vi":"──────────"},{"ja":"～とき (N5): Khi...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('157.  つまり  - Nói cách khác; tóm lại; nói tóm lại ~', 'N3', 'Là một liên từ, dùng để tóm tắt, giải thích lại hoặc đưa ra kết luận cho những gì đã nói ở vế trước bằng một cách nói khác, dễ hiểu hơn.', 'Câu 1.  つまり、Câu 2.', '[{"ja":"父の兄の子供、つまり私のいとこは、医者です。","romaji":"→ (Con của anh trai bố tôi, tức là anh họ tôi, là bác sĩ.)","vi":""},{"ja":"彼は会議に来なかった。つまり、この計画に反対なのだろう。","romaji":"→ (Anh ta không đến cuộc họp. Tóm lại, có lẽ anh ta phản đối kế hoạch này.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('158.  つもりだった  - Tôi đã nghĩ ~; tôi tin rằng ~; đã định ~; đã có ý định ~', 'N3', 'Diễn tả một ý định, dự định hoặc một suy nghĩ đã có trong quá khứ, nhưng thực tế đã không xảy ra hoặc khác đi so với dự định đó.', 'V-る / V-ない +  つもりだった', '[{"ja":"昨日は買い物に行くつもりだったが、雨で中止した。","romaji":"→ (Hôm qua tôi đã định đi mua sắm nhưng vì mưa nên đã hủy.)","vi":""},{"ja":"彼は手伝ってくれるつもりだったらしいが、急用ができた。","romaji":"→ (Anh ấy hình như đã định giúp nhưng lại có việc gấp.)","vi":"──────────"},{"ja":"～ようと思った (N4): Đã nghĩ là sẽ...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('159.  つもりで  - Với ý định làm ~; Xem như là ~', 'N3', 'Diễn tả việc làm một hành động với một ý định, cảm giác, hoặc giả định nào đó, dù thực tế có thể không hoàn toàn như vậy.', 'V-る / V-た / N +  の +  つもりで', '[{"ja":"死んだつもりで、一生懸命働いた。","romaji":"→ (Tôi đã làm việc hết sức mình xem như là đã chết rồi.)","vi":""},{"ja":"旅行に行ったつもりで、貯金しよう。","romaji":"→ (Hãy tiết kiệm tiền xem như là đã đi du lịch.)","vi":"──────────"},{"ja":"～のようだ (N4): Giống như là...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('160.  うちに  - Trong khi; trước khi ~', 'N3', 'Nghĩa 1: Diễn tả việc cần làm một hành động nào đó (vế sau) trong khi một trạng thái nào đó (vế trước) vẫn còn, trước khi nó thay đổi.   Nghĩa 2: Diễn tả rằng trong khi đang làm/đang ở trạng thái A thì có một sự thay đổi B xảy ra một cách tự nhiên.', 'N +  の +  うちに / V-る / V-ない / Adj-い / Adj-な +  うちに', '[{"ja":"日本にいるうちに、一度富士山に登りたい。","romaji":"→ (Trong khi còn ở Nhật, tôi muốn leo núi Phú Sĩ một lần.) - Nghĩa 1","vi":""},{"ja":"音楽を聞いているうちに、眠ってしまった。","romaji":"→ (Trong khi đang nghe nhạc, tôi đã ngủ quên mất.) - Nghĩa 2","vi":"──────────"},{"ja":"～最中に (N3): Đúng vào lúc...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('161.  上で  (うえで) - Khi; sau khi; để; nhằm ~', 'N3', 'Nghĩa 1: Diễn tả hành động B được thực hiện sau khi và dựa trên kết quả của hành động A. (Sau khi...).   Nghĩa 2: Diễn tả phạm vi, điều kiện hoặc khía cạnh liên quan đến một vấn đề. (Về mặt..., Khi...).', 'V-た +  上で / N +  の +  上で', '[{"ja":"よく考えた上で、返事をします。","romaji":"→ (Sau khi suy nghĩ kỹ, tôi sẽ trả lời.) - Nghĩa 1","vi":""},{"ja":"仕事の上で、大切なことは何ですか。","romaji":"→ (Trong công việc, điều quan trọng là gì?) - Nghĩa 2","vi":"──────────"},{"ja":"～ために (N4): Để (chỉ mục đích).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('162.  上に  (うえに) - Hơn nữa; ngoài ra; thêm vào đó; không chỉ… mà còn ~', 'N3', 'Dùng để bổ sung thêm một thông tin, đặc điểm nữa vào một sự việc đã nêu, và thông tin này cùng chiều hướng (cùng tốt hoặc cùng xấu) với thông tin trước.', 'V/Adj/N-thể thường +  上に', '[{"ja":"このレストランは美味しい上に、値段も安い。","romaji":"→ (Nhà hàng này không chỉ ngon mà giá còn rẻ nữa.)","vi":""},{"ja":"昨日は雨だった上に、風も強かった。","romaji":"→ (Hôm qua không chỉ mưa mà gió cũng mạnh nữa.)","vi":"──────────"},{"ja":"～だけでなく (N3): Không chỉ... mà còn...","romaji":"","vi":""},{"ja":"さらに (N3): Hơn nữa (trạng từ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('163.  は別として  (はべつとして) - Ngoại trừ; ngoài; không kể; dù có ~ hay không', 'N3', 'Dùng để tách riêng một đối tượng hoặc một vấn đề ra khỏi chủ đề chính đang nói, hàm ý rằng vấn đề đó là ngoại lệ hoặc không cần bàn đến lúc này.', 'N +  は別として', '[{"ja":"味は別として、このレストランは雰囲気がいい。","romaji":"→ (Không bàn đến vị, nhà hàng này có không khí tốt.)","vi":""},{"ja":"冗談は別として、真面目に考えてください。","romaji":"→ (Không nói chuyện đùa nữa, hãy suy nghĩ nghiêm túc đi.)","vi":"──────────"},{"ja":"～以外に (N4): Ngoài... ra.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('164.  はもちろん  - Chưa kể đến; không chỉ ... mà còn ~', 'N3', 'Dùng để nói rằng điều N là đương nhiên, rõ ràng, rồi sau đó bổ sung thêm một điều khác cũng đúng (thường là ở mức độ cao hơn hoặc đáng chú ý hơn).', 'N +  はもちろん', '[{"ja":"彼は英語はもちろん、フランス語も話せる。","romaji":"→ (Anh ấy tiếng Anh thì đương nhiên rồi, tiếng Pháp cũng nói được nữa.)","vi":""},{"ja":"この店は料理はもちろん、サービスも素晴らしい。","romaji":"→ (Quán này đồ ăn thì khỏi nói rồi, dịch vụ cũng tuyệt vời.)","vi":"──────────"},{"ja":"～ばかりでなく (N3): Không chỉ... mà còn...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('165.  は～で有名  (は～でゆうめい) - Nổi tiếng về ~', 'N3', 'Dùng để nói rằng một người, một vật, hoặc một địa điểm nào đó (N1) nổi tiếng vì một đặc điểm, sản phẩm, hoặc sự kiện nào đó (N2).', 'N1 +  は + N2 +  で有名だ', '[{"ja":"京都は古いお寺で有名だ。","romaji":"→ (Kyoto nổi tiếng về những ngôi chùa cổ.)","vi":""},{"ja":"この店はラーメンで有名だ。","romaji":"→ (Quán này nổi tiếng về món mì ramen.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('166.  わけだ  - Vì lý do đó; thảo nào; đúng như mong đợi; sự thật là ~', 'N3', 'Dùng để đưa ra một kết luận logic, một sự thật đương nhiên hoặc một lời giải thích dựa trên những thông tin đã có.', 'V/Adj/N-thể thường +  わけだ', '[{"ja":"彼は日本に１０年も住んでいる。日本語が上手なわけだ。","romaji":"→ (Anh ấy sống ở Nhật 10 năm rồi. Thảo nào tiếng Nhật giỏi.)","vi":""},{"ja":"１０引く２は８。つまり、８足す２は１０になるわけだ。","romaji":"→ (10 trừ 2 là 8. Tức là, 8 cộng 2 sẽ bằng 10.)","vi":"──────────"},{"ja":"だから (N5): Vì vậy...","romaji":"","vi":""},{"ja":"なるほど (N4): Quả là vậy, thảo nào.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('167.  わけではない  - Không có nghĩa là; không phải là trường hợp ~', 'N3', 'Dùng để phủ định một phần hoặc phủ định một suy luận/kết luận quá vội vàng, hàm ý rằng "không hẳn là...", "không phải là lúc nào cũng...".', 'V/Adj/N-thể thường +  わけではない', '[{"ja":"嫌いだわけではないが、あまり食べたくない。","romaji":"→ (Không hẳn là ghét, nhưng tôi không muốn ăn lắm.)","vi":""},{"ja":"日本人なら誰でも納豆が好きだわけではない。","romaji":"→ (Không phải người Nhật nào cũng thích natto.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('168.  わけがない  - Không thể nào; không có khả năng ~', 'N3', 'Dùng để phủ định một cách mạnh mẽ, diễn tả rằng một điều gì đó là hoàn toàn không thể xảy ra, không có lý do gì để nó xảy ra.', 'V/Adj/N-thể thường +  わけがない', '[{"ja":"あんなに練習したんだから、試合に負けるわけがない。","romaji":"→ (Đã luyện tập nhiều đến thế, không thể nào thua trận được.)","vi":""},{"ja":"彼がそんなことを言うわけがない。","romaji":"→ (Anh ấy không thể nào nói những lời như vậy được.)","vi":"──────────"},{"ja":"～ことはない (N3): Không có khả năng... / Không cần phải...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('169.  わけにはいかない  - Không thể (làm); Phải (làm) ~', 'N3', 'Diễn tả sự khó xử, không thể làm (hoặc không thể không làm) một việc gì đó vì áp lực từ hoàn cảnh, quy tắc xã hội, hoặc tình cảm cá nhân, chứ không phải vì không có năng lực.', 'V-る +  わけにはいかない (Không thể làm V, vì lý do xã hội, đạo đức, tâm lý)   V-ない +  わけにはいかない (Không thể không làm V, tức là phải làm V)', '[{"ja":"約束したから、行かないわけにはいかない。","romaji":"→ (Vì đã hứa nên tôi phải đi / không thể không đi.)","vi":""},{"ja":"友達の頼みだから、断るわけにはいかない。","romaji":"→ (Vì là lời nhờ của bạn bè nên tôi không thể từ chối.)","vi":"──────────"},{"ja":"～てはいけない (N5): Không được làm...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('170.  割に  (わりに) - So với ~; đối với ~; mặc dù ~', 'N3', 'Dùng để diễn tả sự khác biệt (tốt hơn hoặc kém hơn) so với những gì người ta thường mong đợi từ một tiêu chuẩn, mức độ hoặc sự thật được nêu ở vế trước. Tương tự  ～にしては.', 'V/Adj/N-thể thường +  割に（は）', '[{"ja":"彼は年の割に若く見える。","romaji":"→ (Anh ấy trông trẻ hơn so với tuổi.)","vi":""},{"ja":"このレストランは値段が高い割には、あまり美味しくない。","romaji":"→ (Nhà hàng này so với giá cả đắt đỏ thì không ngon lắm.)","vi":"──────────"},{"ja":"～のに (N4): Mặc dù...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('171.  わざと  - Cố tình; cố ý ~', 'N3', 'Là một trạng từ, diễn tả một hành động được thực hiện một cách có chủ đích, cố ý, thường mang hàm ý không tốt hoặc để trêu chọc.', 'わざと + V', '[{"ja":"彼はわざと聞こえないふりをした。","romaji":"→ (Anh ta cố tình giả vờ không nghe thấy.)","vi":""},{"ja":"彼女はわざとグラスを落とした。","romaji":"→ (Cô ấy cố tình làm rơi cái ly.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('172.  わざわざ  - Cất công; mất công ~', 'N3', 'Là một trạng từ, diễn tả việc ai đó đã bỏ ra công sức, thời gian đặc biệt để làm một việc gì đó, thường là việc không nhất thiết phải làm hoặc có thể làm đơn giản hơn. Có thể dùng để bày tỏ sự cảm kích hoặc đôi khi là sự ngạc nhiên/phàn nàn nhẹ.', 'わざわざ + V', '[{"ja":"わざわざお越しいただき、ありがとうございます。","romaji":"→ (Cảm ơn anh đã cất công đến đây.)","vi":""},{"ja":"そんなことのために、わざわざ行く必要はない。","romaji":"→ (Không cần phải cất công đi chỉ vì chuyện đó đâu.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('173.  よりも  - So với; hơn là; hơn ~', 'N3', 'Dùng trong câu so sánh, tương tự như  ～より nhưng nhấn mạnh hơn sự so sánh, làm nổi bật sự khác biệt.', 'A +  は + B +  よりも + C', '[{"ja":"実践は理論よりも重要だ。","romaji":"→ (Thực hành quan trọng hơn là lý thuyết.)","vi":""},{"ja":"彼は私が思っていたよりもずっと若かった。","romaji":"→ (Anh ấy trẻ hơn rất nhiều so với tôi nghĩ.)","vi":"──────────"},{"ja":"～のほうが (N4): ... thì ... hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('174.  ようがない  /  ようもない  - Không có cách nào để ~; không thể ~', 'N3', 'Diễn tả rằng không có phương tiện, cách thức, hoặc khả năng để thực hiện một hành động nào đó.', 'V-ます (bỏ  ます) +  ようがない /  ようもない', '[{"ja":"手紙に住所が書いてなかったので、返事を出しようがない。","romaji":"→ (Vì trên thư không ghi địa chỉ nên không có cách nào gửi thư trả lời được.)","vi":""},{"ja":"こんなに壊れてしまったら、直しようがない。","romaji":"→ (Nếu hỏng đến mức này thì không có cách nào sửa được.)","vi":"──────────"},{"ja":"方法がない (N4/N3): Không có cách/phương pháp.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('175.  ような気がする  (ようなきがする) - Có cảm giác rằng; cảm thấy như; có vẻ như; nghĩ rằng ~', 'N3', 'Diễn tả một cảm giác, linh cảm, hoặc suy nghĩ không rõ ràng, không chắc chắn của người nói.', 'V/Adj/N-thể thường +  ような気がする', '[{"ja":"誰かが後ろにいるような気がする。","romaji":"→ (Tôi có cảm giác như ai đó đang ở phía sau.)","vi":""},{"ja":"この方法はあまり効果がないような気がする。","romaji":"→ (Tôi cảm thấy hình như phương pháp này không hiệu quả lắm.)","vi":"──────────"},{"ja":"～みたいだ (N4): Hình như...","romaji":"","vi":""},{"ja":"多分～だろう (N5/N4): Có lẽ là...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('176.  ように  - Để; sao cho ~', 'N3', 'Nghĩa 1 (Mục đích): Diễn tả mục đích, sao cho đạt được một trạng thái hoặc khả năng nào đó. Thường đi với V2 là  言う,  頼む,  祈る,  努力する,  する...   Nghĩa 2 (Giống như): Như đã nói/nhìn thấy... (ご覧のように - như quý vị thấy).', 'V-る / V-ない +  ように + V2', '[{"ja":"みんなに聞こえるように、もっと大きな声で話してください。","romaji":"→ (Xin hãy nói to hơn để mọi người có thể nghe thấy.) - Nghĩa 1","vi":""},{"ja":"風邪をひかないように、気をつけてください。","romaji":"→ (Hãy cẩn thận để không bị cảm lạnh.) - Nghĩa 1","vi":"──────────"},{"ja":"～ようにする (N4): Cố gắng để...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('177.  ように見える  (ようにみえる) - Trông; có vẻ; dường như ~', 'N3', 'Diễn tả sự phán đoán của người nói dựa trên vẻ bề ngoài, những gì quan sát được bằng mắt.', 'V/Adj/N-thể thường +  ように見える', '[{"ja":"彼女はとても疲れているように見える。","romaji":"→ (Cô ấy trông có vẻ rất mệt.)","vi":""},{"ja":"この絵は、遠くから見ると写真のように見える。","romaji":"→ (Bức tranh này, nếu nhìn từ xa thì trông giống như ảnh chụp.)","vi":"──────────"},{"ja":"～ようだ (N4): Hình như...","romaji":"","vi":""},{"ja":"～みたいだ (N4): Trông có vẻ...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('178.  ようとしない  - Không cố gắng; không nỗ lực; không định ~', 'N3', 'Diễn tả rằng ai đó (thường là ngôi thứ ba) không có ý định hoặc không chịu nỗ lực để làm một việc gì đó, thường mang sắc thái phê phán hoặc thất vọng.', 'V-ý chí (Thể ý chí) +  としない', '[{"ja":"彼は自分の間違いを認めようとしない。","romaji":"→ (Anh ta không chịu thừa nhận lỗi lầm của mình.)","vi":""},{"ja":"子供は薬を飲もうとしない。","romaji":"→ (Đứa trẻ không chịu uống thuốc.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('179.  ようとする  - Cố gắng; thử; sắp ~', 'N3', 'Nghĩa 1: Diễn tả nỗ lực, cố gắng làm gì đó.   Nghĩa 2: Diễn tả hành động sắp sửa xảy ra, ngay trước khi bắt đầu.   Nghĩa 3 (ようとした): Thường diễn tả một nỗ lực đã thất bại hoặc bị gián đoạn.', 'V-ý chí (Thể ý chí) +  とする', '[{"ja":"電車に乗ろうとした時、ドアが閉まってしまった。","romaji":"→ (Đúng lúc tôi định lên tàu thì cửa đóng lại mất.) - Nghĩa 3","vi":""},{"ja":"いくら説明しようとしても、彼は聞いてくれない。","romaji":"→ (Dù tôi cố gắng giải thích bao nhiêu, anh ấy cũng không nghe.) - Nghĩa 1","vi":"──────────"},{"ja":"～つもりだ (N4): Định...","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('180.  ずに  - Mà không làm ~', 'N3', 'Là cách nói trang trọng hơn hoặc dùng trong văn viết của  ～ないで, có nghĩa là làm một việc gì đó mà không làm V.', 'V-ない (bỏ  ない) +  ずに (Lưu ý:  する →  せずに)', '[{"ja":"昨夜は、歯を磨かずに寝てしまった。","romaji":"→ (Tối qua tôi đã đi ngủ mà không đánh răng.)","vi":""},{"ja":"彼は何も言わずに、出て行った。","romaji":"→ (Anh ấy đã bỏ đi mà không nói một lời nào.)","vi":""},{"ja":"辞書を使わずに、新聞を読めるようになりたい。","romaji":"→ (Tôi muốn có thể đọc báo mà không cần dùng từ điển.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('181.  ずにはいられない  - Không thể không cảm thấy; không thể không làm; phải làm ~', 'N3', 'Diễn tả một cảm xúc hoặc hành động mà người nói không thể kiềm chế được, dù có muốn hay không, vẫn phải làm hoặc cảm thấy như vậy.', 'V-ない (bỏ  ない) +  ずにはいられない (Lưu ý:  する →  せずにはいられない)', '[{"ja":"彼の話を聞いて、笑わずにはいられなかった。","romaji":"→ (Nghe câu chuyện của anh ấy, tôi không thể không bật cười.)","vi":""},{"ja":"この状況を見て、心配せずにはいられない。","romaji":"→ (Nhìn tình hình này, tôi không thể không lo lắng.)","vi":"──────────"},{"ja":"～てしょうがない (N3): ... không chịu được (nhấn mạnh cảm xúc).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('182.  ずつ  - Mỗi; từng; một lần ~', 'N3', 'Dùng sau từ chỉ số lượng để diễn tả sự phân chia đều đặn, hoặc sự lặp lại theo từng lượng bằng nhau.', 'Số lượng +  ずつ', '[{"ja":"子供たちにお菓子を三つずつあげました。","romaji":"→ (Tôi đã cho mỗi đứa trẻ 3 cái kẹo.)","vi":""},{"ja":"毎日漢字を五つずつ覚えています。","romaji":"→ (Mỗi ngày tôi học thuộc 5 chữ Hán.)","vi":""},{"ja":"少しずつ日本語が分かるようになってきた。","romaji":"→ (Tôi đã dần dần hiểu được tiếng Nhật từng chút một.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('1.  ～あげく: Cuối cùng; sau khi ~ (thường là kết quả không tốt).', 'N2', 'Diễn tả một hành động hoặc tình trạng kéo dài, tốn nhiều công sức, và cuối cùng dẫn đến một kết quả (thường là tiêu cực, đáng tiếc).', 'Động từ thể  た (V た) +  あげく (に)   Danh từ (N) +  の +  あげく (に)', '[{"ja":"いろいろ悩んだあげく、彼女と別れることにした。","romaji":"→ Sau khi đã trăn trở rất nhiều, cuối cùng tôi đã quyết định chia tay cô ấy.","vi":""},{"ja":"３時間も待たされたあげく、結局試合は中止になった。","romaji":"→ Sau khi bị bắt chờ đến 3 tiếng đồng hồ, cuối cùng trận đấu lại bị hủy.","vi":"──────────"},{"ja":"～結果（けっか）  (N4/N3): Chỉ đơn thuần nêu lên \"kết quả\", không mang sắc thái tiêu cực mạnh như  「あげく」.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('2.  あるいは: Hoặc là; có lẽ; có thể ~.', 'N2', '1.   Nối các lựa chọn tương đương (trang trọng).  2.   Thể hiện sự phỏng đoán, khả năng xảy ra.', 'N1 +  あるいは + N2   文 1 +  あるいは +  文 2   あるいは +  文', '[{"ja":"来週の会議は、月曜日あるいは火曜日に行われます。","romaji":"→ Buổi họp tuần tới sẽ được tổ chức vào thứ Hai hoặc là thứ Ba.","vi":""},{"ja":"あるいは、彼はもうこの町にはいないのかもしれない。","romaji":"→ Có lẽ, anh ấy đã không còn ở thị trấn này nữa.","vi":"──────────"},{"ja":"か  (N5): Dùng phổ biến trong văn nói, ít trang trọng hơn.","romaji":"","vi":""},{"ja":"もしかしたら  (N3): Tương tự nghĩa \"có lẽ\", thường dùng trong văn nói.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('3.  ～ばかりだ: Cứ tiếp tục (theo một chiều hướng, thường là tiêu cực).', 'N2', 'Diễn tả một sự thay đổi đang diễn ra và có xu hướng tiếp tục theo một chiều hướng nhất định (thường là xấu đi).', 'Động từ thể từ điển (V る) +  ばかりだ', '[{"ja":"最近、祖母の病気は悪くなるばかりだ。","romaji":"→ Gần đây, bệnh tình của bà tôi cứ xấu đi.","vi":""},{"ja":"人口は減るばかりで、この村の将来が心配だ。","romaji":"→ Dân số cứ giảm đi, tôi lo lắng cho tương lai của ngôi làng này.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('4.  ～ばかりか: Không chỉ... mà còn ~; Hơn nữa ~.', 'N2', 'Diễn tả rằng không chỉ có A, mà còn có B (ở mức độ cao hơn, rộng hơn).', 'N / A な / A い / V る +  ばかりか', '[{"ja":"彼は漢字が読めないばかりか、ひらがなさえ書けない。","romaji":"→ Anh ta không chỉ không đọc được Kanji mà đến cả Hiragana cũng không viết được.","vi":""},{"ja":"このレストランは料理がおいしいばかりか、値段も安い。","romaji":"→ Nhà hàng này không chỉ món ăn ngon mà giá cả cũng rẻ.","vi":"──────────"},{"ja":"～のみならず  (N2): Rất trang trọng, thường dùng trong văn viết.","romaji":"","vi":""},{"ja":"～上に（うえに）  (N3): Cũng có nghĩa \"không chỉ... mà còn\", nhấn mạnh hai vế cùng chiều.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('5.  ～ばかりに: Chỉ vì; tại vì ~ (dẫn đến kết quả xấu).', 'N2', 'Diễn tả một nguyên nhân dẫn đến một kết quả xấu, không mong muốn. Thể hiện sự tiếc nuối, bất mãn.', 'V た / A い / A な / N +  ばかりに', '[{"ja":"うっかり住所を間違えたばかりに、荷物が届かなかった。","romaji":"→ Chỉ vì lỡ nhầm địa chỉ mà hành lý đã không đến được.","vi":""},{"ja":"お金がないばかりに、大学に進学できなかった。","romaji":"→ Chỉ vì không có tiền mà tôi đã không thể học lên đại học.","vi":"──────────"},{"ja":"～から  /  ～ので  (N5/N4): Chỉ nguyên nhân - kết quả thông thường, không nhất thiết tiêu cực.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('6.  ちなみに: Nhân tiện; tiện thể ~.', 'N2', 'Dùng để bổ sung một thông tin có liên quan nhưng không phải là thông tin chính.', 'ちなみに、[Thông tin bổ sung]', '[{"ja":"次の会議は来週の月曜日です。ちなみに、場所は第一会議室です。","romaji":"→ Buổi họp tiếp theo là vào thứ Hai tuần sau. Nhân tiện, địa điểm là phòng họp số 1.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('7.  ちっとも～ない: Không ~ chút nào cả.', 'N2', 'Dùng để phủ định hoàn toàn, nhấn mạnh rằng không có một chút nào.', 'ちっとも + V ない / A くない / A でない / N でない', '[{"ja":"あの映画はちっとも面白くなかった。","romaji":"→ Bộ phim đó không thú vị chút nào cả.","vi":"──────────"},{"ja":"少しも（すこしも）～ない  (N2): Nghĩa tương tự, \"không một chút nào\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('8.  だけあって: Quả đúng là; chính vì ~ (nên ~ là đương nhiên).', 'N2', 'Diễn tả rằng vì có một đặc điểm tốt, nên kết quả tốt là điều đương nhiên, xứng đáng.', 'V / A い / A な / N +  だけあって', '[{"ja":"このホテルは五つ星だけあって、サービスが素晴らしい。","romaji":"→ Khách sạn này quả đúng là 5 sao, dịch vụ tuyệt vời.","vi":"──────────"},{"ja":"～だけのことはある  (N2): Gần như đồng nghĩa, nhấn mạnh sự \"đáng giá\".","romaji":"","vi":""},{"ja":"さすが  (N3): Diễn tả sự thán phục, \"quả không hổ danh là\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('9.  だけあって: Quả đúng là; chính vì ~ (nên ~ là đương nhiên).', 'N2', 'Dùng để diễn tả rằng vì có một đặc điểm, tính chất, hoặc sự thật nào đó (vế trước), nên kết quả hoặc đánh giá ở vế sau là điều đương nhiên, xứng đáng, phù hợp. Thường dùng để khen ngợi hoặc đưa ra nhận xét tích cực.', 'V / A い / A な / N +  だけあって', '[{"ja":"このホテルは五つ星だけあって、サービスが素晴らしい。","romaji":"→ Khách sạn này quả đúng là 5 sao, dịch vụ tuyệt vời.","vi":""},{"ja":"彼は長年日本に住んでいただけあって、日本語がぺらぺらだ。","romaji":"→ Anh ấy chính vì đã sống ở Nhật nhiều năm nên tiếng Nhật rất trôi chảy.","vi":"──────────"},{"ja":"～だけのことはある  (N2): Gần như đồng nghĩa, nhấn mạnh sự \"đáng giá\".","romaji":"","vi":""},{"ja":"さすが  (N3): Diễn tả sự thán phục, \"quả không hổ danh là\", nhưng thường đứng đầu câu.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('10.  だけましだ: ~ là còn tốt chán; nên cảm thấy biết ơn vì ~.', 'N2', 'Dùng để diễn tả rằng dù tình hình hiện tại không lý tưởng, nhưng so với một tình huống tồi tệ hơn thì vẫn còn là may mắn.', 'V / A い / A な +  だけましだ', '[{"ja":"給料は下がったが、首にならないだけましだ。","romaji":"→ Lương thì giảm thật, nhưng không bị đuổi việc là còn tốt chán rồi.","vi":""},{"ja":"事故で車は傷ついたが、けががなかっただけましだ。","romaji":"→ Xe bị xước do tai nạn, nhưng không bị thương là còn may chán.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('11.  だけに: Chính vì; bởi vì ~ (nên càng ~).', 'N2', 'Dùng để nhấn mạnh rằng vì có một lý do đặc biệt nào đó, nên kết quả hoặc cảm xúc ở vế sau càng trở nên mạnh mẽ, rõ ràng hơn.', 'V / A い / A な / N +  だけに', '[{"ja":"楽しみにしていた旅行だけに、中止になって本当に残念だ。","romaji":"→ Chính vì là chuyến du lịch mà tôi đã rất mong chờ, nên việc bị hủy thực sự rất đáng tiếc.","vi":""},{"ja":"この商品は値段が高いだけに、品質も非常に良い。","romaji":"→ Sản phẩm này chính vì giá cao nên chất lượng cũng cực kỳ tốt.","vi":"──────────"},{"ja":"～からこそ  (N3): Cũng nhấn mạnh lý do \"chính vì\", nhưng tập trung vào sự đặc biệt của lý do.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('12.  だけのことはある: Thảo nào; quả đúng là; không phải ... mà không có lý do.', 'N2', 'Dùng để bày tỏ sự thán phục, công nhận rằng một kết quả là hoàn toàn xứng đáng với nguyên nhân, nỗ lực, danh tiếng đã biết.', 'V / A い / A な / N +  だけのことはある', '[{"ja":"世界一周旅行は高かったが、素晴らしい経験ができた。行っただけのことはあった。","romaji":"→ Chuyến du lịch vòng quanh thế giới tuy đắt đỏ nhưng đã có được những trải nghiệm tuyệt vời. Quả đúng là bõ công đi.","vi":""},{"ja":"有名な画家が描いただけのことはあって、この絵は本当に感動的だ。","romaji":"→ Quả đúng là do một họa sĩ nổi tiếng vẽ, bức tranh này thực sự cảm động.","vi":"──────────"},{"ja":"～さすが  (N3): Diễn tả sự thán phục.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('13.  だけは: Làm tất cả những gì có thể (trong giới hạn đó).', 'N2', 'Diễn tả việc đã làm hoặc sẽ làm đến mức tối đa có thể trong một phạm vi, dù kết quả có thể không như ý.', 'V る +  だけは + V た / V る / V よう...   V たい +  だけは + V た', '[{"ja":"やるだけはやったのだから、あとは結果を待つしかない。","romaji":"→ Vì đã làm tất cả những gì có thể làm rồi, nên giờ chỉ còn cách chờ kết quả thôi.","vi":""},{"ja":"時間はなかったが、言うだけは言っておいた方がいいと思った。","romaji":"→ Tuy không có thời gian, nhưng tôi nghĩ ít nhất cũng nên nói ra những gì cần nói.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('14.  だって: Bởi vì; nhưng mà; rốt cuộc; ngay cả; cũng.', 'N2', 'Từ đa nghĩa, dùng trong văn nói, mang sắc thái thân mật.  1.   Nêu lý do (biện hộ).  2.   Phản đối.  3.   Nhấn mạnh (giống  も/さえ).', '[Câu] +  だって (Bởi vì)   だって、[Câu] (Nhưng mà)   N +  だって (Ngay cả N / N cũng)', '[{"ja":"A:  なぜ宿題をしなかったの？ B:  だって、難しかったんだもん。","romaji":"→ A: Sao không làm bài tập? B: Tại vì... nó khó quá mà.","vi":""},{"ja":"子供だって、それくらいはわかるよ。","romaji":"→ Ngay cả trẻ con cũng hiểu được chừng đó.","vi":"──────────"},{"ja":"でも  (N5): Chỉ sự đối lập \"nhưng mà\".","romaji":"","vi":""},{"ja":"～も  (N5) /  ～さえ  (N3): Chỉ sự bao gồm/nhấn mạnh \"ngay cả\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('15.  でしかない: Chỉ là; không hơn không kém ~.', 'N2', 'Dùng để nhấn mạnh rằng một cái gì đó chỉ là N mà thôi, không có giá trị hay ý nghĩa hơn. Thường mang sắc thái đánh giá thấp, khiêm tốn.', 'N +  でしかない', '[{"ja":"彼の成功は、幸運の結果でしかない。","romaji":"→ Thành công của anh ta chẳng qua chỉ là kết quả của sự may mắn.","vi":""},{"ja":"これは私の個人的な意見でしかありません。","romaji":"→ Đây chỉ là ý kiến cá nhân của tôi mà thôi.","vi":"──────────"},{"ja":"～だけだ  (N4): Cũng có nghĩa \"chỉ là\", nhưng ít mang sắc thái đánh giá thấp.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('16.  どころではない: Không phải lúc để; không phải nơi để; còn xa mới ~.', 'N2', 'Diễn tả rằng vì một lý do nào đó, nên hoàn toàn không thể thực hiện hành động hoặc ở trong trạng thái đó.', 'N +  どころではない   V る +  どころではない', '[{"ja":"仕事が忙しすぎて、旅行どころではない。","romaji":"→ Công việc bận quá, không phải là lúc để đi du lịch.","vi":""},{"ja":"風邪がひどくて、ご飯を食べるどころではない。","romaji":"→ Bị cảm nặng quá, chẳng còn tâm trí đâu mà ăn cơm.","vi":"──────────"},{"ja":"～（V る）わけにはいかない  (N3): Diễn tả việc không thể làm gì đó vì lý do xã hội, đạo đức hoặc tâm lý.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('17.  どころか: Nói gì đến; chứ đừng nói là; còn xa mới ~.', 'N2', 'Dùng để diễn tả một sự việc không chỉ không đạt đến mức A (như mong đợi hoặc dự đoán), mà còn hoàn toàn trái ngược hoặc ở mức độ B (thường là tệ hơn hoặc khác biệt lớn).', 'N / V る / A い / A な +  どころか', '[{"ja":"彼は貯金するどころか、借金までしている。","romaji":"→ Anh ta nói gì đến tiết kiệm, đến cả nợ nần cũng có.","vi":""},{"ja":"忙しくて、休みを取るどころか、食事の時間もない。","romaji":"→ Bận quá, đừng nói là nghỉ ngơi, đến cả thời gian ăn cũng không có.","vi":""},{"ja":"静かどころか、とてもうるさい部屋だった。","romaji":"→ Yên tĩnh đâu chẳng thấy, đó là một căn phòng cực kỳ ồn ào.","vi":"──────────"},{"ja":"～ばかりか  (N2) /  ～だけでなく  (N3): Chỉ sự \"không chỉ... mà còn\", thường là bổ sung thêm thông tin cùng chiều.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('18.  どうやら: Có vẻ như; hình như; bằng cách nào đó; vừa mới ~.', 'N2', '1.   Diễn tả sự phán đoán không chắc chắn lắm nhưng có cơ sở nào đó, "có vẻ như", "hình như".  2.   Diễn tả một kết quả đạt được sau nhiều nỗ lực hoặc khó khăn, "bằng cách nào đó", "cuối cùng thì".', 'どうやら + [Phán đoán] (ようだ /  らしい /  そうだ /  みたいだ)   どうやら + [Kết quả]', '[{"ja":"空が暗くなってきた。どうやら雨が降りそうだ。","romaji":"→ Bầu trời tối sầm lại. Có vẻ như trời sắp mưa.","vi":""},{"ja":"どうやら終電に間に合ったようだ。","romaji":"→ Hình như (bằng cách nào đó) chúng ta đã kịp chuyến tàu cuối.","vi":""},{"ja":"何度も試して、どうやら成功した。","romaji":"→ Sau nhiều lần thử, cuối cùng thì cũng thành công.","vi":"──────────"},{"ja":"多分（たぶん）  (N5): Chỉ sự phỏng đoán \"có lẽ\", mức độ chắc chắn cao hơn một chút.","romaji":"","vi":""},{"ja":"ようだ  (N4) /  らしい  (N3) /  そうだ  (N4/N3): Các mẫu câu chỉ sự phỏng đoán, thường đi sau  「どうやら」.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('19.  どうせ: Đằng nào thì; dù sao đi nữa; rốt cuộc ~.', 'N2', 'Dùng khi người nói cho rằng kết quả cuối cùng đã được định sẵn (thường là không tốt hoặc không thay đổi được), và do đó hành động tiếp theo cũng không có nhiều ý nghĩa hoặc nên làm theo một hướng nhất định.', 'どうせ + [Kết luận/Hành động]', '[{"ja":"どうせ失敗するだろうから、やらない方がいい。","romaji":"→ Đằng nào thì chắc cũng thất bại thôi, nên tốt hơn là đừng làm.","vi":""},{"ja":"どうせ間に合わないなら、ゆっくり行こう。","romaji":"→ Dù sao đi nữa cũng không kịp, nên cứ đi thong thả thôi.","vi":""},{"ja":"どうせ私なんて、誰も愛してくれないんだ。","romaji":"→ Rốt cuộc hạng người như tôi thì chẳng ai yêu cả.","vi":"──────────"},{"ja":"いずれにしても  (N2): Có nghĩa \"dù thế nào đi nữa\", nhưng mang tính trung lập hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('20.  得ない（えない）: Không thể; không có khả năng ~.', 'N2', 'Diễn tả rằng một việc gì đó không thể xảy ra hoặc không thể thực hiện được, dựa trên logic, tình huống, hoặc khả năng thông thường.', 'Động từ thể  ます (bỏ  ます) +  得ない (えない)', '[{"ja":"そんなことはあり得ない。","romaji":"→ Chuyện đó không thể nào xảy ra được.","vi":""},{"ja":"彼の行動は理解し得ない。","romaji":"→ Hành động của anh ta không thể hiểu nổi.","vi":""},{"ja":"この状況では、成功は望み得ないだろう。","romaji":"→ Trong tình huống này, có lẽ không thể hy vọng thành công được.","vi":"──────────"},{"ja":"～わけにはいかない  (N3): \"Không thể\" vì lý do xã hội, đạo đức, tâm lý.","romaji":"","vi":""},{"ja":"～かねる  (N2): \"Khó có thể\", \"không thể\" (thường dùng để từ chối một cách lịch sự).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('21.  得る（える  /  うる）: Có thể; có khả năng ~.', 'N2', 'Diễn tả rằng một việc gì đó có khả năng xảy ra hoặc có thể thực hiện được.', 'Động từ thể  ます (bỏ  ます) +  得る (える /  うる)', '[{"ja":"それは十分あり得ることだ。","romaji":"→ Chuyện đó hoàn toàn có thể xảy ra.","vi":""},{"ja":"人間は過ちを犯し得る生き物だ。","romaji":"→ Con người là sinh vật có thể phạm sai lầm.","vi":""},{"ja":"このデータから、いくつかの結論を導き得る。","romaji":"→ Từ dữ liệu này, có thể rút ra một vài kết luận.","vi":"──────────"},{"ja":"～可能性がある  (N4/N3): \"Có khả năng\", thường dùng để nói về xác suất.","romaji":"","vi":""},{"ja":"～かねない  (N2): \"Có thể sẽ ~\" (nhưng thường dùng cho khả năng xảy ra việc xấu).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('22.  再び（ふたたび）: Lại; một lần nữa.', 'N2', 'Diễn tả sự lặp lại của một hành động hoặc trạng thái. Mang sắc thái trang trọng hơn  「また」.', 'Là một trạng từ (副詞).', '[{"ja":"彼は再び日本を訪れた。","romaji":"→ Anh ấy đã lại đến thăm Nhật Bản.","vi":""},{"ja":"戦争が再び起こらないことを祈る。","romaji":"→ Tôi cầu mong chiến tranh sẽ không xảy ra một lần nữa.","vi":""},{"ja":"会議は来週再び開かれます。","romaji":"→ Cuộc họp sẽ được tổ chức lại vào tuần sau.","vi":"──────────"},{"ja":"もう一度（もういちど）  (N5): \"Một lần nữa\", nhấn mạnh vào số lần.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('23.  ふうに: Theo cách này; theo cách đó; theo cách ~; như thế nào.', 'N2', 'Dùng để mô tả cách thức, phương pháp, hoặc trạng thái của một hành động hoặc sự việc.', 'こんな/そんな/あんな/どんな +  ふうに   V る/V た +  ふうに   A い +  ふうに   A な +  な +  ふうに', '[{"ja":"どんなふうに作ればいいですか？","romaji":"→ Tôi nên làm theo cách nào thì được?","vi":""},{"ja":"彼が言ったふうにやってみてください。","romaji":"→ Hãy thử làm theo cách anh ấy đã nói xem.","vi":""},{"ja":"もっと優しいふうに話してください。","romaji":"→ Xin hãy nói theo cách dịu dàng hơn.","vi":"──────────"},{"ja":"～みたいに  (N4/N3): \"Giống như\", thường dùng trong văn nói, so sánh ví von.","romaji":"","vi":""},{"ja":"～通りに  (N3): \"Đúng theo như\", nhấn mạnh sự tuân thủ chính xác.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('24.  がきっかけで  /  をきっかけに: Nhân cơ hội; là kết quả của; lấy ~ làm khởi đầu.', 'N2', 'Diễn tả một sự việc, sự kiện nào đó (N) trở thành nguyên nhân, động lực trực tiếp dẫn đến một sự thay đổi, một hành động mới, hoặc một sự phát triển.', 'N +  がきっかけで / N +  をきっかけに (して)', '[{"ja":"病気がきっかけで、健康の大切さを知った。","romaji":"→ Nhờ trận ốm mà tôi đã biết được tầm quan trọng của sức khỏe.","vi":""},{"ja":"彼の言葉をきっかけに、彼女は留学を決意した。","romaji":"→ Lấy lời nói của anh ấy làm động lực, cô ấy đã quyết tâm đi du học.","vi":"──────────"},{"ja":"～を機に（をきに）  (N1): Trang trọng hơn, cũng có nghĩa là \"nhân dịp\", \"nhân cơ hội\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('25.  げ: Trông có vẻ; dường như ~.', 'N2', 'Gắn vào sau tính từ hoặc động từ chỉ mong muốn để biến chúng thành một tính từ  な, dùng để mô tả dáng vẻ, tâm trạng của người khác mà người nói cảm nhận được thông qua quan sát bên ngoài. Không dùng để nói về bản thân.', 'Tính từ  い (bỏ  い) +  げ   Tính từ  な (bỏ  な) +  げ   V たい (bỏ  い) +  げ   (Một số trạng thái đặc biệt như:  自信ありげ、自信なさげ)', '[{"ja":"彼女は何か言いたげな顔でこちらを見ていた。","romaji":"→ Cô ấy nhìn về phía tôi với vẻ mặt như muốn nói điều gì đó.","vi":""},{"ja":"子供たちは楽しげに遊んでいる。","romaji":"→ Lũ trẻ đang chơi đùa trông rất vui vẻ.","vi":""},{"ja":"老人は寂しげに窓の外を眺めていた。","romaji":"→ Ông lão nhìn ra ngoài cửa sổ với vẻ đượm buồn.","vi":"──────────"},{"ja":"～っぽい  (N3): Có nghĩa \"có vẻ ~\", \"mang tính ~\", nhưng thường dùng để chỉ đặc tính nổi bật hoặc xu hướng (子供っぽい - như trẻ con), hoặc chỉ sự suy đoán không chắc chắn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('26.  逆に（ぎゃくに）: Ngược lại; trái lại ~.', 'N2', 'Dùng để giới thiệu một ý, một sự thật, hoặc một kết quả trái ngược hoàn toàn với những gì đã được nói trước đó hoặc với những gì người ta thường nghĩ.', 'Là một trạng từ (副詞).   逆に、[Câu]   [Câu 1]。逆に [Câu 2]。', '[{"ja":"薬を飲んだら、逆に気分が悪くなった。","romaji":"→ Uống thuốc xong, ngược lại tôi lại thấy khó chịu hơn.","vi":""},{"ja":"彼は親切だと思っていたが、逆にとても冷たい人だった。","romaji":"→ Tôi đã nghĩ anh ta tốt bụng, nhưng trái lại anh ta là một người rất lạnh lùng.","vi":""},{"ja":"値段は高いが、逆に言えば、品質は保証されているということだ。","romaji":"→ Giá thì cao thật, nhưng nói ngược lại, điều đó có nghĩa là chất lượng được đảm bảo.","vi":"──────────"},{"ja":"そのかわり  (N3): \"Đổi lại\", \"thay vào đó\", thường chỉ sự bù trừ hoặc thay thế.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('27.  反面（はんめん）: Trong khi; mặc dù; mặt khác ~.', 'N2', 'Dùng để diễn tả hai mặt đối lập của cùng một sự vật, sự việc, hoặc con người.', 'V る / A い / A な / N である +  反面 (はんめん)', '[{"ja":"この薬はよく効く反面、副作用も強い。","romaji":"→ Thuốc này một mặt thì hiệu quả tốt, mặt khác thì tác dụng phụ cũng mạnh.","vi":""},{"ja":"都会の生活は便利な反面、ストレスも多い。","romaji":"→ Cuộc sống ở thành thị một mặt thì tiện lợi, mặt khác cũng nhiều căng thẳng.","vi":""},{"ja":"彼は優しい反面、決断力に欠けるところがある。","romaji":"→ Anh ấy một mặt thì hiền lành, mặt khác lại có điểm thiếu quyết đoán.","vi":"──────────"},{"ja":"～けど  /  ～が  (N5): Chỉ sự đối lập thông thường, dùng nhiều trong văn nói.","romaji":"","vi":""},{"ja":"～のに  (N4): Cũng chỉ sự đối lập, nhưng thường mang sắc thái bất mãn hoặc ngạc nhiên.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('28.  果たして（はたして）: Đúng như dự đoán; quả nhiên; thực sự; liệu có ~.', 'N2', '1.   Dùng trong câu nghi vấn để nhấn mạnh sự hoài nghi, băn khoăn, "liệu có thực sự...".  2.   Dùng để xác nhận một kết quả đúng như những gì đã dự đoán hoặc nghi ngờ trước đó, "quả nhiên", "đúng như...".', '果たして +  ～か /  ～だろうか (Liệu có ~ không?)   果たして + [Phán đoán] (Quả nhiên là ~)', '[{"ja":"果たして彼の話は本当だろうか。","romaji":"→ Liệu câu chuyện của anh ta có thật không nhỉ?","vi":""},{"ja":"噂は本当だった。果たして、二人は結婚した。","romaji":"→ Lời đồn là thật. Quả nhiên hai người họ đã kết hôn.","vi":""},{"ja":"果たして、この計画は成功するのだろうか。","romaji":"→ Liệu kế hoạch này có thành công không đây?","vi":"──────────"},{"ja":"いったい  (N3): Dùng để nhấn mạnh câu nghi vấn, thường thể hiện sự tò mò hoặc khó hiểu, \"rốt cuộc là...\".  「果たして」 thiên về sự hoài nghi về tính xác thực.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('29.  一応（いちおう）: Đại khái; ít nhiều; tạm thời ~.', 'N2', 'Dùng để diễn tả một hành động hoặc tình trạng chưa hoàn hảo, chưa đầy đủ nhưng cũng tạm chấp nhận được ở một mức độ nào đó; hoặc một việc làm mang tính tạm thời, phòng hờ.', 'Là một trạng từ (副詞).', '[{"ja":"食事は一応済ませましたが、まだお腹が空いています。","romaji":"→ Bữa ăn thì coi như là xong rồi, nhưng tôi vẫn còn đói.","vi":""},{"ja":"一応、傘を持っていった方がいいだろう。","romaji":"→ Tạm thời (để đề phòng) thì có lẽ nên mang ô đi.","vi":""},{"ja":"これで一応完成ですが、まだ修正が必要です。","romaji":"→ Thế này thì coi như là hoàn thành, nhưng vẫn cần chỉnh sửa.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('30.  以外（いがい）: Ngoại trừ; trừ ~.', 'N2', 'Dùng để loại trừ một đối tượng (N) ra khỏi một nhóm hoặc một phạm vi nào đó.', 'N +  以外 (に /  の)', '[{"ja":"日曜日以外は毎日働いています。","romaji":"→ Ngoại trừ Chủ nhật, ngày nào tôi cũng làm việc.","vi":""},{"ja":"このクラスでは、彼以外に英語を話せる人はいない。","romaji":"→ Trong lớp này, ngoài anh ta ra thì không có ai nói được tiếng Anh.","vi":""},{"ja":"あなた以外の人はみんな知っていますよ。","romaji":"→ Mọi người trừ bạn ra đều biết đấy.","vi":"──────────"},{"ja":"～を除いて（をのぞいて）  (N2): Nghĩa rất giống, \"ngoại trừ\", \"loại trừ\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('31.  以上に（いじょうに）: Hơn; không ít hơn; vượt quá ~.', 'N2', 'Dùng để so sánh, nhấn mạnh rằng mức độ của vế sau còn cao hơn, nhiều hơn, hoặc vượt trội hơn vế trước.', 'N +  以上に   V る / A い / A な +  以上に   これ /  それ /  あれ +  以上に', '[{"ja":"彼は私が想像した以上に強かった。","romaji":"→ Anh ta mạnh hơn cả những gì tôi tưởng tượng.","vi":""},{"ja":"健康以上に大切なものはない。","romaji":"→ Không có gì quan trọng hơn sức khỏe.","vi":""},{"ja":"必要以上に買い物をしないでください。","romaji":"→ Xin đừng mua sắm nhiều hơn mức cần thiết.","vi":"──────────"},{"ja":"～ほど  (N4): Thường dùng trong so sánh không bằng (～ほど～ない) hoặc chỉ mức độ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('32.  以上は（いじょうは）: Một khi đã; bởi vì; vì ~.', 'N2', 'Diễn tả rằng một khi đã ở vào tình huống A, hoặc một khi đã quyết định/hứa/nói A, thì việc làm B (thường là một nghĩa vụ, quyết tâm, hoặc điều đương nhiên) là điều bắt buộc hoặc hợp lý.', 'V る / V た +  以上は (いじょうは)', '[{"ja":"約束した以上は、守らなければならない。","romaji":"→ Một khi đã hứa thì phải giữ lời.","vi":""},{"ja":"日本に来た以上は、日本語が話せるようになりたい。","romaji":"→ Một khi đã đến Nhật thì tôi muốn có thể nói được tiếng Nhật.","vi":""},{"ja":"やると言った以上は、最後まで責任を持つべきだ。","romaji":"→ Một khi đã nói là làm thì nên có trách nhiệm đến cùng.","vi":"──────────"},{"ja":"～上は（うえは）  (N2): Cũng giống nhau, nhưng có thể trang trọng hơn một chút.","romaji":"","vi":""},{"ja":"～のだから  (N3): Chỉ lý do \"vì là...\", nhưng không mang sắc thái bắt buộc mạnh như  「以上は」.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('33.  いきなり: Đột ngột; bất thình lình; không báo trước.', 'N2', 'Diễn tả một hành động hoặc sự việc xảy ra đột ngột, không có dấu hiệu báo trước, thường gây ra sự ngạc nhiên.', 'Là một trạng từ (副詞).', '[{"ja":"後ろからいきなり肩をたたかれたので、びっくりした。","romaji":"→ Vì bị vỗ vai đột ngột từ phía sau nên tôi đã giật mình.","vi":""},{"ja":"彼は会議中にいきなり立ち上がって部屋を出て行った。","romaji":"→ Anh ta đột ngột đứng dậy và đi ra khỏi phòng giữa cuộc họp.","vi":""},{"ja":"何の前触れもなく、いきなり雨が降り出した。","romaji":"→ Không có dấu hiệu báo trước nào, trời đột nhiên đổ mưa.","vi":"──────────"},{"ja":"突然（とつぜん）  (N3): \"Đột nhiên\", \"bất ngờ\", mang tính khách quan và trang trọng hơn  「急に」, nhấn mạnh sự xảy ra không lường trước.  「いきなり」 thường nhấn mạnh hơn vào sự đường đột và bất ngờ đối với người cảm nhận.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('34.  一気に（いっきに）: Một hơi; không ngừng; một lần; ngay lập tức ~.', 'N2', 'Diễn tả một hành động được thực hiện trong một lần, không nghỉ, hoặc một sự thay đổi diễn ra rất nhanh chóng, mạnh mẽ trong một thời gian ngắn.', 'Là một trạng từ (副詞).', '[{"ja":"彼はビールをジョッキで一気に飲み干した。","romaji":"→ Anh ta đã uống cạn cốc bia bằng một hơi.","vi":""},{"ja":"長い坂道を一気に駆け上がった。","romaji":"→ Tôi đã chạy một mạch lên con dốc dài.","vi":""},{"ja":"宿題を夏休みの最後に一気に片付けた。","romaji":"→ Tôi đã giải quyết hết đống bài tập hè trong một lần vào cuối kỳ nghỉ.","vi":"──────────"},{"ja":"すぐに  (N5): \"Ngay lập tức\", chỉ sự bắt đầu nhanh chóng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('35.  一方で（いっぽうで）: Một mặt thì, mặt khác thì; mặc dù ~.', 'N2', 'Dùng để trình bày hai mặt, hai khía cạnh khác nhau hoặc đối lập của cùng một vấn đề, sự vật, hiện tượng. Cũng có thể dùng để chỉ một xu hướng đang diễn ra song song.', 'V る / A い / A な / N である +  一方で (いっぽうで)', '[{"ja":"インターネットは便利な一方で、危険も潜んでいる。","romaji":"→ Internet một mặt thì tiện lợi, mặt khác cũng tiềm ẩn nguy hiểm.","vi":""},{"ja":"彼は熱心な研究者である一方で、優れた教育者でもある。","romaji":"→ Anh ấy một mặt là một nhà nghiên cứu nhiệt huyết, mặt khác cũng là một nhà giáo ưu tú.","vi":""},{"ja":"人口が増える一方で、食料不足が深刻になっている。","romaji":"→ Một mặt dân số đang tăng lên, mặt khác tình trạng thiếu lương thực đang trở nên nghiêm trọng.","vi":"──────────"},{"ja":"～けど  /  ～が  (N5): Chỉ sự đối lập thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('36.  いわゆる: Cái gọi là; nói nôm na là ~.', 'N2', 'Dùng để giới thiệu hoặc giải thích một thuật ngữ, một khái niệm, hoặc một cách gọi phổ biến nào đó.', 'いわゆる + N', '[{"ja":"彼女はいわゆる「キャリアウーマン」だ。","romaji":"→ Cô ấy là người mà người ta hay gọi là \"nữ doanh nhân thành đạt\".","vi":""},{"ja":"これがいわゆる「クールジャパン」の文化です。","romaji":"→ Đây là văn hóa \"Cool Japan\" (Nhật Bản thú vị) mà người ta hay nói đến.","vi":""},{"ja":"彼はチームのいわゆる「ムードメーカー」だ。","romaji":"→ Anh ấy là người mà người ta gọi là \"người tạo không khí\" cho cả đội.","vi":"──────────"},{"ja":"すなわち  (N1): \"Nghĩa là\", \"tức là\", dùng để giải thích hoặc định nghĩa, trang trọng hơn  「つまり」.  「いわゆる」 tập trung vào cách gọi phổ biến.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('37.  いよいよ: Cuối cùng; chắc chắn; không còn nghi ngờ gì; ngày càng.', 'N2', '1.   Diễn tả một sự việc quan trọng, được mong đợi từ lâu sắp sửa diễn ra, "cuối cùng thì".  2.   Nhấn mạnh mức độ ngày càng tăng lên.  3.   Nhấn mạnh sự chắc chắn, "không còn nghi ngờ gì".', 'Là một trạng từ (副詞).', '[{"ja":"明日はいよいよ出発の日だ。","romaji":"→ Ngày mai cuối cùng cũng là ngày xuất phát rồi.","vi":""},{"ja":"試験が近づき、いよいよ緊張してきた。","romaji":"→ Kỳ thi đến gần, tôi ngày càng cảm thấy căng thẳng.","vi":""},{"ja":"これでいよいよ彼の無実が証明された。","romaji":"→ Bằng cái này, sự vô tội của anh ta chắc chắn đã được chứng minh.","vi":"──────────"},{"ja":"ついに  (N3): \"Cuối cùng thì\", cũng chỉ kết quả sau quá trình dài, thường mang tính đột phá hoặc đáng mong đợi.  「いよいよ」 thường nhấn mạnh thời điểm ngay trước khi sự kiện xảy ra.","romaji":"","vi":""},{"ja":"ますます  (N3): \"Ngày càng\", chỉ sự tăng tiến.  「いよいよ」 cũng có nghĩa này nhưng thường mang cảm xúc mạnh hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('38.  上（じょう）: Về mặt; từ quan điểm; theo ~.', 'N2', 'Gắn vào sau danh từ (thường là danh từ Hán-Nhật) để chỉ một phương diện, một khía cạnh, hoặc một lĩnh vực nào đó.', 'N +  上 (じょう)', '[{"ja":"健康上の理由で、仕事を辞めることにしました。","romaji":"→ Vì lý do sức khỏe, tôi đã quyết định nghỉ việc.","vi":""},{"ja":"この製品は、安全上いくつかの問題がある。","romaji":"→ Sản phẩm này có một vài vấn đề về mặt an toàn.","vi":""},{"ja":"教育上、その言葉遣いはよくない。","romaji":"→ Từ quan điểm giáo dục, cách dùng từ đó là không tốt.","vi":"──────────"},{"ja":"～の点で  (N3): \"Về điểm ~\", chỉ một điểm cụ thể.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('39.  かのように: Như thể là; cứ như là ~.', 'N2', 'Dùng để so sánh một sự việc, hành động với một điều khác không có thật hoặc không phải là sự thật, nhằm nhấn mạnh trạng thái hoặc cách thức của sự việc đó.', 'V / A い / A な / N + (thể thường) +  かのように   (N và A な có thể +  である +  かのように)', '[{"ja":"彼はまるで全てを知っているかのように話す。","romaji":"→ Anh ta nói chuyện cứ như thể là biết tuốt mọi thứ.","vi":""},{"ja":"空は、まるで泣き出すかのように暗くなった。","romaji":"→ Bầu trời tối sầm lại cứ như thể sắp khóc.","vi":""},{"ja":"彼女は何もなかったかのように、にこやかに笑った。","romaji":"→ Cô ấy mỉm cười rạng rỡ cứ như thể chưa có chuyện gì xảy ra.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('40.  かと思ったら（かとおもったら）: Vừa mới; ngay khi ~.', 'N2', 'Diễn tả hai hành động xảy ra gần như đồng thời hoặc liên tiếp rất nhanh, đến mức gây ngạc nhiên. Vế sau thường là một hành động bất ngờ hoặc trái ngược với vế trước.', 'V た +  かと思ったら /  かと思うと', '[{"ja":"赤ちゃんは今泣いたかと思ったら、もう笑っている。","romaji":"→ Em bé vừa mới khóc đó mà giờ đã cười rồi.","vi":""},{"ja":"ピカッと光ったかと思ったら、ゴロゴロと雷が鳴り出した。","romaji":"→ Vừa mới thấy lóe sáng thì sấm đã bắt đầu kêu ầm ầm.","vi":""},{"ja":"あの人は部屋に入ってきたかと思うと、すぐにどこかへ行ってしまった。","romaji":"→ Người đó vừa mới thấy vào phòng xong thì đã đi đâu mất ngay lập tức.","vi":"──────────"},{"ja":"～やいなや  (N1): \"Vừa mới... thì ngay lập tức...\", rất giống nhau nhưng trang trọng và mang tính văn viết hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('41.  か～ないかのうちに: Ngay khi; vừa mới ~.', 'N2', 'Diễn tả một hành động xảy ra gần như đồng thời với hành động trước đó, đến mức cảm giác như hành động trước còn chưa kết thúc hẳn thì hành động sau đã bắt đầu.', 'Động từ thể từ điển (V る) +  か + Động từ thể  ない (V ない) +  かのうちに', '[{"ja":"彼はベッドに横になるかならないかのうちに、ぐっすり眠ってしまった。","romaji":"→ Anh ấy vừa mới đặt lưng xuống giường thì đã ngủ say tít.","vi":""},{"ja":"授業終了のチャイムが鳴るか鳴らないかのうちに、生徒たちは教室を 飛び出した。","romaji":"→ Chuông báo hết giờ học vừa mới reo (hoặc chưa reo xong) thì học sinh đã ùa ra khỏi lớp.","vi":""},{"ja":"電車が止まるか止まらないかのうちに、ドアが開いた。","romaji":"→ Tàu điện vừa mới dừng (hoặc chưa dừng hẳn) thì cửa đã mở.","vi":"──────────"},{"ja":"～かと思ったら  (N2): \"Vừa mới... thì đã...\", nhấn mạnh sự thay đổi nhanh chóng, bất ngờ giữa hai hành động/trạng thái.","romaji":"","vi":""},{"ja":"～やいなや  (N1): \"Vừa mới... thì ngay lập tức...\", rất giống nhau nhưng trang trọng và văn viết hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('42.  かえって: Ngược lại; trái lại ~.', 'N2', 'Diễn tả một kết quả xảy ra trái ngược với dự đoán, mong đợi, hoặc lẽ thường. Thường là một kết quả không mong muốn hoặc bất ngờ.', 'Là một trạng từ (副詞).', '[{"ja":"親切のつもりで手伝ったら、かえって迷惑になってしまった。","romaji":"→ Tưởng là tốt bụng nên đã giúp đỡ, ai ngờ ngược lại còn gây phiền phức.","vi":""},{"ja":"薬を飲んだら、かえって症状がひどくなった。","romaji":"→ Uống thuốc xong, trái lại triệu chứng còn nặng hơn.","vi":""},{"ja":"近道をしたつもりが、かえって時間がかかった。","romaji":"→ Tưởng là đi đường tắt, ai ngờ ngược lại còn tốn thời gian hơn.","vi":"──────────"},{"ja":"むしろ  (N2): \"Thà... còn hơn\", \"ngược lại thì...\", dùng khi so sánh hai thứ và cho rằng vế sau thích hợp/đúng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('43.  限り（かぎり）: Chừng nào còn; trong khi ~; theo như ~; hết mức ~.', 'N2', 'Là một mẫu ngữ pháp đa nghĩa:  1.   Điều kiện: Diễn tả rằng chừng nào điều kiện A còn tồn tại thì B vẫn tiếp diễn.  2.   Phạm vi thông tin: Diễn tả rằng thông tin đưa ra dựa trên phạm vi hiểu biết/điều tra/nhìn thấy... của người nói.  3.   Giới hạn: Diễn tả việc làm gì đó đến mức tối đa có thể.', '1.   V る / V ない / A い / A な / N の +  限り (Chừng nào còn ~)  2.   V る / V た / V ている +  限り (では) (Theo như ~)  3.   V る / N の +  限り (Hết mức có thể ~)', '[{"ja":"1.   私が生きている限り、あなたを守ります。","romaji":"→ (Chừng nào tôi còn sống, tôi sẽ bảo vệ em.)","vi":"2.   私が知っている限りでは、彼は独身です。"},{"ja":"～以上は（いじょうは）  (N2): \"Một khi đã\", chỉ sự quyết tâm/nghĩa vụ khi đã có điều kiện A.","romaji":"","vi":""},{"ja":"～によると  (N3): \"Theo như\", chỉ nguồn thông tin.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('44.  甲斐がある（かいがある）: Đáng công; bõ công làm gì đó.', 'N2', 'Diễn tả rằng một hành động, nỗ lực nào đó mang lại kết quả tốt đẹp, xứng đáng với công sức bỏ ra.', 'V る / V た +  甲斐がある (かいがある)   N の +  甲斐がある (かいがある)', '[{"ja":"頑張って練習した甲斐があって、試合に勝つことができた。","romaji":"→ Bõ công đã cố gắng luyện tập, tôi đã có thể chiến thắng trận đấu.","vi":""},{"ja":"遠くまで来た甲斐があった。こんなにきれいな景色が見られるなんて。","romaji":"→ Bõ công đã đi xa đến đây. Không ngờ lại được ngắm cảnh đẹp thế này.","vi":""},{"ja":"待った甲斐があって、素晴らしいコンサートだった。","romaji":"→ Đáng công chờ đợi, đó là một buổi hòa nhạc tuyệt vời.","vi":"──────────"},{"ja":"～てよかった  (N4): \"Thật tốt vì đã làm ~\", diễn tả sự hài lòng/may mắn đơn giản hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('45.  かねない: Có thể sẽ ~ (thường là việc không tốt).', 'N2', 'Diễn tả khả năng xảy ra một việc gì đó, nhưng thường là một kết quả xấu, không mong muốn, dựa trên tình hình hoặc điều kiện hiện tại.', 'Động từ thể  ます (bỏ  ます) +  かねない', '[{"ja":"あんなにスピードを出したら、事故を起こしかねない。","romaji":"→ Nếu phóng tốc độ như thế thì có thể sẽ gây ra tai nạn đấy.","vi":""},{"ja":"このままでは、会社は倒産しかねない。","romaji":"→ Cứ thế này thì công ty có thể sẽ phá sản.","vi":""},{"ja":"油断していると、大きな失敗をしかねないよ。","romaji":"→ Nếu lơ là, cậu có thể sẽ thất bại lớn đấy.","vi":"──────────"},{"ja":"～おそれがある  (N2): \"E là\", \"có nguy cơ là\", cũng dùng cho việc xấu, nhưng trang trọng hơn và thường dùng trong tin tức, cảnh báo.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('46.  かねる: Không thể làm gì đó (thường dùng để từ chối).', 'N2', 'Dùng để diễn tả sự không thể làm một việc gì đó, thường là vì lý do tâm lý, tình huống, hoặc quy định. Thường được dùng như một cách từ chối lịch sự, gián tiếp.', 'Động từ thể  ます (bỏ  ます) +  かねる', '[{"ja":"申し訳ありませんが、そのご要望にはお応えしかねます。","romaji":"→ Chúng tôi rất xin lỗi nhưng khó có thể đáp ứng yêu cầu đó ạ.","vi":""},{"ja":"私一人では決めかねますので、上司に相談させてください。","romaji":"→ Vì một mình tôi không thể quyết định được, nên xin phép cho tôi thảo luận với cấp trên.","vi":""},{"ja":"彼の提案には賛成しかねる点が多い。","romaji":"→ Có nhiều điểm trong đề xuất của anh ta mà tôi khó có thể tán thành.","vi":"──────────"},{"ja":"～得ない  (N2): \"Không thể xảy ra\", \"không thể làm được\", trang trọng nhưng thường chỉ sự bất khả thi về logic/tình huống hơn là từ chối.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('47.  から言うと  /  から言えば: Nói về; từ quan điểm của ~.', 'N2', 'Dùng để đưa ra nhận xét, đánh giá, hoặc phán đoán từ một góc độ, một lập trường, hoặc một khía cạnh cụ thể (N).', 'N +  から言うと /  から言えば /  から言って', '[{"ja":"親から言えば、子供にはもっと勉強してほしい。","romaji":"→ Từ quan điểm của cha mẹ mà nói thì họ muốn con cái học hành nhiều hơn.","vi":""},{"ja":"品質から言うと、こちらの商品の方がおすすめです。","romaji":"→ Nói về chất lượng thì tôi khuyên dùng sản phẩm bên này hơn.","vi":""},{"ja":"彼の能力から言って、この仕事は簡単にできるだろう。","romaji":"→ Xét từ năng lực của anh ấy thì công việc này chắc là có thể làm dễ dàng.","vi":"──────────"},{"ja":"～から見ると  (N2): \"Nhìn từ ~\", \"xét từ ~\", rất giống nhau, thường dùng khi nhìn từ một vị trí hoặc góc độ khách quan hơn.","romaji":"","vi":""},{"ja":"～にしたら  /  ～にすれば  (N2): \"Đối với ~\", \"từ lập trường của ~\", thường dùng để thể hiện cảm xúc, suy nghĩ khi đặt mình vào vị trí của người khác.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('48.  からこそ: Chính vì ~.', 'N2', 'Dùng để nhấn mạnh một lý do đặc biệt, duy nhất, hoặc quan trọng nhất dẫn đến một kết quả hoặc hành động.', 'V / A い / A な / N + (thể thường) +  からこそ', '[{"ja":"愛しているからこそ、厳しく言うのです。","romaji":"→ Chính vì yêu nên tôi mới nói nghiêm khắc.","vi":""},{"ja":"努力したからこそ、成功できたんだ。","romaji":"→ Chính vì đã nỗ lực nên mới thành công được.","vi":""},{"ja":"あなただからこそ、この仕事をお願いしたい。","romaji":"→ Chính vì là bạn nên tôi mới muốn nhờ công việc này.","vi":"──────────"},{"ja":"～だけに  (N2): \"Chính vì... nên càng...\", nhấn mạnh mức độ của kết quả do lý do đó.  「からこそ」 nhấn mạnh sự đặc biệt của lý do.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('49.  から見ると  /  から見れば: Từ quan điểm của; nhìn từ; xét từ ~.', 'N2', 'Dùng để đưa ra nhận xét, đánh giá hoặc phán đoán dựa trên một góc nhìn, lập trường, hoặc tiêu chuẩn nào đó (N). Thường nhấn mạnh góc nhìn khách quan hơn so với  「から言うと」.', 'N +  から見ると /  から見れば /  から見て', '[{"ja":"専門家から見ると、この絵はあまり価値がないらしい。","romaji":"→ Từ quan điểm của chuyên gia thì có vẻ bức tranh này không có giá trị lắm.","vi":""},{"ja":"昔の人から見れば、現代の生活は夢のようだ。","romaji":"→ Nhìn từ góc độ của người xưa, cuộc sống hiện đại giống như một giấc mơ.","vi":""},{"ja":"データから見て、この計画は成功する可能性が高い。","romaji":"→ Xét từ dữ liệu thì kế hoạch này có khả năng thành công cao.","vi":"──────────"},{"ja":"～からすると  (N2): \"Xét từ ~\", cũng rất giống nhau, thường dùng khi suy đoán dựa trên cơ sở nào đó.","romaji":"","vi":""},{"ja":"～にとって  (N3): \"Đối với ~\", chỉ đối tượng chịu ảnh hưởng hoặc đối tượng của sự đánh giá.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('50.  からには: Một khi đã; vì ~.', 'N2', 'Diễn tả rằng một khi đã có một sự thật hoặc quyết định A, thì việc làm B là điều đương nhiên, tất yếu, hoặc là nghĩa vụ, trách nhiệm phải làm.', 'Động từ thể thường (V る / V た) +  からには', '[{"ja":"引き受けたからには、最後まで責任を持ってやります。","romaji":"→ Một khi đã nhận lời thì tôi sẽ làm có trách nhiệm đến cùng.","vi":""},{"ja":"日本に来たからには、ぜひ富士山に登ってみたい。","romaji":"→ Một khi đã đến Nhật thì tôi nhất định muốn thử leo núi Phú Sĩ.","vi":""},{"ja":"プロであるからには、常に最高のパフォーマンスを目指すべきだ。","romaji":"→ Vì là dân chuyên nghiệp nên phải luôn nhắm đến màn trình diễn tốt nhất.","vi":"──────────"},{"ja":"～上は（うえは）  (N2): Cũng giống nhau, có thể trang trọng hơn một chút.","romaji":"","vi":""},{"ja":"～のだから  (N3): \"Vì là...\", chỉ lý do nhưng không mạnh bằng  「からには 」.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('51.  からして: Xét từ; dựa trên; ngay cả ~.', 'N2', '1.   Đưa ra ví dụ tiêu biểu: Dùng để nêu lên một ví dụ cơ bản nhất, điển hình nhất để nói rằng ngay cả cái đó đã như vậy thì những cái khác cũng tương tự hoặc tệ hơn/tốt hơn.  2.   Căn cứ phán đoán: Dùng để chỉ căn cứ, cơ sở để đưa ra một phán đoán nào đó (ít dùng hơn nghĩa 1).', 'N +  からして', '[{"ja":"あのレストランは、入り口からして汚い。料理も期待できないだろう。","romaji":"→ Nhà hàng đó, ngay cả cái lối vào cũng đã bẩn rồi. Chắc món ăn cũng không trông mong gì được.","vi":""},{"ja":"彼の態度からして、反省しているようには見えない。","romaji":"→ Xét từ thái độ của anh ta thì không có vẻ gì là đang hối lỗi.","vi":""},{"ja":"タイトルからして、面白そうな本だ。","romaji":"→ Ngay từ cái tựa đề đã thấy là một cuốn sách có vẻ thú vị.","vi":"──────────"},{"ja":"～はもちろん  (N3): \"~ thì đương nhiên rồi\", dùng để nói A là đương nhiên, B cũng vậy.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('52.  からすると  /  からすれば: Xét từ; xem xét; nhìn từ ~.', 'N2', 'Dùng để đưa ra một sự phán đoán, suy luận, hoặc ý kiến dựa trên một cơ sở, một bằng chứng, hoặc một lập trường nào đó (N).', 'N +  からすると /  からすれば', '[{"ja":"症状からすると、インフルエンザの可能性が高い。","romaji":"→ Xét từ triệu chứng thì khả năng cao là bị cúm.","vi":""},{"ja":"周囲の状況からすれば、彼の成功は難しいだろう。","romaji":"→ Xét từ tình hình xung quanh thì thành công của anh ấy chắc là khó khăn.","vi":""},{"ja":"私からすれば、それは当たり前のことだ。","romaji":"→ Đối với tôi (xét từ lập trường của tôi) thì đó là chuyện đương nhiên.","vi":"──────────"},{"ja":"～から見ると  (N2): \"Nhìn từ ~\".","romaji":"","vi":""},{"ja":"～にしたら  /  ～にすれば  (N2): \"Đối với ~\", thường dùng khi đặt mình vào vị trí người khác.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('53.  からと言って（からといって）: Chỉ vì; ngay cả khi; mặc dù ~.', 'N2', 'Dùng để diễn tả rằng chỉ vì có lý do A không có nghĩa là B cũng luôn đúng hoặc B là điều nên làm. Thường dùng để phủ định một kết luận dễ dãi, hoặc đưa ra ý kiến trái ngược.', 'V / A い / A な / N + (thể thường) +  からと言って', '[{"ja":"日本に住んでいるからと言って、日本語がぺらぺらだとは限らない。","romaji":"→ Chỉ vì sống ở Nhật không có nghĩa là tiếng Nhật sẽ trôi chảy.","vi":""},{"ja":"好きだからと言って、何でも買ってあげるわけにはいかない。","romaji":"→ Dù là thích nhưng không phải cái gì cũng mua cho được.","vi":""},{"ja":"安いからと言って、すぐに買うのはやめなさい。","romaji":"→ Đừng có chỉ vì rẻ mà mua ngay lập tức.","vi":"──────────"},{"ja":"～のに  (N4): \"Mặc dù... nhưng...\", chỉ sự đối lập thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('54.  っこない: Không đời nào; chắc chắn không thể ~.', 'N2', 'Dùng để phủ định mạnh mẽ một khả năng nào đó, khẳng định rằng việc đó tuyệt đối không thể xảy ra hoặc không thể làm được. Mang tính chủ quan và thường dùng trong văn nói.', 'Động từ thể  ます (bỏ  ます) +  っこない', '[{"ja":"宝くじなんて、当たりっこないよ。","romaji":"→ Xổ số á, không đời nào trúng được đâu.","vi":""},{"ja":"あんなに難しい試験、私にできっこない。","romaji":"→ Kỳ thi khó như thế, tôi chắc chắn không thể làm được.","vi":""},{"ja":"今から行っても、間に合いっこない。","romaji":"→ Giờ có đi thì cũng không đời nào kịp.","vi":"──────────"},{"ja":"～わけがない  (N3): \"Không có lý nào...\", phủ định mạnh mẽ dựa trên logic hoặc tình huống.  「っこない」 mang tính chủ quan, cảm tính hơn.","romaji":"","vi":""},{"ja":"～得ない  (N2): \"Không thể\", trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('55.  ことだ: Nên ~ (dùng để gợi ý hoặc khuyên bảo).', 'N2', 'Dùng để đưa ra lời khuyên, gợi ý, hoặc mệnh lệnh nhẹ nhàng, thường là từ người có vị thế cao hơn hoặc có kinh nghiệm hơn nói với người khác, hoặc tự nhủ với bản thân.', 'V る / V ない +  ことだ', '[{"ja":"疲れているなら、無理をしないことです。","romaji":"→ Nếu mệt thì nên không cố gắng quá sức.","vi":""},{"ja":"人の悪口は言わないことだ。","romaji":"→ Không nên nói xấu người khác.","vi":""},{"ja":"合格したければ、もっと勉強することだ。","romaji":"→ Nếu muốn đỗ thì nên học nhiều hơn.","vi":"──────────"},{"ja":"～べきだ  (N3): \"Nên ~\", chỉ điều nên làm theo lẽ thường, đạo đức, hoặc quy tắc chung.","romaji":"","vi":""},{"ja":"～なさい  (N5): \"Hãy ~\", là mệnh lệnh (thường dùng cho người dưới).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('56.  ことだから: Bởi vì; vì là ~ (thường nói về người, dựa vào tính cách/đặc điểm của họ).', 'N2', 'Dùng khi đưa ra một phán đoán hoặc suy luận về hành động của một người (N), dựa trên tính cách, thói quen, hoặc đặc điểm vốn có của người đó mà người nói biết rõ.', 'N の +  ことだから', '[{"ja":"真面目な田中さんのことだから、きっと時間通りに来るでしょう。","romaji":"→ Vì là anh Tanaka người nghiêm túc nên chắc chắn anh ấy sẽ đến đúng giờ.","vi":""},{"ja":"いつも優しい母のことだから、きっと許してくれるはずだ。","romaji":"→ Vì là người mẹ luôn hiền hậu của tôi nên chắc chắn mẹ sẽ tha thứ.","vi":""},{"ja":"あわてんぼうの彼のことだから、また何か忘れたんじゃない？","romaji":"→ Vì là cậu ta, một người hay vội vàng hấp tấp, nên chẳng phải lại quên gì đó rồi sao?","vi":"──────────"},{"ja":"～だけに  (N2): \"Chính vì... nên càng...\", nhấn mạnh mức độ, còn  「ことだ から」 nhấn mạnh sự suy đoán dựa trên bản chất.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('57.  ことか: Biết bao!; làm sao!; thật là ~!', 'N2', 'Dùng để diễn tả cảm xúc mạnh mẽ, sự cảm thán, ngạc nhiên, hoặc than thở về một điều gì đó. Thường đi kèm với các từ như  「どんなに」、「なんと」 、「どれほど」 để nhấn mạnh mức độ.', 'V た / A かった / A なだった +  ことか   どんなに /  なんと /  どれほど + V た / A い / A な +  ことか', '[{"ja":"外国で一人暮らしをするのが、どんなに寂しいことか。","romaji":"→ Sống một mình ở nước ngoài thật là buồn biết bao!","vi":""},{"ja":"合格の知らせを聞いた時、どれほど嬉しかったことか。","romaji":"→ Khi nghe tin báo đỗ, tôi đã vui mừng biết chừng nào!","vi":""},{"ja":"この日をどれだけ待ち望んだことか。","romaji":"→ Tôi đã mong chờ ngày này biết bao nhiêu.","vi":"──────────"},{"ja":"どんなに～か  (N3): Cũng diễn tả mức độ \"Biết bao nhiêu\", thường dùng trong câu tường thuật cảm xúc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('58.  ことなく: Mà không (làm gì dù chỉ một lần).', 'N2', 'Diễn tả một hành động hoặc trạng thái diễn ra mà không có hành động V đi kèm. Mang sắc thái trang trọng hơn  「ないで」 hoặc  「ずに」.', 'Động từ thể từ điển (V る) +  ことなく', '[{"ja":"彼は一度も休むことなく、研究を続けた。","romaji":"→ Anh ấy đã tiếp tục nghiên cứu mà không nghỉ một lần nào.","vi":""},{"ja":"最後まであきらめることなく、頑張ってください。","romaji":"→ Xin hãy cố gắng đến cùng mà không bỏ cuộc.","vi":""},{"ja":"雨は止むことなく、一日中降り続いた。","romaji":"→ Mưa đã rơi suốt cả ngày mà không ngớt.","vi":"──────────"},{"ja":"～ずに  (N3): \"Mà không ~\", trang trọng hơn  「ないで」 một chút, thường dùng trong văn viết.  「ことなく」 là cách nói trang trọng nhất.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('59.  ことに: Thật là ~ (nhấn mạnh cảm xúc).', 'N2', 'Đứng ở đầu câu, dùng để nhấn mạnh cảm xúc, sự ngạc nhiên, hoặc đánh giá của người nói về sự việc được trình bày ở vế sau.', 'V た / A い / A な +  ことに', '[{"ja":"嬉しいことに、試験に合格しました。","romaji":"→ Thật là vui, tôi đã thi đỗ.","vi":""},{"ja":"驚いたことに、彼は私の元カレの弟だった。","romaji":"→ Thật là ngạc nhiên, anh ta lại là em trai của bạn trai cũ tôi.","vi":""},{"ja":"残念なことに、楽しみにしていた旅行が中止になった。","romaji":"→ Thật là đáng tiếc, chuyến du lịch mà tôi mong chờ đã bị hủy.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('60.  ことにはならない: Chỉ vì... không có nghĩa là ~.', 'N2', 'Dùng để phủ nhận rằng chỉ dựa vào một lý do hoặc một điều kiện nào đó thì không thể kết luận hoặc khẳng định một điều khác.', '[Lý do/Sự thật] +  からといって +  ～ことにはならない   [Điều kiện] +  だけでは +  ～ことにはならない', '[{"ja":"少し日本語が話せるからと言って、通訳ができることにはならない。","romaji":"→ Chỉ vì nói được một chút tiếng Nhật không có nghĩa là có thể làm phiên dịch.","vi":""},{"ja":"書類を提出しただけでは、申し込みが完了したことにはならない。","romaji":"→ Chỉ nộp tài liệu thôi thì không có nghĩa là việc đăng ký đã hoàn tất.","vi":""},{"ja":"知っていることにはならない。","romaji":"→ (Không có nghĩa là biết.)","vi":"──────────"},{"ja":"～とは限らない  (N3): \"Không nhất thiết là...\", \"chưa chắc là...\".  「ことに はならない」 nhấn mạnh hơn vào việc không thể được coi là.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('61.  くせして: Mặc dù; dù ~ (thể hiện sự bất mãn, chỉ trích).', 'N2', 'Giống như  「くせに」, dùng để diễn tả sự đối lập giữa hai vế, nhưng mang sắc thái chỉ trích, bất mãn, hoặc khinh thường mạnh hơn. Thường dùng trong văn nói thân mật, đôi khi hơi thô.', 'V / A い / A な / N + (thể thường) +  くせして   (A な +  な / N +  の +  くせして)', '[{"ja":"知らないくせして、知っているふりをするな。","romaji":"→ Đã không biết thì đừng có giả vờ là biết.","vi":""},{"ja":"子供のくせして、大人のような口をきく。","romaji":"→ Dù là trẻ con mà lại nói năng như người lớn.","vi":""},{"ja":"お金もないくせして、高いものばかり欲しがる。","romaji":"→ Tiền thì không có vậy mà toàn đòi những thứ đắt tiền.","vi":"──────────"},{"ja":"～のに  (N4): \"Mặc dù\", chỉ sự đối lập thông thường, không nhất thiết mang ý chỉ trích.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('62.  まだしも: ~ thì còn được; ~ thì còn hơn.', 'N2', 'Dùng để so sánh hai sự việc, và cho rằng vế trước (A) còn có thể chấp nhận được, nhưng vế sau (B) thì quá đáng, không thể chấp nhận được.', 'N +  なら +  まだしも   V る / A い / A な +  なら +  まだしも', '[{"ja":"１０分や２０分の遅刻ならまだしも、１時間も待たせるなんて許せない。","romaji":"→ Nếu trễ 10 hay 20 phút thì còn được, chứ bắt chờ cả tiếng đồng hồ thì không thể tha thứ được.","vi":""},{"ja":"少しのミスならまだしも、こんなに大きな失敗は問題だ。","romaji":"→ Nếu là lỗi nhỏ thì còn đỡ, chứ thất bại lớn thế này thì là vấn đề đấy.","vi":""},{"ja":"旅行先が国内ならまだしも、海外となると準備が大変だ。","romaji":"→ Nếu điểm du lịch là trong nước thì còn được, chứ là nước ngoài thì chuẩn bị mệt lắm.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('63.  まい: Sẽ không; có lẽ sẽ không; định không; không được ~.', 'N2', '1.   Phủ định ý chí: Diễn tả ý chí mạnh mẽ rằng sẽ không làm gì đó (giống  ～ないつもりだ).  2.   Phủ định suy đoán: Diễn tả sự suy đoán rằng có lẽ sẽ không xảy ra (giống  ～ないだろう).', 'V る +  まい (Nhóm 1&2, một số V nhóm 3)   V ます (bỏ  ます) +  まい (Nhóm 1&2)   するまい /  すまい /  くるまい /  こまい (Động từ đặc biệt)', '[{"ja":"もう二度とあんな間違いはするまいと心に誓った。","romaji":"→ Tôi đã thề với lòng là sẽ không bao giờ mắc sai lầm như thế nữa.","vi":""},{"ja":"彼が本当のことを言うことはあるまい。","romaji":"→ Có lẽ anh ta sẽ không nói sự thật đâu.","vi":""},{"ja":"行こうか行くまいか、迷っている。","romaji":"→ Tôi đang phân vân không biết nên đi hay không.","vi":"──────────"},{"ja":"～つもりはない  (N3): \"Không định\", chỉ sự phủ định ý chí, phổ biến hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('64.  ままに: Cứ theo như ~.', 'N2', 'Diễn tả việc làm theo y như sự chỉ dẫn, gợi ý, mong muốn, hoặc trạng thái tự nhiên của một cái gì đó, phó mặc cho nó.', 'V られる +  ままに   V る / N の +  ままに', '[{"ja":"セールスマンに言われるままに、高価な契約をしてしまった。","romaji":"→ Tôi đã ký một hợp đồng đắt tiền cứ theo như lời người bán hàng nói.","vi":""},{"ja":"足の向くままに歩いていたら、知らない場所に来てしまった。","romaji":"→ Cứ đi theo chân đưa lối, tôi đã đến một nơi không biết.","vi":""},{"ja":"心の赴くままに、絵を描く。","romaji":"→ Tôi vẽ tranh cứ theo như con tim mách bảo.","vi":"──────────"},{"ja":"～ように  (N4): \"Theo như\", \"giống như\", có thể dùng rộng hơn.  「ままに 」 có sắc thái phó mặc, tự nhiên hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('65.  全く～ない（まったく～ない）: Hoàn toàn không ~.', 'N2', 'Dùng để phủ định hoàn toàn một sự việc hoặc trạng thái. Nhấn mạnh mức độ "không" là tuyệt đối.', '全く + V ない / A くない / A でない / N でない', '[{"ja":"彼の言っていることは、全く理解できない。","romaji":"→ Những gì anh ta nói tôi hoàn toàn không thể hiểu được.","vi":""},{"ja":"昨日の試験は全くできなかった。","romaji":"→ Bài thi hôm qua tôi hoàn toàn không làm được.","vi":""},{"ja":"私はお酒が全く飲めません。","romaji":"→ Tôi hoàn toàn không thể uống rượu.","vi":"──────────"},{"ja":"ちっとも～ない  (N2): \"Không ~ chút nào cả\", thường mang cảm xúc hơn.","romaji":"","vi":""},{"ja":"少しも（すこしも）～ない  (N2): \"Không một chút nào\", cũng nhấn mạnh sự phủ định hoàn toàn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('66.  もかまわず: Không quan tâm đến; bất chấp ~.', 'N2', 'Diễn tả việc thực hiện một hành động mà không để ý, không bận tâm đến những thứ xung quanh (người khác, hoàn cảnh, quy tắc...). Thường dùng để chỉ những hành động hơi tiêu cực, thiếu suy nghĩ hoặc liều lĩnh.', 'N +  もかまわず   V るの +  もかまわず', '[{"ja":"彼女は人目もかまわず、道で大声で泣いた。","romaji":"→ Cô ấy đã khóc lớn trên đường mà không quan tâm đến ánh mắt người khác.","vi":""},{"ja":"子供たちは服が汚れるのもかまわず、泥遊びをしている。","romaji":"→ Lũ trẻ đang chơi bùn mà không bận tâm đến việc quần áo bị bẩn.","vi":""},{"ja":"彼は危険もかまわず、燃えている家の中に飛び込んだ。","romaji":"→ Anh ấy đã lao vào ngôi nhà đang cháy bất chấp nguy hiểm.","vi":"──────────"},{"ja":"～にもかかわらず  (N2): \"Mặc dù ~\", chỉ sự đối lập, trang trọng hơn và không nhất thiết mang ý phớt lờ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('67.  も当然だ（もとうぜんだ）: ~ là đương nhiên; thảo nào ~.', 'N2', 'Diễn tả rằng một kết quả hoặc tình huống nào đó là điều hợp lý, dễ hiểu, không có gì đáng ngạc nhiên dựa trên nguyên nhân hoặc tình huống đã có.', '～のは当然だ (Noha touzen da)   ～ても当然だ (Temo touzen da)', '[{"ja":"あれだけ努力したのだから、彼が成功するのも当然だ。","romaji":"→ Vì đã nỗ lực đến thế nên việc anh ấy thành công cũng là đương nhiên.","vi":""},{"ja":"約束を破ったのだから、彼女が怒るのも当然だ。","romaji":"→ Vì đã thất hứa nên việc cô ấy tức giận cũng là đương nhiên.","vi":""},{"ja":"何も勉強しなかったのだから、試験に落ちても当然だ。","romaji":"→ Vì chẳng học gì cả nên dù thi trượt cũng là đương nhiên.","vi":"──────────"},{"ja":"～はずだ  (N4): \"Chắc chắn là\", diễn tả sự suy đoán có căn cứ, nhưng không mạnh bằng \"đương nhiên\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('68.  もの  /  もん: Bởi vì; vì (chỉ lý do/ viện cớ/ bất mãn - thường dùng trong văn nói).', 'N2', 'Đứng cuối câu, dùng để đưa ra lý do, lời giải thích, hoặc viện cớ. Thường được dùng trong các cuộc hội thoại thân mật, đặc biệt là bởi phụ nữ và trẻ em. Mang sắc thái chủ quan, đôi khi là nũng nịu hoặc bất mãn.', '[Câu] +  もの /  もん', '[{"ja":"A:  どうして遅刻したの？ (Sao lại đến muộn?) B:  だって、電車が遅れたんだもの。","romaji":"→ (Tại vì... tàu điện bị trễ mà.)","vi":""},{"ja":"もう寝るの？子供なんだもん、早く寝なきゃ。","romaji":"→ (Ngủ rồi à? Vì là trẻ con mà, phải ngủ sớm chứ.)","vi":""},{"ja":"勉強したくないんだもん。","romaji":"→ (Tại con không muốn học mà.)","vi":"──────────"},{"ja":"～んだ  /  ～んだもん  (N4/N3): Cũng dùng để giải thích lý do, rất giống nhau, mang tính văn nói.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('69.  ものだ: Diễn tả cảm xúc; hồi tưởng; nêu lên sự thật/bản chất.', 'N2', 'Là một mẫu ngữ pháp đa nghĩa:  1.   Bản chất: Diễn tả một sự thật hiển nhiên, một quy luật tự nhiên, hoặc một điều nên/không nên làm theo lẽ thường.  2.   Hồi tưởng: Nhớ lại những thói quen, sự việc thường xảy ra trong quá khứ.  3.   Cảm thán: Nhấn mạnh cảm xúc, sự ngạc nhiên, thán phục.', '1.   V る / V ない +  ものだ (Bản chất/Quy luật/Lời khuyên)  2.   V た +  ものだ (Hồi tưởng)  3.   V たい / A い / A な +  ものだ (Cảm thán)', '[{"ja":"1.   人間は誰でも間違いを犯すものだ。","romaji":"→ (Con người ai cũng là kẻ phạm sai lầm - Bản chất)","vi":"2.   子供のころ、よくこの川で泳いだものだ。"},{"ja":"～ことだ  (N2): \"Nên ~\", chỉ lời khuyên.","romaji":"","vi":""},{"ja":"～ことか  (N2): \"Biết bao\", chỉ cảm thán mạnh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('70.  ものだから: Vì; do đó; lý do là ~.', 'N2', 'Dùng để trình bày lý do, nhưng thường là những lý do mang tính khách quan, hoàn cảnh bắt buộc, hoặc để biện minh một cách nhẹ nhàng.', 'V / A い / A な / N + (thể thường) +  ものだから /  もので   (A な +  な / N +  な +  ものだから)', '[{"ja":"事故があったものだから、電車が遅れてしまった。","romaji":"→ Vì có tai nạn nên tàu điện đã bị trễ.","vi":""},{"ja":"急いでいたもので、挨拶もせずにすみません。","romaji":"→ Vì đang vội nên xin lỗi vì đã không chào hỏi.","vi":""},{"ja":"彼はまだ子供なものですから、失礼をお許しください。","romaji":"→ Vì cháu nó còn nhỏ nên xin hãy bỏ qua sự thất lễ.","vi":"──────────"},{"ja":"～もの  /  もん  (N2): Chỉ lý do, nhưng thân mật và chủ quan hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('71.  ものではない: Không nên làm gì đó; không thể ~.', 'N2', '1.   Lời khuyên/Quy tắc: Diễn tả một điều không nên làm theo lẽ thường, đạo đức, hoặc quy tắc xã hội.  2.   Phủ định khả năng: Diễn tả một việc gì đó không thể làm được (ít dùng hơn).', 'V る +  ものではない /  もんではない', '[{"ja":"目上の人に対して、そんな失礼なことを言うものではない。","romaji":"→ Không nên nói những lời thất lễ như vậy với người trên.","vi":""},{"ja":"人の悪口は聞くものではない。","romaji":"→ Không nên nghe chuyện nói xấu người khác.","vi":""},{"ja":"約束は簡単に破るものではない。","romaji":"→ Lời hứa không phải là thứ có thể dễ dàng phá vỡ.","vi":"──────────"},{"ja":"～べきではない  (N3): \"Không nên\", chỉ điều không nên làm theo lẽ thường/đạo đức.  「ものではない」 mang tính quy tắc xã hội, lẽ thường chung chung hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('72.  ものがある: Có cảm giác như là; có điều gì đó ~.', 'N2', 'Dùng để diễn tả rằng người nói cảm nhận được một điều gì đó đặc biệt, một cảm giác khó tả, hoặc một giá trị nào đó từ một sự vật, sự việc.', 'V る / A い / A な +  ものがある', '[{"ja":"彼の絵には、人の心を惹きつけるものがある。","romaji":"→ Tranh của anh ấy có một cái gì đó thu hút lòng người.","vi":""},{"ja":"彼の話には、どこか納得できないものがある。","romaji":"→ Trong câu chuyện của anh ta, có điều gì đó mà tôi không thể chấp nhận được.","vi":""},{"ja":"彼の演奏には、感動させるものがある。","romaji":"→ Buổi biểu diễn của anh ấy có điều gì đó khiến người ta cảm động.","vi":"──────────"},{"ja":"～気がする  (N4): \"Cảm thấy hình như là...\", diễn tả cảm giác không chắc chắn.  「ものがある」 thường chỉ một giá trị hoặc đặc tính sâu sắc hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('73.  ものか  /  もんか: Làm gì có chuyện; không đời nào ~.', 'N2', 'Dùng để phủ định mạnh mẽ một điều gì đó, thể hiện ý chí hoặc sự quả quyết của người nói rằng "tuyệt đối không", "không đời nào". Thường dùng trong văn nói thân mật.', 'V る / A い / A な / N な +  ものか /  もんか', '[{"ja":"あんな失礼な人に、二度と会うものか。","romaji":"→ Người bất lịch sự như thế, không đời nào tôi gặp lại lần nữa.","vi":""},{"ja":"負けるもんか！最後まで戦うぞ！","romaji":"→ Không đời nào thua! Sẽ chiến đấu đến cùng!","vi":""},{"ja":"あの店の料理が美味しいものか。二度と行かない。","romaji":"→ Món ăn quán đó mà ngon á? Làm gì có chuyện! Tôi sẽ không đến lần thứ hai.","vi":"──────────"},{"ja":"～わけがない  (N3): \"Không có lý nào...\", phủ định mạnh mẽ dựa trên logic. 「ものか」 mang tính ý chí, cảm xúc mạnh hơn.","romaji":"","vi":""},{"ja":"～っこない  (N2): \"Chắc chắn không thể...\", phủ định khả năng, thân mật.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('74.  ものなら: Nếu có thể; nếu [A] có thể, thì [B] ~.', 'N2', 'Dùng để diễn tả một giả định, thường là về một điều khó hoặc không thể xảy ra. Vế sau thường thể hiện mong muốn mạnh mẽ hoặc một kết quả tất yếu nếu điều đó xảy ra.', 'Động từ thể khả năng (V れる) +  ものなら', '[{"ja":"やれるものなら、やってみろ。","romaji":"→ Nếu có thể làm được thì làm thử đi.","vi":""},{"ja":"昔に戻れるものなら、戻って人生をやり直したい。","romaji":"→ Nếu có thể quay lại quá khứ, tôi muốn quay lại làm lại cuộc đời.","vi":""},{"ja":"買えるものなら、あの大きな家が欲しい。","romaji":"→ Nếu có thể mua được, tôi muốn có căn nhà lớn đó.","vi":"──────────"},{"ja":"もし～たら  (N4): \"Nếu ~ thì ~\", chỉ giả định thông thường.  「ものなら」 nhấn mạnh vào điều kiện khó xảy ra.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('75.  ものの: Nhưng; mặc dù; dù cho ~.', 'N2', 'Dùng để nối hai vế có ý nghĩa tương phản, trái ngược. Vế trước thừa nhận một sự thật, nhưng vế sau lại đưa ra một kết quả hoặc tình trạng không tương xứng, bất ngờ. Mang sắc thái trang trọng hơn  「けど」.', 'V / A い / A な / N + (thể thường) +  ものの   (A な +  な / N +  である +  ものの)', '[{"ja":"免許は取ったものの、車がないので運転できない。","romaji":"→ Mặc dù đã lấy được bằng lái, nhưng vì không có xe nên không thể lái được.","vi":""},{"ja":"薬を飲んだものの、熱はなかなか下がらない。","romaji":"→ Dù đã uống thuốc nhưng sốt mãi không hạ.","vi":""},{"ja":"大学は卒業したものの、まだ就職先が見つからない。","romaji":"→ Tuy đã tốt nghiệp đại học nhưng tôi vẫn chưa tìm được việc làm.","vi":"──────────"},{"ja":"～のに  (N4): \"Mặc dù\", thường mang sắc thái bất mãn, ngạc nhiên.","romaji":"","vi":""},{"ja":"～にもかかわらず  (N2): \"Bất chấp\", \"mặc dù\", trang trọng, nhấn mạnh sự đối lập mạnh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('76.  もっとも: Nhưng mà; tuy nhiên; mặc dù ~.', 'N2', 'Dùng để bổ sung thông tin, đưa ra một ngoại lệ, hoặc một điều kiện giới hạn cho những gì đã nói ở vế trước.', '[Câu 1]。もっとも、[Câu 2]。', '[{"ja":"旅行は無料です。もっとも、食費は自己負担となります。","romaji":"→ Chuyến du lịch là miễn phí. Tuy nhiên, tiền ăn sẽ tự túc.","vi":""},{"ja":"彼は試験に合格した。もっとも、それは一番簡単なレベルだったが。","romaji":"→ Anh ta đã thi đỗ. Mặc dù, đó là cấp độ dễ nhất.","vi":""},{"ja":"このレストランは美味しい。もっとも、値段は少し高い。","romaji":"→ Nhà hàng này ngon. Có điều là, giá hơi cao một chút.","vi":"──────────"},{"ja":"しかし  (N4): \"Tuy nhiên\", chỉ sự đối lập mạnh mẽ hơn.","romaji":"","vi":""},{"ja":"でも  (N5): \"Nhưng\", dùng phổ biến trong văn nói.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('77.  もう少しで（もうすこしで）: Suýt nữa; gần ~.', 'N2', 'Diễn tả một tình huống suýt nữa đã xảy ra (thường là việc không tốt), nhưng cuối cùng lại không xảy ra.', 'もう少しで + V る +  ところだった', '[{"ja":"もう少しで車にひかれるところだった。","romaji":"→ Suýt nữa thì tôi bị xe ô tô đâm.","vi":""},{"ja":"あと５分遅れていたら、もう少しで飛行機に乗り遅れるところだった。","romaji":"→ Nếu muộn thêm 5 phút nữa thì suýt nữa đã lỡ chuyến bay.","vi":""},{"ja":"もう少しでゴールだったのに、転んでしまった。","romaji":"→ Suýt nữa là về đích rồi, vậy mà lại bị ngã.","vi":"──────────"},{"ja":"あやうく～ところだった  (N2): \"Suýt soát\", \"nguy hiểm\", nhấn mạnh sự may mắn thoát khỏi tình huống xấu.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('78.  ないではいられない: Không thể không cảm thấy; không thể không làm ~.', 'N2', 'Diễn tả một cảm xúc hoặc hành động mà người nói không thể kìm nén được, dù có muốn hay không cũng phải bộc lộ hoặc thực hiện.', 'Động từ thể  ない (bỏ  ない) +  ないではいられない', '[{"ja":"彼の面白い話を聞いて、笑わないではいられなかった。","romaji":"→ Nghe câu chuyện thú vị của anh ấy, tôi đã không thể không cười.","vi":""},{"ja":"あの感動的な映画を見て、泣かないではいられなかった。","romaji":"→ Xem bộ phim cảm động đó, tôi đã không thể không khóc.","vi":""},{"ja":"この状況を見て、何か言わないではいられない。","romaji":"→ Thấy tình hình này, tôi không thể không nói gì đó.","vi":"──────────"},{"ja":"～てならない  (N2): \"Rất ~\", \"không chịu được\", dùng để nhấn mạnh cảm xúc mạnh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('79.  ないことには～ない: Nếu không ~ thì không ~.', 'N2', 'Diễn tả rằng nếu không thực hiện hành động A (vế trước) thì hành động B (vế sau) cũng không thể thực hiện được. A là điều kiện tiên quyết cho B.', 'V ない +  ことには + [Vế sau ở thể phủ định]', '[{"ja":"実際に会ってみないことには、どんな人かわからない。","romaji":"→ Nếu không thực sự gặp thử thì không thể biết là người thế nào.","vi":""},{"ja":"詳しく調べてみないことには、原因は特定できない。","romaji":"→ Nếu không điều tra chi tiết thì không thể xác định được nguyên nhân.","vi":""},{"ja":"お金がないことには、この計画は始められない。","romaji":"→ Nếu không có tiền thì kế hoạch này không thể bắt đầu được.","vi":"──────────"},{"ja":"～てからでないと～ない  (N3): \"Nếu chưa ~ thì không ~\", nhấn mạnh vào trình tự thời gian, phải làm A xong rồi mới làm B.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('80.  中を  /  中では（なかを  /  なかでは）: Trong; giữa lúc; khi; trong khi ~.', 'N2', 'Dùng để diễn tả một hành động xảy ra trong một hoàn cảnh, tình huống, hoặc điều kiện đặc biệt nào đó (thường là khó khăn, không thuận lợi).', 'N +  の +  中を /  中では   V ている / A い +  中を /  中では', '[{"ja":"雨の中を、わざわざお越しいただきありがとうございます。","romaji":"→ Cảm ơn quý khách đã cất công đến đây giữa lúc trời mưa.","vi":""},{"ja":"お忙しい中を、手伝ってくださって感謝します。","romaji":"→ Tôi rất biết ơn vì anh đã giúp đỡ giữa lúc bận rộn.","vi":""},{"ja":"危険な中では、冷静に行動することが大切だ。","romaji":"→ Trong lúc nguy hiểm, việc hành động bình tĩnh là rất quan trọng.","vi":"──────────"},{"ja":"～うちに  (N3): \"Trong lúc\", thường dùng khi cần tranh thủ làm gì đó hoặc khi có sự thay đổi.","romaji":"","vi":""},{"ja":"～ときに  (N5): \"Khi\", chỉ thời điểm.  「中を/中では」 nhấn mạnh hơn vào bối cảnh/hoàn cảnh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('81.  なくはない  /  なくもない: Không phải là không; cũng có thể ~.', 'N2', 'Là dạng phủ định kép, dùng để khẳng định một cách yếu ớt, dè dặt, hoặc miễn cưỡng. Diễn tả rằng "không phải là hoàn toàn không, mà cũng có một chút khả năng/cảm giác là có".', 'V なくはない / V なくもない   A くなくはない / A くなくもない   A でなくはない / A でなくもない', '[{"ja":"納豆は食べなくはないですが、あまり好きではありません。","romaji":"→ Natto thì không phải là tôi không ăn được, nhưng không thích lắm.","vi":""},{"ja":"難しいけれど、今から頑張れば合格できなくもない。","romaji":"→ Khó thì khó thật, nhưng nếu cố gắng từ bây giờ thì cũng không phải là không thể đỗ.","vi":""},{"ja":"彼の気持ちも分からなくはない。","romaji":"→ Tôi cũng không phải là không hiểu cảm giác của anh ấy.","vi":"──────────"},{"ja":"～かもしれない  (N4): \"Có lẽ\", chỉ khả năng, nhưng không mang sắc thái phủ định kép.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('82.  なくて済む（なくてすむ）: Không cần làm ~ cũng được; xoay sở mà không cần làm ~.', 'N2', 'Diễn tả rằng một việc gì đó đã được giải quyết hoặc hoàn thành mà không cần phải thực hiện hành động V.', 'V なくて +  済む (すむ)   V ないで +  済む (すむ)', '[{"ja":"バスがすぐ来たので、タクシーに乗らなくて済んだ。","romaji":"→ Vì xe buýt đến ngay nên tôi đã không cần phải đi taxi.","vi":""},{"ja":"友達が古い辞書をくれたので、新しいのを買わなくて済んだ。","romaji":"→ Vì bạn tôi cho cuốn từ điển cũ nên tôi đã không cần mua cái mới.","vi":""},{"ja":"軽いけがだったので、手術しないで済んだ。","romaji":"→ Vì là vết thương nhẹ nên đã ổn mà không cần phẫu thuật.","vi":"──────────"},{"ja":"～必要はない  (N4): \"Không cần thiết phải ~\".","romaji":"","vi":""},{"ja":"～ずに済む  (N2): Nghĩa giống hệt, trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('83.  何も～ない（なにも～ない）: Không có gì; hoàn toàn không ~; không cần phải ~.', 'N2', '1.   Phủ định hoàn toàn: "Không có gì ~ cả", "hoàn toàn không ~".  2.   Không cần thiết: "Không cần phải ~".', '何も + V ない', '[{"ja":"朝から何も食べていないので、お腹がペコペコだ。","romaji":"→ Từ sáng tôi chưa ăn gì cả nên bụng đói meo.","vi":""},{"ja":"彼はその事故について、何も知らなかった。","romaji":"→ Anh ta hoàn toàn không biết gì về vụ tai nạn đó.","vi":""},{"ja":"そんなに心配することはないよ。何も問題ないから。","romaji":"→ Không cần phải lo lắng thế đâu. Vì không có vấn đề gì cả.","vi":""},{"ja":"何もそんなに怒らなくてもいいじゃないか。","romaji":"→ Đâu cần phải tức giận đến thế, phải không?","vi":"──────────"},{"ja":"～必要はない  (N4): \"Không cần thiết phải ~\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('84.  なお: Vẫn còn; hơn nữa; ngoài ra ~.', 'N2', '1.   Vẫn còn (Trạng từ): Diễn tả một trạng thái vẫn tiếp diễn (giống  「まだ」 nhưng trang trọng hơn).  2.   Hơn nữa/Ngoài ra (Liên từ): Dùng để bổ sung thêm thông tin, thêm một điểm nữa vào những gì đã nói.', 'Là một trạng từ (副詞) hoặc liên từ (接続詞).', '[{"ja":"会場の詳細は後日お知らせします。なお、参加費は無料です。","romaji":"→ Chi tiết về hội trường sẽ được thông báo sau. Ngoài ra, phí tham gia là miễn phí.","vi":""},{"ja":"この件については、なお検討が必要です。","romaji":"→ Về vấn đề này, vẫn cần xem xét thêm.","vi":""},{"ja":"彼は以前にも増して、なお一層努力した。","romaji":"→ Anh ấy đã nỗ lực hơn nữa, vượt cả trước đây.","vi":"──────────"},{"ja":"その上（そのうえ）  (N2): \"Hơn nữa\", \"thêm vào đó\".","romaji":"","vi":""},{"ja":"まだ  (N5): \"Vẫn còn\", dùng phổ biến trong văn nói.","romaji":"","vi":""},{"ja":"それに  (N4): \"Hơn nữa\", dùng trong văn nói.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('85.  ねばならない: Phải làm; bắt buộc phải ~.', 'N2', 'Dùng để diễn tả nghĩa vụ, sự bắt buộc phải làm một việc gì đó. Đây là cách nói trang trọng và hơi cổ của  「なければならない」.', 'Động từ thể  ない (bỏ  ない) +  ねばならない /  ねばならぬ', '[{"ja":"どんなに困難でも、この計画は成功させねばならない。","romaji":"→ Dù khó khăn đến mấy cũng phải làm cho kế hoạch này thành công.","vi":""},{"ja":"我々は真実を明らかにせねばならない。","romaji":"→ Chúng ta phải làm rõ sự thật.","vi":""},{"ja":"約束は守らねばならない。","romaji":"→ Lời hứa là phải giữ.","vi":"──────────"},{"ja":"～なくてはいけない  (N4): \"Phải làm\", cũng rất phổ biến.","romaji":"","vi":""},{"ja":"～べきだ  (N3): \"Nên làm\" (theo lẽ thường, đạo đức).","romaji":"","vi":""},{"ja":"～ざるを得ない  (N2): \"Buộc phải làm\" (dù không muốn).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('86.  にあたって: Vào lúc; nhân dịp ~.', 'N2', 'Dùng để nói về một thời điểm, một cơ hội đặc biệt, quan trọng, thường là một sự khởi đầu mới hoặc một sự kiện mang tính bước ngoặt. Vế sau thường nói về những điều cần làm, cần chú ý, hoặc cảm nghĩ vào thời điểm đó.', 'N / V る +  にあたって /  にあたり', '[{"ja":"新しい年を迎えるにあたり、一言ご挨拶申し上げます。","romaji":"→ Nhân dịp chào đón năm mới, tôi xin có đôi lời chào hỏi.","vi":""},{"ja":"開会にあたって、いくつか注意点をお知らせします。","romaji":"→ Vào lúc khai mạc, tôi xin thông báo một vài điểm cần chú ý.","vi":""},{"ja":"留学にあたり、多くの人にお世話になりました。","romaji":"→ Nhân dịp đi du học, tôi đã nhận được sự giúp đỡ của rất nhiều người.","vi":"──────────"},{"ja":"～際に  (N3): \"Vào lúc\", \"khi\", trang trọng hơn  「とき」 nhưng không bằng 「にあたって」.","romaji":"","vi":""},{"ja":"～とき  (N5): \"Khi\", cách nói thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('87.  にほかならない: Không gì khác ngoài; chính là ~.', 'N2', 'Dùng để khẳng định một cách mạnh mẽ rằng nguyên nhân hoặc bản chất của một sự việc chính là N, chứ không phải là bất cứ thứ gì khác.', 'N +  にほかならない', '[{"ja":"今回の成功は、皆さんの協力の賜物にほかならない。","romaji":"→ Thành công lần này không gì khác chính là kết quả của sự hợp tác của mọi người.","vi":""},{"ja":"戦争は悲劇にほかならない。","romaji":"→ Chiến tranh chính là bi kịch.","vi":""},{"ja":"彼が合格したのは、彼自身の努力の結果にほかならない。","romaji":"→ Việc anh ấy đỗ không gì khác chính là kết quả nỗ lực của bản thân anh ấy.","vi":"──────────"},{"ja":"～に違いない  (N3): \"Chắc chắn là\", diễn tả sự suy đoán mạnh mẽ.  「にほ かならない」 diễn tả sự khẳng định, kết luận.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('88.  に限らず（にかぎらず）: Không chỉ; không những... mà còn ~.', 'N2', 'Dùng để diễn tả rằng một sự việc không chỉ đúng với N mà còn đúng với cả những đối tượng khác có phạm vi rộng hơn.', 'N +  に限らず (にかぎらず)', '[{"ja":"この映画は子供に限らず、大人も楽しめます。","romaji":"→ Bộ phim này không chỉ trẻ em mà người lớn cũng có thể thưởng thức.","vi":""},{"ja":"最近は、女性に限らず男性も化粧をする人が増えている。","romaji":"→ Gần đây, không chỉ phụ nữ mà số lượng nam giới trang điểm cũng đang tăng lên.","vi":""},{"ja":"日本国内に限らず、海外でも人気がある。","romaji":"→ Không chỉ trong nước Nhật mà nó còn nổi tiếng cả ở nước ngoài.","vi":"──────────"},{"ja":"～ばかりか  (N2): \"Không chỉ... mà còn...\", nhấn mạnh hơn vào vế sau.","romaji":"","vi":""},{"ja":"～のみならず  (N2): \"Không chỉ...\", trang trọng hơn, thường dùng trong văn viết.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('89.  に限る（にかぎる）: Là nhất; không gì tốt hơn ~.', 'N2', 'Dùng để diễn tả ý kiến chủ quan của người nói rằng trong một tình huống nào đó, N hoặc hành động V là lựa chọn tốt nhất, tuyệt vời nhất.', 'N +  に限る   V る +  に限る', '[{"ja":"暑い夏は、冷たいビールに限る。","romaji":"→ Mùa hè nóng nực thì bia lạnh là nhất.","vi":""},{"ja":"疲れた時は、ゆっくりお風呂に入るに限る。","romaji":"→ Khi mệt mỏi, không gì tốt hơn là ngâm mình thư thái trong bồn tắm.","vi":""},{"ja":"映画はやっぱり映画館で見るに限るね。","romaji":"→ Phim ảnh thì quả nhiên xem ở rạp là tuyệt nhất nhỉ.","vi":"──────────"},{"ja":"～に越したことはない  (N2): \"...là tốt nhất/hơn cả\", nhưng thường dùng để nói về việc có thì tốt hơn, không có cũng không sao.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('90.  に限って（にかぎって）: Chỉ; đặc biệt là ~ (thường chỉ những lúc không may).', 'N2', '1.   Chỉ riêng N: Nhấn mạnh rằng chỉ N mới có đặc điểm đó (thường là đặc biệt tốt, đáng tin cậy).  2.   Đúng vào lúc N: Nhấn mạnh rằng đúng vào lúc quan trọng hoặc lúc không mong muốn (N) thì lại xảy ra chuyện xui xẻo.', 'N +  に限って', '[{"ja":"1.   うちの子に限って、そんな悪いことをするはずがない。","romaji":"→ Riêng con nhà tôi thì làm gì có chuyện làm việc xấu như thế.","vi":"2.   急いでいる時に限って、バスがなかなか来ない。"},{"ja":"～に限らず  (N2): \"Không chỉ\", mang ý nghĩa trái ngược.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('91.  に関わらず（にかかわらず）: Bất kể; không phân biệt ~.', 'N2', 'Diễn tả rằng một sự việc nào đó vẫn xảy ra hoặc vẫn đúng mà không bị ảnh hưởng, không phụ thuộc vào N hoặc sự khác biệt (có hay không, tốt hay xấu...).', 'N +  にかかわらず /  にはかかわらず   V る / V ない +  にかかわらず /  にはかかわらず   A い / A くない +  にかかわらず /  にはかかわらず   N (số lượng) +  の +  いかん +  にかかわらず (Bất kể ít hay nhiều)', '[{"ja":"経験のあるなしにかかわらず、やる気のある人を募集します。","romaji":"→ Chúng tôi tuyển những người có nhiệt huyết, bất kể có kinh nghiệm hay không.","vi":""},{"ja":"天候にかかわらず、試合は行われます。","romaji":"→ Bất kể thời tiết thế nào, trận đấu vẫn sẽ diễn ra.","vi":""},{"ja":"理由のいかんにかかわらず、遅刻は認められません。","romaji":"→ Bất kể lý do là gì, việc đi muộn sẽ không được chấp nhận.","vi":"──────────"},{"ja":"～に関係なく（にかんけいなく）  (N3): \"Không liên quan đến\", \"bất kể\", nghĩa tương tự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('92.  に関わる（にかかわる）: Liên quan đến ~.', 'N2', 'Dùng để chỉ mối quan hệ, sự liên quan, hoặc ảnh hưởng đến một vấn đề, sự việc, hoặc đối tượng nào đó (N). Thường dùng cho những vấn đề quan trọng, có ảnh hưởng lớn.', 'N +  に関わる (にかかわる)', '[{"ja":"彼は環境問題に関わる仕事をしている。","romaji":"→ Anh ấy đang làm công việc liên quan đến vấn đề môi trường.","vi":""},{"ja":"それは人の命に関わる重大な問題だ。","romaji":"→ Đó là vấn đề trọng đại liên quan đến tính mạng con người.","vi":""},{"ja":"この決定は、会社の将来に関わるだろう。","romaji":"→ Quyết định này có lẽ sẽ ảnh hưởng đến tương lai của công ty.","vi":"──────────"},{"ja":"～に関して  (N3): \"Liên quan đến ~\", trang trọng hơn  「について」.  「に 関わる」 mang sắc thái quan trọng, ảnh hưởng lớn hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('93.  に決まっている（にきまっている）: Chắc chắn là; tôi chắc rằng ~.', 'N2', 'Dùng để diễn tả sự phán đoán chắc chắn của người nói, dựa trên cơ sở logic, kinh nghiệm, hoặc niềm tin mạnh mẽ. Mang tính chủ quan và thường dùng trong văn nói.', 'V / A い / A な / N + (thể thường) +  に決まっている', '[{"ja":"あのチームが勝つに決まっているよ。","romaji":"→ Đội đó chắc chắn thắng rồi.","vi":""},{"ja":"そんなことをしたら、怒られるに決まっている。","romaji":"→ Nếu làm chuyện đó thì chắc chắn sẽ bị mắng.","vi":""},{"ja":"彼は正直だから、嘘をつくはずがないに決まっている。","romaji":"→ Anh ấy trung thực nên chắc chắn không đời nào nói dối.","vi":"──────────"},{"ja":"～はずだ  (N4): \"Chắc chắn là\" (theo lẽ thường), mức độ chắc chắn có thể thấp hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('94.  に越したことはない（にこしたことはない）: ~ là tốt nhất; không gì bằng ~.', 'N2', 'Dùng để diễn tả rằng có một điều gì đó (A) thì tốt hơn là không có, hoặc làm A thì tốt hơn là không làm. Thể hiện một lời khuyên hoặc một sự thật hiển nhiên rằng có điều kiện tốt thì vẫn hơn.', 'V る / A い / A な / N +  に越したことはない (にこしたことはない)', '[{"ja":"旅行の荷物は、軽いに越したことはない。","romaji":"→ Hành lý du lịch, nhẹ thì vẫn tốt hơn.","vi":""},{"ja":"用心するに越したことはない。何が起こるかわからないから。","romaji":"→ Cẩn thận thì vẫn tốt hơn. Vì không biết chuyện gì sẽ xảy ra.","vi":""},{"ja":"お金はあるに越したことはないが、それが全てではない。","romaji":"→ Tiền thì có vẫn tốt hơn, nhưng đó không phải là tất cả.","vi":"──────────"},{"ja":"～に限る  (N2): \"~ là nhất\", thể hiện ý kiến chủ quan mạnh mẽ về lựa chọn tốt nhất.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('95.  に応えて（にこたえて）: Đáp lại; hưởng ứng ~.', 'N2', 'Diễn tả một hành động được thực hiện để đáp lại sự kỳ vọng, mong muốn, yêu cầu, hoặc lời kêu gọi của người khác hoặc từ một phía nào đó.', 'N +  に応えて (にこたえて) /  に応え (にこたえ)', '[{"ja":"選手たちは、ファンの声援に応えて、最後まで戦った。","romaji":"→ Các tuyển thủ đã chiến đấu đến cùng để đáp lại sự cổ vũ của người hâm mộ.","vi":""},{"ja":"国民の期待に応えて、政府は新しい政策を発表した。","romaji":"→ Đáp lại sự kỳ vọng của người dân, chính phủ đã công bố chính sách mới.","vi":""},{"ja":"お客様のご要望に応え、営業時間を延長しました。","romaji":"→ Đáp ứng yêu cầu của quý khách, chúng tôi đã kéo dài thời gian kinh doanh.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('96.  に加えて（にくわえて）: Thêm vào đó; ngoài ra ~.', 'N2', 'Dùng để bổ sung thêm một yếu tố, một thông tin vào những gì đã có sẵn. Tương tự như  「だけでなく」 nhưng mang sắc thái trang trọng hơn.', 'N +  に加えて (にくわえて)', '[{"ja":"この料理は、味がいいのに加えて、見た目も美しい。","romaji":"→ Món ăn này, thêm vào vị ngon, vẻ ngoài cũng đẹp mắt.","vi":""},{"ja":"英語に加えて、フランス語も話せます。","romaji":"→ Ngoài tiếng Anh, tôi còn có thể nói tiếng Pháp.","vi":""},{"ja":"雨に加えて、風も強くなってきた。","romaji":"→ Thêm vào mưa, gió cũng đã mạnh lên.","vi":"──────────"},{"ja":"～ばかりか  (N2): \"Không chỉ... mà còn...\", nhấn mạnh hơn vế sau.","romaji":"","vi":""},{"ja":"～上に（うえに）  (N3): \"Hơn nữa\", \"thêm vào đó\", thường dùng khi hai vế cùng chiều (cùng tốt/cùng xấu).","romaji":"","vi":""},{"ja":"さらに  (N3): \"Hơn nữa\", là một trạng từ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('97.  に基づいて（にもとづいて）: Dựa trên; căn cứ vào ~.', 'N2', 'Dùng để diễn tả rằng một hành động, quyết định, hoặc sản phẩm nào đó được thực hiện hoặc tạo ra dựa trên một cơ sở, nền tảng, hoặc nguồn thông tin nào đó (N).', 'N +  に基づいて (にもとづいて) /  に基づき (にもとづき)', '[{"ja":"この映画は、事実に基づいて作られた。","romaji":"→ Bộ phim này được làm dựa trên sự thật.","vi":""},{"ja":"最新のデータに基づき、計画を修正した。","romaji":"→ Dựa trên dữ liệu mới nhất, chúng tôi đã chỉnh sửa kế hoạch.","vi":""},{"ja":"法律に基づいて、公平に判断する。","romaji":"→ Sẽ phán đoán một cách công bằng dựa trên pháp luật.","vi":"──────────"},{"ja":"～によって  (N3): Có nhiều nghĩa, một trong số đó là \"dựa vào\", nhưng thường chỉ phương pháp, cách thức.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('98.  に向かって（にむかって）: Hướng về; đối mặt; đi về phía ~.', 'N2', '1.   Hướng vật lý: Chỉ phương hướng của hành động di chuyển hoặc hướng của một vật.  2.   Hướng mục tiêu: Chỉ đối tượng mà hành động hoặc lời nói nhắm đến.  3.   Hướng thời gian: Chỉ sự tiến dần đến một thời điểm nào đó.', 'N +  に向かって (にむかって) /  に向かい (にむかい) /  に向け(て) (にむ けて)', '[{"ja":"彼は駅に向かって歩いている。","romaji":"→ Anh ấy đang đi bộ về phía nhà ga.","vi":""},{"ja":"出口に向かってください。","romaji":"→ Xin hãy đi về phía lối ra.","vi":""},{"ja":"彼は聴衆に向かってスピーチを始めた。","romaji":"→ Anh ấy đã bắt đầu bài phát biểu hướng về phía khán giả.","vi":""},{"ja":"試験に向けて、一生懸命勉強している。","romaji":"→ (Dùng  「に向けて」)","vi":"→ Tôi đang học hành chăm chỉ hướng tới kỳ thi."},{"ja":"～に対して  (N3): \"Đối với ~\", thường chỉ đối tượng của hành động hoặc thái độ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('99.  に応じて（におうじて）: Tùy theo; ứng với; phù hợp với ~.', 'N2', 'Diễn tả rằng một hành động hoặc trạng thái ở vế sau thay đổi sao cho phù hợp với sự thay đổi, sự khác biệt, hoặc yêu cầu của N ở vế trước.', 'N +  に応じて (におうじて) /  に応じ (におうじ)', '[{"ja":"能力に応じて、クラス分けをします。","romaji":"→ Chúng tôi sẽ phân lớp tùy theo năng lực.","vi":""},{"ja":"予算に応じて、旅行のプランを立てましょう。","romaji":"→ Chúng ta hãy lên kế hoạch du lịch phù hợp với ngân sách.","vi":""},{"ja":"状況に応じた対応が必要です。","romaji":"→ Cần phải có sự đối ứng phù hợp với tình hình.","vi":"──────────"},{"ja":"～に従って（にしたがって）  (N2): \"Theo ~\", chỉ sự thay đổi đồng biến (A thay đổi thì B cũng thay đổi theo).","romaji":"","vi":""},{"ja":"～に応えて  (N2): \"Đáp lại ~\", chỉ sự đáp lại kỳ vọng/yêu cầu.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('100.  に際して（にさいして）: Vào dịp; vào lúc ~ (trang trọng).', 'N2', 'Dùng để chỉ thời điểm bắt đầu hoặc đang diễn ra một sự kiện quan trọng, đặc biệt. Thường dùng trong các thông báo, hướng dẫn, hoặc các tình huống trang trọng.', 'N / V る +  に際して (にさいして) /  に際し (にさいし)', '[{"ja":"お申し込みに際しては、写真が必要となります。","romaji":"→ Vào lúc đăng ký, ảnh là cần thiết.","vi":""},{"ja":"会議を行うに際して、資料を準備した。","romaji":"→ Khi tiến hành cuộc họp, tôi đã chuẩn bị tài liệu.","vi":""},{"ja":"ご利用に際しての注意点をご説明します。","romaji":"→ Tôi xin giải thích những điểm cần chú ý khi sử dụng.","vi":"──────────"},{"ja":"～際に  (N3): \"Vào lúc\", \"khi\", trang trọng hơn  「とき」.","romaji":"","vi":""},{"ja":"～とき  (N5): \"Khi\", cách nói thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('101.  に先立ち（にさきだち）: Trước khi ~ (trang trọng).', 'N2', 'Dùng để diễn tả một hành động được thực hiện trước khi bắt đầu một sự kiện quan trọng, một kế hoạch, hoặc một hoạt động nào đó.', 'N / V る +  に先立ち (にさきだち) /  に先立って (にさきだって)', '[{"ja":"開店に先立ち、関係者だけのパーティーが行われた。","romaji":"→ Trước khi khai trương, một bữa tiệc chỉ dành cho những người liên quan đã được tổ chức.","vi":""},{"ja":"会議に先立って、資料をご確認ください。","romaji":"→ Trước cuộc họp, xin vui lòng xác nhận tài liệu.","vi":""},{"ja":"出発に先立ち、荷物の最終チェックをした。","romaji":"→ Trước khi xuất phát, tôi đã kiểm tra hành lý lần cuối.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('102.  にせよ  /  にしろ: Cho dù; bất kể; dù là... hay là ~.', 'N2', 'Dùng để đưa ra một ví dụ và khẳng định rằng dù trong trường hợp đó hay bất kỳ trường hợp nào khác, vế sau vẫn đúng. Thường dùng để nêu lên một giả định cực đoan hoặc một điều kiện nào đó.', 'V / A い / A な / N + (thể thường) +  にせよ /  にしろ', '[{"ja":"たとえ反対されるにせよ、私は自分の意見を言うつもりだ。","romaji":"→ Cho dù bị phản đối, tôi vẫn định nói ra ý kiến của mình.","vi":""},{"ja":"行くにせよ行かないにせよ、早く連絡してください。","romaji":"→ Dù đi hay không đi, xin hãy liên lạc sớm.","vi":""},{"ja":"どんな理由があるにしろ、遅刻はよくない。","romaji":"→ Bất kể có lý do gì, việc đi muộn là không tốt.","vi":"──────────"},{"ja":"たとえ～ても  (N3): \"Giả sử ~ thì cũng ~\", nhấn mạnh giả định.  「にせよ」 trang trọng hơn và thường dùng khi đưa ra ví dụ để khẳng định một điều.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('103.  にしろ～にしろ  /  にせよ～にせよ: Dù là... hay là ~.', 'N2', 'Dùng để liệt kê hai hoặc nhiều khả năng, lựa chọn, và khẳng định rằng dù là trường hợp nào đi nữa thì kết luận ở vế sau vẫn không thay đổi.', '[A] +  にしろ + [B] +  にしろ   [A] +  にせよ + [B] +  にせよ   (A và B thường là các lựa chọn, danh từ, hoặc động từ đối lập/cùng loại)', '[{"ja":"行くにしろ行かないにしろ、早く決めてください。","romaji":"→ Dù đi hay không đi, xin hãy quyết định sớm.","vi":""},{"ja":"ビールにしろ、日本酒にしろ、飲みすぎは体に悪い。","romaji":"→ Dù là bia hay rượu Nhật, uống quá nhiều đều không tốt cho sức khỏe.","vi":""},{"ja":"賛成するにせよ反対するにせよ、自分の意見をはっきり言うべきだ。","romaji":"→ Dù tán thành hay phản đối, cũng nên nói rõ ý kiến của mình.","vi":"──────────"},{"ja":"～であれ～であれ  (N1): Cách nói trang trọng, văn viết.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('104.  にしたら  /  にすれば: Đối với; từ góc nhìn của ~.', 'N2', 'Dùng để thể hiện ý kiến, cảm xúc, hoặc phán đoán khi đặt mình vào lập trường hoặc vị trí của một người nào đó (N).', 'N (chỉ người) +  にしたら /  にすれば', '[{"ja":"親にしたら、子供の将来が心配なのは当然だろう。","romaji":"→ Đối với cha mẹ thì việc lo lắng cho tương lai con cái có lẽ là đương nhiên.","vi":""},{"ja":"突然仕事を辞めると言われたら、会社にすれば大迷惑だろう。","romaji":"→ Nếu bị nói là đột nhiên nghỉ việc thì đối với công ty chắc là phiền phức lớn.","vi":""},{"ja":"あなたにすれば些細なことかもしれないが、私にとっては大問題だ。","romaji":"→ Đối với bạn có lẽ đó là chuyện nhỏ, nhưng đối với tôi thì là vấn đề lớn.","vi":"──────────"},{"ja":"～から言うと  (N2): \"Nói về ~\", \"từ quan điểm ~\".  「にしたら」 nhấn mạnh hơn vào lập trường và cảm xúc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('105.  にしても～にしても: Bất kể là ~; Dù là... hay là ~.', 'N2', 'Tương tự như  「にしろ～にしろ」, dùng để liệt kê hai hoặc nhiều ví dụ (thường là cùng loại hoặc đối lập) và khẳng định rằng dù là trường hợp nào thì kết luận ở vế sau cũng không thay đổi.', 'N1 +  にしても + N2 +  にしても   V1 +  にしても + V2 +  にしても', '[{"ja":"進学するにしても就職するにしても、自分でよく考えて決めなさい。","romaji":"→ Dù là học lên hay đi làm, hãy tự mình suy nghĩ kỹ và quyết định.","vi":""},{"ja":"来るにしても来ないにしても、連絡ぐらいはすべきだ。","romaji":"→ Dù đến hay không đến, ít nhất cũng nên liên lạc.","vi":""},{"ja":"野菜にしても魚にしても、新鮮なものが一番おいしい。","romaji":"→ Dù là rau hay cá, đồ tươi là ngon nhất.","vi":"──────────"},{"ja":"～ても～ても  (N4): Cách nói tương tự nhưng ít trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('106.  に沿って（にそって）: Men theo; dọc theo; theo ~.', 'N2', '1.   Dọc theo (Không gian): Diễn tả sự di chuyển hoặc tồn tại dọc theo một đường, một tuyến nào đó (sông, đường, bờ biển...).  2.   Theo ~ (Tiêu chuẩn): Diễn tả việc làm theo một quy tắc, kế hoạch, mong đợi, hoặc phương châm nào đó.', 'N +  に沿って (にそって) /  に沿い (にそい)', '[{"ja":"1.   川に沿って歩くと、美しい公園があります。","romaji":"→ Nếu đi bộ men theo bờ sông, sẽ có một công viên đẹp.","vi":"2.   計画に沿って、プロジェクトを進めてください。"},{"ja":"～に従って（にしたがって）  (N2): \"Theo ~\", chỉ sự tuân thủ hoặc sự thay đổi đồng biến.","romaji":"","vi":""},{"ja":"～に基づいて  (N2): \"Dựa trên ~\", chỉ cơ sở, căn cứ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('107.  に相違ない（にそういない）: Chắc chắn; không sai; không nghi ngờ gì ~.', 'N2', 'Dùng để diễn tả sự phán đoán chắc chắn của người nói, dựa trên một cơ sở hoặc bằng chứng nào đó. Đây là cách nói rất trang trọng.', 'V / A い / A な / N + (thể thường) +  に相違ない (にそういない)   (A な và N có thể +  である +  に相違ない)', '[{"ja":"現場の状況から見て、これは事故に相違ない。","romaji":"→ Nhìn từ tình hình hiện trường, đây chắc chắn là một vụ tai nạn.","vi":""},{"ja":"彼が犯人であるに相違ない。","romaji":"→ Anh ta chắc chắn là thủ phạm.","vi":""},{"ja":"この証拠があれば、彼の無実は証明されるに相違ない。","romaji":"→ Nếu có bằng chứng này, sự vô tội của anh ta chắc chắn sẽ được chứng minh.","vi":"──────────"},{"ja":"～に決まっている  (N2): \"Chắc chắn là\", mang tính chủ quan và văn nói hơn.","romaji":"","vi":""},{"ja":"～はずだ  (N4): \"Chắc chắn là\" (theo lẽ thường), mức độ chắc chắn có thể thấp hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('108.  に過ぎない（にすぎない）: Chỉ là; không hơn ~.', 'N2', 'Dùng để nhấn mạnh rằng một sự việc hoặc đối tượng nào đó không có gì đặc biệt, không vượt quá một mức độ nhất định, hoặc chỉ đơn thuần là như vậy. Thường mang sắc thái khiêm tốn hoặc đánh giá thấp.', 'N +  に過ぎない (にすぎない)   V る / V た +  に過ぎない (にすぎない)', '[{"ja":"それは私の個人的な意見に過ぎません。","romaji":"→ Đó chỉ là ý kiến cá nhân của tôi mà thôi.","vi":""},{"ja":"彼はただの友達に過ぎない。","romaji":"→ Anh ấy chỉ là một người bạn bình thường.","vi":""},{"ja":"今回の成功は、幸運だったに過ぎない。","romaji":"→ Thành công lần này chẳng qua chỉ là may mắn mà thôi.","vi":"──────────"},{"ja":"～でしかない  (N2): \"Chỉ là\", nghĩa rất giống, có thể mang sắc thái đánh giá thấp mạnh hơn một chút.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('109.  に伴って（にともなって）: Cùng với; đồng thời với; theo ~.', 'N2', 'Diễn tả rằng khi một sự thay đổi (A) xảy ra, thì một sự thay đổi khác (B) cũng xảy ra đồng thời hoặc theo sau đó như một hệ quả tự nhiên.', 'N +  に伴って (にともなって) /  に伴い (にともない)   V る +  に伴って /  に伴い', '[{"ja":"経済の発展に伴って、生活水準も向上した。","romaji":"→ Cùng với sự phát triển kinh tế, mức sống cũng được nâng cao.","vi":""},{"ja":"人口の増加に伴い、様々な社会問題が発生している。","romaji":"→ Cùng với sự gia tăng dân số, nhiều vấn đề xã hội đa dạng đang phát sinh.","vi":""},{"ja":"年齢が上がるに伴って、体力が低下する。","romaji":"→ Cùng với tuổi tác tăng lên, thể lực cũng giảm sút.","vi":"──────────"},{"ja":"～につれて  (N2): \"Càng... càng...\", nhấn mạnh sự thay đổi tỷ lệ thuận theo một chiều hướng.","romaji":"","vi":""},{"ja":"～に従って  (N2): \"Theo ~\", cũng chỉ sự thay đổi đồng biến.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('110.  につけ: Mỗi lần; bất cứ khi nào; dù là ~.', 'N2', 'Diễn tả rằng mỗi khi nhìn thấy, nghe thấy, hoặc làm một hành động nào đó (V), thì luôn có một cảm xúc hoặc suy nghĩ nào đó nảy sinh. Thường dùng trong văn viết hoặc văn nói mang tính trang trọng, biểu cảm.', 'V る +  につけ   A い +  につけ', '[{"ja":"この写真を見るにつけ、楽しかった子供時代を思い出す。","romaji":"→ Mỗi khi nhìn tấm ảnh này, tôi lại nhớ về thời thơ ấu vui vẻ.","vi":""},{"ja":"彼の話を聞くにつけ、その誠実さに感動する。","romaji":"→ Mỗi khi nghe câu chuyện của anh ấy, tôi lại cảm động trước sự thành thật đó.","vi":""},{"ja":"良いにつけ悪いにつけ、彼の行動はいつも注目の的だ。","romaji":"→ Dù tốt hay xấu, hành động của anh ta luôn là tâm điểm chú ý.","vi":"──────────"},{"ja":"～とき  (N5): \"Khi\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('111.  につき: Vì; do; mỗi ~.', 'N2', '1.   Chỉ lý do (Vì, do): Dùng để thông báo một lý do nào đó, thường là trong các văn bản thông báo, biển báo. Rất trang trọng.  2.   Chỉ tỷ lệ (Mỗi ~): Dùng để chỉ đơn vị, tỷ lệ (mỗi người, mỗi cái, mỗi giờ...).', 'N +  につき', '[{"ja":"1.   本日は祝日につき、休業いたします。","romaji":"→ Vì hôm nay là ngày lễ nên chúng tôi xin phép nghỉ.","vi":"2.   工事中につき、ご協力をお願いします。"},{"ja":"～ごとに  (N3): \"Mỗi ~\", chỉ sự lặp lại hoặc tỷ lệ, nhưng  「につき」 thường dùng trong các thông báo giá cả, quy định.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('112.  にわたって: Trải khắp; trong suốt (khoảng thời gian, không gian) ~.', 'N2', 'Dùng để diễn tả một sự việc, hành động, hoặc trạng thái diễn ra hoặc có ảnh hưởng trên một phạm vi rộng lớn về không gian hoặc trong một khoảng thời gian dài.', 'N +  にわたって /  にわたり', '[{"ja":"会議は５日間にわたって行われた。","romaji":"→ Cuộc họp đã diễn ra trong suốt 5 ngày.","vi":""},{"ja":"台風の影響で、関東地方全域にわたって大雨が降った。","romaji":"→ Do ảnh hưởng của bão, mưa lớn đã xảy ra trên khắp toàn bộ khu vực Kanto.","vi":""},{"ja":"彼は長年にわたり、この研究を続けてきた。","romaji":"→ Ông ấy đã tiếp tục nghiên cứu này trong suốt nhiều năm.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('113.  にも関わらず（にもかかわらず）: Mặc dù; bất chấp; tuy nhiên ~.', 'N2', 'Dùng để diễn tả một sự việc xảy ra trái với dự đoán hoặc lẽ thường dựa trên điều kiện ở vế trước. Mang sắc thái trang trọng và có thể thể hiện sự ngạc nhiên hoặc bất mãn.', 'V / A い / A な / N + (thể thường) +  にもかかわらず   (A な và N có thể +  である +  にもかかわらず)', '[{"ja":"悪天候にもかかわらず、試合は予定通り行われた。","romaji":"→ Bất chấp thời tiết xấu, trận đấu vẫn diễn ra theo lịch trình.","vi":""},{"ja":"何度も注意したにもかかわらず、彼は同じ間違いを繰り返した。","romaji":"→ Mặc dù đã nhắc nhở nhiều lần, anh ta vẫn lặp lại sai lầm tương tự.","vi":""},{"ja":"彼は学生であるにもかかわらず、高級車に乗っている。","romaji":"→ Anh ta dù là sinh viên nhưng lại đi xe hơi cao cấp.","vi":"──────────"},{"ja":"～ものの  (N2): \"Mặc dù\", trang trọng, thừa nhận vế 1 nhưng vế 2 không tương xứng.","romaji":"","vi":""},{"ja":"～けれど  /  が  (N5): \"Nhưng\", chỉ sự đối lập thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('114.  にて: Ở; tại; bằng; bởi (trợ từ trang trọng).', 'N2', 'Là một trợ từ mang tính văn viết và trang trọng, được dùng thay ch  「 で」 trong các trường hợp sau:  1.   Chỉ địa điểm xảy ra hành động (ở, tại).  2.   Chỉ phương tiện, cách thức (bằng).  3.   Chỉ thời điểm kết thúc (vào lúc).  4.   Chỉ nguyên nhân (bởi).', 'N +  にて', '[{"ja":"1.   会議は本社にて行われます。","romaji":"→ (Cuộc họp sẽ được tổ chức tại trụ sở chính.)","vi":"2.   詳細につきましては、書面にてご連絡いたします。"},{"ja":"～において  (N2): \"Tại\", \"ở\", cũng chỉ địa điểm/thời điểm trang trọng, nhưng không dùng cho phương tiện/nguyên nhân.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('115.  のももっともだ: ~ là đương nhiên; thảo nào ~.', 'N2', 'Dùng để thể hiện sự đồng tình, công nhận rằng một hành động, cảm xúc, hoặc tình trạng nào đó là hợp lý, có lý do chính đáng, không có gì lạ.', 'V る / V た / A い / A な +  のももっともだ', '[{"ja":"あれだけ裏切られたのだから、彼女が彼を信じられないのももっともだ。","romaji":"→ Vì bị phản bội đến mức đó nên việc cô ấy không thể tin anh ta cũng là điều đương nhiên.","vi":""},{"ja":"一晩中勉強したのなら、眠いのももっともだ。","romaji":"→ Nếu đã học cả đêm thì việc buồn ngủ cũng là điều dễ hiểu.","vi":""},{"ja":"彼が怒るのももっともだ。君が悪かったんだから。","romaji":"→ Anh ấy tức giận cũng phải thôi. Vì cậu đã sai mà.","vi":"──────────"},{"ja":"～はずだ  (N4): \"Chắc chắn là\", có thể dùng để chỉ điều đương nhiên theo lẽ thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('116.  の下で（のもとで）: Dưới (sự chỉ đạo, điều kiện, ảnh hưởng); với ~.', 'N2', 'Dùng để diễn tả một hành động hoặc sự việc diễn ra dưới một sự ảnh hưởng, sự chỉ đạo, một điều kiện, hoặc một danh nghĩa nào đó (N).', 'N +  の下で (のもとで) /  の下に (のもとに)', '[{"ja":"厳しい先生の下で、私たちは多くのことを学んだ。","romaji":"→ Dưới sự chỉ bảo nghiêm khắc của thầy, chúng tôi đã học được rất nhiều điều.","vi":""},{"ja":"平等の原則の下に、法律は運用されるべきだ。","romaji":"→ Pháp luật nên được vận hành dưới nguyên tắc bình đẳng.","vi":""},{"ja":"国際協力の名の下で、様々な活動が行われている。","romaji":"→ Dưới danh nghĩa hợp tác quốc tế, nhiều hoạt động đa dạng đang được tiến hành.","vi":"──────────"},{"ja":"～に基づいて  (N2): \"Dựa trên ~\", chỉ cơ sở.  「の下で」 nhấn mạnh sự ảnh hưởng hoặc điều kiện bao trùm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('117.  の上では（のうえでは）: Theo; từ quan điểm của; về mặt ~.', 'N2', 'Dùng để chỉ một sự việc hoặc đánh giá dựa trên một khía cạnh, một phương diện nào đó (như lý thuyết, kế hoạch, số liệu, quy định...). Thường dùng khi có sự khác biệt giữa lý thuyết/bề ngoài và thực tế.', 'N +  の上では (のうえでは) /  の上でも (のうえでも) /  の上の (のうえ の)', '[{"ja":"理論の上では可能だが、実践は難しいだろう。","romaji":"→ Về mặt lý thuyết thì có thể, nhưng thực hành chắc sẽ khó.","vi":""},{"ja":"暦の上ではもう春だが、まだ寒い日が続いている。","romaji":"→ Theo lịch thì đã là mùa xuân rồi, nhưng những ngày lạnh vẫn tiếp diễn.","vi":""},{"ja":"データの上では、問題はないように見える。","romaji":"→ Theo số liệu thì có vẻ không có vấn đề gì.","vi":"──────────"},{"ja":"～から見ると  (N2): \"Nhìn từ ~\", \"xét từ ~\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('118.  のみ: Chỉ; chỉ có ~.', 'N2', 'Dùng để giới hạn, chỉ duy nhất một đối tượng hoặc hành động. Đây là cách nói trang trọng và mang tính văn viết của  「だけ」.', 'N +  のみ   V る +  のみ', '[{"ja":"会場内での飲食はご遠慮ください。ただし、水のみ許可します。","romaji":"→ Xin vui lòng không ăn uống trong hội trường. Tuy nhiên, chỉ riêng nước thì được phép.","vi":""},{"ja":"関係者のみ、立ち入りを許可する。","romaji":"→ Chỉ những người có liên quan mới được phép vào.","vi":""},{"ja":"成功は努力する者のみに与えられる。","romaji":"→ Thành công chỉ được ban cho những người nỗ lực.","vi":"──────────"},{"ja":"～しか～ない  (N4): \"Chỉ\", dùng với phủ định, nhấn mạnh sự giới hạn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('119.  のみならず: Không chỉ; bên cạnh đó; cũng như ~.', 'N2', 'Dùng để diễn tả rằng không chỉ có A mà còn có B. Đây là cách nói trang trọng của  「だけでなく」.', 'N +  のみならず   V / A い / A な + (thể thường) +  のみならず', '[{"ja":"この映画は日本国内のみならず、海外でも高く評価されている。","romaji":"→ Bộ phim này không chỉ ở Nhật Bản mà còn được đánh giá cao ở nước ngoài.","vi":""},{"ja":"彼は学者としてのみならず、芸術家としても有名だ。","romaji":"→ Ông ấy không chỉ nổi tiếng với tư cách là một học giả mà còn là một nghệ sĩ.","vi":""},{"ja":"大気汚染は、健康被害のみならず、環境にも悪影響を及ぼす。","romaji":"→ Ô nhiễm không khí không chỉ gây hại cho sức khỏe mà còn ảnh hưởng xấu đến môi trường.","vi":"──────────"},{"ja":"～ばかりか  (N2): \"Không chỉ... mà còn...\", nhấn mạnh hơn vế sau.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('120.  ぬ: Thể phủ định của động từ (cổ, tương đương  ない).', 'N2', 'Là dạng phủ định cổ của động từ, tương đương với  「ない」. Hiện nay chủ yếu được dùng trong các thành ngữ, quán dụng ngữ, hoặc trong văn viết mang sắc thái trang trọng, cổ xưa. Dạng  「ん」 cũng bắt nguồn từ đây.', 'Động từ thể  ない (bỏ  ない) +  ぬ (ん)', '[{"ja":"思わぬ事故に巻き込まれてしまった。","romaji":"→ (Bị cuốn vào một tai nạn không ngờ tới.)","vi":""},{"ja":"何事も諦めぬ精神が大切だ。","romaji":"→ (Tinh thần không từ bỏ bất cứ điều gì là quan trọng.)","vi":""},{"ja":"分からぬことは、先生に聞くべきだ。","romaji":"→ (Việc không hiểu thì nên hỏi thầy cô.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('121.  抜きにして  /  抜きで（ぬきにして  /  ぬきで）: Bỏ qua; không có ~.', 'N2', 'Dùng để diễn tả việc thực hiện một hành động hoặc xem xét một vấn đề mà không có N, hoặc bỏ qua N.', 'N + (は /  を) +  抜きにして (ぬきにして) /  抜きで (ぬきで)', '[{"ja":"冗談抜きで、真剣に考えてください。","romaji":"→ Bỏ qua chuyện đùa cợt, hãy suy nghĩ nghiêm túc đi.","vi":""},{"ja":"お世辞抜きに、あなたの日本語は本当に上手です。","romaji":"→ Không phải nịnh đâu, tiếng Nhật của bạn thực sự giỏi đấy.","vi":""},{"ja":"忙しいので、朝食抜きで会社に行った。","romaji":"→ Vì bận nên tôi đã đến công ty mà không ăn sáng.","vi":"──────────"},{"ja":"～を除いて  (N2): \"Ngoại trừ ~\", dùng để loại trừ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('122.  抜く（ぬく）: Làm ~ đến cùng; hoàn toàn, cực kỳ ~.', 'N2', 'Dùng sau động từ để diễn tả việc thực hiện hành động đó một cách trọn vẹn, đến cùng, vượt qua khó khăn để hoàn thành.', 'Động từ thể  ます (bỏ  ます) +  抜く (ぬく)', '[{"ja":"大変だったが、最後までやり抜くことができた。","romaji":"→ Tuy vất vả nhưng tôi đã có thể làm được đến cùng.","vi":""},{"ja":"彼はフルマラソンを走り抜いた。","romaji":"→ Anh ấy đã chạy hết (đến cùng) cuộc thi marathon.","vi":""},{"ja":"悩み抜いた末に、会社を辞めることにした。","romaji":"→ Sau khi đã suy nghĩ trăn trở đến cùng, tôi quyết định nghỉ việc.","vi":"──────────"},{"ja":"最後まで～する  (N5): \"Làm ~ đến cuối cùng\", diễn đạt ý tương tự nhưng 「抜く」 nhấn mạnh hơn vào sự nỗ lực và hoàn thành trọn vẹn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('123.  を契機に（をけいきに）: Nhân cơ hội; là kết quả của; tận dụng ~.', 'N2', 'Dùng để diễn tả một sự việc, sự kiện (N) trở thành thời cơ hoặc nguyên cớ trực tiếp dẫn đến một sự thay đổi lớn, một bước ngoặt, hoặc một hành động quan trọng mới.', 'N +  を契機に (をけいきに) /  を契機として (をけいきとして)', '[{"ja":"会社の創立 50 周年を契機に、新しいロゴをデザインした。","romaji":"→ Nhân dịp kỷ niệm 50 năm thành lập công ty, chúng tôi đã thiết kế logo mới.","vi":""},{"ja":"1964 年のオリンピックを契機として、日本の高速道路は整備された。","romaji":"→ Lấy Olympic năm 1964 làm thời cơ, đường cao tốc của Nhật Bản đã được xây dựng.","vi":""},{"ja":"この事件を契機に、法律が見直されることになった。","romaji":"→ Nhân vụ việc này, pháp luật đã được xem xét lại.","vi":"──────────"},{"ja":"～を機に  (N1): \"Nhân dịp\", \"nhân cơ hội\", cũng rất trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('124.  をめぐって: Xoay quanh; liên quan đến ~ (thường là tranh luận, bàn cãi).', 'N2', 'Dùng để chỉ chủ đề, vấn đề (N) đang là trung tâm của sự tranh luận, bàn cãi, xung đột, hoặc thảo luận giữa nhiều người, nhiều phía.', 'N +  をめぐって (をめぐって) /  をめぐる + N', '[{"ja":"遺産をめぐって、兄弟が争っている。","romaji":"→ Anh em đang tranh giành nhau xoay quanh vấn đề tài sản thừa kế.","vi":""},{"ja":"新しい法律をめぐり、国会で激しい議論が続いている。","romaji":"→ Xoay quanh bộ luật mới, các cuộc tranh luận gay gắt đang tiếp diễn tại Quốc hội.","vi":""},{"ja":"その事件をめぐる様々な憶測が飛び交っている。","romaji":"→ Nhiều phỏng đoán khác nhau xoay quanh vụ án đó đang lan truyền.","vi":"──────────"},{"ja":"～に関して  (N3): \"Liên quan đến ~\", trang trọng hơn  「について」.  「を めぐって」 đặc biệt nhấn mạnh vào sự tranh luận, đối đầu xoay quanh chủ đề.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('125.  をもとに: Dựa trên; xuất phát từ ~.', 'N2', 'Dùng để diễn tả rằng một cái gì đó được tạo ra, hình thành, hoặc quyết định dựa trên một nguyên liệu, ý tưởng, sự thật, hoặc dữ liệu cơ bản nào đó (N).', 'N +  をもとに (して) /  をもとにした + N', '[{"ja":"この小説は、作者自身の経験をもとに書かれた。","romaji":"→ Cuốn tiểu thuyết này được viết dựa trên kinh nghiệm của chính tác giả.","vi":""},{"ja":"アンケートの結果をもとにして、新しい商品を開発した。","romaji":"→ Chúng tôi đã phát triển sản phẩm mới dựa trên kết quả khảo sát.","vi":""},{"ja":"事実をもとに、判断を下す。","romaji":"→ Đưa ra phán đoán dựa trên sự thật.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('126.  を除いて（をのぞいて）: Ngoại trừ; không kể ~.', 'N2', 'Dùng để loại trừ một đối tượng (N) ra khỏi một nhóm hoặc một phạm vi nào đó.', 'N +  を除いて (をのぞいて) /  を除けば (をのぞけば)', '[{"ja":"日曜日を除いて、毎日営業しています。","romaji":"→ Ngoại trừ Chủ nhật, chúng tôi mở cửa hàng ngày.","vi":""},{"ja":"彼を除いて、全員がその計画に賛成した。","romaji":"→ Trừ anh ta ra, tất cả mọi người đều tán thành kế hoạch đó.","vi":""},{"ja":"この点をを除けば、彼のレポートは完璧だ。","romaji":"→ Nếu trừ điểm này ra thì bài báo cáo của anh ấy hoàn hảo.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('127.  を問わず（をとわず）: Bất kể; không phân biệt ~.', 'N2', 'Dùng để diễn tả rằng một sự việc nào đó được áp dụng hoặc diễn ra mà không có sự phân biệt, không phụ thuộc vào N.', 'N +  を問わず (をとわず)', '[{"ja":"このイベントは、年齢を問わずどなたでも参加できます。","romaji":"→ Sự kiện này, bất kể tuổi tác, bất kỳ ai cũng có thể tham gia.","vi":""},{"ja":"経験の有無を問わず、広く人材を募集します。","romaji":"→ Chúng tôi tuyển dụng nhân tài rộng rãi, bất kể có kinh nghiệm hay không.","vi":""},{"ja":"この店は昼夜を問わず、２４時間営業している。","romaji":"→ Cửa hàng này hoạt động 24 giờ, bất kể ngày đêm.","vi":"──────────"},{"ja":"～に関係なく  (N3): \"Không liên quan đến\", nghĩa tương tự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('128.  お～願う（お～ねがう）: Làm ơn; xin hãy ~; tôi nhờ bạn ~.', 'N2', 'Là một dạng kính ngữ (khiêm nhường ngữ) dùng để yêu cầu, nhờ vả người khác làm gì đó cho mình một cách rất lịch sự.', 'お + V ます (bỏ  ます) +  願う (ねがう)   ご + N (Hán-Nhật) +  願う (ねがう)', '[{"ja":"少々お待ち願えますでしょうか。","romaji":"→ Xin quý khách vui lòng chờ một chút được không ạ?","vi":""},{"ja":"こちらの書類にご記入願います。","romaji":"→ Xin vui lòng điền vào tài liệu này ạ.","vi":""},{"ja":"ご確認願います。","romaji":"→ Xin vui lòng xác nhận ạ.","vi":"──────────"},{"ja":"お～ください  (N4): Yêu cầu lịch sự (tôn kính ngữ).","romaji":"","vi":""},{"ja":"～ていただく  (N4/N3): \"Nhận được việc ~ (từ ai đó)\", là khiêm nhường ngữ để diễn tả việc mình được người khác làm cho.  「お～願う」 là cách nhờ vả trực tiếp hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('129.  おまけに: Tồi tệ hơn là; bên cạnh đó; hơn nữa; thêm vào đó ~.', 'N2', 'Dùng để bổ sung thêm một thông tin, một yếu tố nữa vào những gì đã nói trước đó. Thường dùng khi vế trước và vế sau cùng chiều (cùng tốt hoặc cùng xấu), và thường mang sắc thái văn nói, đôi khi nhấn mạnh sự cộng hưởng (thường là tiêu cực).', '[Câu 1]。おまけに、[Câu 2]。', '[{"ja":"今日は雨が降っているし、おまけに風も強い。","romaji":"→ Hôm nay trời vừa mưa, thêm vào đó gió cũng mạnh.","vi":""},{"ja":"このレストランは高いし、おまけにサービスも悪い。","romaji":"→ Nhà hàng này vừa đắt, hơn nữa dịch vụ cũng tồi.","vi":""},{"ja":"彼はハンサムでおまけに頭もいい。","romaji":"→ Anh ấy vừa đẹp trai, thêm vào đó còn thông minh nữa.","vi":"──────────"},{"ja":"しかも  (N3): \"Hơn nữa\", \"vả lại\", dùng phổ biến.","romaji":"","vi":""},{"ja":"それに  (N4): \"Hơn nữa\", dùng trong văn nói.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('130.  恐らく（おそらく）: Có lẽ; rất có thể; có khả năng ~.', 'N2', 'Dùng để diễn tả sự phán đoán của người nói với mức độ chắc chắn khá cao, dựa trên một số cơ sở nào đó. Thường dùng cho những phán đoán về tương lai hoặc những điều chưa rõ ràng.', '恐らく + [Phán đoán] +  だろう /  でしょう /  と思う /  に違いない…', '[{"ja":"明日はおそらく雨が降るだろう。","romaji":"→ Ngày mai có lẽ trời sẽ mưa.","vi":""},{"ja":"このままでは、おそらく間に合わないだろう。","romaji":"→ Cứ thế này thì rất có thể sẽ không kịp.","vi":""},{"ja":"彼は恐らく会議に遅れてくるだろう。","romaji":"→ Anh ấy có khả năng sẽ đến muộn cuộc họp.","vi":"──────────"},{"ja":"きっと  (N4): \"Chắc chắn\", mức độ chắc chắn cao hơn, thường mang tính chủ quan.  「おそらく」 dựa trên cơ sở khách quan hơn một chút.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('131.  恐れがある（おそれがある）: E là; có nguy cơ là ~.', 'N2', 'Dùng để diễn tả khả năng xảy ra một việc gì đó xấu, không mong muốn. Thường được dùng trong các bản tin, thông báo, cảnh báo để nói về những rủi ro tiềm ẩn.', 'N の +  恐れがある (おそれがある)   V る +  恐れがある (おそれがある)', '[{"ja":"台風が上陸し、大きな被害が出る恐れがある。","romaji":"→ Bão đổ bộ, e là sẽ có thiệt hại lớn.","vi":""},{"ja":"この薬は副作用の恐れがありますので、注意してください。","romaji":"→ Thuốc này có nguy cơ gây tác dụng phụ, xin hãy chú ý.","vi":""},{"ja":"このまま感染が拡大すると、医療崩壊を招く恐れがある。","romaji":"→ Nếu tình trạng lây nhiễm cứ lan rộng thế này, e là sẽ dẫn đến sụp đổ y tế.","vi":"──────────"},{"ja":"～かねない  (N2): \"Có thể sẽ ~\", cũng dùng cho việc xấu nhưng ít trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('132.  及び（および）: Và; cũng như ~.', 'N2', 'Dùng để nối hai hoặc nhiều danh từ có vai trò tương đương nhau. Đây là cách nói rất trang trọng, thường dùng trong văn viết, văn bản pháp luật, tài liệu chính thức.', 'N1  及び N2 (N1  および N2)', '[{"ja":"会場には、テーブル及び椅子が用意されています。","romaji":"→ Trong hội trường, bàn và ghế đã được chuẩn bị.","vi":""},{"ja":"本契約書には、甲及び乙が署名捺印するものとする。","romaji":"→ Hợp đồng này sẽ do bên A và bên B ký tên đóng dấu.","vi":""},{"ja":"住所、氏名及び電話番号を記入してください。","romaji":"→ Xin hãy điền địa chỉ, họ tên và số điện thoại.","vi":"──────────"},{"ja":"～や  (N5): \"Và\", dùng để liệt kê không đầy đủ.","romaji":"","vi":""},{"ja":"並びに（ならびに）  (N1): \"Và\", cũng rất trang trọng, thường dùng để nối các nhóm danh từ lớn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('133.  ろくに～ない: Không ~ tử tế; không ~ đủ; không ~ ra hồn.', 'N2', 'Dùng để diễn tả rằng một hành động nào đó không được thực hiện một cách đầy đủ, chu đáo, hoặc đúng mức cần thiết. Thường mang sắc thái bất mãn hoặc than phiền.', 'ろくに + V ない', '[{"ja":"忙しくて、昨日はろくに寝ていない。","romaji":"→ Bận quá nên hôm qua tôi đã không ngủ được tử tế.","vi":""},{"ja":"彼はろくに勉強もしないで、いつも遊んでばかりいる。","romaji":"→ Cậu ta chẳng học hành gì ra hồn, lúc nào cũng chỉ toàn chơi bời.","vi":""},{"ja":"字が下手で、自分の名前もろくに書けない。","romaji":"→ Chữ xấu quá, đến tên mình tôi cũng không viết được tử tế.","vi":"──────────"},{"ja":"十分に～ない  (N4): \"Không ~ đủ\".  「ろくに～ない」 mang sắc thái mạnh hơn, thể hiện sự thiếu sót đáng kể.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('134.  幸いなことに（さいわいなことに）: May mắn là; thật may ~.', 'N2', 'Đứng đầu câu, dùng để diễn tả rằng một sự việc tốt đẹp, may mắn nào đó đã xảy ra, thường là trong một tình huống khó khăn hoặc có nguy cơ xấu.', '幸いなことに、[Câu]   幸い（にも）、[Câu]', '[{"ja":"幸いなことに、事故にあったが、けがはなかった。","romaji":"→ May mắn là tuy gặp tai nạn nhưng tôi không bị thương.","vi":""},{"ja":"幸いにも、なくした財布が見つかった。","romaji":"→ Thật may, cái ví bị mất đã được tìm thấy.","vi":""},{"ja":"幸いなことに、天気にも恵まれ、旅行はとても楽しかった。","romaji":"→ May mắn là thời tiết cũng đẹp nên chuyến đi rất vui.","vi":"──────────"},{"ja":"～てよかった  (N4): \"Thật tốt vì đã ~\", diễn tả sự hài lòng/may mắn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('135.  せいか: Có lẽ là vì ~.', 'N2', 'Dùng để đưa ra một nguyên nhân có thể có cho một kết quả nào đó, nhưng người nói không chắc chắn hoàn toàn. Thường dùng khi kết quả không tốt, nhưng không mang ý đổ lỗi mạnh như  「せいで」.', 'V / A い / A な / N + (thể thường) +  せいか', '[{"ja":"緊張したせいか、頭が痛くなってきた。","romaji":"→ Có lẽ là vì căng thẳng nên tôi bắt đầu đau đầu.","vi":""},{"ja":"寝不足のせいか、今日は集中できない。","romaji":"→ Có lẽ là do thiếu ngủ nên hôm nay tôi không thể tập trung được.","vi":""},{"ja":"年のせいか、最近忘れっぽくなった。","romaji":"→ Có lẽ là tại tuổi tác mà gần đây tôi trở nên hay quên.","vi":"──────────"},{"ja":"～ためか  (N3): \"Có lẽ là do ~\", cũng tương tự.","romaji":"","vi":""},{"ja":"～せいで  (N3): \"Tại vì ~\", chỉ nguyên nhân xấu, mang tính khẳng định và đổ lỗi.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('136.  せっかく: Cất công; đặc biệt; (cảm ơn vì) đã mất công ~.', 'N2', '1.   Diễn tả một hành động được thực hiện với sự cố gắng, nỗ lực, hoặc trong một cơ hội hiếm có.  2.   Đi với  「のに」、「だから」 để thể hiện sự tiếc nuối khi công sức hoặc cơ hội đó bị lãng phí.  3.   Dùng để bày tỏ lòng biết ơn khi ai đó đã cất công làm gì cho mình.', 'Là một trạng từ (副詞).   せっかく + [Hành động/Sự việc]', '[{"ja":"せっかく作った料理なのに、誰も食べてくれなかった。","romaji":"→ (Tôi đã cất công nấu ăn, vậy mà không ai ăn cả.)","vi":""},{"ja":"せっかくの日曜日なのに、雨でどこにも行けない。","romaji":"→ (Đã là ngày Chủ nhật hiếm có, vậy mà trời mưa chẳng đi đâu được.)","vi":""},{"ja":"せっかくですから、どうぞお召し上がりください。","romaji":"→ (Vì đã cất công (chuẩn bị) rồi, xin mời anh/chị dùng.)","vi":""},{"ja":"せっかく来てくれたのに、留守にしていてごめんね。","romaji":"→ (Bạn đã cất công đến chơi, vậy mà tớ lại đi vắng, xin lỗi nhé.)","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('137.  せめて: Ít nhất; tối thiểu ~.', 'N2', 'Dùng để diễn tả một mong muốn tối thiểu, một điều nhỏ nhất mà người nói hy vọng có thể đạt được, đặc biệt là khi không thể đạt được điều lý tưởng nhất.', 'せめて + [Mong muốn/Yêu cầu tối thiểu]', '[{"ja":"優勝は無理でも、せめて決勝には進みたい。","romaji":"→ Dù không thể vô địch, nhưng ít nhất tôi cũng muốn tiến vào trận chung kết.","vi":""},{"ja":"毎日とは言わないが、せめて週に一度は電話してほしい。","romaji":"→ Tôi không nói là mỗi ngày, nhưng ít nhất cũng mong bạn gọi điện mỗi tuần một lần.","vi":""},{"ja":"全部食べなくてもいいから、せめてスープだけでも飲んでください。","romaji":"→ Không cần ăn hết cũng được, xin hãy uống ít nhất là món súp.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('138.  次第（しだい）: Ngay khi ~.', 'N2', 'Dùng để diễn tả rằng ngay sau khi hành động 1 (V ます) hoàn thành thì hành động 2 sẽ được thực hiện ngay lập tức. Thường dùng trong các tình huống trang trọng, thông báo, hoặc kinh doanh.', 'Động từ thể  ます (bỏ  ます) +  次第 (しだい)', '[{"ja":"詳しいことが分かり次第、ご連絡いたします。","romaji":"→ Ngay khi biết thông tin chi tiết, tôi sẽ liên lạc.","vi":""},{"ja":"会議が終わり次第、そちらへ伺います。","romaji":"→ Ngay khi cuộc họp kết thúc, tôi sẽ đến chỗ anh/chị.","vi":""},{"ja":"準備ができ次第、出発しましょう。","romaji":"→ Ngay khi chuẩn bị xong, chúng ta hãy xuất phát.","vi":"──────────"},{"ja":"～たとたん  (N3): \"Ngay khi\", thường dùng cho kết quả bất ngờ, không kiểm soát được.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('139.  次第で（しだいで）: Tùy thuộc vào; do đó ~.', 'N2', 'Dùng để diễn tả rằng kết quả hoặc tình hình ở vế sau sẽ thay đổi, phụ thuộc vào N ở vế trước.', 'N +  次第で (しだいで) /  次第だ (しだいだ)', '[{"ja":"明日の天気次第で、ハイキングに行くかどうか決めましょう。","romaji":"→ Tùy thuộc vào thời tiết ngày mai mà chúng ta quyết định có đi leo núi hay không.","vi":""},{"ja":"努力次第で、夢は叶うかもしれない。","romaji":"→ Tùy thuộc vào nỗ lực mà giấc mơ có thể sẽ thành hiện thực.","vi":""},{"ja":"この試合に勝てるかどうかは、練習次第だ。","romaji":"→ Việc có thể thắng trận đấu này hay không là tùy thuộc vào việc luyện tập.","vi":"──────────"},{"ja":"～にかかっている  (N3): \"Phụ thuộc vào ~\", nhấn mạnh sự quyết định nằm ở N.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('140.  次第に（しだいに）: Dần dần; từ từ; theo thứ tự ~.', 'N2', 'Dùng để diễn tả một sự thay đổi diễn ra một cách từ từ, từng chút một theo thời gian.', 'Là một trạng từ (副詞).', '[{"ja":"秋になり、木の葉が次第に色づいてきた。","romaji":"→ Mùa thu đến, lá cây đã dần dần đổi màu.","vi":""},{"ja":"夜が更けるにつれて、気温は次第に下がってきた。","romaji":"→ Đêm càng về khuya, nhiệt độ càng dần dần hạ xuống.","vi":""},{"ja":"彼の病気は次第に回復に向かっている。","romaji":"→ Bệnh của anh ấy đang dần dần hồi phục.","vi":"──────────"},{"ja":"少しずつ（すこしずつ）  (N4): \"Từng chút một\".","romaji":"","vi":""},{"ja":"徐々に（じょじょに）  (N1): \"Dần dần\", \"từ từ\", rất trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('141.  しかも: Hơn nữa; vả lại; mà lại ~.', 'N2', 'Dùng để bổ sung thêm một thông tin, nhấn mạnh rằng không chỉ có A mà còn có B. Thường dùng khi vế sau bổ sung thêm một đặc điểm (tốt hoặc xấu) cùng chiều với vế trước.', '[Câu 1]。しかも、[Câu 2]。', '[{"ja":"このレストランは美味しいし、しかも値段も安い。","romaji":"→ Nhà hàng này vừa ngon, hơn nữa giá lại còn rẻ.","vi":""},{"ja":"彼は頭がいい。しかも、スポーツも万能だ。","romaji":"→ Anh ta thông minh. Hơn nữa, thể thao cũng toàn năng.","vi":""},{"ja":"雨が降ってきた。しかも、風も強くなってきた。","romaji":"→ Mưa đã rơi rồi. Mà lại, gió cũng mạnh lên nữa.","vi":"──────────"},{"ja":"おまけに  (N2): \"Hơn nữa\", mang tính văn nói hơn.","romaji":"","vi":""},{"ja":"さらに  (N3): \"Hơn nữa\", \"thêm nữa\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('142.  その上（そのうえ）: Bên cạnh đó; thêm vào đó; hơn nữa ~.', 'N2', 'Tương tự như  「しかも」, dùng để bổ sung thêm một thông tin, thường là cùng chiều (cùng tốt hoặc cùng xấu).', '[Câu 1]。その上、[Câu 2]。', '[{"ja":"彼は仕事ができる。その上、性格もいい。","romaji":"→ Anh ấy làm việc tốt. Thêm vào đó, tính cách cũng tốt.","vi":""},{"ja":"今日は寝坊した。その上、電車も遅れた。","romaji":"→ Hôm nay tôi ngủ quên. Hơn nữa, tàu điện cũng bị trễ.","vi":""},{"ja":"彼は日本語が話せる。その上、英語も流暢だ。","romaji":"→ Anh ấy nói được tiếng Nhật. Bên cạnh đó, tiếng Anh cũng trôi chảy.","vi":"──────────"},{"ja":"おまけに  (N2): \"Hơn nữa\", mang tính văn nói.","romaji":"","vi":""},{"ja":"さらに  (N3): \"Hơn nữa\", \"thêm nữa\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('143.  それなのに: Thế nhưng; dù vậy; vậy mà ~.', 'N2', 'Dùng để nối hai vế có ý nghĩa trái ngược, trong đó vế sau thể hiện một kết quả không như mong đợi hoặc trái với lẽ thường dựa trên vế trước. Thường mang sắc thái bất mãn, ngạc nhiên, hoặc phàn nàn.', '[Câu 1]。それなのに、[Câu 2]。', '[{"ja":"一生懸命勉強した。それなのに、試験に落ちてしまった。","romaji":"→ Tôi đã học hành chăm chỉ. Thế nhưng, tôi lại thi trượt.","vi":""},{"ja":"彼は何度も謝った。それなのに、彼女は許してくれなかった。","romaji":"→ Anh ấy đã xin lỗi nhiều lần. Dù vậy, cô ấy vẫn không tha thứ.","vi":""},{"ja":"今日は日曜日だ。それなのに、働かなければならない。","romaji":"→ Hôm nay là Chủ nhật. Vậy mà tôi vẫn phải làm việc.","vi":"──────────"},{"ja":"のに  (N4): \"Mặc dù\", có thể dùng giữa câu.","romaji":"","vi":""},{"ja":"けれど  /  でも  (N5): \"Nhưng\", chỉ sự đối lập thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('144.  それなら: Nếu vậy; trong trường hợp đó ~.', 'N2', 'Dùng khi nghe một thông tin nào đó (Câu 1) và dựa vào đó để đưa ra một đề nghị, gợi ý, hoặc kết luận (Câu 2).', '[Câu 1]。それなら、[Câu 2]。', '[{"ja":"A:  頭が痛いんです。","romaji":"→ (Tôi bị đau đầu.) B:  それなら、薬を飲んだ方がいいですよ。","vi":"→ (Nếu vậy thì bạn nên uống thuốc đi.)"},{"ja":"A:  明日は雨だそうです。","romaji":"→ (Nghe nói ngày mai trời mưa.) B:  それなら、ピクニックは中止にしましょう。","vi":"→ (Vậy thì chúng ta hãy hủy buổi dã ngoại đi.)"},{"ja":"A:  このレストランは高いよ。","romaji":"→ (Nhà hàng này đắt đấy.) B:  それなら、別の店を探そう。","vi":"→ (Nếu vậy thì tìm quán khác đi.)"},{"ja":"では  (N5): \"Vậy thì\", lịch sự hơn  「じゃあ」, nhưng không bằng  「それな ら」.","romaji":"","vi":""},{"ja":"そしたら  (N4): \"Nếu vậy thì\", dùng trong văn nói.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('145.  それにしても: Dù sao đi nữa; tuy nhiên; kể cả như vậy ~.', 'N2', 'Dùng để thừa nhận nội dung của vế trước (Câu 1), nhưng đồng thời đưa ra một nhận xét, cảm xúc (thường là ngạc nhiên, thán phục, hoặc phàn nàn) ở vế sau (Câu 2) mà người nói cảm thấy vượt quá mức bình thường hoặc dự đoán.', '[Câu 1]。それにしても、[Câu 2]。', '[{"ja":"彼は努力家だが、それにしても、あんなに短期間で成功するとは驚きだ。","romaji":"→ Anh ấy là người nỗ lực, nhưng dù sao đi nữa, việc thành công trong thời gian ngắn như vậy thật đáng ngạc nhiên.","vi":""},{"ja":"値段が高いのは知っていたが、それにしても、これは高すぎる。","romaji":"→ Tôi biết là giá cao, nhưng kể cả vậy thì cái này cũng quá đắt.","vi":""},{"ja":"暑いとは聞いていたけど、それにしても今日の暑さは異常だ。","romaji":"→ Nghe nói là nóng, nhưng dù sao đi nữa, cái nóng hôm nay thật bất thường.","vi":"──────────"},{"ja":"だとしても  (N2): \"Ngay cả nếu ~ thì cũng\", chỉ giả định.  「それにしても 」 thừa nhận vế 1 là thật và thể hiện cảm xúc về mức độ của nó.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('146.  そう言えば（そういえば）: Nghĩ lại thì; nhân tiện nói đến ~.', 'N2', 'Dùng khi người nói chợt nhớ ra một điều gì đó có liên quan đến chủ đề đang được nói đến.', 'そう言えば、[Câu]。', '[{"ja":"A:  明日は山田さんの誕生日だね。","romaji":"→ (Mai là sinh nhật Yamada nhỉ.) B:  そう言えば、彼、最近元気ないみたいだけど、どうしたんだろう。","vi":"→ (Nghĩ lại thì, dạo này anh ấy có vẻ không khỏe, không biết sao nhỉ.)"},{"ja":"そう言えば、駅前に新しいカフェができたらしいよ。","romaji":"→ Nhân tiện nói đến, hình như trước ga có quán cà phê mới mở đấy.","vi":""},{"ja":"A:  この映画、面白かったね。","romaji":"→ (Bộ phim này hay nhỉ.) B:  うん。そう言え ば、主役の俳優、結婚したんだって。","vi":"→ (Ừ. Nghĩ lại thì, diễn viên chính nghe nói kết hôn rồi đấy.)"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('147.  そうすると: Nếu làm vậy thì; nếu thế thì ~.', 'N2', 'Dùng để chỉ kết quả hoặc hành động tiếp theo xảy ra một cách logic dựa trên nội dung của câu trước.', '[Câu 1]。そうすると、[Câu 2]。', '[{"ja":"A:  電車で行きますか。","romaji":"→ (Chúng ta đi bằng tàu điện nhé?) B:  電車は混むかもしれませんね。","vi":"→ (Tàu điện có thể sẽ đông đấy.) A:  そうすると、バスで行った方がいいかもしれません。"},{"ja":"雨が降ってきた。そうすると、今日の試合は中止になるだろう。","romaji":"→ Trời mưa rồi. Nếu thế thì trận đấu hôm nay chắc sẽ bị hủy.","vi":"──────────"},{"ja":"では  /  じゃあ  (N5): \"Vậy thì\", dùng phổ biến trong văn nói.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('148.  末に（すえに）: Sau khi; cuối cùng thì ~.', 'N2', 'Dùng để diễn tả một kết quả cuối cùng đạt được sau một quá trình dài, tốn nhiều công sức, suy nghĩ, hoặc trải qua nhiều biến cố. Có thể dùng cho cả kết quả tốt và xấu.', 'N の +  末に (すえに)   V た +  末に (すえに)', '[{"ja":"長い議論の末に、やっと結論が出た。","romaji":"→ Sau một thời gian dài thảo luận, cuối cùng cũng đưa ra được kết luận.","vi":""},{"ja":"色々迷った末に、この大学に決めた。","romaji":"→ Sau khi đã phân vân rất nhiều, cuối cùng tôi đã quyết định chọn trường đại học này.","vi":""},{"ja":"彼は苦労した末に、成功を手に入れた。","romaji":"→ Anh ấy sau khi đã vất vả, cuối cùng đã nắm được thành công.","vi":"──────────"},{"ja":"～結果（けっか）  (N4/N3): \"Kết quả\", chỉ kết quả thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('149.  少しも～ない（すこしも～ない）: Không ~ một chút nào.', 'N2', 'Dùng để phủ định hoàn toàn, nhấn mạnh rằng không có một chút nào, dù là nhỏ nhất.', '少しも + V ない / A くない / A でない', '[{"ja":"彼の話は、少しも面白くなかった。","romaji":"→ Câu chuyện của anh ta không thú vị một chút nào.","vi":""},{"ja":"私はお酒が少しも飲めません。","romaji":"→ Tôi không uống được rượu một chút nào.","vi":""},{"ja":"彼は自分の間違いを少しも反省していない。","romaji":"→ Anh ta không hối lỗi về sai lầm của mình một chút nào.","vi":"──────────"},{"ja":"ちっとも～ない  (N2): \"Không ~ chút nào cả\", thường mang cảm xúc hơn.","romaji":"","vi":""},{"ja":"全く～ない  (N2): \"Hoàn toàn không\", trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('150.  少なくとも（すくなくとも）: Ít nhất ~.', 'N2', 'Dùng để đưa ra một mức độ hoặc số lượng tối thiểu, nhấn mạnh rằng dù không nhiều hơn nhưng chắc chắn cũng phải bằng mức đó.', '少なくとも + [Số lượng/Mức độ]', '[{"ja":"この仕事には、少なくとも３人は必要だ。","romaji":"→ Công việc này cần ít nhất 3 người.","vi":""},{"ja":"旅行に行くなら、少なくとも１週間は休みが欲しい。","romaji":"→ Nếu đi du lịch thì tôi muốn nghỉ ít nhất 1 tuần.","vi":""},{"ja":"少なくとも、彼は嘘をつくような人ではない。","romaji":"→ Ít nhất thì anh ta cũng không phải là người nói dối.","vi":"──────────"},{"ja":"最低でも（さいていでも）  (N3): \"Tối thiểu cũng\", nghĩa tương tự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('151.  直ちに（ただちに）: Ngay lập tức; trực tiếp ~.', 'N2', 'Dùng để diễn tả việc thực hiện một hành động ngay lập tức, không chậm trễ. Là cách nói trang trọng.', 'Là một trạng từ (副詞).', '[{"ja":"火事が発生した場合は、直ちに避難してください。","romaji":"→ Trong trường hợp xảy ra hỏa hoạn, xin hãy sơ tán ngay lập tức.","vi":""},{"ja":"問題が見つかったら、直ちに報告してください。","romaji":"→ Nếu phát hiện vấn đề, xin hãy báo cáo ngay lập tức.","vi":""},{"ja":"この命令は直ちに実行されなければならない。","romaji":"→ Mệnh lệnh này phải được thực thi ngay lập tức.","vi":"──────────"},{"ja":"至急（しきゅう）  (N2/N1): \"Khẩn cấp\", \"ngay lập tức\", nhấn mạnh tính cấp bách.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('152.  たまえ: Hãy ~ (mệnh lệnh).', 'N2', 'Là một dạng mệnh lệnh, thường được người có vị thế cao hơn (giáo viên, cấp trên, cha mẹ...) dùng với người dưới. Mang sắc thái hơi bề trên, cổ xưa, hoặc  dùng trong các tác phẩm văn học, phim ảnh.', 'Động từ thể  ます (bỏ  ます) +  たまえ', '[{"ja":"君、ちょっとこれをコピーしたまえ。","romaji":"→ (Cậu, hãy photo cái này một chút.)","vi":""},{"ja":"もう少し静かにしたまえ。","romaji":"→ (Hãy yên lặng một chút đi.)","vi":""},{"ja":"分からないことがあれば、何でも聞きたまえ。","romaji":"→ (Nếu có gì không hiểu, hãy cứ hỏi bất cứ điều gì.)","vi":"──────────"},{"ja":"～ろ  /  ～よ  (N5): Dạng mệnh lệnh thông thường, suồng sã.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('153.  てばかりはいられない: Không thể cứ mãi ~.', 'N2', 'Diễn tả rằng không thể cứ tiếp tục mãi một hành động hoặc trạng thái nào đó, thường là vì có lý do, trách nhiệm, hoặc tình huống đòi hỏi phải thay đổi hoặc làm việc khác.', 'V て +  ばかりは +  いられない   V て +  ばかりも +  いられない', '[{"ja":"もうすぐ試験だから、遊んでばかりはいられない。","romaji":"→ Sắp thi rồi nên không thể cứ mãi chơi được.","vi":""},{"ja":"困難な状況だが、泣いてばかりもいられない。何か行動を起こさなければ。","romaji":"→ Tình hình khó khăn thật, nhưng cũng không thể cứ mãi khóc được. Phải làm gì đó thôi.","vi":""},{"ja":"いつまでも親に頼ってばかりはいられない。自立しなければ。","romaji":"→ Không thể cứ mãi dựa dẫm vào bố mẹ được. Phải tự lập thôi.","vi":"──────────"},{"ja":"～わけにはいかない  (N3): \"Không thể ~\" (vì lý do xã hội, tâm lý), có thể dùng khi không thể không làm hoặc không thể cứ làm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('154.  てでも: Cho dù phải ~; bằng mọi giá ~.', 'N2', 'Dùng để diễn tả sự quyết tâm mạnh mẽ sẽ làm một việc gì đó, cho dù phải dùng đến những biện pháp cực đoan, bất thường, hoặc phải hy sinh.', 'V て +  でも', '[{"ja":"家を売ってでも、彼の借金を返済しなければならない。","romaji":"→ Dù có phải bán nhà, tôi cũng phải trả nợ cho anh ấy.","vi":""},{"ja":"どんな手を使ってでも、この試合には勝ちたい。","romaji":"→ Dù phải dùng bất cứ thủ đoạn nào, tôi cũng muốn thắng trận này.","vi":""},{"ja":"徹夜してでも、このレポートを完成させるつもりだ。","romaji":"→ Dù có phải thức trắng đêm, tôi cũng định hoàn thành bài báo cáo này.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('155.  て以来（ていらい）: Kể từ khi ~.', 'N2', 'Dùng để nói về một thời điểm trong quá khứ (khi V xảy ra) và diễn tả một trạng thái hoặc hành động nào đó đã bắt đầu từ lúc đó và kéo dài liên tục cho đến hiện tại.', 'V て +  以来 (いらい)', '[{"ja":"日本に来て以来、一度も国に帰っていない。","romaji":"→ Kể từ khi đến Nhật, tôi chưa về nước lần nào.","vi":""},{"ja":"卒業して以来、彼とは会っていない。","romaji":"→ Kể từ khi tốt nghiệp, tôi không gặp anh ấy.","vi":""},{"ja":"母が入院して以来、父が家事をしている。","romaji":"→ Kể từ khi mẹ nhập viện, bố tôi (suốt) làm việc nhà.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('156.  ていては: Nếu cứ ~ (thường dẫn đến kết quả không tốt).', 'N2', 'Dùng để diễn tả rằng nếu cứ tiếp tục một hành động hoặc trạng thái nào đó (V ている), thì sẽ dẫn đến một kết quả không tốt hoặc không mong muốn. Thường mang sắc thái cảnh báo hoặc phê phán.', 'V て +  いては', '[{"ja":"そんなに遊んでばかりいては、試験に落ちますよ。","romaji":"→ Nếu cứ chỉ toàn chơi như thế thì sẽ thi trượt đấy.","vi":""},{"ja":"いつまでも失敗を恐れていては、何も新しいことは始められない。","romaji":"→ Nếu cứ mãi sợ thất bại thì không thể bắt đầu được việc gì mới.","vi":""},{"ja":"そんなに甘やかしていては、子供のためにならない。","romaji":"→ Nếu cứ nuông chiều như thế thì sẽ không tốt cho đứa trẻ.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('157.  てこそ: Chỉ khi ~ (mới...).', 'N2', 'Dùng để nhấn mạnh rằng chỉ khi thực hiện hành động V (thường là một nỗ lực, trải nghiệm) thì mới có thể đạt được một kết quả tích cực, một sự hiểu biết, hoặc một giá trị nào đó.', 'V て +  こそ', '[{"ja":"困難を乗り越えてこそ、本当の成功がある。","romaji":"→ Chỉ khi vượt qua khó khăn thì mới có thành công thực sự.","vi":""},{"ja":"親になってこそ、親のありがたみが分かる。","romaji":"→ Chỉ khi trở thành cha mẹ thì mới hiểu được sự biết ơn đối với cha mẹ.","vi":""},{"ja":"努力してこそ、夢は実現する。","romaji":"→ Chỉ khi nỗ lực thì giấc mơ mới thành hiện thực.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('158.  てまで: Đến mức phải ~; thậm chí ~.', 'N2', 'Dùng để diễn tả một hành động (V) được thực hiện như một phương tiện cực đoan, đôi khi là phi thường hoặc đáng ngạc nhiên, để đạt được một mục đích nào đó. Nhấn mạnh sự hy sinh hoặc mức độ bất thường.', 'V て +  まで', '[{"ja":"借金してまで、海外旅行に行きたいとは思わない。","romaji":"→ Tôi không nghĩ là muốn đi du lịch nước ngoài đến mức phải vay nợ.","vi":""},{"ja":"親に嘘をついてまで、遊びに行きたくない。","romaji":"→ Tôi không muốn đi chơi đến mức phải nói dối bố mẹ.","vi":""},{"ja":"彼は仕事を休んでまで、そのコンサートを見に行った。","romaji":"→ Anh ta thậm chí đã nghỉ làm để đi xem buổi hòa nhạc đó.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('159.  てならない: Không chịu được; rất; không thể không ~.', 'N2', 'Dùng để diễn tả một cảm xúc, cảm giác, hoặc suy nghĩ nảy sinh một cách tự nhiên và mạnh mẽ đến mức không thể kìm nén hoặc kiểm soát được.', 'V て +  ならない   A くて +  ならない   A で +  ならない', '[{"ja":"試験の結果が気になってならない。","romaji":"→ Tôi rất lo lắng về kết quả kỳ thi (không thể không lo).","vi":""},{"ja":"彼の将来が心配でならない。","romaji":"→ Tôi rất lo lắng cho tương lai của anh ấy.","vi":""},{"ja":"久しぶりに国に帰れるのが、嬉しくてならない。","romaji":"→ Việc có thể về nước sau một thời gian dài khiến tôi vui không chịu được.","vi":"──────────"},{"ja":"～て仕方がない  (N3): \"Không thể chịu được\", nghĩa tương tự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('160.  てたまらない: Không chịu được; rất; không thể không ~.', 'N2', 'Tương tự như  「てならない」, dùng để diễn tả một cảm xúc, cảm giác, hoặc mong muốn mạnh mẽ đến mức không thể kìm nén.', 'V たくて +  たまらない   A くて +  たまらない   A で +  たまらない', '[{"ja":"暑くてたまらない。エアコンをつけよう。","romaji":"→ Nóng không chịu được. Bật điều hòa lên thôi.","vi":""},{"ja":"会いたくてたまらない。","romaji":"→ Tôi muốn gặp (anh/cô ấy) không chịu được.","vi":""},{"ja":"息子が大学に合格して、嬉しくてたまらない。","romaji":"→ Con trai tôi đỗ đại học, tôi vui không chịu được.","vi":"──────────"},{"ja":"～て仕方がない  (N3): \"Không thể chịu được\", nghĩa tương tự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('161.  て当然だ（てとうぜんだ）: Là đương nhiên; tất nhiên ~.', 'N2', 'Tương tự  「～のは当然だ」, dùng để diễn tả rằng một kết quả hoặc tình huống nào đó là điều hợp lý, dễ hiểu, không có gì đáng ngạc nhiên dựa trên nguyên nhân hoặc tình huống đã có.', 'V て +  当然だ (とうぜんだ)   A くて +  当然だ   A で +  当然だ', '[{"ja":"あれだけ頑張ったのだから、成功して当然だ。","romaji":"→ Vì đã cố gắng đến thế nên thành công là điều đương nhiên.","vi":""},{"ja":"人の物を盗んだのだから、罰せられて当然だ。","romaji":"→ Vì đã trộm đồ của người khác nên bị trừng phạt là điều đương nhiên.","vi":""},{"ja":"彼は親切だから、人気があって当然だ。","romaji":"→ Anh ấy tốt bụng nên được yêu mến là điều tất nhiên.","vi":"──────────"},{"ja":"～て当たり前だ  (N3): \"Là đương nhiên\", nghĩa rất giống, có thể mang sắc thái mạnh hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('162.  ては  /  では: Mỗi khi; nếu; khi ~; hành động lặp đi lặp lại.', 'N2', 'Là một cấu trúc đa nghĩa:  1.   Điều kiện tiêu cực (Nếu ~ thì): Giống như  「ていては」, diễn tả nếu cứ làm A thì sẽ dẫn đến kết quả xấ', 'V ては   A くては   A では   N では', '[{"ja":"そんなに食べては太るよ - Nếu cứ ăn thế thì sẽ béo đấy.)","romaji":"2.   Hành động lặp lại: Diễn tả hai hành động đối lập hoặc tương tự lặp đi lặp","vi":"──────────"},{"ja":"Cần chú ý ngữ cảnh để hiểu đúng.","romaji":"──────────","vi":"Ví dụ:"},{"ja":"～ては～ては  (N2): Nhấn mạnh sự lặp lại.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('163.  てはいられない: Không thể cứ ~; không thể chịu đựng được ~.', 'N2', 'Diễn tả rằng không thể tiếp tục ở trong một trạng thái hoặc thực hiện một hành động nào đó nữa, vì tình huống, cảm xúc, hoặc trách nhiệm không cho phép.', 'V て +  は +  いられない', '[{"ja":"もう時間がないから、のんびりしてはいられない。","romaji":"→ Vì không còn thời gian nữa nên không thể cứ thong thả được.","vi":""},{"ja":"人が困っているのを見て、黙ってはいられなかった。","romaji":"→ Thấy người khác gặp khó khăn, tôi đã không thể im lặng được.","vi":""},{"ja":"試験が近いのに、テレビを見てはいられない。","romaji":"→ Sắp thi rồi, không thể cứ xem TV được.","vi":"──────────"},{"ja":"～わけにはいかない  (N3): \"Không thể ~\" (vì lý do xã hội/tâm lý).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('164.  てはならない: Không được; không thể; không nên ~.', 'N2', 'Dùng để diễn tả sự cấm đoán mạnh mẽ, hoặc một điều không nên làm theo quy tắc, đạo đức, hoặc luật lệ. Đây là cách nói trang trọng và cứng rắn.', 'V て +  は +  ならない', '[{"ja":"法律は守らなければならない。決して破ってはならない。","romaji":"→ Pháp luật là phải tuân thủ. Tuyệt đối không được phá vỡ.","vi":""},{"ja":"人の信頼を裏切ってはならない。","romaji":"→ Không được phản bội lòng tin của người khác.","vi":""},{"ja":"危険な場所には近づいてはならない。","romaji":"→ Không được đến gần những nơi nguy hiểm.","vi":"──────────"},{"ja":"～べきではない  (N3): \"Không nên\", chỉ điều không nên làm theo lẽ thường/đạo đức.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('165.  ては～ては: Cứ ~ rồi lại ~ (hành động lặp đi lặp lại).', 'N2', 'Dùng để diễn tả một chuỗi hành động được lặp đi lặp lại nhiều lần.', 'V1 ては + V2 て   (Thường V1 và V2 là một hoặc hai động từ đối lập/tương tự)', '[{"ja":"彼は食べては寝て、食べては寝ての生活をしている。","romaji":"→ Anh ta đang sống một cuộc sống cứ ăn rồi ngủ, ăn rồi ngủ.","vi":""},{"ja":"雨が降っては止み、降っては止み、はっきりしない天気だ。","romaji":"→ Trời cứ mưa rồi tạnh, mưa rồi tạnh, thời tiết thật không rõ ràng.","vi":""},{"ja":"試験の前、教科書を読んではノートにまとめ、読んではノートにまとめた。","romaji":"→ Trước kỳ thi, tôi cứ đọc sách giáo khoa rồi tóm tắt vào vở, đọc rồi lại tóm tắt.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('166.  と同時に（とどうじに）: Đồng thời với; trong khi ~.', 'N2', '1.   Đồng thời: Diễn tả hai hành động xảy ra cùng một lúc.  2.   Ngay khi: Diễn tả hành động 2 xảy ra ngay sau hành động 1 (giống  ～たとたん).  3.   Vừa... vừa...: Diễn tả hai mặt, hai đặc tính cùng tồn tại (giống A であり、Bでもある).', 'N +  と同時に (とどうじに)   V る +  と同時に (とどうじに)', '[{"ja":"1.   ドアが開くと同時に、彼が入ってきた。","romaji":"→ (Cửa vừa mở thì đồng thời anh ấy bước vào.)","vi":"2.   彼は大学を卒業すると同時に、会社を設立した。"},{"ja":"～たとたん  (N3): \"Ngay khi\", chỉ hành động xảy ra ngay lập tức.","romaji":"","vi":""},{"ja":"～ながら  (N4): \"Vừa... vừa...\", chỉ hai hành động do cùng một chủ thể thực hiện đồng thời.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('167.  といった: Như là ~ (liệt kê ví dụ).', 'N2', 'Dùng để đưa ra một vài ví dụ (N1, N2...) tiêu biểu cho một nhóm hoặc một loại nào đó (N3).', 'N1  や N2 +  といった + N3', '[{"ja":"彼は、野球やサッカーといったスポーツが好きだ。","romaji":"→ Anh ấy thích những môn thể thao như là bóng chày hay bóng đá.","vi":""},{"ja":"この地域では、リンゴやブドウといった果物がよく取れる。","romaji":"→ Ở vùng này, những loại hoa quả như là táo hay nho được trồng nhiều.","vi":""},{"ja":"敬語には、尊敬語、謙譲語、丁寧語といった種類がある。","romaji":"→ Trong kính ngữ, có những loại như là tôn kính ngữ, khiêm nhường ngữ, và thể lịch sự.","vi":"──────────"},{"ja":"～のような  (N4): \"Giống như là\", dùng để so sánh hoặc nêu ví dụ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('168.  というふうに: Theo cách mà ~; Như là ~.', 'N2', 'Dùng để trích dẫn hoặc mô tả lại một nội dung, một cách nói, hoặc một cách làm nào đó.', '[Câu / Cụm từ] +  というふうに', '[{"ja":"彼は「大丈夫だ」というふうに言った。","romaji":"→ Anh ấy đã nói theo cách là \"Không sao đâu\".","vi":""},{"ja":"もっと具体的に説明してほしいというふうに感じました。","romaji":"→ Tôi đã cảm thấy (muốn) rằng anh/chị giải thích cụ thể hơn.","vi":""},{"ja":"このボタンを押すと、こういうふうに動きます。","romaji":"→ Khi ấn nút này, nó sẽ chuyển động theo cách như thế này.","vi":"──────────"},{"ja":"～というように  (N3): Nghĩa rất giống.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('169.  ということは: Điều đó có nghĩa là; nói cách khác ~.', 'N2', 'Dùng để đưa ra một kết luận hoặc suy luận logic dựa trên một sự thật hoặc thông tin đã được nêu ra trước đó.', '[Sự thật / Thông tin] +  ということは + [Kết luận / Suy luận]', '[{"ja":"彼はまだ来ない。ということは、道に迷ったのかもしれない。","romaji":"→ Anh ấy vẫn chưa đến. Điều đó có nghĩa là có lẽ anh ấy đã lạc đường.","vi":""},{"ja":"この部屋は家賃が安い。ということは、何か問題があるのではないか。","romaji":"→ Căn phòng này tiền thuê rẻ. Điều đó có nghĩa là chẳng phải có vấn đề gì đó sao?","vi":""},{"ja":"全員が賛成したということは、この案は可決されるだろう。","romaji":"→ Việc tất cả mọi người tán thành có nghĩa là phương án này chắc sẽ được thông qua.","vi":"──────────"},{"ja":"すなわち  (N1): \"Tức là\", \"nghĩa là\", trang trọng hơn  「つまり」.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('170.  というものだ: Cái gọi là ~; quả là ~.', 'N2', 'Dùng để đưa ra một kết luận hoặc nhận xét mang tính nhấn mạnh, khẳng định rằng một điều gì đó là đương nhiên, hợp lý, hoặc đúng với bản chất của nó.', 'V / A い / A な / N + (thể thường) +  というものだ', '[{"ja":"困った時に助け合うのが、本当の友達というものだ。","romaji":"→ Giúp đỡ nhau lúc khó khăn, đó mới gọi là bạn bè thực sự.","vi":""},{"ja":"何の説明もなく仕事を辞めるのは、無責任というものだ。","romaji":"→ Nghỉ việc mà không có lời giải thích nào thì quả là vô trách nhiệm.","vi":""},{"ja":"若者が未来に希望を持てない社会は、問題だというものだ。","romaji":"→ Một xã hội mà người trẻ không thể có hy vọng vào tương lai thì quả là có vấn đề.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('171.  というものではない: Không hẳn là ~; không phải lúc nào cũng ~.', 'N2', 'Dùng để phủ định một cách nhẹ nhàng hoặc không hoàn toàn một quan điểm, một suy nghĩ thông thường. Khẳng định rằng không phải cứ A là sẽ B, hoặc không phải cứ A là tốt/đúng.', 'V / A い / A な / N + (thể thường) +  というものではない /  というものでもない', '[{"ja":"努力すれば必ず成功するというものではない。","romaji":"→ Không phải cứ nỗ lực là chắc chắn sẽ thành công.","vi":""},{"ja":"お金があれば幸せだというものでもない。","romaji":"→ Không hẳn là cứ có tiền là sẽ hạnh phúc.","vi":""},{"ja":"有名な大学を出たからといって、仕事ができるというものではない。","romaji":"→ Không phải cứ tốt nghiệp đại học nổi tiếng là có thể làm được việc.","vi":"──────────"},{"ja":"～とは限らない  (N3): \"Không nhất thiết là...\", \"chưa chắc là...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('172.  と考えられる（とかんがえられる）: Có thể nghĩ rằng; được cho là ~.', 'N2', 'Dùng để đưa ra một phán đoán, suy luận hoặc giả thuyết một cách khách quan, thường dựa trên một số cơ sở. Đây là cách nói trang trọng, thường dùng trong văn viết, báo cáo, nghiên cứu.', '[Phán đoán] +  と考えられる (とかんがえられる) /  と思われる (とおもわれる)', '[{"ja":"今後、この地域では人口が増加すると考えられる。","romaji":"→ Có thể nghĩ rằng trong tương lai, dân số ở khu vực này sẽ tăng.","vi":""},{"ja":"事件の原因は、不明だと考えられる。","romaji":"→ Nguyên nhân vụ án được cho là không rõ ràng.","vi":""},{"ja":"この結果から、A が B に影響を与えていると考えられる。","romaji":"→ Từ kết quả này, có thể cho rằng A đang ảnh hưởng đến B.","vi":"──────────"},{"ja":"～そうだ  (N4/N3 - suy đoán): \"Có vẻ là\", dựa trên quan sát hoặc thông tin. 「と考えられる」 mang tính học thuật, phân tích hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('173.  とか（で）: Nghe nói là ~.', 'N2', 'Dùng để truyền đạt lại một thông tin mà mình nghe được từ người khác, nhưng không chắc chắn hoàn toàn về tính xác thực của nó. Thường dùng trong văn nói thân mật.', '[Thông tin] +  とか /  とかで', '[{"ja":"田中さん、来月結婚するとか。本当かな？","romaji":"→ Nghe nói anh Tanaka tháng sau cưới とか. Có thật không nhỉ?","vi":""},{"ja":"駅前のレストラン、美味しいとかで、いつも混んでいるよ。","romaji":"→ Nhà hàng trước ga nghe nói là ngon とかで, lúc nào cũng đông khách.","vi":""},{"ja":"明日は雪が降るとか。","romaji":"→ Nghe nói mai tuyết rơi とか.","vi":"──────────"},{"ja":"～らしい  (N3): \"Hình như là\", \"nghe nói là\", dựa trên thông tin nghe được hoặc quan sát.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('174.  とっくに: Từ lâu rồi; đã ~.', 'N2', 'Dùng để nhấn mạnh rằng một hành động hoặc sự việc đã xảy ra hoặc hoàn thành từ rất lâu trước thời điểm nói, hoặc sớm hơn nhiều so với dự kiến.', 'Là một trạng từ (副詞).', '[{"ja":"その宿題なら、とっくに終わらせたよ。","romaji":"→ Nếu là bài tập đó thì tớ đã làm xong từ lâu rồi.","vi":""},{"ja":"会議はとっくに始まっている。早く行こう！","romaji":"→ Cuộc họp đã bắt đầu từ lâu rồi. Nhanh lên đi!","vi":""},{"ja":"彼はとっくに帰ったと思っていたのに、まだいたのか。","romaji":"→ Cứ tưởng anh ta đã về từ lâu rồi, vậy mà vẫn còn ở đây à.","vi":"──────────"},{"ja":"すでに  (N3): \"Đã\", trang trọng hơn  「もう」.  「とっくに」 nhấn mạnh sự \"lâu\" hoặc \"sớm\" hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('175.  ところだった: Suýt nữa thì ~.', 'N2', 'Dùng để diễn tả một tình huống suýt nữa đã xảy ra (thường là việc không tốt), nhưng cuối cùng lại không xảy ra.', 'V る +  ところだった', '[{"ja":"注意していなかったら、車にひかれるところだった。","romaji":"→ Nếu không chú ý thì tôi đã suýt bị xe đâm.","vi":""},{"ja":"目覚ましが鳴らなかったら、寝坊するところだった。","romaji":"→ Nếu chuông báo thức không reo thì tôi đã suýt ngủ quên.","vi":""},{"ja":"あともう少しで勝てるところだったのに、残念だ。","romaji":"→ Suýt nữa thì thắng rồi, thật đáng tiếc.","vi":"──────────"},{"ja":"あやうく～ところだった  (N2): \"Suýt soát\", \"nguy hiểm\", nhấn mạnh sự may mắn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('176.  ところに  /  ところへ: Đúng lúc; đúng vào lúc ~.', 'N2', 'Dùng để diễn tả rằng đúng vào thời điểm một hành động (V) đang diễn ra, vừa mới kết thúc, hoặc sắp bắt đầu thì có một hành động khác xảy ra (thường là bất ngờ hoặc làm gián đoạn).', 'V ている / V た / V ようとした +  ところに /  ところへ', '[{"ja":"出かけようとしたところに、電話がかかってきた。","romaji":"→ Đúng lúc tôi định ra ngoài thì có điện thoại gọi đến.","vi":""},{"ja":"料理をしているところに、友達が遊びに来た。","romaji":"→ Đúng lúc tôi đang nấu ăn thì bạn bè đến chơi.","vi":""},{"ja":"犯人が逃げようとしたところへ、警察官が駆けつけた。","romaji":"→ Đúng lúc tên tội phạm định bỏ chạy thì cảnh sát ập đến.","vi":"──────────"},{"ja":"～途中で  (N4): \"Giữa chừng\", chỉ sự gián đoạn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('177.  ところを見ると（ところをみると）: Nhìn vào ~ thì thấy; xét từ ~.', 'N2', 'Dùng để đưa ra một phán đoán hoặc suy luận dựa trên những gì quan sát được từ hành động hoặc trạng thái của người khác.', 'V ている / V た +  ところを見ると', '[{"ja":"彼が慌てているところを見ると、何か大変なことが起きたのかもしれない。","romaji":"→ Nhìn vào việc anh ấy đang hốt hoảng thì có lẽ đã có chuyện gì đó nghiêm trọng xảy ra.","vi":""},{"ja":"部屋の電気がついているところを見ると、彼はまだ起きているのだろ う。","romaji":"→ Nhìn vào việc đèn phòng còn sáng thì có lẽ anh ấy vẫn còn thức.","vi":""},{"ja":"あの二人が親しそうに話しているところを見ると、付き合っているに 違いない。","romaji":"→ Nhìn vào cảnh hai người đó nói chuyện thân mật thì chắc chắn là họ đang hẹn hò.","vi":"──────────"},{"ja":"～様子から  (N3): \"Từ dáng vẻ ~\", cũng chỉ sự phán đoán qua quan sát.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('178.  とも: Cho dù; bất kể; không ~.', 'N2', '1.   V よう  +  とも  (Cho dù): Diễn tả ý nghĩa "cho dù có làm V hay không, thì vế sau vẫn không thay đổi". Thường dùng với  「たとえ」, mang sắc thái trang trọng, văn viết.  2.   N +  とも  + V ない  (Không ~): Dùng để phủ định hoàn toàn. (Ít phổ biến hơn).', 'V よう +  とも   N +  とも + V ない', '[{"ja":"1.   たとえ誰に反対されようとも、私は自分の道を歩むつもりだ。","romaji":"→ Cho dù có bị ai phản đối đi nữa, tôi vẫn định đi con đường của mình.","vi":"2.   どんな困難があろうとも、決して諦めない。"},{"ja":"たとえ～ても  (N3): \"Giả sử ~ thì cũng ~\", nhấn mạnh giả định.","romaji":"","vi":""},{"ja":"～にしろ  /  ～にせよ  (N2): \"Cho dù ~\", \"Bất kể ~\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('179.  として～ない: Hoàn toàn không; không một ~.', 'N2', 'Dùng để phủ định hoàn toàn bằng cách nhấn mạnh rằng ngay cả đơn vị nhỏ nhất cũng không có.', '[Từ chỉ số lượng nhỏ nhất:  一人 (ひとり) /  一つ (ひとつ) /  一日 (いちにち) /  一度 (いちど) ...] +  として + V ない', '[{"ja":"この秘密は、誰一人として知らない。","romaji":"→ Bí mật này, không một ai biết cả.","vi":""},{"ja":"会場には、一人として知っている人はいなかった。","romaji":"→ Trong hội trường, không có một người nào tôi quen cả.","vi":""},{"ja":"地震の被害を受けた地域には、一日として早く支援が必要だ。 (Trong trường hợp này không đi với  ない, mà mang nghĩa nhấn mạnh \"dù chỉ một ngày cũng phải nhanh\") Câu này có thể gây nhầm lẫn, nên tập trung vào dạng phủ định.","romaji":"","vi":""},{"ja":"彼は今まで一度として約束を破ったことがない。","romaji":"→ Anh ta từ trước đến giờ chưa từng một lần nào thất hứa.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('180.  としても: Giả sử là; ngay cả nếu ~.', 'N2', 'Dùng để đưa ra một giả định (thường là cực đoan hoặc khó xảy ra) và khẳng định rằng dù giả định đó có đúng đi nữa thì vế sau vẫn không thay đổi hoặc vẫn nên làm như vậy.', 'V / A い / A な / N + (thể thường) +  としても /  としたって', '[{"ja":"たとえ失敗するとしても、挑戦する価値はある。","romaji":"→ Ngay cả nếu thất bại, việc thử thách vẫn có giá trị.","vi":""},{"ja":"今から行くとしても、もう間に合わないだろう。","romaji":"→ Giả sử là bây giờ đi thì chắc cũng không kịp nữa.","vi":""},{"ja":"彼が本当のことを言ったとしても、誰も信じないだろう。","romaji":"→ Ngay cả nếu anh ta nói sự thật thì chắc cũng không ai tin.","vi":"──────────"},{"ja":"たとえ～ても  (N3): \"Giả sử ~ thì cũng ~\".  「としても」 gần như đồng nghĩa.","romaji":"","vi":""},{"ja":"～にせよ  /  ～にしろ  (N2): \"Cho dù ~\", \"Bất kể ~\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('181.  つつ: Trong khi; mặc dù; dù ~.', 'N2', '1.   Trong khi (Đồng thời): Diễn tả hai hành động diễn ra song song (giống  「ながら」).  2.   Mặc dù (Đối lập): Diễn tả sự đối lập giữa hai vế, vế trước thừa nhận một điều nhưng vế sau lại trái ngược (giống  「ものの」).', 'Động từ thể  ます (bỏ  ます) +  つつ', '[{"ja":"1.   彼はテレビを見つつ、食事をしている。","romaji":"→ (Anh ta vừa xem TV vừa ăn cơm.)","vi":"2.   危険だと知りつつ、彼は山に登り続けた。"},{"ja":"～ものの  (N2): \"Mặc dù\", chỉ sự đối lập.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('182.  つつある: Đang; đang trong quá trình ~.', 'N2', 'Diễn tả một sự thay đổi đang diễn ra, đang trong quá trình tiến triển. Thường dùng cho những thay đổi có quy mô lớn hoặc diễn ra trong một khoảng thời gian.', 'Động từ thể  ます (bỏ  ます) +  つつある', '[{"ja":"日本の伝統文化は、失われつつある。","romaji":"→ Văn hóa truyền thống Nhật Bản đang dần mất đi.","vi":""},{"ja":"医療技術は、日々進歩しつつある。","romaji":"→ Kỹ thuật y tế đang tiến bộ từng ngày.","vi":""},{"ja":"景気は、徐々に回復しつつある。","romaji":"→ Tình hình kinh tế đang dần dần hồi phục.","vi":"──────────"},{"ja":"～一方だ  (N2) /  ～ばかりだ  (N2): \"Cứ ~\", cũng chỉ xu hướng thay đổi.  「 つつある」 nhấn mạnh vào quá trình đang diễn ra.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('183.  上は（うえは）: Một khi đã; vì ~.', 'N2', 'Tương tự  「からには」 và  「以上は」, diễn tả rằng một khi đã ở vào tình huống A, hoặc một khi đã quyết định/hứa/nói A, thì việc làm B là điều đương nhiên, tất yếu, hoặc là nghĩa vụ phải làm.', 'V る / V た +  上は (うえは)', '[{"ja":"約束した上は、必ず守ります。","romaji":"→ Một khi đã hứa thì nhất định sẽ giữ lời.","vi":""},{"ja":"試合に出る上は、全力で戦うつもりだ。","romaji":"→ Một khi đã ra sân thi đấu thì tôi định sẽ chiến đấu hết sức.","vi":""},{"ja":"こうなった上は、覚悟を決めるしかない。","romaji":"→ Một khi đã đến nước này thì chỉ còn cách quyết tâm thôi.","vi":"──────────"},{"ja":"～以上は  (N2): Nghĩa rất giống.  「上は」 có thể được coi là trang trọng nhất trong ba mẫu này.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('184.  はもとより: ~ là đương nhiên, mà cả ~ cũng; nói gì đến ~.', 'N2', 'Dùng để diễn tả rằng N1 là điều đương nhiên, không cần bàn cãi, nhưng không chỉ dừng lại ở đó, mà N2 (thường ở mức độ cao hơn hoặc rộng hơn) cũng như vậy.', 'N1 +  はもとより + N2 +  も', '[{"ja":"彼は英語はもとより、フランス語も話せる。","romaji":"→ Anh ấy tiếng Anh thì đã đành, mà cả tiếng Pháp cũng nói được.","vi":""},{"ja":"この村には、バスはもとより、電車も通っていない。","romaji":"→ Làng này, xe buýt đã đành, mà cả tàu điện cũng không chạy qua.","vi":""},{"ja":"見た目はもとより、味も素晴らしい。","romaji":"→ Vẻ ngoài thì đã đành, mà cả vị cũng tuyệt vời.","vi":"──────────"},{"ja":"～だけでなく  (N3) /  ～ばかりか  (N2): \"Không chỉ... mà còn...\", cũng dùng để bổ sung, nhưng  「はもとより」 nhấn mạnh hơn vào sự \"đương nhiên\" của vế 1.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('185.  はともかく: Khoan hãy nói đến; bất kể ~.', 'N2', 'Dùng để nhấn mạnh rằng yếu tố N2 quan trọng hơn hoặc cần được ưu tiên xem xét hơn N1. N1 có thể quan trọng, nhưng trong ngữ cảnh này, người nói muốn tạm gác N1 lại để tập trung vào N2.', 'N1 +  はともかく (として) + N2 +  は/が', '[{"ja":"見た目はともかく、味がとてもいい。","romaji":"→ Khoan hãy nói đến vẻ ngoài, vị của nó rất ngon.","vi":""},{"ja":"結果はともかく、最後まで努力したことが大切だ。","romaji":"→ Bất kể kết quả thế nào, việc đã nỗ lực đến cùng mới là quan trọng.","vi":""},{"ja":"値段はともかくとして、デザインが気に入らない。","romaji":"→ Khoan bàn đến giá cả, tôi không thích thiết kế này.","vi":"──────────"},{"ja":"～は別として  (N3): \"Ngoại trừ A\", \"Không tính đến A\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('186.  わずかに: Chỉ một chút; một ít; vừa đủ; suýt soát ~.', 'N2', 'Diễn tả một số lượng, mức độ, hoặc khoảng cách rất nhỏ, rất ít.', 'Là một trạng từ (副詞).', '[{"ja":"会場には、わずかに空席が残っていた。","romaji":"→ Trong hội trường, chỉ còn lại một vài chỗ trống.","vi":""},{"ja":"彼はわずかに微笑んだ。","romaji":"→ Anh ấy chỉ mỉm cười một chút.","vi":""},{"ja":"ゴールまでわずか１メートルのところで転んでしまった。","romaji":"→ Tôi đã bị ngã khi chỉ còn cách vạch đích suýt soát 1 mét.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('187.  やがて: Chẳng mấy chốc; sắp; gần như; cuối cùng thì ~.', 'N2', 'Dùng để diễn tả một sự việc sẽ xảy ra trong một tương lai không xa, hoặc một sự thay đổi sẽ diễn ra sau một khoảng thời gian. Cũng có thể dùng với nghĩa "cuối cùng thì".', 'Là một trạng từ (副詞).', '[{"ja":"冬が終わり、やがて春が来る。","romaji":"→ Mùa đông kết thúc, chẳng mấy chốc mùa xuân sẽ đến.","vi":""},{"ja":"雨はやがて止むだろう。","romaji":"→ Mưa rồi cũng sẽ tạnh thôi.","vi":""},{"ja":"彼は努力を続け、やがて有名な作家になった。","romaji":"→ Anh ấy tiếp tục nỗ lực, và cuối cùng đã trở thành một nhà văn nổi tiếng.","vi":"──────────"},{"ja":"まもなく  (N3): \"Sắp\", trang trọng hơn  「もうすぐ」.","romaji":"","vi":""},{"ja":"そのうち  (N3): \"Một lúc nào đó\", \"chẳng mấy chốc\".","romaji":"","vi":""},{"ja":"結局（けっきょく）  (N3): \"Cuối cùng\", chỉ kết quả.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('188.  やら～やら: Nào là A nào là B; A và B vân vân ~.', 'N2', 'Dùng để liệt kê một vài ví dụ một cách lộn xộn, không theo thứ tự. Thường mang hàm ý rằng có rất nhiều thứ (hành động, sự vật, cảm xúc) và người nói không thể kể hết được, đôi khi thể hiện sự than phiền hoặc tình trạng bận rộn, hỗn loạn.', 'N1 +  やら + N2 +  やら   V1 る +  やら + V2 る +  やら   A1 い +  やら + A2 い +  やら', '[{"ja":"引っ越しの準備で、荷造りするやら、手続きするやらで、とても忙しい。","romaji":"→ Chuẩn bị chuyển nhà, nào là đóng gói hành lý, nào là làm thủ tục, rất bận rộn.","vi":""},{"ja":"嬉しいやら恥ずかしいやらで、顔が赤くなった。","romaji":"→ Vừa vui vừa xấu hổ, mặt tôi đỏ bừng lên.","vi":""},{"ja":"部屋には、本やら服やらが散らかっていた。","romaji":"→ Trong phòng, nào là sách nào là quần áo vứt bừa bãi.","vi":"──────────"},{"ja":"～たり～たり  (N4): Liệt kê các hành động không theo thứ tự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('189.  よほど  /  よっぽど: Rất; lắm; nhiều; phần lớn ~.', 'N2', 'Dùng để nhấn mạnh mức độ cao của một tính chất, trạng thái, hoặc hành động. Cũng có thể dùng để diễn tả ý định hoặc suy nghĩ "suýt nữa thì định...".', 'Là một trạng từ (副詞).', '[{"ja":"よほど疲れていたのか、彼はソファで寝てしまった。","romaji":"→ Chắc là mệt lắm hay sao mà anh ấy ngủ thiếp đi trên sofa.","vi":""},{"ja":"あの人はよほどの金持ちに違いない。","romaji":"→ Người đó chắc chắn là một người rất giàu.","vi":""},{"ja":"よっぽど言おうかと思ったが、結局やめた。","romaji":"→ Tôi đã suýt nữa thì định nói ra, nhưng cuối cùng lại thôi.","vi":"──────────"},{"ja":"相当（そうとう）  (N2): \"Khá là\", \"tương đối\".  「よほど」 thường mang sắc thái mạnh hơn hoặc chỉ sự phán đoán.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('190.  より: Từ~ (thời gian, địa điểm, người - trang trọng).', 'N2', 'Dùng để chỉ điểm bắt đầu của thời gian, địa điểm, hoặc nguồn gốc. Đây là cách nói trang trọng hơn  「から」.', 'N +  より', '[{"ja":"会議は午後１時より開始いたします。","romaji":"→ Cuộc họp sẽ bắt đầu từ 1 giờ chiều.","vi":""},{"ja":"大阪より参りました田中です。","romaji":"→ Tôi là Tanaka, đến từ Osaka.","vi":""},{"ja":"これより先は、立ち入り禁止です。","romaji":"→ Từ điểm này trở đi, cấm vào.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('191.  よりほかない: Không còn cách nào khác ngoài ~.', 'N2', 'Dùng để diễn tả rằng trong một tình huống nào đó, không còn lựa chọn nào khác ngoài việc phải làm V. Thể hiện sự bắt buộc hoặc không có phương án thay thế.', 'V る +  よりほかない /  ほかはない', '[{"ja":"終電が行ってしまったので、歩いて帰るよりほかない。","romaji":"→ Vì chuyến tàu cuối đã đi mất nên không còn cách nào khác ngoài đi bộ về.","vi":""},{"ja":"証拠がない以上、彼を信じるよりほかない。","romaji":"→ Một khi không có bằng chứng thì không còn cách nào khác ngoài tin anh ta.","vi":""},{"ja":"この病気を治すには、手術するよりほかはないと言われた。","romaji":"→ Tôi được bảo rằng để chữa khỏi bệnh này thì không còn cách nào khác ngoài phẫu thuật.","vi":"──────────"},{"ja":"～ざるを得ない  (N2): \"Buộc phải ~\" (dù không muốn), nhấn mạnh sự bắt buộc do hoàn cảnh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('192.  ようでは: Nếu mà ~ (thì sẽ có kết quả xấu).', 'N2', 'Dùng để diễn tả rằng nếu cứ ở trong tình trạng A (thường là tiêu cực) thì sẽ dẫn đến kết quả xấu B. Mang sắc thái phê phán, cảnh báo, hoặc lo lắng.', 'V る / V ない +  ようでは', '[{"ja":"こんなに簡単な問題も分からないようでは、試験に合格するのは難しいだろう。","romaji":"→ Nếu mà đến cả vấn đề đơn giản thế này cũng không hiểu thì việc thi đỗ chắc là khó.","vi":""},{"ja":"少し注意されただけで泣くようでは、この仕事は続けられないよ。","romaji":"→ Nếu mà chỉ bị nhắc nhở một chút đã khóc thì không thể tiếp tục công việc này được đâu.","vi":""},{"ja":"計画も立てないようでは、成功はおぼつかない。","romaji":"→ Nếu mà đến cả kế hoạch cũng không lập thì thành công là không chắc chắn.","vi":"──────────"},{"ja":"～ていては  (N2): \"Nếu cứ ~\", cũng chỉ điều kiện dẫn đến kết quả xấu, nhưng thường nhấn mạnh vào hành động đang tiếp diễn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('193.  ようではないか: Chúng ta hãy ~; tại sao chúng ta không ~.', 'N2', 'Dùng để đưa ra lời kêu gọi, rủ rê, hoặc đề xuất một cách mạnh mẽ, thường là trong các bài diễn văn, hoặc khi muốn khuyến khích, cổ vũ một nhóm người cùng làm gì đó.', 'Động từ thể ý chí (V よう) +  ではないか /  じゃないか', '[{"ja":"さあ、みんなで頑張ろうではないか。","romaji":"→ Nào, chúng ta hãy cùng nhau cố gắng lên nào!","vi":""},{"ja":"この機会に、新しいことに挑戦しようではないか。","romaji":"→ Nhân cơ hội này, chúng ta hãy thử thách những điều mới đi!","vi":""},{"ja":"問題解決のために、皆で話し合おうではないか。","romaji":"→ Để giải quyết vấn đề, chúng ta hãy cùng nhau thảo luận đi!","vi":"──────────"},{"ja":"～ませんか  (N5): \"Chúng ta cùng ~ không?\", là cách rủ rê lịch sự.  「ようではないか」 mang tính kêu gọi mạnh mẽ hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('194.  ようか～まいか: Có nên ~ hay không; phân vân giữa hai lựa chọn.', 'N2', 'Dùng để diễn tả sự phân vân, do dự, không biết nên làm hay không nên làm một hành động nào đó.', 'V よう +  か + V る +  まいか', '[{"ja":"会社を辞めようか辞めるまいか、ずっと悩んでいる。","romaji":"→ Tôi cứ mãi phân vân không biết nên nghỉ việc hay không.","vi":""},{"ja":"雨が降りそうだが、傘を持っていこうか行くまいか考えている。","romaji":"→ Trời có vẻ sắp mưa, tôi đang nghĩ không biết có nên mang ô đi hay không.","vi":""},{"ja":"本当のことを話そうか話すまいか、彼女は迷った。","romaji":"→ Cô ấy đã phân vân không biết có nên nói sự thật hay không.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('195.  要するに（ようするに）: Tóm lại; nói ngắn gọn ~.', 'N2', 'Dùng để tóm tắt lại những gì đã nói trước đó, đưa ra ý chính, hoặc kết luận một cách ngắn gọn.', '要するに、[Câu tóm tắt]', '[{"ja":"色々説明しましたが、要するに、この計画は中止ということです。","romaji":"→ Tôi đã giải thích nhiều thứ, nhưng tóm lại, kế hoạch này bị hủy.","vi":""},{"ja":"彼は遅刻が多く、仕事もミスばかり。要するに、彼は会社に必要ない人間だ。","romaji":"→ Anh ta đi muộn nhiều, công việc cũng toàn sai sót. Tóm lại, anh ta là người không cần thiết cho công ty.","vi":""},{"ja":"要するに、君は何が言いたいんだ？","romaji":"→ Tóm lại, cậu muốn nói gì?","vi":"──────────"},{"ja":"結局（けっきょく）  (N3): \"Cuối cùng\", \"rốt cuộc\", chỉ kết quả cuối cùng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('196.  ざるを得ない（ざるをえない）: Không thể không; buộc phải ~.', 'N2', 'Dùng để diễn tả rằng mặc dù không muốn làm nhưng vì hoàn cảnh, tình huống bắt buộc nên không còn cách nào khác là phải làm.', 'Động từ thể  ない (bỏ  ない) +  ざるを得ない (ざるをえない)   (する →  せざるを得ない)', '[{"ja":"台風のため、旅行は中止せざるを得なかった。","romaji":"→ Vì bão nên chuyến đi đã buộc phải hủy.","vi":""},{"ja":"上司の命令なので、やりたくなくてもやらざるを得ない。","romaji":"→ Vì là mệnh lệnh của cấp trên nên dù không muốn làm cũng buộc phải làm.","vi":""},{"ja":"多くの反対があったが、計画変更を認めざるを得なかった。","romaji":"→ Dù có nhiều ý kiến phản đối nhưng chúng tôi đã buộc phải chấp nhận thay đổi kế hoạch.","vi":"──────────"},{"ja":"～よりほかない  (N2): \"Không còn cách nào khác ngoài ~\", nhấn mạnh sự không có lựa chọn.  「ざるを得ない」 nhấn mạnh sự bắt buộc dù không muốn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('197.  ずに済む  （ずにすむ）: Không cần làm ~ cũng được (giống  なくて済 む).', 'N2', 'Tương tự như  「なくて済む」, diễn tả rằng một việc gì đó đã được giải quyết hoặc hoàn thành mà không cần phải thực hiện hành động V.  「ずに」 là dạng phủ định trang trọng hơn  「ないで」.', 'Động từ thể  ない (bỏ  ない) +  ずに +  済む (すむ)   (する →  せずに済む)', '[{"ja":"予約していたおかげで、長時間待たずに済んだ。","romaji":"→ Nhờ đã đặt trước nên tôi đã không cần phải chờ lâu.","vi":""},{"ja":"友達がお金を貸してくれたので、銀行に行かずに済んだ。","romaji":"→ Vì bạn tôi cho vay tiền nên tôi đã không cần phải ra ngân hàng.","vi":""},{"ja":"幸い、薬を飲まずに済むほど回復した。","romaji":"→ May mắn là tôi đã hồi phục đến mức không cần uống thuốc nữa.","vi":"──────────"},{"ja":"～なくてもいい  (N4): \"Không cần làm ~ cũng được\", chỉ sự cho phép hoặc không cần thiết.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('1.  敢えて（あえて）: Dám ~; mạnh dạn ~; cố tình ~; chủ đích ~', 'N1', 'Diễn tả hành động được thực hiện một cách có chủ ý, dù biết rằng điều đó có thể không cần thiết, khó khăn, hoặc đi ngược lại với lẽ thường/mong đợi.', '敢えて + V/A/N', '[{"ja":"負けるとわかっていたが、敢えて彼に挑戦した。","romaji":"→ Dù biết sẽ thua, nhưng tôi vẫn dám thách đấu với anh ta.","vi":""},{"ja":"みんなが反対する中、彼は敢えてその計画を実行した。","romaji":"→ Giữa sự phản đối của mọi người, anh ấy vẫn mạnh dạn thực hiện kế hoạch đó.","vi":"──────────"},{"ja":"無理に  (N4): \"Ép buộc\", \"cố gắng quá sức\".  敢えて nhấn mạnh sự lựa chọn có ý thức hơn.","romaji":"","vi":""},{"ja":"わざわざ  (N3): \"Cất công\", làm việc tốn sức (thường là tốt).  敢えて là làm việc khó/không cần thiết.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('2.  あくまでも: Đến cùng; kiên trì; tuyệt đối; chỉ là ~', 'N1', 'Nhấn mạnh việc giữ vững lập trường/thái độ đến cùng, hoặc nhấn mạnh một điều gì đó chỉ là/hoàn toàn là.', 'あくまでも + V/A/N/Cụm từ/Câu', '[{"ja":"彼はあくまでも自分の無実を主張した。","romaji":"→ Anh ấy đã kiên trì khẳng định sự vô tội của mình đến cùng.","vi":""},{"ja":"これはあくまでも私個人の意見です。","romaji":"→ Đây tuyệt đối chỉ là ý kiến cá nhân của tôi.","vi":"──────────"},{"ja":"絶対  (N5/N4): \"Tuyệt đối\", dùng cho cấm đoán hoặc khẳng định chắc chắn. あくまでも linh hoạt hơn, có cả nghĩa \"chỉ là\".","romaji":"","vi":""},{"ja":"単に  (N2): \"Chỉ là\", \"đơn thuần là\".  あくまでも khi mang nghĩa \"chỉ là\" thường nhấn mạnh hơn về việc giới hạn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('3.  案の定（あんのじょう）: Đúng như đã nghĩ; như thường lệ; quả đúng là', 'N1', 'Dùng khi một kết quả xảy ra đúng như dự đoán hoặc lo sợ trước đó.', '案の定、～', '[{"ja":"怪しいと思っていたら、案の定、彼は詐欺師だった。","romaji":"→ Tôi đã nghi ngờ rồi, và đúng như dự đoán, hắn ta là một kẻ lừa đảo.","vi":"──────────"},{"ja":"思った通り  (N4): \"Đúng như đã nghĩ\", gần nghĩa nhất, nhưng  案の定 thường mang hàm ý mạnh hơn về kết quả không tốt đã được lường trước.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('4.  あらかじめ: Trước; sẵn; trước đó', 'N1', 'Diễn tả hành động hoặc sự chuẩn bị được thực hiện trước một thời điểm/sự kiện nhất định.', 'あらかじめ + V', '[{"ja":"会議に出席される方は、あらかじめ資料を読んでおいてください。","romaji":"→ Những vị tham dự cuộc họp, vui lòng đọc trước tài liệu.","vi":"──────────"},{"ja":"事前に  (N2): Rất trang trọng, thường dùng trong văn viết.","romaji":"","vi":""},{"ja":"～ておく  (N4): \"Làm sẵn\", diễn tả sự chuẩn bị, nhưng  あらかじめ là trạng từ và trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('5.  あっての: Tồn tại được là nhờ có; tất cả là nhờ vào ~', 'N1', 'Nhấn mạnh rằng N2 chỉ tồn tại/có ý nghĩa khi có N1. N1 là điều kiện tiên quyết.', 'N1 +  あっての + N2', '[{"ja":"お客様あっての商売です。","romaji":"→ Việc kinh doanh tồn tại được là nhờ có khách hàng.","vi":"──────────"},{"ja":"からこそ  (N3): \"Chính vì\", nhấn mạnh lý do.  あっての nhấn mạnh nền tảng tồn tại.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('6.  ばこそ: Chỉ vì ~', 'N1', 'Dùng để nhấn mạnh một lý do đặc biệt (thường là tích cực) dẫn đến một hành động.', 'V-ば / A-ければ / Na-であれば / N-であれば +  こそ', '[{"ja":"あなたのことを思えばこそ、厳しく言うのです。","romaji":"→ Chỉ vì nghĩ cho bạn nên tôi mới nói nghiêm khắc như vậy.","vi":"──────────"},{"ja":"～から  (N5): Chỉ lý do thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('7.  ばそれまでだ  /  たらそれまでだ: Nếu… thì hết; thì coi như xong', 'N1', 'Diễn tả rằng nếu một sự việc nào đó xảy ra, thì mọi nỗ lực, giá trị khác sẽ trở nên vô nghĩa.', 'V-ば / V-たら +  それまでだ', '[{"ja":"どんなに高価なものでも、壊れてしまえばそれまでだ。","romaji":"→ Dù là đồ đắt tiền đến mấy, nếu hỏng mất thì cũng coi như xong.","vi":"──────────"},{"ja":"～ても無駄だ  (N3): \"Dù... cũng vô ích\".  それまでだ nhấn mạnh sự \"chấm hết\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('8.  べからず  /  べからざる: Không được; không nên; cấm ~', 'N1', 'Diễn tả sự cấm đoán mạnh, thường mang tính trang trọng, cổ xưa, dùng trong văn viết, quy tắc.', 'V-る +  べからず / V-る +  べからざる + N', '[{"ja":"芝生に入るべからず。","romaji":"→ Cấm dẫm lên cỏ.","vi":""},{"ja":"政治家として許すべからざる発言だ。","romaji":"→ Với tư cách là một chính trị gia, đó là một phát ngôn không thể tha thứ được.","vi":"──────────"},{"ja":"～禁止  (N3): \"Cấm\", thường dùng trong biển báo.","romaji":"","vi":""},{"ja":"～べきではない  (N3): \"Không nên\", khuyên răn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('9.  べく: Để; với mục đích ~', 'N1', 'Diễn tả mục đích thực hiện hành động. Cách nói trang trọng, văn viết.', 'V-る +  べく (する ->  すべく)', '[{"ja":"彼はサッカー選手になるべく、毎日厳しい練習をしている。","romaji":"→ Để trở thành cầu thủ bóng đá, anh ấy đang luyện tập khắc nghiệt mỗi ngày.","vi":"──────────"},{"ja":"～ように  (N4): Dùng cho mục đích liên quan đến khả năng, trạng thái.","romaji":"","vi":""},{"ja":"～んがために  (N1): Gần nghĩa, văn chương hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('10.  べくもない: Không thể nào ~', 'N1', 'Diễn tả rằng một việc gì đó là không thể xảy ra hoặc làm được.', 'V-る +  べくもない', '[{"ja":"素人の彼がプロに勝つべくもない。","romaji":"→ Một người nghiệp dư như anh ta thì làm sao có thể thắng được dân chuyên nghiệp.","vi":"──────────"},{"ja":"～わけがない  (N3): Không thể (vô lý).","romaji":"","vi":""},{"ja":"～ことはできない  (N5): Không thể (khả năng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('11.  べくして: Như thể nó phải xảy ra; theo lẽ tự nhiên', 'N1', 'Diễn tả một kết quả xảy ra là điều tất yếu, không thể tránh khỏi.', 'V-る +  べくして + V-た', '[{"ja":"事故は起こるべくして起こった。","romaji":"→ Vụ tai nạn xảy ra là điều không thể tránh khỏi.","vi":"──────────"},{"ja":"必然的に  (N1/N2): \"Một cách tất yếu\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('12.  びる  /  びて  /  びた: Có vẻ là; trông như; hành xử như ~', 'N1', 'Diễn tả có vẻ ngoài, thái độ giống N/A.', 'N / A-i (bỏ  い) +  びる', '[{"ja":"彼女はまだ子供なのに、ずいぶん大人びて見える。","romaji":"→ Dù vẫn còn là trẻ con, cô bé trông ra dáng người lớn.","vi":"──────────"},{"ja":"～らしい  (N4): Phù hợp với bản chất.","romaji":"","vi":""},{"ja":"～めく  (N1): Thường dùng với danh từ trừu tượng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('13.  ぶり  /  っぷり: Phong cách; cách thức; kiểu ~', 'N1', 'Diễn tả cách thức, trạng thái, hoặc mức độ của hành động.', 'V-ます (bỏ  ます) / N +  ぶり /  っぷり', '[{"ja":"彼の食べっぷりは見事だ。","romaji":"→ Cách anh ấy ăn thật đáng nể.","vi":"──────────"},{"ja":"様子  (N4): \"Trạng thái\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('14.  ぶる  /  ぶって  /  ぶった: Ra vẻ; hành xử như; giả vờ như ~', 'N1', 'Diễn tả hành động cố tỏ ra có đặc tính nào đó mà thực chất không có.', 'N / A-i (bỏ  い) / Na +  ぶる', '[{"ja":"彼は専門家ぶっているが、実は何も知らない。","romaji":"→ Anh ta ra vẻ là chuyên gia nhưng thực ra chẳng biết gì cả.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('15.  だに  /  だにしない: Ngay cả; thậm chí không ~', 'N1', 'Khẳng định: "Chỉ cần ~ thôi cũng đã..." / Phủ định: "Ngay cả ~ cũng không...".', 'N / V-る +  だに / N +  だに + V-ない', '[{"ja":"想像だにしなかった。","romaji":"→ Tôi thậm chí còn không tưởng tượng được.","vi":"──────────"},{"ja":"～すら  (N1/N2): \"Ngay cả\". Trang trọng hơn  さえ.","romaji":"","vi":""},{"ja":"～ですら  (N1): \"Ngay cả\". Gần nghĩa với  すら.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('16.  だの～だの: Nào là ~ nào là ~; và những thứ tương tự ~', 'N1', 'Dùng để liệt kê các ví dụ, thường là mang hàm ý phàn nàn, không hài lòng, hoặc kể lể một cách thiếu trật tự.', 'N/V/A (Thể thông thường) +  だの + N/V/A (Thể thông thường) +  だの', '[{"ja":"彼は給料が安いだの、仕事が忙しいだの、文句ばかり言っている。","romaji":"→ Anh ta toàn phàn nàn, nào là lương thấp, nào là công việc bận rộn.","vi":"──────────"},{"ja":"～や～など  (N5): Liệt kê không đầy đủ, mang tính trang trọng hơn.","romaji":"","vi":""},{"ja":"～なり～なり  (N1): Dùng để đưa ra ví dụ về lựa chọn hành động.  だの～だ の chỉ liệt kê (thường là phàn nàn).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('17.  だろうに: (1) Chắc chắn là..., nhưng ~ (2) Lẽ ra nên (hối tiếc)', 'N1', 'Diễn tả sự tiếc nuối, bất mãn hoặc ngạc nhiên về một sự thật trái với mong đợi ("Chắc là... vậy mà...") hoặc diễn tả sự hối tiếc ("Lẽ ra nên...").', '(Thể thông thường) +  だろうに', '[{"ja":"あんなに勉強したんだろうに、合格できなかったなんて、残念だ。","romaji":"→ Chắc là đã học nhiều đến thế, vậy mà không thể đỗ được, thật đáng tiếc.","vi":""},{"ja":"言ってくれれば手伝っただろうに。","romaji":"→ Lẽ ra cậu nói thì tôi đã giúp rồi.","vi":"──────────"},{"ja":"～ばよかった  (N4): Diễn tả sự hối tiếc \"lẽ ra nên làm\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('18.  であれ  /  であろうと: Dù là ai; dù là gì; dù thế nào; ngay cả ~', 'N1', 'Dùng để đưa ra một ví dụ cực đoan hoặc bao hàm mọi trường hợp, và khẳng định rằng vế sau vẫn đúng.', 'N / Từ để hỏi +  であれ /  であろうと', '[{"ja":"たとえ国王であれ、法を犯すことは許されない。","romaji":"→ Dù là quốc vương đi nữa, cũng không được phép vi phạm pháp luật.","vi":"──────────"},{"ja":"～(で)あっても  (N2): Gần nghĩa, cũng diễn tả sự nhượng bộ.","romaji":"","vi":""},{"ja":"～といえども  (N1): Cũng mang nghĩa \"dù là\", rất trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('19.  であれ～であれ: Dù là [A] hay [B]', 'N1', 'Dùng để liệt kê hai hoặc nhiều ví dụ và khẳng định rằng vế sau đúng cho tất cả.', 'N1 +  であれ + N2 +  であれ', '[{"ja":"男であれ女であれ、能力のある人がリーダーになるべきだ。","romaji":"→ Dù là nam hay nữ, người có năng lực nên trở thành lãnh đạo.","vi":"──────────"},{"ja":"～といい～といい  (N2): Dùng để nêu ví dụ và đưa ra đánh giá chung.","romaji":"","vi":""},{"ja":"～ようと～ようと  (N1): Dùng với động từ thể ý chí.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('20.  でもあり～でもある: Vừa là… vừa là ~; cả… và ~', 'N1', 'Dùng để nói rằng một người/vật có đồng thời hai đặc điểm, vai trò.', 'N1 +  でもあり + N2 +  でもある', '[{"ja":"彼は私の先生でもあるし、親友でもある。","romaji":"→ Anh ấy vừa là thầy giáo của tôi, vừa là bạn thân của tôi.","vi":"──────────"},{"ja":"～し～し  (N4): Liệt kê lý do hoặc đặc điểm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('21.  でも何でもない  /  くも何ともない: Không hề; không có gì như thế cả', 'N1', 'Dùng để phủ định mạnh mẽ một điều gì đó, khẳng định rằng nó hoàn toàn không phải như vậy.', 'N +  でも何でもない / A-く +  も何ともない', '[{"ja":"これは冗談でも何でもない。","romaji":"→ Đây không hề là trò đùa.","vi":"──────────"},{"ja":"決して～ない  (N3): \"Tuyệt đối không\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('22.  でなくてなんだろう: Hẳn là; chắc chắn là ~', 'N1', 'Dùng để nhấn mạnh một cách đầy cảm xúc rằng một điều gì đó chắc chắn là N.', 'N +  でなくてなんだろう /  でなくてなんだろうか', '[{"ja":"これこそ真実の愛でなくてなんだろう。","romaji":"→ Đây hẳn là tình yêu đích thực rồi, còn gì nữa!","vi":"──────────"},{"ja":"まさに～だ  (N2): \"Đúng là\", \"chính là\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('23.  ではあるまいか: Chẳng phải là ~ sao; tôi tự hỏi liệu có phải là không ~', 'N1', 'Dùng để đưa ra ý kiến, phán đoán một cách mềm mỏng.', 'N/V/A (Thể thông thường) +  の +  ではあるまいか / N/Na +  ではあるまいか', '[{"ja":"この計画には、まだ問題があるのではあるまいか。","romaji":"→ Kế hoạch này chẳng phải là vẫn còn vấn đề sao?","vi":"──────────"},{"ja":"～かもしれない  (N4): \"Có lẽ\", diễn tả khả năng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('24.  ではあるまいし: Đâu phải là ~; không phải như thể là ~', 'N1', 'Dùng để phủ định một giả định, thường để đưa ra lời khuyên, phê bình.', 'N / V/A (Thể thông thường) +  の /  ん +  ではあるまいし', '[{"ja":"子供ではあるまいし、そんなことで泣くのはやめなさい。","romaji":"→ Đâu phải là trẻ con, đừng khóc vì những chuyện như thế nữa.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('25.  では済まない（ではすまない）: Không chỉ dừng lại ở ~; sẽ cần nhiều hơn ~', 'N1', 'Diễn tả rằng một vấn đề không thể giải quyết hoặc kết thúc chỉ bằng một hành động/mức độ đơn giản.', 'N / V る/V た +  だけ/こと +  では済まない', '[{"ja":"謝っただけでは済まない問題だ。","romaji":"→ Đây là vấn đề không thể xong chỉ bằng một lời xin lỗi.","vi":"──────────"},{"ja":"～ずには済まない  (N1): \"Không thể không...\", \"buộc phải...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('26.  どうにも～ない: Không ... bằng mọi cách; dù cố gắng thế nào cũng không thể ~', 'N1', 'Dùng để nhấn mạnh rằng dù đã cố gắng bằng mọi cách nhưng vẫn không thể làm được gì.', 'どうにも + V-ない / V-ようがない / A-くない / Na-ではない', '[{"ja":"この問題は難しすぎて、どうにも解けない。","romaji":"→ Vấn đề này khó quá, tôi không tài nào giải được.","vi":"──────────"},{"ja":"とても～ない  (N4): \"Hoàn toàn không thể\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('27.  が早いか（がはやいか）: Vừa mới ~ thì đã; ngay sau khi ~', 'N1', 'Diễn tả một hành động xảy ra gần như đồng thời hoặc ngay lập tức sau một hành động khác.', 'V-る / V-た +  が早いか', '[{"ja":"授業終了のチャイムが鳴るが早いか、生徒たちは教室を飛び出した。 - Chuông tan học vừa reo lên, học sinh đã lao ra khỏi lớp.","romaji":"──────────","vi":"Ngữ pháp tương tự:"},{"ja":"～なり  (N2): Thường dùng với hành động bất thường.","romaji":"","vi":""},{"ja":"～や否や  (N1): Trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('28.  が/も～なら、～も～だ: Nối/so sánh tiêu cực (cha nào con nấy)', 'N1', 'Dùng để nêu ra hai sự vật/sự việc và nhận xét rằng cả hai đều có chung một đặc điểm (thường là tiêu cực).', 'N1 +  が/も + N1 +  なら、 + N2 +  も + N2 +  だ', '[{"ja":"親も親なら、子も子だ。","romaji":"→ Cha nào con nấy.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('29.  がましい: Trông giống; nghe giống; xấp xỉ; tương tự; hơi giống ~', 'N1', 'Diễn tả rằng cái gì đó trông giống, nghe giống như N, thường mang sắc thái không cần thiết, giả tạo.', 'N +  がましい', '[{"ja":"言い訳がましいことは言いたくない。","romaji":"→ Tôi không muốn nói những lời nghe như bào chữa.","vi":"──────────"},{"ja":"～っぽい  (N3/N2): \"Có vẻ\", nhưng  がましい thường mang tính phê phán hành động/thái độ hơn.","romaji":"","vi":""},{"ja":"～ぶる  (N1): \"Ra vẻ\", \"giả vờ\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('30.  がてら: Nhân tiện; đồng thời; cùng lúc; tình cờ ~', 'N1', 'Diễn tả việc thực hiện một hành động (vế sau) nhân tiện khi đang thực hiện một hành động chính khác.', 'N (chỉ hành động) / V-ます (bỏ  ます) +  がてら', '[{"ja":"散歩がてら、コンビニに寄ってきた。","romaji":"→ Nhân tiện đi dạo, tôi đã ghé vào cửa hàng tiện lợi.","vi":"──────────"},{"ja":"～かたわら  (N2): Hai hành động quan trọng song song trong thời gian dài.","romaji":"","vi":""},{"ja":"～を兼ねて  (N1): Kết hợp hai mục đích.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('31.  ごとき  /  ごとく  /  ごとし: Giống như; như thể; như là ~', 'N1', 'Dùng để so sánh, ví von một cách trang trọng, có phần cổ xưa.', 'N +  の/が +  ごとき + N / N/V-る +  ごとく + V/A/Adv / N/V-る + ごとし', '[{"ja":"夢のごとき**年月だった。","romaji":"→ Đó là những năm tháng như một giấc mơ.","vi":""},{"ja":"矢のごとく**飛び去った。","romaji":"→ Bay đi nhanh như tên bắn.","vi":"──────────"},{"ja":"～みたい  (N4): Dùng trong văn nói, suồng sã hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('32.  ぐるみ: Cùng với; toàn ~', 'N1', 'Diễn tả ý nghĩa "bao gồm cả N", "toàn bộ N", thường dùng với nhóm người, gia đình, tổ chức.', 'N +  ぐるみ', '[{"ja":"彼らは家族ぐるみで旅行に出かけた。","romaji":"→ Họ đã đi du lịch cùng với cả gia đình.","vi":"──────────"},{"ja":"～全体  (N3): \"Toàn thể\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('33.  羽目になる（はめになる）: Rơi vào tình thế; cuối cùng lại (gặp phải điều khó chịu)', 'N1', 'Diễn tả việc rơi vào một tình huống khó khăn, rắc rối, không mong muốn.', 'V-る +  羽目になる', '[{"ja":"電車に乗り遅れて、結局タクシーで行く羽目になった。","romaji":"→ Vì lỡ chuyến tàu, cuối cùng tôi lại phải đi taxi.","vi":"──────────"},{"ja":"～ざるを得ない  (N1): \"Buộc phải làm\".","romaji":"","vi":""},{"ja":"～しまつだ  (N1): \"Kết cục là\" (xấu).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('34.  ほどのことではない: Không đáng; không cần phải ~', 'N1', 'Diễn tả rằng một việc gì đó không quan trọng, không nghiêm trọng, hoặc không đáng để bận tâm.', 'V-る / N +  ほどのことではない', '[{"ja":"こんな小さな怪我、心配するほどのことではないよ。","romaji":"→ Vết thương nhỏ thế này, không đáng để lo lắng đâu.","vi":"──────────"},{"ja":"～までもない  (N1): \"Không cần phải\" (vì hiển nhiên).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('35.  ほうがましだ: Tốt hơn là; thà ~ còn hơn', 'N1', 'Dùng để so sánh hai lựa chọn, và cho rằng dù lựa chọn được nêu ra không tốt, nhưng nó vẫn tốt hơn so với một lựa chọn khác.', 'V-る / V-ない +  ほうがましだ', '[{"ja":"あんな人と結婚するくらいなら、一生独身のほうがましだ。","romaji":"→ Nếu phải kết hôn với người như thế thì thà sống độc thân cả đời còn hơn.","vi":"──────────"},{"ja":"～くらいなら  (N2): Thường dùng làm vế điều kiện ch","romaji":"","vi":""},{"ja":"ほうがましだ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('36.  放題（ほうだい）: Làm thỏa thích; làm hết ý; để mặc ~', 'N1', 'Diễn tả việc thực hiện một hành động nào đó một cách tự do, không bị giới hạn, thỏa thích. Thường đi kèm với ý nghĩa tiêu cực (làm quá mức) hoặc dùng trong các dịch vụ.', 'V-ます (bỏ  ます) +  放題 (ほうだい)', '[{"ja":"子供たちは夏休みだからと、遊び放題だ。","romaji":"→ Bọn trẻ vì là nghỉ hè nên chơi thỏa thích.","vi":"──────────"},{"ja":"～ままに  (N2): \"Theo như\", \"cứ để...\", chỉ sự thuận theo tự nhiên/ý muốn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('37.  いかんだ  /  いかんでは  /  いかんによっては: Tùy theo; tùy thuộc vào; dù có hay không ~', 'N1', 'Diễn tả rằng kết quả hoặc tình hình ở vế sau sẽ thay đổi, phụ thuộc vào nội dung hoặc trạng thái của N ở vế trước.', 'N +  いかんだ /  いかんでは /  いかんによっては', '[{"ja":"試験の結果いかんでは、卒業できない可能性もある。","romaji":"→ Tùy thuộc vào kết quả kỳ thi mà cũng có khả năng không tốt nghiệp được.","vi":"──────────"},{"ja":"～次第で  (N2): \"Tùy thuộc vào\", rất gần nghĩa, cũng trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('38.  いかんにかかわらず  /  いかんによらず  /  いかんをとわず: Bất kể; dù có hay không; không quan trọng là ~', 'N1', 'Diễn tả rằng vế sau vẫn xảy ra hoặc đúng, bất kể nội dung, trạng thái của N.', 'N +  の +  いかんにかかわらず /  いかんによらず /  いかんをとわず', '[{"ja":"理由のいかんにかかわらず、欠席は欠席として扱います。","romaji":"→ Bất kể lý do là gì, vắng mặt sẽ được xem là vắng mặt.","vi":"──────────"},{"ja":"～を問わず  (N2): \"Bất kể\", \"không phân biệt\", cũng gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('39.  いかなる: Bất kỳ loại nào; mọi; bất cứ ~', 'N1', 'Dùng trước danh từ để nhấn mạnh rằng điều ở vế sau áp dụng cho mọi trường hợp, không có ngoại lệ.', 'いかなる + N + (Trợ từ)', '[{"ja":"いかなる理由があっても、暴力は許されない。","romaji":"→ Dù có bất cứ lý do nào, bạo lực cũng không được tha thứ.","vi":"──────────"},{"ja":"どのような  (N3): Trang trọng hơn  どんな.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('40.  いかに: Như thế nào; bằng cách nào; bao nhiêu; đến mức nào', 'N1', 'Dùng để hỏi hoặc nhấn mạnh mức độ, cách thức. Thường dùng trong câu cảm thán hoặc nhượng bộ.', 'いかに + A/Na +  か /  いかに + V +  か /  いかに +  ～ても/でも', '[{"ja":"彼がいかに努力したか、誰も知らない。","romaji":"→ Không ai biết anh ấy đã nỗ lực đến mức nào.","vi":"──────────"},{"ja":"どんなに  (N4): \"Đến mức nào\".  いかに trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('41.  いかにも: Quả thực; thực sự; thật là; giống như; rất; cực kỳ ~', 'N1', 'Dùng để nhấn mạnh rằng một điều gì đó thực sự hoặc trông rất giống với những gì được mô tả.', 'いかにも +  ～そうだ /  ～らしい /  ～のようだ / N', '[{"ja":"その話はいかにも本当らしく聞こえる。","romaji":"→ Câu chuyện đó nghe quả thực giống như thật.","vi":"──────────"},{"ja":"まるで～のようだ  (N3): \"Cứ như là\".  いかにも nhấn mạnh sự phù hợp với hình mẫu.","romaji":"","vi":""},{"ja":"実に  (N2): \"Thực sự\", \"quả thực\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('42.  いずれにしても  /  いずれにしろ  /  いずれにせよ: Dù sao đi nữa; dù thế nào đi nữa; trong mọi trường hợp ~', 'N1', 'Dùng để kết luận hoặc đưa ra ý kiến chung sau khi xem xét nhiều khả năng.', 'いずれにしても /  いずれにしろ /  いずれにせよ、～', '[{"ja":"いずれにしても、傘は持っていこう。","romaji":"→ Dù sao đi nữa, hãy mang theo ô.","vi":"──────────"},{"ja":"とにかく  (N3): \"Dù sao thì\", thường dùng để chuyển hướng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('43.  じみた: Trở nên; có vẻ như; trông giống như; nhuốm màu ~', 'N1', 'Diễn tả rằng cái gì đó có vẻ, có khuynh hướng, hoặc nhuốm màu sắc của N, thường là theo hướng không mong muốn.', 'N +  じみた + N', '[{"ja":"そんな子供じみたことはやめなさい。","romaji":"→ Hãy bỏ những hành động như trẻ con đó đi.","vi":"──────────"},{"ja":"～びる  (N1): \"Trông như\", thường chỉ vẻ bề ngoài/sự thay đổi.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('44.  か否か（かいなか）: Có hay không ~', 'N1', 'Dùng để diễn tả sự lựa chọn hoặc câu hỏi giữa hai khả năng đối lập: có hoặc không.', 'V-る / V-ない +  か否か / N +  である +  か否か', '[{"ja":"出席するか否か、早めにご連絡ください。","romaji":"→ Xin vui lòng liên lạc sớm xem có tham dự hay không.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('45.  かと思いきや（かとおもいきや）: Trái với mong đợi; cứ tưởng là..., nhưng ~', 'N1', 'Diễn tả một sự việc xảy ra trái ngược với những gì người nói đã nghĩ hoặc dự đoán.', '(Thể thông thường) +  かと思いきや、～', '[{"ja":"試験は簡単だったかと思いきや、意外に難しい問題が多かった。","romaji":"→ Cứ tưởng bài thi dễ, ai dè lại có nhiều câu khó bất ngờ.","vi":"──────────"},{"ja":"～のに  (N4): \"Vậy mà...\", diễn tả sự tương phản.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('46.  限りだ（かぎりだ）: Cảm thấy rất ~; vô cùng ~', 'N1', 'Dùng để diễn tả cảm xúc của người nói đang ở mức độ cao nhất.', 'A-い / Na な +  限りだ', '[{"ja":"久しぶりに友人に会えて、嬉しい限りだ。","romaji":"→ Lâu lắm mới gặp lại bạn, tôi vui vô cùng.","vi":"──────────"},{"ja":"極まる  /  極まりない  (N1): \"Cực kỳ\", có thể dùng cho cả đánh giá khách quan.","romaji":"","vi":""},{"ja":"この上ない  (N1): \"Không gì hơn\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('47.  甲斐もなく（かいもなく）: Bất chấp; mặc dù ~ (công cốc)', 'N1', 'Diễn tả rằng mặc dù đã nỗ lực hoặc có giá trị nhưng kết quả lại không như mong đợi, trở nên vô ích.', 'V-た / N +  の +  甲斐もなく', '[{"ja":"必死の治療の甲斐もなく、祖父は亡くなってしまった。","romaji":"→ Mặc dù đã hết lòng chữa trị nhưng ông tôi vẫn qua đời.","vi":"──────────"},{"ja":"～にもかかわらず  (N3): \"Bất chấp\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('48.  可能性がある（かのうせいがある）: Có thể; có khả năng là ~', 'N1', 'Diễn tả sự tồn tại của một khả năng nào đó có thể xảy ra.', 'V-る / N +  の +  可能性がある', '[{"ja":"このままでは、計画が失敗する可能性がある。","romaji":"→ Nếu cứ thế này, có khả năng kế hoạch sẽ thất bại.","vi":"──────────"},{"ja":"～恐れがある  (N2): \"Có nguy cơ\" (tiêu cực).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('49.  からある  /  からする  /  からの: Ít nhất; đến; những ~', 'N1', 'Dùng sau một con số để nhấn mạnh rằng số lượng đó là rất lớn. (からある: trọng lượng, kích thước;  からする: giá tiền;  からの: số người).', '(Số lượng) +  からある /  からする /  からの + N', '[{"ja":"彼は 100 キロからあるバーベルを持ち上げた。","romaji":"→ Anh ấy đã nâng được quả tạ nặng đến 100kg.","vi":""},{"ja":"この絵は 500 万円からするそうだ。","romaji":"→ Bức tranh này nghe nói có giá đến 5 triệu yên.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('50.  かれ～かれ: Sớm hay muộn; ít nhiều', 'N1', 'Dùng để kết hợp hai tính từ/trạng từ trái ngược, mang ý nghĩa "dù là A hay B thì...", "ít nhiều".', 'A-かれ + B-かれ (Thường dùng với  遅かれ早かれ)', '[{"ja":"遅かれ早かれ、真実は明らかになるだろう。","romaji":"→ Sớm hay muộn thì sự thật cũng sẽ được làm sáng tỏ.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('51.  かたがた: Nhân tiện; đồng thời; tình cờ; với mục đích ~', 'N1', 'Diễn tả việc thực hiện một hành động nhân tiện hoặc kết hợp với một mục đích chính khác.', 'N (chỉ hành động/sự kiện) +  かたがた', '[{"ja":"お礼かたがた、ご挨拶に伺います。","romaji":"→ Tôi đến để chào hỏi, đồng thời cũng là để cảm ơn.","vi":"──────────"},{"ja":"～ついでに  (N3): Phổ biến nhất, ít trang trọng nhất.","romaji":"","vi":""},{"ja":"～を兼ねて  (N1): \"Kết hợp\", nhấn mạnh hai mục đích.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('52.  かたわら: Trong khi; bên cạnh đó; đồng thời; ngoài ra', 'N1', 'Diễn tả việc thực hiện hai hành động quan trọng song song trong một khoảng thời gian nhất định.', 'N +  の +  かたわら / V-る +  かたわら', '[{"ja":"彼は大学で教えるかたわら、小説を書いている。","romaji":"→ Anh ấy vừa dạy học ở đại học, vừa viết tiểu thuyết.","vi":"──────────"},{"ja":"～一方（で）(N2): \"Mặt khác\", dùng để so sánh hai mặt hoặc hai hành động song song.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('53.  かつて: Đã từng; trước đây; xưa kia', 'N1', 'Dùng để chỉ một sự việc, trạng thái đã tồn tại trong quá khứ, nhưng hiện tại không còn nữa.', 'かつて + V-た /  かつて +  の + N /  かつて～ない', '[{"ja":"ここはかつて海だったと言われている。","romaji":"→ Nơi đây được cho là đã từng là biển.","vi":"──────────"},{"ja":"昔  (N5): \"Ngày xưa\".  かつて trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('54.  嫌いがある（きらいがある）: Có tật xấu; có xu hướng ~', 'N1', 'Dùng để chỉ ra một khuynh hướng, một thói quen không tốt.', 'V-る / N +  の +  嫌いがある', '[{"ja":"彼は物事を大げさに言う嫌いがある。","romaji":"→ Anh ta có tật là hay nói quá mọi chuyện.","vi":"──────────"},{"ja":"～がち  (N3): \"Thường hay\",  嫌いがある mang tính phê phán mạnh hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('55.  切りがない（きりがない）: Vô tận; không giới hạn; kéo dài mãi; không có hồi kết ~', 'N1', 'Diễn tả rằng nếu cứ tiếp tục làm gì đó thì sẽ không bao giờ kết thúc.', 'V-ば / V-たら +  切りがない / N +  を言い出したら切りがない', '[{"ja":"彼の欠点を数え上げれば切りがない。","romaji":"→ Nếu cứ đếm những khuyết điểm của anh ta thì không biết bao giờ mới hết.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('56.  きっての: ... nhất trong số ~', 'N1', 'Dùng để nhấn mạnh rằng ai đó hoặc cái gì đó là người/vật nổi bật nhất, xuất sắc nhất, hoặc tiêu biểu nhất trong một phạm vi hoặc nhóm cụ thể.', '(Phạm vi/Nhóm) +  きっての + N (Người/Vật xuất sắc)', '[{"ja":"彼は政界きっての実力者だ。","romaji":"→ Ông ấy là người có thực lực nhất trong giới chính trị.","vi":"──────────"},{"ja":"随一（ずいいち）(N?): \"Số một\", \"đệ nhất\", gần nghĩa và cũng trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('57.  極まる  /  極まりない（きわまる  /  きわまりない）: Cực kỳ; rất ~', 'N1', 'Dùng để nhấn mạnh rằng một trạng thái, tình huống, hoặc cảm xúc đang ở mức độ tột cùng.  極まりない thường mang sắc thái tiêu cực hoặc trang trọng hơn.', 'N +  極まる   A な +  極まる /  極まりない   A い +  こと +  極まりない', '[{"ja":"感動極まるスピーチだった。","romaji":"→ Đó là một bài phát biểu vô cùng cảm động.","vi":""},{"ja":"要求を無視するとは、失礼極まりない態度だ。","romaji":"→ Phớt lờ yêu cầu là một thái độ cực kỳ thất lễ.","vi":"──────────"},{"ja":"～限りだ  (N1): \"Vô cùng\", thường dùng cho cảm xúc cá nhân.","romaji":"","vi":""},{"ja":"この上ない  (N1): \"Không gì hơn\", cũng diễn tả mức độ cao nhất.","romaji":"","vi":""},{"ja":"～の至り  (N1) /  ～の極み  (N1): \"Tột cùng\", thường đi với danh từ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('58.  こそあれ: Mặc dù; dù cho ~', 'N1', 'Dùng để thừa nhận sự tồn tại của một đặc điểm (vế trước), nhưng đồng thời nhấn mạnh rằng vế sau mới là điều quan trọng hoặc trái ngược.', 'N / A な +  で +  こそあれ / A く +  こそあれ', '[{"ja":"苦労こそあれ、後悔はしていない。","romaji":"→ Tuy có vất vả nhưng tôi không hối hận.","vi":"──────────"},{"ja":"～けれども  (N4): \"Nhưng\".  こそあれ trang trọng hơn.","romaji":"","vi":""},{"ja":"～といえども  (N1): \"Dù là\", cũng mang tính nhượng bộ, nhưng thường nhấn mạnh sự tương phản giữa địa vị/trạng thái và hành động/kết quả.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('59.  こそすれ: Và; mặc dù; nhưng ~', 'N1', 'Dùng để nhấn mạnh rằng một hành động hoặc trạng thái chỉ xảy ra (vế trước) chứ tuyệt đối không xảy ra điều ngược lại hoặc điều tiêu cực (vế sau).', 'V-ます (bỏ  ます) +  こそすれ、～ない', '[{"ja":"感謝こそすれ、恨む気持ちなど全くない。","romaji":"→ Tôi chỉ có lòng biết ơn chứ hoàn toàn không có cảm giác oán hận.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('60.  こそ「～が・けれど」: Nhưng; mặc dù (nhấn mạnh)', 'N1', 'Dùng  こそ để nhấn mạnh mệnh đề đứng trước nó, sau đó dùng  が hoặc けれど để nối với mệnh đề sau, tạo ra ý nghĩa tương phản hoặc bổ sung.', '(Mệnh đề) +  こそ +  が /  けれど、～', '[{"ja":"彼の日本語は上手だこそ、が、まだビジネスで使うには難しい点もある。","romaji":"→ Tiếng Nhật của anh ấy chính là giỏi, nhưng vẫn còn những điểm khó khăn để sử dụng trong kinh doanh.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('61.  ことごとく: Hoàn toàn; toàn bộ; tất cả ~', 'N1', 'Dùng như một trạng từ để nhấn mạnh rằng tất cả mọi thứ trong một nhóm hoặc phạm vi nào đó đều có chung một đặc điểm hoặc chịu chung một hành động, không có ngoại lệ.', 'ことごとく + V /  ことごとく +  の + N', '[{"ja":"提出した案はことごとく却下された。","romaji":"→ Tất cả các phương án tôi đưa ra đều bị bác bỏ.","vi":"──────────"},{"ja":"残らず  (N?): \"Không còn sót lại\", gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('62.  ことこの上ない  /  この上ない  /  この上なく: Nhất trong tất cả; tốt nhất; không gì ... hơn ~', 'N1', 'Dùng để diễn tả mức độ cao nhất, không có gì có thể hơn được nữa.', 'A い / Na な / N +  の +  ことこの上ない /  この上ない /  この上なく + A/Adv', '[{"ja":"晴れ渡った空の下、この上なく気持ちがいい。","romaji":"→ Dưới bầu trời trong xanh, cảm giác thật dễ chịu không gì bằng.","vi":"──────────"},{"ja":"極まる  /  極まりない  (N1): \"Cực kỳ\".","romaji":"","vi":""},{"ja":"～限りだ  (N1): \"Vô cùng\".","romaji":"","vi":""},{"ja":"～の至り  (N1) /  ～の極み  (N1): \"Tột cùng\".  この上ない nhấn mạnh \"không có gì sánh bằng\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('63.  こともあって: Một phần vì; cũng vì; cộng thêm lý do ~', 'N1', 'Dùng để nêu ra một trong số nhiều lý do dẫn đến kết quả ở vế sau.', '(Thể thông thường) +  こともあって、～', '[{"ja":"彼は元々体が弱いこともあって、よく病気になる。","romaji":"→ Cũng một phần vì vốn dĩ sức khỏe yếu, nên anh ấy hay bị bệnh.","vi":"──────────"},{"ja":"～せいもあって  (N?): \"Cũng một phần là tại vì\" (tiêu cực).","romaji":"","vi":""},{"ja":"～おかげもあって  (N?): \"Cũng một phần nhờ\" (tích cực).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('64.  ことなしに: Mà không làm gì đó', 'N1', 'Diễn tả rằng nếu không thực hiện hành động ở vế trước thì không thể thực hiện hành động/đạt được kết quả ở vế sau.', 'V-る +  ことなしに (は)  ～ない /  できない', '[{"ja":"努力することなしに、成功は得られない。","romaji":"→ Nếu không nỗ lực thì không thể có được thành công.","vi":"──────────"},{"ja":"～ずに  (N3): \"Mà không\".  ことなしに thường nhấn mạnh điều kiện hơn.","romaji":"","vi":""},{"ja":"～なしに  (N1): Gần nghĩa, nhưng  ことなしに thường đi với động từ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('65.  ことのないように: Để không ~', 'N1', 'Dùng để đưa ra lời khuyên, yêu cầu, hoặc thể hiện ý định nhằm mục đích ngăn chặn một việc gì đó (thường là tiêu cực) xảy ra.', 'V-る +  ことのないように、～', '[{"ja":"同じ失敗を繰り返すことのないように、注意してください。","romaji":"→ Hãy chú ý để không lặp lại sai lầm tương tự.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('66.  こととて: Bởi vì; vì ~', 'N1', 'Dùng để nêu lý do, thường là những lý do mang tính khách quan, hoàn cảnh đặc biệt, hoặc để biện minh một cách nhẹ nhàng.', '(Thể thông thường) +  こととて、～ / N +  の +  こととて、～', '[{"ja":"急な話こととて、準備が間に合わなかった。","romaji":"→ Vì là chuyện gấp nên tôi đã không kịp chuẩn bị.","vi":"──────────"},{"ja":"～もので  /  ～ものだから  (N3): Cũng dùng để biện minh.  こととて cổ hơn.","romaji":"","vi":""},{"ja":"～ゆえに  (N1): Cũng chỉ lý do trang trọng, nhưng thường mang tính kết luận hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('67.  くらいなら: Thay vì (làm ...) ~', 'N1', 'Dùng để so sánh hai hành động, và cho rằng thà làm hành động ở vế sau còn hơn là làm hành động ở vế trước.', 'V-る +  くらいなら、～ほうがいい /  ～ほうがましだ / V-たい / V- よう', '[{"ja":"あんな人に頭を下げるくらいなら、会社を辞めたほうがましだ。","romaji":"→ Nếu phải cúi đầu trước người như thế thì thà nghỉ việc còn hơn.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('68.  くらいのものだ: Chỉ (nhấn mạnh)', 'N1', 'Dùng để nhấn mạnh rằng chỉ có N hoặc chỉ có thể làm V là lựa chọn duy nhất, hoặc là người/vật duy nhất.', 'N / V-る +  くらいのものだ /  くらいなものだ', '[{"ja":"彼を説得できるのは、君くらいのものだ。","romaji":"→ Người có thể thuyết phục được anh ta chỉ có cậu mà thôi.","vi":"──────────"},{"ja":"～しかない  (N4): \"Chỉ còn cách\", nhấn mạnh sự không có lựa chọn khác.","romaji":"","vi":""},{"ja":"～をおいて～ない  (N1): \"Ngoài... ra thì không...\", nhấn mạnh sự độc nhất vô nhị.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('69.  までだ  /  までのことだ: Chỉ; chỉ là; không gì khác', 'N1', 'Diễn tả rằng hành động đó được làm chỉ vì một lý do đơn giản, hoặc nếu việc không thành thì chỉ cần làm việc khác.', 'V-る / V-た +  までだ /  までのことだ', '[{"ja":"聞かれたから答えたまでだ。","romaji":"→ Vì được hỏi nên tôi trả lời thôi.","vi":"──────────"},{"ja":"ただ～のみだ  (N1): \"Chỉ... mà thôi\", trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('70.  までもない  /  までもなく: Không cần phải; không cần thiết phải ~', 'N1', 'Dùng để diễn tả rằng một hành động nào đó là không cần thiết vì kết quả đã quá rõ ràng.', 'V-る +  までもない /  までもなく', '[{"ja":"その結果は言うまでもなく、彼の圧勝だった。","romaji":"→ Kết quả đó thì không cần nói cũng biết, là chiến thắng áp đảo của anh ấy.","vi":"──────────"},{"ja":"～ほどのことではない  (N1): \"Không đáng\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('71.  まじき: Không nên; không được ~', 'N1', 'Dùng để phê phán mạnh mẽ một hành động là hoàn toàn không thể chấp nhận được, không phù hợp với tư cách, địa vị (N).', 'N +  として +  ある +  まじき + N / N +  に +  ある +  まじき + N', '[{"ja":"それは教育者としてあるまじき行為だ。","romaji":"→ Đó là hành vi không được phép có ở một nhà giáo.","vi":"──────────"},{"ja":"～として許されない  (N?): \"Không thể tha thứ với tư cách là\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('72.  まくる: Làm đi làm lại; làm không ngừng', 'N1', 'Diễn tả việc thực hiện một hành động lặp đi lặp lại, liên tục, với mức độ hoặc cường độ lớn.', 'V-ます (bỏ  ます) +  まくる', '[{"ja":"彼は一日中ゲームをやりまくっている。","romaji":"→ Cậu ta chơi game liên tục cả ngày.","vi":"──────────"},{"ja":"～放題  (N1): \"Làm thỏa thích\".  まくる nhấn mạnh sự lặp lại và cường độ.","romaji":"","vi":""},{"ja":"～通す  (N2): \"Làm cho đến cùng\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('73.  まみれ: Phủ đầy; dính; bám đầy ~', 'N1', 'Diễn tả rằng bề mặt bị bao phủ, dính đầy bởi một thứ gì đó (thường là bẩn).', 'N +  まみれ', '[{"ja":"子供たちは泥まみれになって遊んでいた。","romaji":"→ Bọn trẻ chơi đùa dính đầy bùn đất.","vi":"──────────"},{"ja":"～ずくめ  (N1): \"Toàn là\" (đồng nhất).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('74.  まるっきり: Hoàn toàn; tuyệt đối; (không) chút nào ~', 'N1', 'Dùng như một trạng từ để nhấn mạnh sự hoàn toàn, tuyệt đối.', 'まるっきり +  ～ない /  ～だ /  ～のようだ', '[{"ja":"彼の話はまるっきり嘘だった。","romaji":"→ Câu chuyện của anh ta hoàn toàn là dối trá.","vi":"──────────"},{"ja":"すっかり  (N3): \"Hoàn toàn\" (thường dùng cho sự thay đổi trạng thái).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('75.  めく: Có vẻ; có dấu hiệu; có vẻ ngoài ~', 'N1', 'Gắn vào sau danh từ để tạo động từ/tính từ, diễn tả rằng cái gì đó bắt đầu có vẻ, có dấu hiệu, hoặc mang không khí của N.', 'N +  めく /  めいて /  めいた + N', '[{"ja":"最近、少しずつ春めいてきた。","romaji":"→ Gần đây, trời đã dần dần có vẻ xuân.","vi":"──────────"},{"ja":"～っぽい  (N3/N2): \"Có vẻ\", nhưng  めく thường trang trọng hơn và dùng với danh từ trừu tượng hoặc chỉ sự thay đổi tinh tế.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('76.  も同然だ（もどうぜんだ）: Giống hệt; như là ~', 'N1', 'Diễn tả rằng mặc dù không hoàn toàn giống 100%, nhưng tình trạng hoặc bản chất của sự việc gần như là giống hệt, có thể coi là như vậy.', 'N +  も同然だ / V-た +  も同然だ', '[{"ja":"この中古車は新品も同然だ。","romaji":"→ Chiếc xe cũ này coi như là xe mới.","vi":""},{"ja":"契約にサインしたのだから、もう買ったも同然だ。","romaji":"→ Vì đã ký hợp đồng rồi nên coi như là đã mua rồi.","vi":"──────────"},{"ja":"～と同じだ  (N5): \"Giống hệt\".  も同然だ có thể dùng khi không hoàn toàn giống 100% nhưng có thể xem là như vậy.","romaji":"","vi":""},{"ja":"～も同じ  (N?): \"Cũng giống như vậy\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('77.  もさることながら: Đã đành, nhưng~; không chỉ... mà còn ~', 'N1', 'Dùng để thừa nhận rằng N (vế trước) là quan trọng/đáng chú ý/đúng, nhưng đồng thời nhấn mạnh rằng vế sau còn quan trọng/đáng chú ý hơn nữa.', 'N +  もさることながら、～', '[{"ja":"デザインもさることながら、機能性も優れている。","romaji":"→ Thiết kế đã đành (rất tốt), nhưng tính năng cũng rất ưu việt.","vi":""},{"ja":"味もさることながら、この店の雰囲気は最高だ。","romaji":"→ Mùi vị đã đành (rất ngon), nhưng bầu không khí của quán này mới là tuyệt nhất.","vi":"──────────"},{"ja":"～はもちろん～も  (N3): \"A là đương nhiên, B cũng...\", gần nghĩa, nhưng もさることながら thường mang tính đánh giá cao cả hai vế.","romaji":"","vi":""},{"ja":"～上に  (N2): \"Thêm vào đó\", \"hơn nữa\", dùng để bổ sung thêm thông tin cùng chiều.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('78.  もしないで: Ngay cả ~ cũng không làm', 'N1', 'Dùng để phê phán hoặc thể hiện sự ngạc nhiên về việc ai đó ngay cả một hành động tối thiểu hoặc cần thiết cũng không làm.', 'V-ます (bỏ  ます) +  もしないで', '[{"ja":"彼は挨拶もしないで部屋に入ってきた。","romaji":"→ Anh ta vào phòng mà đến cả chào hỏi cũng không.","vi":""},{"ja":"よく確かめもしないで、高価なものを買ってしまった。","romaji":"→ Tôi đã mua đồ đắt tiền mà chẳng thèm kiểm tra kỹ lưỡng gì cả.","vi":"──────────"},{"ja":"～ずに  (N3): Tương tự  ～ないで nhưng trang trọng hơn.","romaji":"","vi":""},{"ja":"～ことなしに  (N1): \"Mà không...\", trang trọng hơn, thường dùng trong văn viết.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('79.  もはや: Đã; bây giờ; không còn nữa', 'N1', 'Dùng để diễn tả rằng một tình trạng nào đó đã thay đổi và không còn như trước nữa, hoặc một sự việc đã xảy ra và không thể đảo ngược được nữa.', 'もはや +  ～ない /  ～だ /  ～V-てしまった', '[{"ja":"彼が助かる見込みは、もはやない。","romaji":"→ Hy vọng anh ấy qua khỏi giờ đã không còn nữa.","vi":""},{"ja":"もはや手遅れだ。","romaji":"→ Giờ thì đã quá muộn rồi.","vi":"──────────"},{"ja":"すでに  (N3): \"Đã\", nhấn mạnh sự việc đã hoàn thành.  もはや nhấn mạnh sự thay đổi trạng thái đến mức không thể quay lại.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('80.  もので: Bởi vì; vì lý do đó', 'N1', 'Dùng để nêu lý do, thường là những lý do mang tính cá nhân, hoàn cảnh, để biện minh hoặc giải thích một cách mềm mỏng, lịch sự.', '(Thể thông thường) +  もので /  ものですから', '[{"ja":"事故があったもので、遅れてしまいました。申し訳ありません。","romaji":"→ Vì có tai nạn nên tôi đã đến muộn. Xin lỗi anh/chị.","vi":""},{"ja":"まだ新入社員なものですから、わからないことばかりです。","romaji":"→ Vì còn là nhân viên mới nên tôi có nhiều điều chưa biết.","vi":"──────────"},{"ja":"～もの  (N3): Cũng chỉ lý do, nhưng thường dùng trong văn nói thân mật, đặc biệt là phụ nữ và trẻ em, hoặc khi phàn nàn \"tại vì (con nít mà/con gái mà...)\".","romaji":"","vi":""},{"ja":"～こととて  (N1): \"Bởi vì\", trang trọng và có phần cổ hơn, thường dùng cho lý do mang tính hoàn cảnh đặc biệt.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('81.  ものを: Giá mà; ước gì; tiếc là không phải (hối tiếc)', 'N1', 'Dùng ở cuối mệnh đề thứ nhất để diễn tả sự không hài lòng, tiếc nuối, hoặc trách móc về việc lẽ ra nên có một kết quả tốt hơn (hoặc khác đi) nhưng thực tế lại không như vậy.', '(Thể thông thường) +  ものを、～', '[{"ja":"早く言えば手伝ってあげたものを、今言われても無理だよ。","romaji":"→ Giá mà cậu nói sớm thì tôi đã giúp rồi, bây giờ mới nói thì chịu thôi.","vi":""},{"ja":"知っていれば教えてあげたものを。","romaji":"→ Nếu mà tôi biết thì tôi đã chỉ cho rồi (tiếc là không biết).","vi":"──────────"},{"ja":"～だろうに  (N1): Cũng diễn tả sự tiếc nuối, nhưng thường bao hàm cả sự suy đoán về điều kiện ở vế trước.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('82.  ものと思われる  /  ものと見られる: Được cho là; được giả định là; được tin/mong đợi là ~', 'N1', 'Dùng để đưa ra phán đoán, suy luận một cách khách quan, thường dựa trên các bằng chứng hoặc thông tin có sẵn. Thường dùng trong tin tức, báo cáo.', '(Thể thông thường) +  ものと思われる /  ものと見られる', '[{"ja":"犯人はすでに海外へ逃亡したものと思われる。","romaji":"→ Kẻ tình nghi được cho là đã bỏ trốn ra nước ngoài.","vi":""},{"ja":"今後、この地域ではさらに雨が強まるものと見られる。","romaji":"→ Được dự đoán là từ giờ trở đi, mưa ở khu vực này sẽ còn mạnh hơn.","vi":"──────────"},{"ja":"～ようだ  /  ～そうだ  (N4): \"Có vẻ\", \"nghe nói\", dựa trên cảm nhận hoặc thông tin nghe được. Cấu trúc này thường dựa trên phân tích, dữ liệu.","romaji":"","vi":""},{"ja":"～とされる  (N1): \"Được coi là\", \"người ta nói rằng\", rất gần nghĩa và cũng mang tính khách quan, trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('83.  ものとする: Sẽ; giả định là; được hiểu là ~', 'N1', 'Dùng trong các văn bản quy định, hợp đồng, luật lệ để quy định hoặc giả định một điều gì đó là đúng hoặc sẽ được thực hiện.', 'V-る / N +  である +  ものとする', '[{"ja":"契約期間は一年ものとする。","romaji":"→ Thời hạn hợp đồng sẽ là một năm.","vi":""},{"ja":"提出された書類は返却しないものとする。","romaji":"→ Các tài liệu đã nộp sẽ không được hoàn trả.","vi":"──────────"},{"ja":"～ことになっている  (N3): \"Được quy định là\", \"theo lệ là\", chỉ quy tắc đã có sẵn.  ものとする thường dùng để đặt ra quy định mới.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('84.  ものとして: Giả định là; cho là; với giả định rằng ~', 'N1', 'Dùng để đưa ra một giả định hoặc coi một điều gì đó là sự thật để làm tiền đề cho hành động hoặc suy luận ở vế sau.', '(Thể thông thường) +  ものとして、～', '[{"ja":"彼は会議に出席するものとして、準備を進めてください。","romaji":"→ Hãy tiến hành chuẩn bị với giả định rằng anh ấy sẽ tham dự cuộc họp.","vi":""},{"ja":"説明はすでに聞いたものとして、次の議題に移ります。","romaji":"→ Coi như là mọi người đã nghe giải thích, chúng ta sẽ chuyển sang chủ đề tiếp theo.","vi":"──────────"},{"ja":"～という前提で  (N1): \"Với tiền đề là\", gần như đồng nghĩa và cũng trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('85.  もしくは: Hoặc; nếu không thì', 'N1', 'Dùng để nối hai danh từ, cụm từ hoặc mệnh đề, đưa ra sự lựa chọn giữa hai hoặc nhiều khả năng.', 'A  もしくは B', '[{"ja":"申し込みは、郵送もしくは窓口で受け付けます。","romaji":"→ Việc đăng ký được tiếp nhận qua đường bưu điện hoặc tại quầy.","vi":""},{"ja":"本人もしくは代理人が手続きを行ってください。","romaji":"→ Chính chủ hoặc người đại diện hãy thực hiện thủ tục.","vi":"──────────"},{"ja":"あるいは  (N2): \"Hoặc là\", cũng trang trọng.","romaji":"","vi":""},{"ja":"か  (N5): \"Hoặc\", dùng phổ biến nhất, ít trang trọng nhất.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('86.  んばかりに: Như thể; như là ~', 'N1', 'Dùng để ví von, diễn tả rằng một hành động hoặc trạng thái trông gần như sắp xảy ra hoặc như thể muốn làm điều gì đó, mặc dù thực tế có thể không phải vậy.', 'V-ない (bỏ  ない) +  んばかりに /  んばかりの + N (する ->  せんばかりに)', '[{"ja":"彼は「出て行け」と言わんばかりに、ドアを指さした。","romaji":"→ Anh ta chỉ tay ra cửa như thể muốn nói \"Đi ra đi\".","vi":""},{"ja":"彼女は喜びで飛び上がらんばかりだった。","romaji":"→ Cô ấy trông như thể sắp nhảy cẫng lên vì sung sướng.","vi":"──────────"},{"ja":"～かのように  (N2): \"Cứ như thể là\", gần nghĩa, nhưng  んばかりに thường đi với động từ thể hiện hành động hoặc trạng thái sắp xảy ra, rất mạnh mẽ.","romaji":"","vi":""},{"ja":"～とばかりに  (N1): \"Như thể muốn nói\", tập trung vào việc diễn đạt ý nghĩ. んばかりに tập trung vào trạng thái/hành động \"gần như\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('87.  んがために: Để ~', 'N1', 'Dùng để diễn tả một mục đích rất lớn lao, quan trọng mà người thực hiện hành động quyết tâm đạt được.', 'V-ない (bỏ  ない) +  んがために (は) /  んがための + N (する ->  せんがために)', '[{"ja":"彼は夢を実現せんがために、故郷を離れた。","romaji":"→ Anh ấy đã rời quê hương để thực hiện ước mơ.","vi":""},{"ja":"一命を救わんがための必死の措置だった。","romaji":"→ Đó là biện pháp liều mình để cứu một mạng người.","vi":"──────────"},{"ja":"～べく  (N1): \"Để\", cũng trang trọng, nhưng  んがために mang sắc thái mạnh mẽ, quyết tâm và có phần văn chương hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('88.  ながらに  /  ながらの: Trong khi; trong lúc; không thay đổi; được thực hiện trong tình trạng này', 'N1', 'Dùng để diễn tả một hành động hoặc trạng thái diễn ra trong một tình trạng hoặc hoàn cảnh nhất định, hoặc một trạng thái tồn tại từ khi sinh ra, không thay đổi.', 'V-ます (bỏ  ます) / N +  ながらに /  ながらの', '[{"ja":"彼女は涙ながらに別れを告げた。","romaji":"→ Cô ấy nói lời chia tay trong nước mắt.","vi":""},{"ja":"ここは昔ながらの風景が残っている。","romaji":"→ Nơi đây vẫn còn lưu giữ phong cảnh như ngày xưa.","vi":"──────────"},{"ja":"～まま  (N4): \"Cứ để nguyên\", chỉ trạng thái không thay đổi, nhưng  ながらの thường dùng với những thứ mang tính truyền thống hoặc bẩm sinh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('89.  ないまでも: Chưa đến mức; dù không đạt đến mức ~', 'N1', 'Diễn tả rằng dù không đạt đến mức độ lý tưởng hoặc mức độ cao nhất (V), nhưng ít nhất cũng đạt được một mức độ thấp hơn hoặc một trạng thái nào đó có thể chấp nhận được.', 'V-ない +  までも', '[{"ja":"満点は取れないまでも、合格点は取りたい。","romaji":"→ Dù không đạt được điểm tối đa thì ít nhất cũng muốn đạt điểm đỗ.","vi":""},{"ja":"毎日とは言わないまでも、週に 2、3 回は運動すべきだ。","romaji":"→ Dù không nói là mỗi ngày, nhưng ít nhất cũng nên vận động 2, 3 lần một tuần.","vi":"──────────"},{"ja":"～とは言わないが  (N?): \"Không nói là...\", gần nghĩa khi dùng với V-ないまでも.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('90.  ないものでもない: Không phải là hoàn toàn không thể', 'N1', 'Dùng để diễn tả rằng mặc dù có chút khó khăn hoặc không hoàn toàn chắc chắn, nhưng vẫn có một chút khả năng có thể thực hiện được, không phải là hoàn toàn không thể. Là cách nói phủ định hai lần để thể hiện sự khẳng định yếu.', 'V-ない (thể khả năng) +  ものでもない / V-ない +  こともない', '[{"ja":"条件によっては、引き受けないものでもない。","romaji":"→ Tùy vào điều kiện, không phải là tôi không thể nhận lời. (Tức là nếu điều kiện tốt thì có thể nhận)","vi":""},{"ja":"頑張れば、できないこともないだろう。","romaji":"→ Nếu cố gắng thì có lẽ không phải là không làm được.","vi":"──────────"},{"ja":"～可能性がある  (N1): \"Có khả năng\", khách quan hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('91.  ないものか  /  ないものだろうか: Không có sao; chúng ta không thể…?; tôi không thể…?', 'N1', 'Dùng để diễn tả một mong muốn mạnh mẽ rằng một điều gì đó (thường là khó khăn) có thể xảy ra hoặc có thể thực hiện được, dù biết là khó.', 'V-ない / V-れる (thể khả năng) +  ものか /  ものだろうか', '[{"ja":"どうにかして、この病気を治す方法はないものだろうか。","romaji":"→ Liệu có cách nào chữa khỏi căn bệnh này không nhỉ?","vi":""},{"ja":"もう少し安くならないものかと交渉してみた。","romaji":"→ Tôi đã thử thương lượng xem liệu có thể rẻ hơn chút nữa không.","vi":"──────────"},{"ja":"～といいな  (N4): \"Giá mà...\", cũng thể hiện mong ước.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('92.  ないとも限らない（ないともかぎらない）: Không hẳn là không; không thể nói rằng không; có lẽ; có thể ~', 'N1', 'Dùng để diễn tả rằng không thể khẳng định chắc chắn 100% một điều gì đó (đặc biệt là phủ định). Luôn có một khả năng (dù nhỏ) rằng điều ngược lại có thể xảy ra.', '(Thể thông thường phủ định) +  とも限らない / (Thể thông thường khẳng định) +  とは限らない', '[{"ja":"必ずしも成功するとは限らないが、失敗するとも限らない。","romaji":"→ Không hẳn là sẽ thành công, nhưng cũng chưa chắc đã thất bại. (Không phải là không có khả năng thất bại)","vi":""},{"ja":"安いからといって、品質が悪いとは限らない。","romaji":"→ Không thể nói rằng vì rẻ mà chất lượng xấu. (Tức là rẻ cũng có thể tốt)","vi":"──────────"},{"ja":"～かもしれない  (N4): \"Có lẽ\", chỉ khả năng nói chung.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('93.  なくしては: Không thể làm nếu không có ~', 'N1', 'Dùng để nhấn mạnh rằng N là điều kiện tuyệt đối cần thiết, không thể thiếu để thực hiện hoặc đạt được điều gì đó ở vế sau.', 'N +  なくしては +  ～ない /  できない', '[{"ja":"皆様の協力なくしては、このプロジェクトは成功しなかっただろう。 - Nếu không có sự hợp tác của mọi người thì dự án này đã không thể thành công.","romaji":"","vi":""},{"ja":"努力なくしては、夢は実現できない。","romaji":"→ Nếu không có nỗ lực thì không thể thực hiện ước mơ.","vi":"──────────"},{"ja":"～なしでは  (N3): Gần nghĩa, nhưng  なくしては thường dùng trong văn viết và tình huống trang trọng hơn, nhấn mạnh hơn.","romaji":"","vi":""},{"ja":"～ことなしに(は)～ない  (N1): Cũng có nghĩa \"nếu không... thì không...\", nhưng thường đi với động từ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('94.  並み（なみ）: Trung bình; bình thường; ngang bằng; tương đương ~', 'N1', 'Diễn tả mức độ, khả năng, hoặc kích thước tương đương với N (N thường là tiêu chuẩn hoặc mức độ cao).   Diễn tả mức độ trung bình, thông thường.', 'N +  並み /  並みの + N', '[{"ja":"彼はまだ子供だが、大人並みの知識を持っている。","romaji":"→ Cậu bé tuy còn nhỏ nhưng có kiến thức ngang người lớn.","vi":""},{"ja":"人並みの生活がしたい。","romaji":"→ Tôi muốn có một cuộc sống bình thường như mọi người.","vi":"──────────"},{"ja":"普通  (N5): \"Bình thường\".  人並み là một cách nói khác.","romaji":"","vi":""},{"ja":"～同様  (N2): \"Tương tự\", \"giống như\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('95.  なんという  /  なんと  /  なんて: Thật (đẹp, v.v.); thật là ~', 'N1', 'Dùng để diễn tả sự ngạc nhiên, cảm thán, hoặc xúc động mạnh mẽ của người nói về một sự việc, tình trạng, hoặc đặc điểm nào đó.', 'なんという + N + (だろう/ことだろう) /  なんと + A/Na + (だろう/ ことだろう) /  なんて + A/Na/N + (なんだ/だろう/ことだろう)', '[{"ja":"なんと美しい景色だろう。","romaji":"→ Thật là một cảnh sắc tươi đẹp!","vi":""},{"ja":"なんてひどい話なんだ。","romaji":"→ Quả là một câu chuyện tồi tệ!","vi":""},{"ja":"なんという偶然でしょう。","romaji":"→ Thật là một sự trùng hợp ngẫu nhiên!","vi":"──────────"},{"ja":"本当に  (N5): \"Thật sự\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('96.  何しろ（なにしろ）: Dù sao đi nữa; rốt cuộc; dù sao; bởi vì; như bạn biết ~', 'N1', 'Dùng để nhấn mạnh một lý do chính, một sự thật không thể chối cãi, hoặc một đặc điểm nổi bật nhất để giải thích cho tình huống hoặc ý kiến được nêu ra.', '何しろ、～ / (Mệnh đề) +  何しろ + (Mệnh đề giải thích)', '[{"ja":"今年の夏は暑かった。何しろ、40 度を超えた日が何日もあったのだから。","romaji":"→ Mùa hè năm nay nóng thật. Nói gì thì nói, cũng có mấy ngày nhiệt độ vượt quá 40 độ cơ mà.","vi":""},{"ja":"彼女が人気があるのは、何しろ可愛いからだ。","romaji":"→ Cô ấy được yêu thích là bởi vì, dù sao đi nữa, cô ấy dễ thương mà.","vi":"──────────"},{"ja":"なぜなら  (N3): \"Bởi vì\", dùng để đưa ra lý do một cách trang trọng.  何しろ có phần nói hơn và nhấn mạnh sự hiển nhiên.","romaji":"","vi":""},{"ja":"だって  (N4): \"Bởi vì\", dùng trong văn nói thân mật, thường để biện minh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('97.  ならでは: Chỉ có ở; đặc trưng của; đặc biệt của ~', 'N1', 'Dùng để nhấn mạnh một đặc điểm, phẩm chất, hoặc trải nghiệm độc đáo, đặc trưng, chỉ có thể tìm thấy ở N, không có ở nơi khác.', 'N +  ならでは (の + N)', '[{"ja":"この味は、この店ならではのものだ。","romaji":"→ Mùi vị này là thứ chỉ có ở quán này mà thôi.","vi":""},{"ja":"京都ならではの美しい景色を楽しんだ。","romaji":"→ Tôi đã thưởng thức cảnh đẹp đặc trưng của Kyoto.","vi":"──────────"},{"ja":"～に特有の  (N?): \"Đặc trưng của\", gần nghĩa, nhưng  ならでは mang tính đánh giá cao hơn và thường là những điều tốt đẹp.","romaji":"","vi":""},{"ja":"～でしか～ない  (N3): \"Chỉ có ở... mới...\", gần nghĩa, nhấn mạnh sự giới hạn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('98.  ならいざしらず  /  はいざしらず: Tôi không biết về ... nhưng; có thể ... thì được nhưng ~', 'N1', 'Dùng để nói rằng trường hợp N thì không bàn đến (vì nó đặc biệt, hoặc không biết), nhưng trường hợp khác (vế sau) thì lại khác/là vấn đề.', 'N +  なら +  いざしらず / N +  は +  いざしらず、～', '[{"ja":"子供ならいざしらず、大人がそんなことをしてはいけない。","romaji":"→ Nếu là trẻ con thì không nói làm gì, nhưng người lớn thì không được làm chuyện đó.","vi":""},{"ja":"昔はいざしらず、今では海外旅行は珍しくない。","romaji":"→ Ngày xưa thì không biết thế nào, chứ bây giờ du lịch nước ngoài không còn hiếm nữa.","vi":"──────────"},{"ja":"～ならまだしも  (N2): \"Nếu là... thì còn được/chấp nhận được, nhưng đằng này...\", cũng dùng để so sánh, nhưng thường với ý chê bai vế sau.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('99.  なり: Ngay sau khi ~', 'N1', 'Diễn tả rằng ngay sau khi hành động V-る xảy ra thì một hành động khác (thường là bất ngờ, không lường trước) xảy ra ngay lập tức.', 'V-る +  なり', '[{"ja":"彼は部屋に入るなり、大声で怒鳴り始めた。","romaji":"→ Anh ta vừa mới vào phòng thì liền bắt đầu la hét lớn tiếng.","vi":""},{"ja":"子供は母親の顔を見るなり、わっと泣き出した。","romaji":"→ Đứa bé vừa nhìn thấy mặt mẹ thì bật khóc nức nở.","vi":"──────────"},{"ja":"～たとたん(に) (N3): Gần nghĩa, nhấn mạnh sự bất ngờ của vế sau.  なり thường dùng với hành động bất ngờ và có thể là tiêu cực hoặc hành động có tính bản năng.","romaji":"","vi":""},{"ja":"～や否や  (N1): Gần như đồng nghĩa, cũng diễn tả sự tức thời, trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('100.  なりに  /  なりの: Phù hợp; theo cách/kiểu riêng ~', 'N1', 'Diễn tả rằng một hành động hoặc trạng thái nào đó được thực hiện hoặc tồn tại theo cách riêng, trong giới hạn, hoặc phù hợp với khả năng, địa vị, hoặc tình trạng của người/vật đó, dù có thể không hoàn hảo hoặc không đạt chuẩn cao.', 'N / V/A (Thể thông thường) +  なりに /  なりの + N', '[{"ja":"私は私なりに一生懸命やっています。","romaji":"→ Tôi đang cố gắng hết sức theo cách của riêng tôi.","vi":""},{"ja":"子供には子供なりの考えがある。","romaji":"→ Trẻ con có suy nghĩ theo kiểu của trẻ con.","vi":"──────────"},{"ja":"～なりに頑張る  (Thành ngữ): \"Cố gắng theo cách của mình\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('101.  なりとも: Ít nhất; dù chỉ một chút (trợ từ trạng thái)', 'N1', 'Dùng để đưa ra một ví dụ tối thiểu, mang ý nghĩa "dù chỉ một chút" hoặc "ít nhất là". Thường dùng trong câu yêu cầu, đề nghị, hoặc mong muốn một cách lịch sự, khiêm tốn.', 'N (Thường là từ chỉ số lượng nhỏ, hoặc từ mang ý nghĩa tối thiểu) +  なりとも', '[{"ja":"何か一言なりとも、アドバイスをいただけませんか。","romaji":"→ Anh có thể cho tôi một lời khuyên, dù chỉ một chút được không ạ?","vi":""},{"ja":"少しなりともお役に立てれば幸いです。","romaji":"→ Nếu có thể giúp ích dù chỉ một chút, tôi cũng rất vui.","vi":"──────────"},{"ja":"～でも  (N5): \"Ngay cả\", dùng để nêu ví dụ, nhưng  なりとも thường dùng với mong muốn/yêu cầu tối thiểu một cách lịch sự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('102.  なり～なり: [A] hoặc [B] hoặc gì đó; ví dụ ~', 'N1', 'Dùng để đưa ra hai hoặc nhiều ví dụ về hành động hoặc lựa chọn, gợi ý rằng người nghe có thể chọn bất kỳ cái nào trong số đó hoặc làm một việc tương tự để giải quyết vấn đề hoặc đạt mục đích.', 'N/V-る +  なり + N/V-る +  なり ( + V  する)', '[{"ja":"熱があるなら、薬を飲むなり、早く寝るなりしたほうがいい。","romaji":"→ Nếu bị sốt thì nên làm gì đó, hoặc là uống thuốc, hoặc là đi ngủ sớm.","vi":""},{"ja":"わからないことがあれば、先生に聞くなり、自分で調べるなりしてください。","romaji":"→ Nếu có điều không hiểu, hãy hoặc là hỏi giáo viên, hoặc là tự mình tra cứu.","vi":"──────────"},{"ja":"～か～か  (N5): \"Hoặc... hoặc...\", dùng để nối hai lựa chọn.  なり～なり có thể bao hàm cả những lựa chọn tương tự khác và thường đi kèm với một hành động giải quyết.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('103.  なしに  /  なしで: Không có; mà không làm ~', 'N1', 'Diễn tả rằng một việc gì đó xảy ra hoặc được thực hiện mà không có N (thường là sự cho phép, sự thông báo, sự nỗ lực...), hoặc không thể xảy ra/thực hiện nếu không có N.', 'N +  なしに (は) /  なしで (は)', '[{"ja":"涙なしには語れない物語だ。","romaji":"→ Đó là câu chuyện không thể kể mà không có nước mắt.","vi":""},{"ja":"予告なしに、試験が行われた。","romaji":"→ Kỳ thi đã được tổ chức mà không báo trước.","vi":"──────────"},{"ja":"～ずに  (N3): \"Mà không\", thường dùng với động từ.  なしに/なしで thường dùng với danh từ.","romaji":"","vi":""},{"ja":"～なくしては  (N1): \"Nếu không có...\", nhấn mạnh mạnh mẽ hơn về điều kiện tuyệt đối cần thiết.","romaji":"","vi":""},{"ja":"～ことなしに  (N1): Gần nghĩa với  なしに nhưng thường đi với động từ ở dạng V-る +  ことなしに.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('104.  に: Và; thêm vào đó; sự kết hợp của ~', 'N1', 'Dùng để liệt kê các danh từ cùng loại, tạo ra cảm giác nhiều thứ được xếp chồng lên nhau hoặc tồn tại cùng lúc một cách tự nhiên.', 'N1 +  に + N2 +  に + ...', '[{"ja":"机の上には、本にノートに辞書に、たくさんのものが置いてあった。 - Trên bàn có rất nhiều thứ, nào là sách, nào là vở, nào là từ điển.","romaji":"","vi":""},{"ja":"朝食はパンに卵にサラダだった。","romaji":"→ Bữa sáng có bánh mì, trứng và salad.","vi":"──────────"},{"ja":"～や  (N5): Liệt kê không đầy đủ, mang tính ví dụ (A, B, và những thứ khác...).","romaji":"","vi":""},{"ja":"～だの～だの  (N1): Liệt kê (thường là phàn nàn hoặc những thứ lộn xộn). に chỉ liệt kê đơn thuần, không có sắc thái cảm xúc.","romaji":"","vi":""},{"ja":"～とか  (N4): Liệt kê ví dụ, có thể dùng cho cả danh từ và động từ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('105.  に値する（にあたいする）: Đáng; xứng đáng ~', 'N1', 'Dùng để đánh giá rằng một người, vật, hoặc hành động có đủ giá trị, phẩm chất để nhận được sự tôn trọng, khen ngợi, tin cậy, hoặc sự chú ý.', 'N / V-る +  に値する', '[{"ja":"彼の勇気ある行動は、尊敬に値する。","romaji":"→ Hành động dũng cảm của anh ấy xứng đáng được tôn trọng.","vi":""},{"ja":"この作品は、注目に値する。","romaji":"→ Tác phẩm này đáng để chú ý.","vi":"──────────"},{"ja":"～に足る  (N1): \"Đủ để\", \"đáng để\", gần như đồng nghĩa, cũng mang tính trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('106.  にあって: Tại; vào; trong; trong điều kiện ~', 'N1', 'Dùng để chỉ một tình huống, hoàn cảnh, hoặc thời điểm đặc biệt mà một sự việc nào đó xảy ra hoặc một người nào đó hành động. Nhấn mạnh hoàn cảnh đặc biệt đó, thường là khó khăn hoặc quan trọng.', 'N +  にあって /  にあっても', '[{"ja":"この困難な状況にあって、彼は冷静さを失わなかった。","romaji":"→ Trong tình huống khó khăn này, anh ấy đã không đánh mất sự bình tĩnh.","vi":""},{"ja":"首相という立場にあって、軽率な発言は許されない。","romaji":"→ Với vị trí là thủ tướng, những phát ngôn thiếu thận trọng là không thể chấp nhận được.","vi":"──────────"},{"ja":"～において  (N2): \"Tại\", \"trong\", cũng trang trọng, dùng để chỉ phạm vi, lĩnh vực, thời gian, địa điểm của sự việc.  にあって thường nhấn mạnh hơn vào tính chất của hoàn cảnh và hành động tương ứng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('107.  に引き換え（にひきかえ）: So với; trái ngược với; không giống như; trong khi; còn ~', 'N1', 'Dùng để so sánh hai sự vật, sự việc có sự tương phản rõ rệt, nhấn mạnh sự khác biệt đó một cách nổi bật.', 'N +  に引き換え / (Thể thông thường) +  の +  に引き換え', '[{"ja":"活発な兄に引き換え、弟はおとなしい性格だ。","romaji":"→ Trái ngược với người anh hoạt bát, người em có tính cách trầm lặng.","vi":""},{"ja":"去年が大豊作だったのに引き換え、今年は不作だ。","romaji":"→ Trái ngược với năm ngoái được mùa lớn, năm nay lại mất mùa.","vi":"──────────"},{"ja":"～に対して  (N3): \"Đối với\", \"trái lại\", cũng dùng để so sánh sự khác biệt, nhưng  に引き換え thường thể hiện sự khác biệt rõ rệt và bất ngờ hơn.","romaji":"","vi":""},{"ja":"～反面  (N2): \"Mặt khác\", chỉ hai mặt đối lập của cùng một sự vật/sự việc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('108.  に至る  /  に至った（にいたる  /  にいたった）: Dẫn đến; đi đến kết luận', 'N1', 'Dùng để diễn tả một quá trình đã phát triển và cuối cùng đạt đến một trạng thái, kết quả, hoặc giai đoạn nào đó (thường là quan trọng hoặc cực điểm).', 'N / V-る +  に至る /  に至った', '[{"ja":"長い議論の末、ようやく合意に至った。","romaji":"→ Sau một thời gian dài thảo luận, cuối cùng chúng tôi đã đi đến thỏa thuận.","vi":""},{"ja":"事態は、もはや手の施しようがないところに至っている。","romaji":"→ Tình hình đã đến mức không còn cách nào cứu vãn được nữa.","vi":"──────────"},{"ja":"ついに～  (N3): \"Cuối cùng thì\", nhấn mạnh kết quả sau một thời gian dài.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('109.  に至るまで（にいたるまで）: Đến tận; cho đến; mọi thứ từ ... đến ~', 'N1', 'Dùng để nhấn mạnh phạm vi rộng lớn của một sự việc, bao gồm cả những thứ tưởng chừng nhỏ nhặt hoặc cực đoan nhất, không bỏ sót.', 'N +  に至るまで', '[{"ja":"彼は洋服から下着に至るまで、ブランド品で固めている。","romaji":"→ Anh ta dùng toàn đồ hiệu, từ quần áo cho đến tận đồ lót.","vi":""},{"ja":"大企業の社長から小学生に至るまで、多くの人がそのゲームに夢中になっている。","romaji":"→ Rất nhiều người, từ giám đốc công ty lớn cho đến học sinh tiểu học, đều mê mẩn trò chơi đó.","vi":"──────────"},{"ja":"～から～にかけて  (N3): \"Từ... đến...\", chỉ khoảng không gian hoặc thời gian, không nhấn mạnh sự chi tiết bằng  に至るまで.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('110.  に至っても（にいたっても）: Ngay cả khi; mặc dù; dù ~ đã đến mức ~', 'N1', 'Dùng để diễn tả rằng ngay cả khi tình hình đã tiến triển đến một mức độ nhất định (thường là nghiêm trọng hoặc đã muộn), một hành động hoặc trạng thái nào đó vẫn không xảy ra hoặc không thay đổi như mong đợi.', 'N / V-る +  に至っても', '[{"ja":"死者が出るに至っても、彼らはまだ責任を認めようとしない。","romaji":"→ Ngay cả khi đã có người chết, họ vẫn không chịu thừa nhận trách nhiệm.","vi":""},{"ja":"何度も説明したに至っても、彼は理解してくれない。","romaji":"→ Ngay cả khi đã giải thích nhiều lần (đến mức này rồi), anh ta vẫn không hiểu.","vi":"──────────"},{"ja":"～たところで  (N1): \"Dù có... thì cũng (vô ích)\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('111.  に至っては（にいたっては）: Khi nói đến; đối với ~', 'N1', 'Dùng để đưa ra một ví dụ đặc biệt, thường là cực đoan hoặc tồi tệ nhất (hoặc tốt nhất) trong số những ví dụ đã được nêu trước đó hoặc so với những cái khác, để nhấn mạnh mức độ.', 'N +  に至っては', '[{"ja":"他の科目はまあまあだが、数学に至っては、全く理解できない。","romaji":"→ Các môn khác thì cũng tạm được, nhưng riêng đối với môn toán thì tôi hoàn toàn không hiểu.","vi":""},{"ja":"兄も弟も怠け者だが、弟に至っては、一日中寝てばかりいる。","romaji":"→ Cả anh và em đều lười biếng, nhưng riêng thằng em thì nó ngủ suốt cả ngày (mức độ lười biếng cao hơn).","vi":"──────────"},{"ja":"～となると  (N1): \"Khi nói đến\", nhưng thường dùng để chuyển sang một tình huống cụ thể hơn.  に至っては dùng để chỉ ra một trường hợp cụ thể trong một nhóm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('112.  に言わせれば（にいわせれば）: Nếu bạn hỏi; nếu tôi được phép nói ~', 'N1', 'Dùng để trình bày ý kiến, quan điểm từ lập trường của một người nào đó (N), thường là để nhấn mạnh rằng đó là ý kiến cá nhân hoặc có thể khác với ý kiến của người khác, hoặc là một sự thật mà N muốn nhấn mạnh.', 'N (Người) +  に言わせれば', '[{"ja":"私に言わせれば、それはただの言い訳にすぎない。","romaji":"→ Nếu để tôi nói thì đó chỉ là một lời bao biện mà thôi.","vi":""},{"ja":"専門家に言わせれば、その方法はあまり効果がないそうだ。","romaji":"→ Theo ý kiến của chuyên gia thì phương pháp đó nghe nói không có hiệu quả lắm.","vi":"──────────"},{"ja":"～から見れば  /  ～からすると  (N2): \"Nhìn từ phía...\", \"xét từ...\", gần nghĩa, nhưng  に言わせれば nhấn mạnh vào \"lời nói\", \"ý kiến được phát biểu\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('113.  に限ったことではない（にかぎったことではない）: Không chỉ giới hạn ở ~', 'N1', 'Dùng để nói rằng một sự việc hoặc tình trạng nào đó không chỉ xảy ra hoặc áp dụng cho một trường hợp cụ thể (N/V), mà còn xảy ra ở những trường hợp khác nữa, mang tính phổ biến hơn.', 'N / V-る +  の +  に限ったことではない', '[{"ja":"遅刻が多いのは、彼に限ったことではない。","romaji":"→ Việc đi muộn nhiều không chỉ riêng anh ta.","vi":""},{"ja":"若者の活字離れは、日本に限ったことではない。","romaji":"→ Việc giới trẻ xa rời chữ viết không chỉ giới hạn ở Nhật Bản.","vi":"──────────"},{"ja":"～に限らず  (N2): \"Không chỉ giới hạn ở\", gần như đồng nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('114.  にかかっては  /  にかかったら  /  にかかると  /  かかれば: Khi được xử lý bởi (N), trở thành một kết quả hoàn toàn khác', 'N1', 'Dùng để nhấn mạnh rằng khi một việc gì đó được thực hiện bởi một người có tài năng, kỹ năng, hoặc quyền lực đặc biệt (N), thì kết quả sẽ rất khác biệt, thường là dễ dàng hoặc xuất sắc một cách đáng ngạc nhiên, vượt xa người thường.', 'N (Người có khả năng đặc biệt) +  にかかっては /  にかかったら /  にかかると /  にかかれば、～', '[{"ja":"どんな難しい料理でも、彼にかかれば、簡単に作ってしまう。","romaji":"→ Dù là món ăn khó đến mấy, nếu là anh ấy ra tay thì cũng làm xong một cách dễ dàng.","vi":""},{"ja":"この道のプロにかかると、修理なんてあっという間だ。","romaji":"→ Với dân chuyên trong lĩnh vực này thì việc sửa chữa chỉ trong nháy mắt.","vi":"──────────"},{"ja":"N の手にかかれば  (N?): \"Nếu rơi vào tay N thì...\", gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('115.  にかかっている: Tùy thuộc vào; phụ thuộc vào; có hay không', 'N1', 'Dùng để diễn tả rằng một kết quả hoặc sự thành bại của một việc gì đó hoàn toàn phụ thuộc vào N, N là yếu tố quyết định.', 'N +  にかかっている', '[{"ja":"このプロジェクトが成功するかどうかは、君の努力にかかっている。 - Dự án này có thành công hay không là phụ thuộc vào nỗ lực của cậu.","romaji":"","vi":""},{"ja":"大会で優勝できるかどうかは、明日の試合にかかっている。","romaji":"→ Có thể vô địch giải đấu hay không là tùy thuộc vào trận đấu ngày mai.","vi":"──────────"},{"ja":"～いかんだ  (N1): \"Tùy thuộc vào\", trang trọng hơn.","romaji":"","vi":""},{"ja":"～による  (N3): \"Do...\", \"bởi...\", chỉ sự phụ thuộc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('116.  にかこつけて: Lấy làm cớ; dùng làm lý do', 'N1', 'Diễn tả việc lợi dụng một sự kiện hoặc tình huống (N) nào đó làm lý do, làm cớ để thực hiện một hành động khác, thường là hành động có mục đích riêng, không hoàn toàn liên quan hoặc thậm chí là không tốt.', 'N +  にかこつけて', '[{"ja":"彼は出張にかこつけて、観光を楽しんだ。","romaji":"→ Anh ta lấy cớ đi công tác để đi tham quan.","vi":""},{"ja":"取材にかこつけて、好きな作家に会いに行った。","romaji":"→ Lấy cớ đi lấy tin, tôi đã đi gặp tác giả mình yêu thích.","vi":"──────────"},{"ja":"～という名目で  (N2): \"Dưới danh nghĩa là\", gần nghĩa, cũng thường chỉ lý do bề mặt để che đậy mục đích thật.","romaji":"","vi":""},{"ja":"～を言い訳に  (N?): \"Lấy... làm lý do bao biện\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('117.  にかまけて: Quá bận rộn; chỉ tập trung vào ~', 'N1', 'Diễn tả việc vì quá bận rộn hoặc quá tập trung vào một việc (N) mà lơ là, bỏ bê những việc quan trọng khác đáng lẽ phải làm.', 'N +  にかまけて', '[{"ja":"忙しさにかまけて、家族サービスを怠っていた。","romaji":"→ Do quá bận rộn mà tôi đã lơ là việc dành thời gian cho gia đình.","vi":""},{"ja":"目先の利益にかまけて、大切なことを見失ってはいけない。","romaji":"→ Không được vì mải mê cái lợi trước mắt mà đánh mất những điều quan trọng.","vi":"──────────"},{"ja":"～に気を取られて  (N?): \"Bị phân tâm bởi...\", kết quả cũng có thể là lơ là việc khác.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('118.  に難くない（にかたくない）: Dễ làm; không khó để (tưởng tượng, hiểu, đoán)', 'N1', 'Diễn tả rằng một việc gì đó (thường là tưởng tượng, hiểu, đoán) có thể được thực hiện một cách dễ dàng, không hề khó khăn, dựa trên tình hình hoặc lẽ thường.', 'N +  する / V-る +  に難くない', '[{"ja":"彼がどれほど苦労したか、想像に難くない。","romaji":"→ Không khó để tưởng tượng anh ấy đã vất vả đến mức nào.","vi":""},{"ja":"その知らせを聞いた両親の喜びようは、察するに難くない。","romaji":"→ Dễ dàng đoán được niềm vui của bố mẹ khi nghe tin đó.","vi":"──────────"},{"ja":"容易に～できる  (N?): \"Có thể... một cách dễ dàng\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('119.  にまつわる: Liên quan đến; liên quan; gắn liền với ~', 'N1', 'Dùng để chỉ những câu chuyện, truyền thuyết, sự kiện, hoặc sự vật có mối liên hệ hoặc gắn liền với một danh từ (N) nào đó, thường là một chủ đề rộng hoặc có nhiều khía cạnh.', 'N +  にまつわる + N (thường là  話,  伝説,  出来事...)', '[{"ja":"この地域にまつわる伝説を調べている。","romaji":"→ Tôi đang tìm hiểu những truyền thuyết liên quan đến vùng này.","vi":""},{"ja":"酒にまつわるエピソードは数多くある。","romaji":"→ Có rất nhiều giai thoại liên quan đến rượu.","vi":"──────────"},{"ja":"～にちなんだ  (N?): \"Có liên quan đến/lấy cảm hứng từ\" (thường là tên gọi, sự kiện).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('120.  に則って（にのっとって）: Dựa trên; theo; phù hợp với ~', 'N1', 'Diễn tả việc thực hiện một hành động dựa trên, tuân theo một tiêu chuẩn, quy tắc, luật lệ, hoặc kinh nghiệm nào đó (N) một cách nghiêm ngặt.', 'N +  に則って', '[{"ja":"法律に則って、適切に処理いたします。","romaji":"→ Chúng tôi sẽ xử lý một cách thích hợp dựa trên pháp luật.","vi":""},{"ja":"伝統に則って、式典が執り行われた。","romaji":"→ Buổi lễ đã được cử hành theo truyền thống.","vi":"──────────"},{"ja":"～に基づいて  (N2): \"Dựa trên\", thường dùng khi dựa trên cơ sở dữ liệu, sự thật, kinh nghiệm để đưa ra quyết định hoặc hành động.","romaji":"","vi":""},{"ja":"～に沿って  (N2): \"Men theo\", \"dọc theo\", \"theo sát\", thường dùng với kế hoạch, phương châm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('121.  に先駆けて（にさきがけて）: Trước; là người đầu tiên (tiên phong); đi trước ~', 'N1', 'Diễn tả rằng một hành động hoặc sự việc nào đó xảy ra trước những hành động/sự việc khác cùng loại, mang ý nghĩa tiên phong, đi đầu, mở đường.', 'N +  に先駆けて / V-る +  の +  に先駆けて', '[{"ja":"その会社は他社に先駆けて、新技術を開発した。","romaji":"→ Công ty đó đã phát triển công nghệ mới, đi trước các công ty khác.","vi":""},{"ja":"夏に先駆けて、新しいエアコンが発売された。","romaji":"→ Đi trước mùa hè (trước các hãng khác), mẫu điều hòa mới đã được bán ra.","vi":"──────────"},{"ja":"～に先立って  (N2): \"Trước khi\", cũng trang trọng, nhưng thường chỉ sự chuẩn bị trước một sự kiện quan trọng, không nhất thiết là tiên phong hay cạnh tranh.","romaji":"","vi":""},{"ja":"真っ先に  (N?): \"Đầu tiên nhất\", \"trước hết\", nhấn mạnh thứ tự.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('122.  に忍びない（にしのびない）: Không nỡ (làm); không thể chịu được ~', 'N1', 'Diễn tả cảm giác không nỡ lòng, không đành lòng, hoặc không thể chịu đựng được việc làm một điều gì đó vì thấy thương tâm, đau lòng, hoặc xấu hổ.', 'V-る / N +  に忍びない', '[{"ja":"彼の悲しむ顔を見るに忍びない。","romaji":"→ Tôi không nỡ nhìn gương mặt đau buồn của anh ấy.","vi":""},{"ja":"古い写真だが、捨てるに忍びない。","romaji":"→ Dù là ảnh cũ nhưng tôi không nỡ vứt đi.","vi":"──────────"},{"ja":"～見るに堪えない  (N1): \"Không thể chịu nổi khi nhìn\", gần nghĩa nhưng cụ thể hơn cho hành động nhìn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('123.  にしたところで  /  としたところで: Ngay cả khi; ngay cả giả sử rằng ~', 'N1', 'Dùng để đưa ra một giả định hoặc thừa nhận một quan điểm, nhưng sau đó chỉ ra rằng ngay cả trong trường hợp đó, kết quả cũng không thay đổi hoặc không có giải pháp tốt hơn, hoặc vấn đề vẫn tồn tại.', 'N / V-る/V-た +  にしたところで /  としたところで', '[{"ja":"今から急いだにしたところで、もう間に合わないだろう。","romaji":"→ Ngay cả khi bây giờ có vội đi nữa thì chắc cũng không kịp.","vi":""},{"ja":"専門家としたところで、この問題を解決するのは難しい。","romaji":"→ Ngay cả là chuyên gia thì việc giải quyết vấn đề này cũng khó khăn.","vi":"──────────"},{"ja":"～たところで  (N1): Rất gần nghĩa, cũng diễn tả sự vô ích hoặc không thay đổi dù có làm gì.","romaji":"","vi":""},{"ja":"～にしろ  /  ～にせよ  (N2): \"Dù là... đi nữa\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('124.  にして: Tại / vào / dưới điều kiện nhất định (thời gian, vị trí, tuổi, số lần)', 'N1', 'Dùng để nhấn mạnh một thời điểm, độ tuổi, số lần, hoặc địa vị mà một sự việc đặc biệt xảy ra, thường là để thể hiện sự ngạc nhiên vì nó xảy ra quá sớm, quá muộn, hoặc quá nhanh. Cũng có thể dùng để chỉ người có khả năng đặc biệt mới làm được, hoặc sự kết hợp vai trò.', 'N (Thời gian/Tuổi/Số lần/Địa vị/Khả năng) +  にして', '[{"ja":"彼は 40 歳にして、初めて自分の会社を設立した。","romaji":"→ Mãi đến 40 tuổi anh ấy mới thành lập công ty của riêng mình.","vi":""},{"ja":"この大事業は、彼にして初めて成し遂げられた。","romaji":"→ Công trình vĩ đại này, phải là anh ấy (với khả năng của anh ấy) thì mới có thể hoàn thành được.","vi":""},{"ja":"彼女は女優にして、作家でもある。","romaji":"→ Cô ấy vừa là diễn viên, vừa là nhà văn.","vi":"──────────"},{"ja":"～で初めて  (N?): \"Lần đầu tiên ở/tại/khi...\".","romaji":"","vi":""},{"ja":"～でもある～でもある  (N1): \"Vừa là... vừa là...\",  にして có thể dùng ngắn gọn hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('125.  に即して（にそくして）: Theo; phù hợp với; dựa trên ~', 'N1', 'Diễn tả việc hành động hoặc suy nghĩ dựa trên, tuân theo, hoặc phù hợp chặt chẽ với một sự thật, tình hình thực tế, quy định, hoặc tiêu chuẩn nào đó (N).', 'N +  に即して /  に即した + N', '[{"ja":"事実に即して報告してください。","romaji":"→ Hãy báo cáo dựa trên sự thật.","vi":""},{"ja":"時代の変化に即した教育改革が必要だ。","romaji":"→ Cần có cải cách giáo dục phù hợp với sự thay đổi của thời đại.","vi":"──────────"},{"ja":"～に基づいて  (N2): \"Dựa trên\", dùng cho cơ sở, nền tảng (dữ liệu, nghiên cứu).","romaji":"","vi":""},{"ja":"～に応じて  (N2): \"Ứng với\", \"tùy theo\" (thường là sự thay đổi, nhu cầu).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('126.  に耐える  /  に耐えない（にたえる  /  にたえない）: Đáng làm; có thể làm; không thể chịu đựng làm ~', 'N1', 'に耐える: Diễn tả rằng cái gì đó có đủ giá trị, chất lượng để đáng được (xem, nghe, đọc, sử dụng...).   に耐えない: Diễn tả rằng cái gì đó quá tệ, quá khủng khiếp hoặc quá đau lòng đến mức không thể chịu đựng được (việc xem, nghe, đọc...).', 'N / V-る +  に耐える /  に耐えない', '[{"ja":"この作品は鑑賞に耐えるものだ。","romaji":"→ Tác phẩm này là thứ đáng để thưởng thức.","vi":""},{"ja":"それは聞くに耐えない悲惨な話だった。","romaji":"→ Đó là một câu chuyện bi thảm không thể chịu nổi khi nghe.","vi":"──────────"},{"ja":"我慢できない  (N4): \"Không thể chịu đựng\", thường dùng cho cảm giác cá nhân, sự khó chịu.  に耐えない thường dùng cho chất lượng hoặc mức độ của sự việc khiến người ta không thể tiếp nhận.","romaji":"","vi":""},{"ja":"～に足る  (N1): \"Đáng để\", gần nghĩa với  に耐える.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('127.  に足らない  /  に足りない（にたらない  /  にたりない）: Không thể; không đáng; không đáng làm ~', 'N1', 'Diễn tả rằng một điều gì đó không đủ giá trị, không quan trọng, hoặc không đáng để được xem xét, lo lắng, hoặc tin tưởng.', 'N / V-る +  に足らない /  に足りない', '[{"ja":"そんな噂は信じるに足らない。","romaji":"→ Tin đồn như vậy không đáng để tin.","vi":""},{"ja":"彼らの議論は、聞くに足らない内容だった。","romaji":"→ Cuộc thảo luận của họ có nội dung không đáng để nghe.","vi":"──────────"},{"ja":"～ほどのことではない  (N1): \"Không đáng\", thường dùng để giảm nhẹ mức độ một sự việc.  に足らない thường mang tính đánh giá thấp hơn về giá trị.","romaji":"","vi":""},{"ja":"取るに足りない  (Thành ngữ): \"Không đáng để nhắc tới/quan tâm\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('128.  に足る  /  に足りる（にたる  /  にたりる）: Có thể làm; đáng; đáng làm', 'N1', 'Diễn tả rằng một người, vật, hoặc hành động có đủ khả năng, giá trị, hoặc phẩm chất để được coi là..., hoặc để đáng được làm gì đó. Là dạng khẳng định của  に足らない/に足りない.', 'N / V-る +  に足る /  に足りる', '[{"ja":"彼は信頼するに足る人物だ。","romaji":"→ Anh ấy là một nhân vật đủ để tin tưởng.","vi":""},{"ja":"この資料は証拠とするに足りるだろうか。","romaji":"→ Liệu tài liệu này có đủ để làm bằng chứng không?","vi":"──────────"},{"ja":"～に値する  (N1): \"Xứng đáng\", gần như đồng nghĩa, cũng trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('129.  に照らして（にてらして）: Theo; xét đến; dưới ánh sáng của ~', 'N1', 'Diễn tả việc xem xét, phán đoán, hoặc hành động dựa trên việc so sánh, đối chiếu với một tiêu chuẩn, quy tắc, luật lệ, hoặc kinh nghiệm (N).', 'N +  に照らして', '[{"ja":"法律に照らして判断する。","romaji":"→ Phán đoán dựa theo pháp luật.","vi":""},{"ja":"過去の判例に照らして、今回の事件を考える。","romaji":"→ Xét theo các án lệ trong quá khứ để suy nghĩ về vụ án lần này.","vi":"──────────"},{"ja":"～に基づいて  (N2): \"Dựa trên\", nhấn mạnh cơ sở, nền tảng.","romaji":"","vi":""},{"ja":"～と比べると  (N3): \"So với\", dùng để so sánh thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('130.  にとどまらず: Không giới hạn ở; không chỉ… mà còn ~', 'N1', 'Diễn tả rằng phạm vi ảnh hưởng hoặc mức độ của một sự việc không chỉ dừng lại ở một giới hạn nào đó, mà còn lan rộng ra hoặc bao gồm cả những phạm vi/mức độ lớn hơn, sâu rộng hơn.', 'N / V-る +  にとどまらず、～', '[{"ja":"その影響は、国内にとどまらず、海外にも及んでいる。","romaji":"→ Ảnh hưởng đó không chỉ dừng lại ở trong nước mà còn lan ra cả nước ngoài.","vi":""},{"ja":"彼は俳優としてにとどまらず、監督としても活躍している。","romaji":"→ Anh ấy không chỉ hoạt động với tư cách diễn viên mà còn cả với tư cách đạo diễn.","vi":"──────────"},{"ja":"～ばかりでなく  (N3): Gần nghĩa với  ～だけでなく.","romaji":"","vi":""},{"ja":"～のみならず  (N1): \"Không chỉ\", rất trang trọng, gần như đồng nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('131.  には無理がある（にはむりがある）: Khó làm; là vô lý / không thực tế / không thể', 'N1', 'Diễn tả rằng việc thực hiện một điều gì đó là không thể, không thực tế, hoặc quá sức, vượt quá khả năng hoặc điều kiện cho phép.', 'N / V-る +  の +  には無理がある', '[{"ja":"この予算で計画を実行するのには無理がある。","romaji":"→ Thực hiện kế hoạch với ngân sách này là không thể (vô lý).","vi":""},{"ja":"たった一日で全ての仕事を終わらせるのには無理がある。","romaji":"→ Hoàn thành tất cả công việc chỉ trong một ngày là quá sức.","vi":"──────────"},{"ja":"～のは難しい  (N4): \"Việc... thì khó\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('132.  によらず: Bất kể ~', 'N1', 'Diễn tả rằng một điều gì đó vẫn đúng hoặc vẫn xảy ra mà không bị ảnh hưởng, không phụ thuộc vào N (thường là những yếu tố có thể thay đổi hoặc khác biệt).', 'N +  によらず', '[{"ja":"この大会には、年齢によらず誰でも参加できます。","romaji":"→ Đại hội này, bất kể tuổi tác, ai cũng có thể tham gia.","vi":""},{"ja":"天候によらず、イベントは開催されます。","romaji":"→ Bất kể thời tiết, sự kiện vẫn được tổ chức.","vi":"──────────"},{"ja":"～を問わず  (N2): \"Bất kể\", \"không phân biệt\" (giới tính, tuổi tác, kinh nghiệm,...).","romaji":"","vi":""},{"ja":"～いかんにかかわらず  (N1): \"Bất kể nội dung/tình trạng của...\", trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('133.  に～を重ねて（に～をかさねて）: Thành công sau (nỗ lực, công việc, điều chỉnh, v.v.) liên tục', 'N1', 'Diễn tả rằng sau khi thực hiện một hành động (N1) lặp đi lặp lại nhiều lần, cuối cùng đã đạt được một kết quả nào đó, hoặc một tình trạng mới đã hình thành.', 'N1 (hành động lặp lại) +  に + N1 (lặp lại) +  を重ねて', '[{"ja":"検討に検討を重ねて、ようやく最終案が決まった。","romaji":"→ Sau khi xem xét đi xem xét lại, cuối cùng phương án cuối cùng đã được quyết định.","vi":""},{"ja":"失敗に失敗を重ねて、彼はついに成功を手にした。","romaji":"→ Trải qua thất bại nối tiếp thất bại, cuối cùng anh ấy đã có được thành công.","vi":"──────────"},{"ja":"～末に  (N2): \"Sau khi...\", nhấn mạnh kết quả sau một quá trình dài.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('134.  にもほどがある: Có giới hạn cho những gì có thể chấp nhận được; đi quá xa', 'N1', 'Dùng để phê phán mạnh mẽ rằng một hành động hoặc trạng thái nào đó đã vượt quá giới hạn chấp nhận được, quá đáng, không thể chịu đựng thêm.', 'V-る / N / A +  にもほどがある', '[{"ja":"冗談にもほどがあるぞ。笑えないよ。","romaji":"→ Đùa cũng phải có chừng mực thôi. Không cười nổi đâu.","vi":""},{"ja":"わがままを言うにもほどがある。","romaji":"→ Nói năng ích kỷ cũng phải có giới hạn chứ.","vi":"──────────"},{"ja":"あんまりだ  (N?): \"Quá đáng\", thể hiện sự bất bình.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('135.  にも増して（にもまして）: Hơn…; trên ~', 'N1', 'Dùng để so sánh, nhấn mạnh rằng mức độ ở vế sau còn cao hơn, mạnh hơn, hoặc quan trọng hơn N (vế trước) hoặc hơn bất kỳ lúc nào/thứ gì khác.', 'N /  いつ /  何 +  にも増して', '[{"ja":"以前にも増して、彼女は美しくなった。","romaji":"→ So với trước đây, cô ấy còn trở nên xinh đẹp hơn.","vi":""},{"ja":"何にも増して、健康が第一だ。","romaji":"→ Hơn bất cứ thứ gì, sức khỏe là số một.","vi":""},{"ja":"今日はいつにも増して暑い。","romaji":"→ Hôm nay còn nóng hơn mọi khi.","vi":"──────────"},{"ja":"一層（いっそう）(N2): \"Hơn nữa\", \"càng... hơn\", cũng chỉ sự gia tăng mức độ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('136.  には当たらない（にはあたらない）: Không đáng; không cần phải; không tương ứng với ~', 'N1', 'Diễn tả rằng một hành động hoặc sự việc nào đó không đủ quan trọng, không đủ nghiêm trọng, hoặc không phù hợp để nhận được một phản ứng mạnh như ngạc nhiên, khen ngợi, chỉ trích, hoặc lo lắng.', 'N / V-る +  には当たらない', '[{"ja":"彼の実力からすれば、今回の受賞も驚くには当たらない。","romaji":"→ Nếu xét thực lực của anh ấy thì việc nhận giải lần này cũng không đáng ngạc nhiên.","vi":""},{"ja":"多少の失敗で、それほど悲観するには当たらない。","romaji":"→ Thất bại đôi chút thì không đáng để bi quan đến mức đó.","vi":"──────────"},{"ja":"～までもない  (N1): \"Không cần phải\", nhấn mạnh sự hiển nhiên, không cần thiết phải làm gì đó.","romaji":"","vi":""},{"ja":"大したことない  (N?): \"Chẳng có gì to tát\", cách nói thông thường.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('137.  には及ばない（にはおよばない）: Không cần phải; không cần thiết; không bì được với ~', 'N1', '1.   Diễn tả rằng không cần thiết phải làm một hành động nào đó (thường là lo lắng, cảm ơn, xin lỗi một cách thái quá). 2.   Diễn tả rằng ai đó/cái gì đó không thể sánh bằng, không đạt đến trình độ/mức độ của người/vật khác.', 'N / V-る +  には及ばない', '[{"ja":"心配には及びません。すべて順調です。","romaji":"→ Không cần phải lo lắng đâu ạ. Mọi thứ đều thuận lợi.","vi":""},{"ja":"わざわざ来ていただくには及びません。","romaji":"→ Không cần anh phải cất công đến đây đâu ạ.","vi":""},{"ja":"私の英語力など、彼には及びません。","romaji":"→ Năng lực tiếng Anh của tôi thì không thể bì được với anh ấy.","vi":"──────────"},{"ja":"～ほど～ない  (N4): \"Không... bằng...\", dùng để so sánh thông thường.  には及ばない (nghĩa 2) nhấn mạnh sự thua kém về trình độ/mức độ một cách rõ ràng.","romaji":"","vi":""},{"ja":"～に比べると劣る  (N?): \"So với thì kém hơn\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('138.  の至り（のいたり）: Tột cùng; cực kỳ ~', 'N1', 'Dùng để diễn tả trạng thái hoặc cảm xúc đang ở mức độ cao nhất, tột cùng, thường là những cảm xúc tích cực và trang trọng.', 'N (Thường là danh từ chỉ cảm xúc/trạng thái trang trọng, tích cực) +  の 至り', '[{"ja":"このような素晴らしい賞をいただき、光栄の至りです。","romaji":"→ Nhận được giải thưởng tuyệt vời như thế này, tôi vô cùng vinh hạnh.","vi":""},{"ja":"若気の至りで、大変失礼なことをしてしまいました。","romaji":"→ Do sự bồng bột của tuổi trẻ mà tôi đã làm một việc hết sức thất lễ.","vi":"──────────"},{"ja":"この上ない  (N1): \"Không gì bằng\", cũng diễn tả mức độ cao nhất.","romaji":"","vi":""},{"ja":"～限りだ  (N1): \"Vô cùng\", cũng thường dùng với cảm xúc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('139.  の極み（のきわみ）: Tột cùng; cực kỳ ~', 'N1', 'Dùng để diễn tả trạng thái hoặc cảm xúc đang ở mức độ tột đỉnh, không thể hơn được nữa. Thường dùng cho cả cảm xúc/trạng thái tích cực và tiêu cực, và có thể mang tính khách quan hơn  の至り.', 'N +  の極み', '[{"ja":"贅沢の極みのような生活を送っている。","romaji":"→ Anh ấy đang sống một cuộc sống xa hoa tột cùng.","vi":""},{"ja":"喜びの極みに達した。","romaji":"→ Đã đạt đến niềm vui sướng tột cùng.","vi":""},{"ja":"疲労の極みだった。","romaji":"→ Mệt mỏi tột độ.","vi":"──────────"},{"ja":"極まる  /  極まりない  (N1): Gần nghĩa, nhưng  の極み thường đi với danh từ chỉ trạng thái đã đạt đến đỉnh điểm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('140.  のなんのって: Cực kỳ ~ (không thể diễn tả bằng lời)', 'N1', 'Dùng trong văn nói để diễn tả một cảm xúc hoặc trạng thái ở mức độ rất cao, đến mức khó có thể diễn tả hết bằng lời, mang tính cảm thán mạnh.', 'A い / A かった / Na だった / V た +  のなんのって', '[{"ja":"昨日の試験、難しかったのなんのって、全然できなかったよ。","romaji":"→ Bài thi hôm qua á, khó kinh khủng khiếp, tớ chẳng làm được gì cả.","vi":""},{"ja":"彼女の驚いた顔のなんのって、今でも忘れられない。","romaji":"→ Vẻ mặt ngạc nhiên của cô ấy á, không thể tả nổi, đến giờ tớ vẫn không quên được.","vi":"──────────"},{"ja":"～てたまらない  (N3): \"Không chịu nổi\", diễn tả cảm xúc mạnh không kìm nén được.  のなんのって diễn tả mức độ nói chung.","romaji":"","vi":""},{"ja":"～といったらない  (N1): \"Cực kỳ\", \"hết chỗ nói\", cũng mang tính cảm thán và nhấn mạnh mức độ cao, nhưng có thể hơi trang trọng hơn một chút so vớiのなんのって.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('141.  のやら  /  ものやら  /  ことやら: Tôi tự hỏi...; không chắc; tôi không biết ~', 'N1', 'Dùng để diễn tả sự không chắc chắn, sự nghi ngờ, hoặc sự băn khoăn, lo lắng của người nói về một điều gì đó.', '(Thể thông thường) +  のやら /  ものやら /  ことやら', '[{"ja":"彼は本当に来るのやら。もう約束の時間を過ぎているのに。","romaji":"→ Không biết anh ta có đến thật không nữa. Đã quá giờ hẹn rồi mà.","vi":""},{"ja":"いつになったらこの仕事が終わるものやら。","romaji":"→ Chẳng biết đến bao giờ công việc này mới xong đây.","vi":"──────────"},{"ja":"～かしら  (N4 - nữ giới): \"Tự hỏi là...\", \"có lẽ nào...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('142.  のやら～のやら: Hay là ~ (tôi không biết)', 'N1', 'Dùng để liệt kê hai hoặc nhiều khả năng hoặc tình trạng mà người nói không thể xác định được đâu là thật, hoặc không hiểu rõ nguyên nhân/tình hình, cảm thấy mơ hồ.', '(Thể thông thường) +  のやら + (Thể thông thường) +  のやら ( +  わからない /  区別がつかない)', '[{"ja":"彼は喜んでいるのやら悲しんでいるのやら、表情からは読み取れなかった。","romaji":"→ Không thể đọc được từ biểu cảm của anh ấy là đang vui hay đang buồn.","vi":""},{"ja":"何が原因なのやら、さっぱりわからない。","romaji":"→ Chẳng hiểu nguyên nhân là gì nữa.","vi":"──────────"},{"ja":"～とも～ともつかない  (N1): \"Không thể nói là A hay B\", gần nghĩa, nhấn mạnh sự khó phân định.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('143.  を踏まえて（をふまえて）: Dựa trên; xét đến ~', 'N1', 'Diễn tả việc thực hiện một hành động hoặc đưa ra một quyết định sau khi đã xem xét, cân nhắc, hoặc lấy một sự thật, kinh nghiệm, ý kiến (N) làm cơ sở, làm nền tảng, làm điểm xuất phát.', 'N +  を踏まえて', '[{"ja":"お客様のご意見を踏まえて、サービスを改善いたします。","romaji":"→ Chúng tôi sẽ cải thiện dịch vụ dựa trên ý kiến của quý khách.","vi":""},{"ja":"調査結果を踏まえて、今後の計画を立てる。","romaji":"→ Lập kế hoạch cho tương lai dựa trên kết quả điều tra.","vi":"──────────"},{"ja":"～を参考にして  (N?): \"Tham khảo\", mức độ phụ thuộc thấp hơn.","romaji":"","vi":""},{"ja":"～を考慮して  (N?): \"Xem xét đến\", \"cân nhắc đến\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('144.  を経て（をへて）: Qua; bằng cách; sau; thông qua ~', 'N1', 'Diễn tả việc đi qua một địa điểm, trải qua một khoảng thời gian, hoặc trải qua một quá trình/kinh nghiệm nào đó để đi đến một kết quả hoặc trạng thái mới.', 'N (Thời gian/Địa điểm/Quá trình/Kinh nghiệm) +  を経て', '[{"ja":"長い年月を経て、その技術は完成した。","romaji":"→ Sau khi trải qua một thời gian dài, kỹ thuật đó đã được hoàn thiện.","vi":""},{"ja":"多くの困難を経て、二人は結ばれた。","romaji":"→ Trải qua nhiều khó khăn, hai người đã đến được với nhau.","vi":""},{"ja":"パリを経て、ロンドンへ向かった。","romaji":"→ Đi London qua ngả Paris.","vi":"──────────"},{"ja":"～後で  (N5): \"Sau khi\", chỉ thứ tự thời gian.  を経て thường nhấn mạnh quá trình và sự thay đổi/kết quả sau quá trình đó.","romaji":"","vi":""},{"ja":"～を通じて  /  ～を通して  (N3): \"Thông qua\" (phương tiện, người trung gian, hoặc suốt một khoảng thời gian).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('145.  を控えて（をひかえて）: Sắp đến; đã đến lúc; gần; trước ~', 'N1', 'Diễn tả rằng một sự kiện hoặc thời điểm quan trọng (N) sắp xảy ra, và thường đi kèm với việc chuẩn bị, một trạng thái chờ đợi, hoặc một hành động nào đó trước thềm sự kiện đó.', 'N (Sự kiện/Thời gian quan trọng) +  を控えて', '[{"ja":"試験を控えて、学生たちは緊張している。","romaji":"→ Trước kỳ thi, các học sinh đang rất căng thẳng.","vi":""},{"ja":"結婚式を控えて、準備に追われている。","romaji":"→ Sắp đến đám cưới nên tôi đang bận rộn chuẩn bị.","vi":"──────────"},{"ja":"～間近に  (N?): \"Gần kề\", \"sắp đến\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('146.  をいいことに: Lợi dụng ~', 'N1', 'Diễn tả việc lợi dụng một tình huống hoặc điều kiện thuận lợi nào đó (thường là sự vắng mặt, sự không biết, sự cho phép, hoặc điểm yếu của người khác) để làm một việc không tốt hoặc không nên làm.', '(Thể thông thường) +  の +  をいいことに / N +  をいいことに', '[{"ja":"先生がいないのをいいことに、生徒たちは騒いでいた。","romaji":"→ Lợi dụng lúc giáo viên vắng mặt, học sinh đã làm ầm lên.","vi":""},{"ja":"誰も見ていないのをいいことに、彼はこっそりお菓子を食べた。","romaji":"→ Nhân lúc không ai nhìn, cậu ta đã lén ăn kẹo.","vi":"──────────"},{"ja":"～おかげで  (N4): \"Nhờ vào\" (kết quả tốt).  をいいことに là \"lợi dụng\" (thường dẫn đến kết quả/hành động không tốt cho người khác hoặc cho tình huống chung).","romaji":"","vi":""},{"ja":"～を利用して  (N3): \"Lợi dụng\", \"sử dụng\", có thể trung tính hoặc tiêu cực.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('147.  を顧みず  /  も顧みず（をかえりみず  /  もかえりみず）: Bất chấp; không xét đến; không lo lắng về; bất kể ~', 'N1', 'Diễn tả việc thực hiện một hành động mà không quan tâm, không màng đến những hậu quả, rủi ro, hoặc những điều quan trọng khác (N) có thể bị ảnh hưởng hoặc cần được xem xét.', 'N +  を顧みず /  も顧みず', '[{"ja":"彼は危険を顧みず、子供を助けに火の中に飛び込んだ。","romaji":"→ Anh ấy đã bất chấp nguy hiểm, lao vào đám cháy để cứu đứa trẻ.","vi":""},{"ja":"彼は家庭も顧みず、仕事に没頭した。","romaji":"→ Anh ấy đã không màng đến gia đình, vùi đầu vào công việc.","vi":"──────────"},{"ja":"～をものともせずに  (N1): \"Bất chấp\", thường dùng để ca ngợi sự dũng cảm, nghị lực khi đối mặt với khó khăn.  を顧みず có thể dùng cho cả trường hợp tiêu cực (bỏ bê).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('148.  を限りに（をかぎりに）: Bắt đầu từ; lần cuối cùng (kết thúc một hành động tiếp diễn)', 'N1', 'Diễn tả rằng một hành động hoặc trạng thái đã kéo dài đến N (thời điểm) thì sẽ kết thúc, chấm dứt hoàn toàn tại thời điểm đó.', 'N (Thời gian/Thời điểm cụ thể) +  を限りに', '[{"ja":"今日を限りに、タバコをやめることにした。","romaji":"→ Kể từ hôm nay (hôm nay là ngày cuối), tôi quyết định bỏ thuốc lá.","vi":""},{"ja":"このレストランは今月を限りに閉店するそうだ。","romaji":"→ Nghe nói nhà hàng này sẽ đóng cửa vào cuối tháng này.","vi":"──────────"},{"ja":"～を最後に  (N2): \"Lần cuối là...\", gần nghĩa, cũng chỉ sự chấm dứt.","romaji":"","vi":""},{"ja":"～をもって  (N1): Cũng có thể dùng để chỉ thời điểm kết thúc (ví dụ:  本日を もって終了します), rất trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('149.  を兼ねて（をかねて）: Cũng với mục đích ~', 'N1', 'Diễn tả rằng một hành động được thực hiện không chỉ với một mục đích chính mà còn kết hợp thêm một mục đích khác (N).', 'N +  を兼ねて', '[{"ja":"父の退職祝いを兼ねて、家族旅行に行った。","romaji":"→ Chúng tôi đi du lịch gia đình, đồng thời cũng là để mừng bố nghỉ hưu.","vi":""},{"ja":"気分転換を兼ねて、少し散歩しませんか。","romaji":"→ Chúng ta đi dạo một chút, kiêm luôn thay đổi không khí, được không?","vi":"──────────"},{"ja":"～がてら  (N1): \"Nhân tiện\", thường dùng với hành động phụ khi đang làm hành động chính (thường là di chuyển).","romaji":"","vi":""},{"ja":"～ついでに  (N3): \"Nhân tiện\", phổ biến nhất, chỉ việc làm thêm một hành động phụ khi có cơ hội.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('150.  を皮切りに（をかわきりに）: Bắt đầu với; lần lượt ~', 'N1', 'Diễn tả rằng một sự việc (N) là điểm khởi đầu, sau đó hàng loạt các sự việc tương tự hoặc liên quan khác bắt đầu diễn ra một cách liên tiếp và mạnh mẽ, thường theo một chiều hướng tích cực hoặc sôi động.', 'N +  を皮切りに (して) /  を皮切りとして', '[{"ja":"東京公演を皮切りに、全国ツアーが始まった。","romaji":"→ Bắt đầu từ buổi biểu diễn ở Tokyo, chuyến lưu diễn toàn quốc đã được khởi động.","vi":""},{"ja":"彼の発言を皮切りとして、議論が活発になった。","romaji":"→ Bắt đầu từ phát ngôn của anh ấy, cuộc thảo luận đã trở nên sôi nổi.","vi":"──────────"},{"ja":"～から始まって  (N?): \"Bắt đầu từ\", cách nói thông thường, không nhấn mạnh tính lan tỏa mạnh mẽ như  を皮切りに.","romaji":"","vi":""},{"ja":"～を手始めに  (N?): \"Bắt đầu bằng việc...\", gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('151.  を機に（をきに）: Như một cơ hội/dịp để ~', 'N1', 'Diễn tả rằng một sự kiện hoặc thời điểm nào đó (N/V) trở thành một cơ hội, một cái cớ tốt để bắt đầu hoặc thay đổi một điều gì đó một cách có ý thức.', 'N / V-る/V-た +  の +  を機に', '[{"ja":"入院したのを機に、お酒をやめることにした。","romaji":"→ Nhân dịp nhập viện, tôi quyết định bỏ rượu.","vi":""},{"ja":"会社の創立 10 周年を機に、新しいロゴが作られた。","romaji":"→ Nhân dịp kỷ niệm 10 năm thành lập công ty, logo mới đã được tạo ra.","vi":"──────────"},{"ja":"～際に  (N3): \"Khi\", \"vào dịp\", chỉ thời điểm, không nhất thiết phải là cơ hội để thay đổi.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('152.  を禁じ得ない（をきんじえない）: Không thể không; không thể kìm nén ~', 'N1', 'Diễn tả rằng một cảm xúc mạnh mẽ nào đó (N) trào dâng một cách tự nhiên và không thể kìm nén lại được, dù có muốn.', 'N (Danh từ chỉ cảm xúc) +  を禁じ得ない', '[{"ja":"彼の不幸な身の上話に、涙を禁じ得なかった。","romaji":"→ Nghe câu chuyện bất hạnh của anh ấy, tôi không thể cầm được nước mắt.","vi":""},{"ja":"その理不尽な決定には、怒りを禁じ得ない。","romaji":"→ Trước quyết định vô lý đó, tôi không thể không cảm thấy tức giận.","vi":"──────────"},{"ja":"～ざるを得ない  (N1): \"Buộc phải làm\", chỉ hành động bị bắt buộc.  を禁じ 得ない chỉ cảm xúc không thể kìm nén.","romaji":"","vi":""},{"ja":"思わず～てしまう  (N3): \"Bất giác làm...\", chỉ hành động vô thức do cảm xúc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('153.  をものともせずに: Bất chấp; không thua/sợ/lo lắng về ~', 'N1', 'Diễn tả việc thực hiện một hành động một cách dũng cảm, mạnh mẽ, bất chấp những khó khăn, trở ngại, hoặc điều kiện bất lợi (N), xem nhẹ chúng.', 'N +  をものともせずに', '[{"ja":"彼は周囲の反対をものともせずに、自分の道を突き進んだ。","romaji":"→ Anh ấy đã bất chấp sự phản đối của mọi người, tiến bước trên con đường của mình.","vi":""},{"ja":"嵐をものともせずに、船は進んでいった。","romaji":"→ Bất chấp cơn bão, con thuyền vẫn tiến lên.","vi":"──────────"},{"ja":"～を顧みず  (N1): \"Bất chấp\", nhưng có thể mang cả ý nghĩa tiêu cực (ích kỷ, bỏ bê).  をものともせずに thường mang nghĩa tích cực (dũng cảm, kiên cường).","romaji":"","vi":""},{"ja":"～に負けずに  (N?): \"Không thua...\", \"cố gắng vượt qua...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('154.  をもって  /  をもちまして: Bằng cách; với; vào (thời gian)', 'N1', '1.   Diễn tả phương tiện, cách thức thực hiện hành động (trang trọng). 2.   Diễn tả thời điểm kết thúc một sự kiện hoặc trạng thái (rất trang trọng, thường trong thông báo).', 'N +  をもって /  をもちまして', '[{"ja":"実力をもって、彼を選んだ。","romaji":"→ Chúng tôi đã chọn anh ấy bằng thực lực.","vi":""},{"ja":"本日をもちまして、受付を終了させていただきます。","romaji":"→ Chúng tôi xin phép kết thúc việc tiếp nhận vào ngày hôm nay. (Kể từ hôm nay là kết thúc)","vi":"──────────"},{"ja":"～を限りに  (N1): Chỉ thời điểm kết thúc.  をもって/をもちまして cũng vậy nhưng trang trọng hơn và thường dùng trong thông báo chính thức kết thúc một giai đoạn/sự kiện.","romaji":"","vi":""},{"ja":"～によって  (N3): \"Bằng cách\", \"do\", chỉ phương tiện hoặc nguyên nhân.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('155.  をおいて～ない: Chỉ; chỉ có thể là; không có lựa chọn nào khác, chỉ ~', 'N1', 'Dùng để khẳng định mạnh mẽ rằng ngoài N ra, không có ai/cái gì khác có thể làm được điều đó hoặc phù hợp hơn. Nhấn mạnh tính độc nhất, không thể thay thế của N.', 'N +  をおいて +  他にない /  ほかにない', '[{"ja":"この仕事を任せられるのは、彼をおいて他にいない。","romaji":"→ Người có thể giao phó công việc này, ngoài anh ấy ra thì không còn ai khác.","vi":""},{"ja":"日本一の景色と言えるのは、ここをおいて他にないだろう。","romaji":"→ Nơi có thể nói là cảnh đẹp nhất Nhật Bản, có lẽ ngoài nơi đây ra thì không còn nơi nào khác.","vi":"──────────"},{"ja":"～ならでは  (N1): \"Chỉ có ở...\", \"đặc trưng của...\", nhấn mạnh tính độc đáo.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('156.  を押して  /  を押し切って（をおして  /  をおしきって）: Vượt qua (sự phản đối); vượt qua ~', 'N1', 'Diễn tả việc thực hiện một hành động bất chấp sự phản đối, khó khăn, hoặc điều kiện không thuận lợi (N).  押し切って mang ý nghĩa mạnh mẽ hơn, thể hiện sự quyết tâm "bất chấp đến cùng" để thực hiện.', 'N (Sự phản đối/khó khăn/ngăn cản) +  を押して /  を押し切って', '[{"ja":"彼は家族の反対を押して、留学を決めた。","romaji":"→ Anh ấy đã quyết định đi du học, bất chấp sự phản đối của gia đình.","vi":""},{"ja":"周囲の制止を押し切って、彼は危険な場所に足を踏み入れた。","romaji":"→ Bất chấp sự ngăn cản của mọi người xung quanh, anh ta đã bước chân vào nơi nguy hiểm.","vi":"──────────"},{"ja":"～にもかかわらず  (N3): \"Bất chấp\", cách nói chung hơn, không nhất thiết phải có sự đối đầu.","romaji":"","vi":""},{"ja":"～を顧みず  (N1): \"Bất chấp\", \"không màng đến\", có thể dùng cho cả việc bỏ qua rủi ro hoặc trách nhiệm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('157.  を境に（をさかいに）: Kể từ ~ (chỉ một thay đổi lớn trước & sau)', 'N1', 'Diễn tả rằng một thời điểm hoặc sự kiện (N) là mốc đánh dấu quan trọng, mà kể từ đó, một sự thay đổi lớn và rõ rệt đã xảy ra (so với trước đó).', 'N (Thời điểm/Sự kiện mang tính bước ngoặt) +  を境に (して)', '[{"ja":"オリンピックを境に、その都市は大きく発展した。","romaji":"→ Kể từ Olympic, thành phố đó đã phát triển rất nhiều.","vi":""},{"ja":"退職を境にして、生活リズムが変わった。","romaji":"→ Kể từ khi nghỉ hưu, nhịp sống của tôi đã thay đổi.","vi":"──────────"},{"ja":"～をきっかけに  (N3) /  ～を機に  (N1): \"Nhân cơ hội\", \"do\", chỉ sự kiện khởi đầu cho một hành động/thay đổi.  を境に chỉ mốc thời gian phân chia rõ rệt hai trạng thái.","romaji":"","vi":""},{"ja":"～以来  (N3): \"Kể từ khi\", chỉ một trạng thái tiếp diễn từ một mốc trong quá khứ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('158.  を余儀なくされる（をよぎなくされる）: Bị buộc phải làm gì đó vì không có lựa chọn nào khác', 'N1', 'Diễn tả việc bị đẩy vào tình thế bắt buộc phải làm một điều gì đó (thường là không mong muốn, tiêu cực) do hoàn cảnh bên ngoài, không còn lựa chọn nào khác.', 'N +  を余儀なくされる / V-る +  こと +  を余儀なくされる', '[{"ja":"災害のため、住民たちは避難生活を余儀なくされた。","romaji":"→ Do thảm họa, người dân đã bị buộc phải sống cuộc sống sơ tán.","vi":""},{"ja":"会社が倒産し、多くの社員が職を失うことを余儀なくされた。","romaji":"→ Công ty phá sản, nhiều nhân viên đã bị buộc phải mất việc.","vi":"──────────"},{"ja":"～ざるを得ない  (N1): \"Không thể không...\", \"buộc phải...\", gần nghĩa, cũng diễn tả sự bắt buộc không mong muốn, nhưng  を余儀なくされる thường dùng với danh từ hơn và mang tính bị động mạnh hơn.","romaji":"","vi":""},{"ja":"～しかない  (N4): \"Chỉ còn cách\", cũng thể hiện sự không có lựa chọn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('159.  をよそに: Bất chấp; không quan tâm đến ~', 'N1', 'Diễn tả việc một hành động nào đó diễn ra mà hoàn toàn không để ý, không quan tâm đến những người, ý kiến, hoặc tình hình xung quanh (N), thường là những thứ đáng lẽ phải quan tâm hoặc chịu ảnh hưởng.', 'N +  をよそに', '[{"ja":"住民の心配をよそに、ダムの建設計画が進められている。","romaji":"→ Bất chấp sự lo lắng của người dân, kế hoạch xây dựng đập vẫn đang được tiến hành.","vi":""},{"ja":"親の期待をよそに、彼は大学を中退してしまった。","romaji":"→ Mặc kệ sự kỳ vọng của bố mẹ, anh ta đã bỏ học đại học.","vi":"──────────"},{"ja":"～にもかかわらず  (N3): \"Bất chấp\", cách nói chung hơn.  をよそに thường nhấn mạnh sự thờ ơ với ý kiến/tình cảm của người khác.","romaji":"","vi":""},{"ja":"～を尻目に  (N?): \"Lờ đi\", \"bỏ ngoài mắt\", gần nghĩa, cũng mang ý không quan tâm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('160.  を前提として（をぜんていとして）: Với ý định; với điều kiện / giả định ~', 'N1', 'Diễn tả rằng một hành động hoặc kế hoạch nào đó được thực hiện dựa trên một điều kiện hoặc giả định (N/Mệnh đề) được đặt ra trước đó và được coi là nền tảng.', 'N / (Mệnh đề thể thông thường +  こと) +  を前提として /  を前提に ( して)', '[{"ja":"来年結婚することを前提として、家を探している。","romaji":"→ Tôi đang tìm nhà với giả định là sẽ kết hôn vào năm sau.","vi":""},{"ja":"この計画は、予算が確保されることを前提に立てられている。","romaji":"→ Kế hoạch này được lập ra với tiền đề là ngân sách sẽ được đảm bảo.","vi":"──────────"},{"ja":"～ものとして  (N1): \"Coi như là\", \"giả định là\", cũng dựa trên giả định, nhưng  を前提として thường dùng cho các kế hoạch, thảo luận có tính hệ thống hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('161.  思いをする（おもいをする）: Nghĩ; cảm thấy ~', 'N1', 'Dùng để diễn tả việc trải qua, nếm trải một cảm giác, một suy nghĩ, hoặc một trải nghiệm nào đó (thường là không dễ chịu, khó chịu, hoặc đáng nhớ).', '(Tính từ đuôi  い / Tính từ đuôi  な +  な / Trạng thái) +  思いをする', '[{"ja":"戦争で、多くの人が辛い思いをした。","romaji":"→ Trong chiến tranh, nhiều người đã trải qua những cảm giác đau khổ.","vi":""},{"ja":"人前で転んで、恥ずかしい思いをした。","romaji":"→ Tôi đã bị ngã trước mặt mọi người và cảm thấy rất xấu hổ.","vi":""},{"ja":"あんな素敵なレストランで食事できて、いい思いをした。","romaji":"→ Được ăn ở một nhà hàng tuyệt vời như vậy, tôi đã có một trải nghiệm thật tốt.","vi":"──────────"},{"ja":"～経験をする  (N4): \"Trải qua kinh nghiệm\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('162.  折に（おりに）: Khi; vào lúc; vào dịp ~', 'N1', 'Dùng để chỉ một thời điểm hoặc một dịp đặc biệt nào đó, thường là một cơ hội tốt hoặc một thời điểm thích hợp.', 'N +  の +  折に / V-る/V-た +  折に', '[{"ja":"次回お会いした折に、詳しくお話しします。","romaji":"→ Vào dịp gặp gỡ lần tới, tôi sẽ nói chuyện chi tiết hơn.","vi":""},{"ja":"来日の折には、ぜひ我が家にお立ち寄りください。","romaji":"→ Nhân dịp ngài đến Nhật, xin nhất định hãy ghé qua nhà tôi.","vi":"──────────"},{"ja":"～際  (N3): \"Khi\", cũng trang trọng, thường dùng trong hướng dẫn, thông báo chính thức, không nhất thiết phải là dịp tốt.","romaji":"","vi":""},{"ja":"～機会に  (N3): \"Nhân cơ hội\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('163.  およそ: Khoảng; gần như; nói chung; xấp xỉ; hoàn toàn ~', 'N1', '1.   Dùng để chỉ số lượng xấp xỉ, khoảng chừng. 2.   Dùng để chỉ sự khái quát, nói chung, đại khái. 3.   Khi đi với phủ định (およそ～ない), có nghĩa là "hoàn toàn không", "không chút nào".', 'およそ + (Số lượng) /  およそ + N /  およそ +  ～ない', '[{"ja":"会場にはおよそ千人の人が集まった。","romaji":"→ Tại hội trường có khoảng 1000 người tập trung.","vi":""},{"ja":"およその見当はついている。","romaji":"→ Tôi đã nắm được đại khái tình hình.","vi":""},{"ja":"それは私にはおよそ関係のないことだ。","romaji":"→ Chuyện đó hoàn toàn không liên quan đến tôi.","vi":"──────────"},{"ja":"大体  (N4): \"Đại khái\", \"nói chung\".","romaji":"","vi":""},{"ja":"全然  /  全く  (N5/N4): \"Hoàn toàn\" (khi đi với phủ định), phổ biến hơn.  およ そ～ない trang trọng hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('164.  さ: Hậu tố cuối câu; biểu thị sự khẳng định', 'N1', 'Dùng ở cuối câu, chủ yếu trong văn nói thân mật, thường do nam giới sử dụng, để khẳng định nhẹ nhàng ý kiến của mình, bày tỏ sự chắc chắn, hoặc để thu hút sự chú ý, đồng tình của người nghe một cách thân mật.', '(Mệnh đề) +  さ', '[{"ja":"そんなこと、当たり前ださ。","romaji":"→ Chuyện đó là đương nhiên rồi mà.","vi":""},{"ja":"大丈夫だよ、心配するなさ。","romaji":"→ Không sao đâu, đừng lo lắng mà.","vi":"──────────"},{"ja":"～ぜ  /  ～ぞ  (N1): Cũng là hậu tố cuối câu nam tính, nhưng thường mạnh mẽ hơn, mang tính rủ rê, mệnh lệnh hoặc cảnh báo.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('165.  さも: Thực sự (có vẻ, v.v.); quả thực; như thể ~', 'N1', 'Dùng để nhấn mạnh rằng một hành động hoặc trạng thái trông thực sự hoặc rất giống như đang có một cảm xúc hoặc tình trạng nào đó, hoặc được thực hiện một cách ra vẻ như vậy, mặc dù thực tế có thể không phải vậy.', 'さも + A-そうに / A-げに /  ～かのように / (Trạng từ chỉ cảm xúc)', '[{"ja":"彼はさも嬉しそうにプレゼントを受け取った。","romaji":"→ Anh ấy nhận quà với vẻ mặt trông rất vui.","vi":""},{"ja":"彼女はさも自分が被害者であるかのように話した。","romaji":"→ Cô ta nói chuyện cứ như thể mình là người bị hại vậy.","vi":"──────────"},{"ja":"まるで～ようだ  (N3): \"Cứ như là\", dùng để ví von.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('166.  さもないと: Nếu không thì; hoặc là; nếu không ~', 'N1', 'Dùng để cảnh báo rằng nếu không làm theo điều được nói ở vế trước (hoặc nếu tình trạng đó không thay đổi), thì một kết quả xấu, không mong muốn sẽ xảy ra.', '(Mệnh đề chỉ thị/yêu cầu/điều kiện) +  さもないと + (Kết quả xấu)', '[{"ja":"早く起きなさい。さもないと、学校に遅刻するよ。","romaji":"→ Dậy nhanh lên. Nếu không thì sẽ muộn học đấy.","vi":""},{"ja":"もっと勉強しなさい。さもないと、試験に落ちるぞ。","romaji":"→ Học hành chăm chỉ hơn đi. Nếu không thì sẽ trượt kỳ thi đấy.","vi":"──────────"},{"ja":"そうしないと  (N?): \"Nếu không làm thế thì\", gần nghĩa.","romaji":"","vi":""},{"ja":"もし～なければ  (N4): \"Nếu không...\", nhấn mạnh điều kiện giả định.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('167.  さぞ: Chắc chắn; nhất định; không nghi ngờ gì; quả thực ~', 'N1', 'Dùng để thể hiện sự suy đoán, đồng cảm mạnh mẽ của người nói về cảm xúc hoặc tình trạng của người khác (thường là người không có mặt hoặc không thể trực tiếp biết được), cho rằng điều đó chắc chắn là như vậy, dựa trên tình huống.', 'さぞ（かし） +  ～だろう /  ～でしょう /  ～ことだろう /  ～と推察します', '[{"ja":"慣れない土地での生活は、さぞ大変だろう。","romaji":"→ Cuộc sống ở một vùng đất xa lạ chắc hẳn là vất vả lắm.","vi":""},{"ja":"合格の知らせを聞いて、ご両親はさぞかしお喜びでしょう。","romaji":"→ Nghe tin đỗ, chắc hẳn bố mẹ bạn vui lắm.","vi":"──────────"},{"ja":"～に違いない  (N3): \"Chắc chắn là\", dựa trên bằng chứng hoặc suy luận logic mạnh.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('168.  始末だ（しまつだ）: Cuối cùng; rốt cuộc; kết quả là (tiêu cực)', 'N1', 'Dùng để chỉ một kết quả xấu, một tình trạng tồi tệ không mong muốn xảy ra sau một loạt các sự kiện hoặc hành động không tốt trước đó.', '(Mệnh đề chỉ quá trình dẫn đến kết quả xấu) +  この /  その /  あの +  始 末だ', '[{"ja":"彼は毎日遅刻ばかりして、とうとう会社をクビになる始末だ。","romaji":"→ Anh ta ngày nào cũng đi muộn, rốt cuộc đã bị công ty đuổi việc.","vi":""},{"ja":"ギャンブルに手を出して、借金まみれの始末だ。","romaji":"→ Dính vào cờ bạc, kết cục là ngập trong nợ nần.","vi":"──────────"},{"ja":"羽目になる  (N1): \"Rơi vào tình thế (khó xử)\", gần nghĩa, cũng chỉ kết quả xấu, nhưng  始末だ thường nhấn mạnh kết quả cuối cùng sau một quá trình tiêu cực kéo dài.","romaji":"","vi":""},{"ja":"～あげく  (N2): \"Sau một hồi... cuối cùng thì (kết quả xấu)\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('169.  そばから: Ngay sau khi ~', 'N1', 'Diễn tả rằng một hành động (vế sau) xảy ra ngay lập tức sau khi một hành động khác (vế trước) vừa kết thúc, và điều này thường lặp đi lặp lại nhiều lần, mang ý nghĩa không có tác dụng, làm không xuể, hoặc gây khó chịu.', 'V-る / V-た +  そばから', '[{"ja":"子供は掃除したそばから、おもちゃを散らかす。","romaji":"→ Bọn trẻ vừa mới dọn dẹp xong lại bày đồ chơi ra.","vi":""},{"ja":"教えたそばから忘れてしまうので、困っている。","romaji":"→ Vì cứ vừa dạy xong là lại quên ngay nên tôi rất khổ sở.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('170.  そびれる: Bỏ lỡ cơ hội; không làm được ~', 'N1', 'Diễn tả việc bỏ lỡ cơ hội làm một hành động nào đó, hoặc muốn làm nhưng cuối cùng lại không làm được do thời điểm không phù hợp, có sự cản trở, hoặc do chần chừ.', 'V-ます (bỏ  ます) +  そびれる', '[{"ja":"買おうと思っていたのに、話しているうちに買いそびれてしまった。 - Tôi đã định mua, nhưng trong lúc nói chuyện lại lỡ mất cơ hội mua.","romaji":"","vi":""},{"ja":"彼に言いそびれたことがある。","romaji":"→ Có một điều tôi đã lỡ mất cơ hội nói với anh ấy.","vi":"──────────"},{"ja":"～機会を失う  (N?): \"Mất cơ hội\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('171.  損なう  /  損ねる  /  損じる（そこなう  /  そこねる  /  そんじる）: Làm sai; do nhầm lẫn; bỏ lỡ cơ hội; không làm được ~ / Làm tổn hại', 'N1', '1.   Diễn tả việc suýt nữa thì làm được, hoặc có ý định làm nhưng cuối cùng lại không thành công, bỏ lỡ cơ hội. 2.   Diễn tả việc làm tổn hại đến cái gì đó (sức khỏe, tâm trạng, giá trị...).', '1.   V-ます (bỏ  ます) +  損なう /  損ねる /  損じる (Nghĩa: Bỏ lỡ cơ hội, làm không thành) 2.   N +  を +  損なう /  損ねる /  損じる (Nghĩa: Làm tổn hại, làm hỏng)', '[{"ja":"あと少しで捕まえられたのに、逃げ損ねた。","romaji":"→ Chỉ còn chút nữa là bắt được rồi, vậy mà lại để lỡ mất. (Nghĩa 1)","vi":""},{"ja":"彼は言い損ねて、彼女を怒らせてしまった。","romaji":"→ Anh ta lỡ lời (nói sai) và làm cô ấy tức giận. (Nghĩa 1)","vi":""},{"ja":"過労は健康を損なう恐れがある。","romaji":"→ Làm việc quá sức có nguy cơ làm tổn hại sức khỏe. (Nghĩa 2)","vi":"──────────"},{"ja":"～を害する（がいする）(N?): \"Gây hại cho\" (Nghĩa 2).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('172.  術がない（すべがない）: Không có cách nào; không thể làm ~', 'N1', 'Diễn tả rằng hoàn toàn không có phương pháp, cách thức, hoặc phương tiện nào để thực hiện một hành động, không còn cách nào khác.', 'V-る +  術がない', '[{"ja":"彼に連絡を取りたいのだが、電話番号も住所も知らず、連絡する術がない。","romaji":"→ Tôi muốn liên lạc với anh ấy, nhưng không biết số điện thoại hay địa chỉ, nên không có cách nào liên lạc được.","vi":""},{"ja":"こうなっては、もはや施す術がない。","romaji":"→ Đã đến nước này thì hết cách cứu chữa rồi.","vi":"──────────"},{"ja":"～ようがない  (N2): \"Không có cách nào\", gần nghĩa, cũng thể hiện sự không thể làm được do thiếu phương tiện/cách thức.","romaji":"","vi":""},{"ja":"どうしようもない  (N3): \"Không còn cách nào khác\", \"bó tay\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('173.  すら  /  ですら: Ngay cả ~ (nhấn mạnh)', 'N1', 'Dùng để đưa ra một ví dụ cực đoan (N) để nhấn mạnh rằng nếu ngay cả N (vốn dễ/hiển nhiên/cơ bản/quan trọng) mà còn như vậy, thì những thứ khác càng không cần phải bàn đến.', 'N +  すら /  ですら', '[{"ja":"彼は自分の名前すら書けない。","romaji":"→ Cậu ta đến cả tên mình cũng không viết được.","vi":""},{"ja":"子供ですら知っていることを、大人が知らないなんて恥ずかしい。","romaji":"→ Chuyện mà ngay cả trẻ con cũng biết, người lớn lại không biết thì thật xấu hổ.","vi":"──────────"},{"ja":"～だに  (N1): \"Ngay cả\", cổ hơn và thường dùng với các từ hạn chế (tưởng tượng, nghe...).","romaji":"","vi":""},{"ja":"～でさえ  (N?): Dạng nhấn mạnh của  さえ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('174.  た弾みに  /  た拍子に（たはずみに  /  たひょうしに）: Khoảnh khắc [A], vô tình / không cố ý gây ra điều gì đó', 'N1', 'Diễn tả rằng ngay tại khoảnh khắc thực hiện hành động V-た, một hành động khác (thường là bất ngờ, không cố ý, ngoài dự kiến) đã xảy ra do tác động hoặc sự tình cờ của hành động V-た.', 'V-た +  弾みに /  拍子に', '[{"ja":"くしゃみをした拍子に、腰が痛くなった。","romaji":"→ Đúng lúc hắt hơi thì tôi bị đau lưng.","vi":""},{"ja":"ドアを開けた弾みに、壁に頭をぶつけてしまった。","romaji":"→ Ngay khi mở cửa, tôi đã vô tình đập đầu vào tường.","vi":"──────────"},{"ja":"～途端に  (N3): Gần như đồng nghĩa với  ～たとたんに.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('175.  たことにする  /  たことになる: Giả vờ; xem như không đúng sự thật; trái với sự thật ~', 'N1', 'ことにする: Diễn tả việc tự mình quyết định xem như hoặc giả vờ như một việc gì đó đã xảy ra (dù thực tế không phải vậy hoặc khác đi).   ことになる: Diễn tả rằng một việc gì đó được xem như hoặc bị coi như đã xảy ra theo quy định, thỏa thuận, hoặc tình thế (dù thực tế không phải vậy hoặc khác đi).', 'V-た +  ことにする /  ことになる', '[{"ja":"聞かなかったことにしよう。","romaji":"→ Hãy coi như là chưa nghe thấy gì đi.","vi":""},{"ja":"遅刻したが、見逃してもらって、来なかったことになった。","romaji":"→ Tuy đi muộn nhưng được bỏ qua nên bị coi như là đã không đến.","vi":""},{"ja":"この話は、聞かなかったことにしてください。","romaji":"→ Chuyện này, xin hãy coi như anh chưa từng nghe thấy.","vi":"──────────"},{"ja":"～とみなす  (N?): \"Coi như là\", \"xem như là\", thường dùng trong các văn bản pháp lý, quy định.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('176.  たところで: Ngay cả khi; dù (ai, cái gì, khi nào, ở đâu, tại sao, như thế nào)', 'N1', 'Diễn tả rằng dù có thực hiện hành động V đi nữa thì kết quả cũng sẽ không như mong đợi, không có ý nghĩa, hoặc vô ích. Thường đi kèm với vế sau mang ý phủ định hoặc tiêu cực, thể hiện sự vô ích.', 'V-た +  ところで', '[{"ja":"今から急いだところで、もう間に合わないだろう。","romaji":"→ Dù bây giờ có vội đi nữa thì chắc cũng không kịp.","vi":""},{"ja":"何度謝ったところで、許してもらえないかもしれない。","romaji":"→ Dù có xin lỗi bao nhiêu lần thì có lẽ cũng không được tha thứ.","vi":"──────────"},{"ja":"～にしたところで  (N1): Gần nghĩa, nhưng thường dùng để nói về lập trường hoặc giả định.","romaji":"","vi":""},{"ja":"～たって  (N4 - văn nói của  ても): Gần nghĩa với  ても.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('177.  たつもりはない: Không có ý định / không có ý ~', 'N1', 'Dùng để phủ nhận rằng mình đã có ý định làm một việc gì đó, thường là để biện minh hoặc phủ nhận trách nhiệm về một hành động đã làm (hoặc bị cho là đã làm) mà gây ra hiểu lầm hoặc kết quả không tốt.', 'V-た +  つもりはない', '[{"ja":"君を傷つけるつもりはなかったんだ。信じてほしい。","romaji":"→ Tôi không hề có ý làm tổn thương cậu. Xin hãy tin tôi.","vi":""},{"ja":"嘘をついたつもりはないが、誤解を招いたかもしれない。","romaji":"→ Tôi không có ý nói dối, nhưng có lẽ đã gây ra hiểu lầm.","vi":"──────────"},{"ja":"～V る気はなかった  (N?): \"Đã không có ý định...\", gần nghĩa.","romaji":"","vi":""},{"ja":"悪気はなかった  (N?): \"Không có ác ý\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('178.  ただ～のみだ: Tất cả những gì có thể làm là; không thể làm gì khác ngoài; chỉ ~', 'N1', 'Dùng để nhấn mạnh rằng chỉ có một hành động hoặc một điều duy nhất có thể làm hoặc tồn tại, không còn lựa chọn nào khác, hoặc đó là điều duy nhất quan trọng.', 'ただ + V-る / N +  のみだ /  のみならず (のみならず = không chỉ)', '[{"ja":"今はただ祈るのみだ。","romaji":"→ Bây giờ chỉ còn cách cầu nguyện mà thôi.","vi":""},{"ja":"私たちはただ彼の回復を待つのみだった。","romaji":"→ Chúng tôi lúc đó chỉ biết chờ đợi sự hồi phục của anh ấy mà thôi.","vi":"──────────"},{"ja":"～しかない  (N4): \"Chỉ còn cách\", gần nghĩa, cũng thể hiện sự không có lựa chọn khác, nhưng  のみだ có phần trang trọng và văn viết hơn, đôi khi mang tính quyết tâm hơn.","romaji":"","vi":""},{"ja":"～ばかりだ  (N3): \"Toàn là\", \"chỉ...\" (nhưng thường mang ý xu hướng hoặc lặp lại).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('179.  ためしがない: Chưa bao giờ có; chưa bao giờ xảy ra; tôi chưa bao giờ thấy hoặc nghe ~', 'N1', 'Dùng để nhấn mạnh rằng một sự việc nào đó chưa từng xảy ra dù chỉ một lần trong kinh nghiệm của người nói, hoặc với một đối tượng nào đó.', 'V-た +  ためしがない', '[{"ja":"彼は約束を守ったためしがない。","romaji":"→ Anh ta chưa từng giữ lời hứa lần nào.","vi":""},{"ja":"宝くじに当たったためしがない。","romaji":"→ Tôi chưa bao giờ trúng xổ số.","vi":"──────────"},{"ja":"～経験がない  (N4): \"Không có kinh nghiệm...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('180.  たら最後  /  たが最後（たらさいご  /  たがさいご）: Nếu bạn làm... (kết quả tiêu cực)', 'N1', 'Dùng để diễn tả rằng nếu một hành động nào đó xảy ra, thì chắc chắn sẽ dẫn đến một kết quả rất xấu, không thể cứu vãn hoặc thay đổi được nữa. Mang tính cảnh báo hoặc kinh nghiệm tiêu cực.', 'V-たら / V-たが +  最後', '[{"ja":"あの人に秘密を話したら最後、すぐにみんなに知られてしまう。","romaji":"→ Một khi đã nói bí mật cho người đó thì ngay lập tức mọi người sẽ biết hết.","vi":""},{"ja":"彼にお金を貸したが最後、絶対に戻ってこないだろう。","romaji":"→ Một khi đã cho anh ta vay tiền thì chắc chắn sẽ không bao giờ đòi lại được.","vi":"──────────"},{"ja":"～ばそれまでだ  (N1): \"Nếu... thì hết\", nhấn mạnh sự vô ích.  たら最後 nhấn mạnh hậu quả xấu không thể tránh.","romaji":"","vi":""},{"ja":"一度～したら、もう～  (N?): \"Một khi đã làm... thì không thể... nữa\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('181.  たら～たで: Nếu / trong trường hợp... thì tất nhiên / nên ~', 'N1', 'Diễn tả rằng dù tình huống có như thế nào (dù có xảy ra hay không, dù tốt hay xấu), thì cũng sẽ có những vấn đề, khó khăn hoặc cách giải quyết tương ứng với tình huống đó. "Mặt nào cũng có vấn đề của nó".', 'V-たら + V-た +  で / A-かったら + A-かった +  で / Na-だったら + Na-だった +  で', '[{"ja":"家は広かったら広かったで、掃除が大変だ。","romaji":"→ Nhà mà rộng thì cũng có cái khổ của nhà rộng, đó là dọn dẹp vất vả.","vi":""},{"ja":"お金がなかったらなかったで、何とかなるものだ。","romaji":"→ Tiền mà không có thì cũng có cách xoay xở của lúc không có tiền.","vi":"──────────"},{"ja":"それはそれで  (N?): \"Cái đó thì cũng có cái hay/dở của nó\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('182.  たら～ところだ: Nếu... (điều kiện phản thực), thì sẽ là ~', 'N1', 'Dùng để diễn tả một điều kiện giả định trái với sự thật trong quá khứ. Nếu điều kiện đó xảy ra, thì một kết quả khác (thường là tốt hơn hoặc tránh được điều xấu) đã xảy ra.', 'V-たら + (Mệnh đề chỉ kết quả) +  ところだ /  ところだった', '[{"ja":"もし飛行機に乗り遅れていなかったら、今頃はハワイにいるところだ 。","romaji":"→ Nếu mà không bị lỡ chuyến bay thì giờ này đã đang ở Hawaii rồi.","vi":""},{"ja":"もう少し注意していたら、事故は防げたところだった。","romaji":"→ Nếu mà chú ý hơn một chút thì tai nạn đã có thể phòng tránh được rồi.","vi":"──────────"},{"ja":"～ばよかった  (N4): \"Giá mà... thì tốt rồi\", thể hiện sự hối tiếc.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('183.  たりとも: Ngay cả; không một ~', 'N1', 'Dùng để nhấn mạnh sự phủ định hoàn toàn, rằng ngay cả một đơn vị nhỏ nhất cũng không được phép hoặc không xảy ra.', '(Số đếm nhỏ, thường là 1) +  助数詞 (từ chỉ đơn vị) +  たりとも +  ～ない', '[{"ja":"試験中は、一瞬たりとも気を抜いてはいけない。","romaji":"→ Trong lúc thi, không được lơ là dù chỉ một khoảnh khắc.","vi":""},{"ja":"一円たりとも無駄にはできない。","romaji":"→ Không thể lãng phí dù chỉ một yên.","vi":"──────────"},{"ja":"～すら  /  ～さえ  (N1/N3): \"Ngay cả\", nhưng  たりとも thường đi với số đếm và đơn vị cụ thể, mang tính tuyệt đối hơn trong phạm vi đó.","romaji":"","vi":""},{"ja":"微塵も～ない  (N?): \"Không một chút nào\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('184.  たるもの  /  たる: (Những) người là; (cái) là; với tư cách là ... nên ~', 'N1', 'Dùng để nhấn mạnh rằng một người hoặc vật, với tư cách hoặc địa vị N, thì đương nhiên phải có những phẩm chất, trách nhiệm, hoặc hành động tương xứng với địa vị đó.', 'N +  たる + N / N +  たるもの (は)', '[{"ja":"教師たるもの、学生の模範となるべきだ。","romaji":"→ Người là giáo viên thì phải là tấm gương cho học sinh.","vi":""},{"ja":"指導者たる者は、常に冷静でなければならない。","romaji":"→ Người là lãnh đạo thì phải luôn bình tĩnh.","vi":"──────────"},{"ja":"～ともあろうものが  (N1): \"Người như... mà lại...\", dùng để phê phán khi người có địa vị không hành xử đúng mực.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('185.  て敵わない（てかなわない）: Không thể chịu được; không thể; phiền phức; không thể chịu đựng ~', 'N1', 'Dùng để diễn tả sự khó chịu, phiền phức, hoặc không thể chịu đựng được một tình trạng hoặc cảm giác nào đó đến mức quá sức chịu đựng.', 'A-くて +  敵わない / Na で +  敵わない / V-て +  敵わない', '[{"ja":"今日の暑さには敵わない。","romaji":"→ Cái nóng hôm nay thật không chịu nổi.","vi":""},{"ja":"隣の工事の音がうるさくて敵わない。","romaji":"→ Tiếng công trình bên cạnh ồn ào không chịu được.","vi":""},{"ja":"毎日こう雨が降っては敵わない。","romaji":"→ Ngày nào cũng mưa thế này thì không chịu nổi.","vi":"──────────"},{"ja":"～てしょうがない  /  ～て仕方がない  (N3): \"Không chịu nổi\", \"không còn cách nào khác\", gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('186.  てからというもの: Kể từ khi ~', 'N1', 'Dùng để nhấn mạnh một mốc thời gian (V-て), và kể từ đó, một trạng thái hoặc hành động mới (thường là có sự thay đổi lớn so với trước) bắt đầu và kéo dài liên tục.', 'V-て +  からというもの', '[{"ja":"子供が生まれてからというもの、生活が一変した。","romaji":"→ Kể từ khi đứa con ra đời, cuộc sống của tôi đã thay đổi hoàn toàn.","vi":""},{"ja":"日本に来てからというもの、毎日が勉強だ。","romaji":"→ Kể từ khi đến Nhật, ngày nào cũng là học tập (và trạng thái đó vẫn tiếp diễn).","vi":"──────────"},{"ja":"～以来  (N3): \"Kể từ khi\", cũng chỉ một trạng thái tiếp diễn từ một mốc trong quá khứ, nhưng  てからというもの thường nhấn mạnh hơn sự thay đổi rõ rệt.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('187.  てみせる: Tôi sẽ cố hết sức; tôi chắc chắn sẽ làm; tôi sẽ cho bạn thấy ~', 'N1', 'Dùng để thể hiện ý chí, quyết tâm mạnh mẽ của người nói rằng mình nhất định sẽ làm một việc gì đó (thường là để chứng tỏ khả năng, để cho người khác thấy, hoặc để đạt được mục tiêu).', 'V-て +  みせる', '[{"ja":"今度こそ、必ず成功してみせる。","romaji":"→ Lần này, tôi nhất định sẽ thành công cho mà xem.","vi":""},{"ja":"どんな困難があっても、乗り越えてみせる。","romaji":"→ Dù có khó khăn nào, tôi cũng sẽ vượt qua cho bạn thấy.","vi":"──────────"},{"ja":"絶対～する  (N5): \"Nhất định sẽ làm\",  てみせる có thêm sắc thái \"làm cho người khác thấy\", \"chứng tỏ\".","romaji":"","vi":""},{"ja":"～てやる  (N? - suồng sã): \"Làm cho xem\" (có thể mang tính thách thức hoặc thể hiện sự trên cơ).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('188.  てしかるべきだ: Nên; thích hợp; làm ~ là điều tự nhiên', 'N1', 'Dùng để diễn tả rằng một hành động hoặc trạng thái nào đó là điều đương nhiên, hợp lý, hoặc phù hợp theo lẽ thường, đạo lý, hoặc quy tắc xã hội.', 'V-て +  しかるべきだ', '[{"ja":"悪いことをしたのだから、謝ってしかるべきだ。","romaji":"→ Vì đã làm điều xấu nên việc xin lỗi là đương nhiên.","vi":""},{"ja":"彼は長年の功績により、表彰されてしかるべきだ。","romaji":"→ Nhờ công lao nhiều năm, anh ấy đáng lẽ phải được tuyên dương.","vi":"──────────"},{"ja":"～のは当然だ  (N4): \"Là đương nhiên\", gần nghĩa, nhưng  てしかるべきだ thường gắn với một hành động cụ thể \"nên được thực hiện\".","romaji":"","vi":""},{"ja":"当たり前だ  (N4): \"Là đương nhiên\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('189.  て済むことではない（てすむことではない）: ~ không đủ để giải quyết vấn đề; không thể giải quyết bằng ~', 'N1', 'Dùng để nhấn mạnh rằng một vấn đề không thể được giải quyết hoặc bỏ qua chỉ bằng một hành động đơn giản (V-て); vấn đề nghiêm trọng hơn nhiều.', 'V-て +  済むことではない', '[{"ja":"人の命に関わる問題だから、謝って済むことではない。","romaji":"→ Vì là vấn đề liên quan đến mạng người nên không phải chỉ xin lỗi là xong đâu.","vi":""},{"ja":"ちょっと注意して済むことではない。根本的な対策が必要だ。","romaji":"→ Không phải chỉ chú ý một chút là xong. Cần có biện pháp căn cơ.","vi":"──────────"},{"ja":"～だけでは不十分だ  (N?): \"Chỉ... thì không đủ\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('190.  てやまない: Luôn luôn; không ngừng; không thể không ~', 'N1', 'Dùng để diễn tả một cảm xúc hoặc mong muốn mạnh mẽ, sâu sắc, luôn tồn tại trong lòng người nói và không ngừng nghỉ, không phai nhạt.', 'V-て +  やまない', '[{"ja":"卒業生の皆さんのご活躍を願ってやまない。","romaji":"→ Tôi luôn hết lòng mong mỏi sự thành công của các em sinh viên tốt nghiệp.","vi":""},{"ja":"故郷の発展を祈ってやまない。","romaji":"→ Tôi không ngừng cầu nguyện cho sự phát triển của quê hương.","vi":"──────────"},{"ja":"心から～  (N3): \"Từ tận đáy lòng...\", cũng thể hiện sự chân thành.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('191.  手前（てまえ）: Xét đến; trước; trước mặt; quan điểm của ai đó', 'N1', 'Dùng để diễn tả rằng vì phải giữ thể diện, giữ lời hứa, hoặc vì đang ở một vị trí/hoàn cảnh nhất định (xét đến N/V), nên buộc phải làm một việc gì đó (thường là không muốn) hoặc không thể làm một việc gì đó.', 'N +  の +  手前 / V-る/V-た +  手前', '[{"ja":"みんなの前で「やります」と言った手前、今さらやめるわけにはいかない。","romaji":"→ Vì đã nói \"sẽ làm\" trước mặt mọi người nên giờ không thể bỏ được.","vi":""},{"ja":"親の手前、そんな格好で外には出られない。","romaji":"→ Xét đến (thể diện) bố mẹ, tôi không thể ra ngoài với bộ dạng đó được.","vi":"──────────"},{"ja":"～以上は  (N2): \"Một khi đã... thì...\", gần nghĩa với  からには.","romaji":"","vi":""},{"ja":"立場上  (N?): \"Xét về lập trường/vị trí\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('192.  てもどうにもならない: Vô ích; không thể làm gì được', 'N1', 'Dùng để nhấn mạnh rằng dù có làm hành động V đi nữa thì cũng vô ích, không thể thay đổi được tình hình, không giải quyết được vấn đề.', 'V-て +  もどうにもならない', '[{"ja":"今さら後悔してもどうにもならない。","romaji":"→ Bây giờ dù có hối hận cũng chẳng làm được gì.","vi":""},{"ja":"終わってしまったことを、いくら考えてもどうにもならない。","romaji":"→ Chuyện đã kết thúc rồi, dù có nghĩ bao nhiêu cũng vô ích.","vi":"──────────"},{"ja":"どうにも～ない  (N1): \"Không tài nào...\", nhấn mạnh sự không thể.  てもど うにもならない nhấn mạnh sự vô ích của hành động V.","romaji":"","vi":""},{"ja":"～たところで  (N1): \"Dù có... thì cũng (vô ích)\", gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('193.  ても差し支えない（てもさしつかえない）: Có thể ~; không sao nếu ~ (chỉ sự cho phép hoặc thỏa hiệp)', 'N1', 'Dùng để diễn tả sự cho phép hoặc đồng ý rằng một hành động nào đó có thể được thực hiện mà không gây ra vấn đề, cản trở, hoặc phiền hà gì.', 'V-て +  も差し支えない', '[{"ja":"お荷物はここにおいていただいても差し支えありません。","romaji":"→ Hành lý thì anh/chị để ở đây cũng không sao ạ.","vi":""},{"ja":"明日提出しても差し支えなければ、そうさせていただけますか。","romaji":"→ Nếu ngày mai nộp cũng không sao thì xin cho phép tôi làm vậy được không ạ?","vi":"──────────"},{"ja":"～ても構わない  (N3): \"Cũng không sao\", gần nghĩa, nhưng  差し支えない thường nhấn mạnh hơn vào việc \"không gây cản trở\" cho một quy trình hoặc người khác.","romaji":"","vi":""},{"ja":"～ても問題ない  (N?): \"Cũng không có vấn đề gì\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('194.  ても知らない（てもしらない）: Nếu (bạn) tiếp tục... bạn sẽ kết thúc / tôi không quan tâm', 'N1', 'Dùng để cảnh báo mạnh mẽ rằng nếu người nghe cứ tiếp tục làm một hành động nào đó (thường là không tốt hoặc nguy hiểm), thì dù có xảy ra hậu quả xấu, người nói cũng sẽ không chịu trách nhiệm hoặc không quan tâm.', 'V-て +  も知らない', '[{"ja":"そんなことをしても知らないからね。","romaji":"→ Cứ làm chuyện đó đi rồi đừng có trách tôi đấy.","vi":""},{"ja":"約束を破ったら、もう口をきいても知らないぞ。","romaji":"→ Nếu mà thất hứa thì tôi mặc kệ, không thèm nói chuyện nữa đâu.","vi":"──────────"},{"ja":"勝手にしろ  (N? - suồng sã): \"Muốn làm gì thì làm\", thể hiện sự mặc kệ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('195.  と相まって（とあいまって）: Cùng với..., hơn nữa; do ảnh hưởng của..., hơn nữa ~', 'N1', 'Diễn tả rằng hai hoặc nhiều yếu tố (N và yếu tố ở vế sau, hoặc hai N) kết hợp lại với nhau, ảnh hưởng lẫn nhau, tạo ra một kết quả hoặc hiệu ứng còn lớn hơn, mạnh hơn, hoặc rõ rệt hơn.', 'N +  と相まって、～', '[{"ja":"彼女の才能は、努力と相まって、見事に花開いた。","romaji":"→ Tài năng của cô ấy, cùng với sự nỗ lực, đã nở rộ một cách tuyệt vời.","vi":""},{"ja":"好天と相まって、行楽地はどこも大変な混雑だった。","romaji":"→ Cùng với thời tiết đẹp, các khu du lịch đâu đâu cũng đông nghịt.","vi":"──────────"},{"ja":"～に加えて  (N3): \"Thêm vào đó\", chỉ sự bổ sung.  と相まって nhấn mạnh sự kết hợp tạo ra hiệu ứng chung.","romaji":"","vi":""},{"ja":"～おかげで  /  ～せいで  (N4): \"Nhờ có/Tại vì\", chỉ nguyên nhân kết quả.  と相まって chỉ sự kết hợp các yếu tố.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('196.  とあれば: Nếu là trường hợp; nếu ~', 'N1', 'Dùng để diễn tả rằng nếu là vì một lý do đặc biệt, một mục đích quan trọng (N/V), hoặc một tình huống đặc biệt, thì người nói hoặc một người nào đó sẵn sàng làm một việc phi thường, vất vả, hoặc khác với bình thường.', 'N +  とあれば / V-る +  とあれば', '[{"ja":"子供のためとあれば、どんな苦労でもします。","romaji":"→ Nếu là vì con cái thì dù vất vả thế nào tôi cũng làm.","vi":""},{"ja":"社長の命令とあれば、従わないわけにはいかない。","romaji":"→ Nếu là mệnh lệnh của giám đốc thì không thể không tuân theo.","vi":"──────────"},{"ja":"～ためなら  (N3): \"Nếu là vì...\", gần nghĩa, nhưng  とあれば có phần trang trọng hơn và thường ám chỉ một sự sẵn sàng cao độ hơn.","romaji":"","vi":""},{"ja":"～とあっては  (N?): Gần như đồng nghĩa, \"nếu đã là trường hợp đó thì...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('197.  とあって: Do sự thật là; bởi vì ~', 'N1', 'Dùng để nêu ra một lý do hoặc hoàn cảnh đặc biệt, không bình thường, dẫn đến một kết quả cũng đặc biệt hoặc không bình thường tương ứng.', 'N +  とあって / (Thể thông thường) +  とあって', '[{"ja":"有名な作家が来日するとあって、空港には多くのファンが詰めかけた 。","romaji":"→ Vì một tác giả nổi tiếng đến Nhật nên rất nhiều người hâm mộ đã tập trung ở sân bay.","vi":""},{"ja":"今日は久しぶりの休日とあって、朝から気分がいい。","romaji":"→ Vì hôm nay là ngày nghỉ hiếm hoi nên tôi cảm thấy vui vẻ từ sáng.","vi":"──────────"},{"ja":"～こととて  (N1): \"Bởi vì\", cũng trang trọng, nhưng  とあって thường nhấn mạnh hơn vào tính đặc biệt, không thường xuyên của hoàn cảnh.","romaji":"","vi":""},{"ja":"～だけに  (N3): \"Chính vì... nên càng...\", nhấn mạnh kết quả tương xứng với lý do.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('198.  とばかりに: Như thể muốn nói; như thể ~', 'N1', 'Diễn tả một hành động hoặc thái độ được thực hiện như thể muốn nói hoặc thể hiện một ý nghĩ, cảm xúc nào đó một cách rõ ràng, mặc dù không nói ra thành lời.', '(Mệnh đề trích dẫn ngắn/Từ tượng thanh/Từ tượng hình) +  とばかりに', '[{"ja":"彼は「待ってました」とばかりに、話し始めた。","romaji":"→ Anh ta bắt đầu nói chuyện như thể muốn nói \"Tôi chờ mãi\".","vi":""},{"ja":"彼女は「もう知らない」とばかりに、プイッと横を向いた。","romaji":"→ Cô ấy quay ngoắt mặt đi như thể muốn nói \"Tôi không biết nữa\".","vi":"──────────"},{"ja":"～と言わんばかりに  (N1): \"Như thể muốn nói\", rất gần nghĩa, thường dùng với một câu trích dẫn ngầm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('199.  といえども: Ngay cả khi; mặc dù; bất chấp ~', 'N1', 'Dùng để diễn tả sự nhượng bộ, rằng ngay cả trong trường hợp N (dù có địa vị cao, khả năng tốt...) hoặc dù có V (đã làm gì...), thì vế sau vẫn đúng hoặc vẫn cần phải như vậy. Mang ý nghĩa "Dù là... nhưng không phải lúc nào cũng.../vẫn phải...".', 'N / (Thể thông thường) +  といえども', '[{"ja":"いかに専門家といえども、未来のことは予測できない。","romaji":"→ Dù là chuyên gia đi nữa cũng không thể dự đoán được chuyện tương lai.","vi":""},{"ja":"子供といえども、自分の行動には責任を持つべきだ。","romaji":"→ Dù là trẻ con cũng phải có trách nhiệm với hành động của mình.","vi":"──────────"},{"ja":"～であれ  /  ～であろうと  (N1): \"Dù là\", gần nghĩa, cũng diễn tả sự không ngoại lệ.","romaji":"","vi":""},{"ja":"～ながらも  (N2): \"Mặc dù... nhưng...\", diễn tả sự tương phản.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('200.  と言えなくもない: Cũng có thể nói rằng; cũng có thể nói là ~', 'N1', 'Dùng để diễn tả một ý kiến, nhận định một cách không hoàn toàn chắc chắn, không quả quyết, nhưng cũng không hoàn toàn phủ định. Là cách nói vòng vo, thể hiện một khả năng nhỏ hoặc một góc nhìn nào đó.', '(Thể thông thường) +  と言えなくもない', '[{"ja":"彼のやり方は、少し強引だと言えなくもない。","romaji":"→ Cách làm của anh ấy cũng có thể nói là hơi áp đặt (không phải là không thể nói thế).","vi":""},{"ja":"この結果は、ある意味で成功だと言えなくもない。","romaji":"→ Kết quả này, theo một nghĩa nào đó, cũng có thể nói là thành công.","vi":"──────────"},{"ja":"～ないものでもない  (N1): \"Không phải là không thể\", thường dùng cho khả năng hành động.  と言えなくもない dùng cho khả năng đưa ra một nhận định.","romaji":"","vi":""},{"ja":"～きらいがある  (N1): \"Có xu hướng (xấu)\", nhưng nếu nói về một nhận định có thể đúng thì có nét tương đồng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('201.  といい～といい: Cả ... và; không chỉ ... mà còn; dù là ... hay ~', 'N1', 'Dùng để liệt kê hai hoặc nhiều ví dụ (N1, N2...) và đưa ra một đánh giá hoặc nhận xét chung về tất cả chúng, cho thấy tất cả các ví dụ đó đều có chung một đặc điểm hoặc gây ra cùng một ấn tượng.', 'N1 +  といい + N2 +  といい', '[{"ja":"このレストランは、味といいサービスといい、文句のつけようがない 。","romaji":"→ Nhà hàng này, cả vị lẫn dịch vụ, đều không có gì để phàn nàn.","vi":""},{"ja":"色といいデザインといい、このカバンが気に入った。","romaji":"→ Cả màu sắc lẫn thiết kế, tôi đều thích chiếc cặp này.","vi":"──────────"},{"ja":"～であれ～であれ  (N1): \"Dù là... hay...\", nhấn mạnh sự không phân biệt đối với hành động/kết quả ở vế sau.  といい～といい dùng để đưa ra đánh giá dựa trên các yếu tố liệt kê.","romaji":"","vi":""},{"ja":"～から～に至るまで  (N1): \"Từ... cho đến...\", liệt kê phạm vi.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('202.  といったらない: Cực kỳ; rất; không gì ... hơn thế; ... hết mức có thể', 'N1', 'Dùng để nhấn mạnh cảm xúc hoặc trạng thái ở mức độ rất cao, đến mức khó diễn tả bằng lời, mang tính cảm thán mạnh.', 'A い / Na +  といったらない /  といったらありゃしない', '[{"ja":"彼の部屋の汚さといったらありゃしない。","romaji":"→ Phòng của anh ta bẩn không thể tả nổi.","vi":""},{"ja":"その景色は美しいといったらない。","romaji":"→ Cảnh sắc đó đẹp vô cùng.","vi":"──────────"},{"ja":"極まる  /  極まりない  (N1): \"Cực kỳ\", nhưng trang trọng hơn.  といったらない mang tính cảm thán cá nhân hơn.","romaji":"","vi":""},{"ja":"この上ない  (N1): \"Không gì bằng\", cũng chỉ mức độ cao nhất.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('203.  という: Tất cả; mọi ~ (không có ngoại lệ)', 'N1', 'Dùng để lặp lại một danh từ, mang ý nghĩa nhấn mạnh "tất cả", "mọi" danh từ thuộc loại đó, không có ngoại lệ, bao trùm toàn bộ.', 'N +  という + N (N lặp lại)', '[{"ja":"窓という窓が閉められていた。","romaji":"→ Tất cả các cửa sổ đều bị đóng.","vi":""},{"ja":"公園の木という木にイルミネーションが飾られた。","romaji":"→ Mọi cây cối trong công viên đều được trang trí đèn illumination.","vi":"──────────"},{"ja":"N のありとあらゆる N (N?): \"Tất tần tật N\", gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('204.  というか～というか: Đúng hơn là; hoặc có lẽ tôi nên nói; ý tôi là ~', 'N1', 'Dùng khi người nói đang phân vân, tìm cách diễn đạt chính xác nhất ý của mình, đưa ra hai (hoặc nhiều) cách nói khác nhau để mô tả cùng một sự việc hoặc cảm xúc, hoặc khi không chắc chắn nên dùng từ nào.', '(Mệnh đề 1/Từ 1) +  というか + (Mệnh đề 2/Từ 2) +  というか', '[{"ja":"彼は優しいというか、気が弱いというか、頼んでも断れない性格だ。 - Anh ta nên nói là hiền lành hay là yếu đuối đây nhỉ, tính cách không thể từ chối khi được nhờ.","romaji":"","vi":""},{"ja":"驚いたというか、あきれたというか、言葉が出なかった。","romaji":"→ Nên nói là ngạc nhiên hay là cạn lời đây, tôi đã không nói nên lời.","vi":"──────────"},{"ja":"むしろ  (N3): \"Đúng hơn là\", dùng khi muốn sửa lại hoặc chọn một cách diễn đạt chính xác hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('205.  というもの: Trong; suốt; kể từ; trong một khoảng thời gian', 'N1', 'Dùng để nhấn mạnh một khoảng thời gian khá dài mà trong suốt thời gian đó, một trạng thái hoặc hành động nào đó diễn ra liên tục hoặc không thay đổi.', '(Khoảng thời gian cụ thể) +  というもの', '[{"ja":"この一週間というもの、雨が降り続いている。","romaji":"→ Suốt một tuần nay, trời cứ mưa liên tục.","vi":""},{"ja":"彼とはここ数年というもの、会っていない。","romaji":"→ Tôi đã không gặp anh ta suốt mấy năm nay rồi.","vi":"──────────"},{"ja":"ずっと  (N5): \"Suốt\", là trạng từ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('206.  というところだ  /  といったところだ: Nhiều nhất; không quá; tốt nhất; khoảng; khoảng ~', 'N1', 'Dùng để đưa ra một mức độ, số lượng, hoặc đánh giá được cho là hợp lý, tối đa, hoặc xấp xỉ, thường không vượt quá một giới hạn nào đó.', 'V-る / N +  というところだ /  といったところだ', '[{"ja":"この仕事にかかる時間は、せいぜい一週間というところだろう。","romaji":"→ Thời gian cần cho công việc này, nhiều nhất cũng khoảng một tuần thôi.","vi":""},{"ja":"この料理の評価は、まあまあといったところだ。","romaji":"→ Đánh giá về món ăn này thì, cũng tàm tạm thôi.","vi":"──────────"},{"ja":"せいぜい  (N2): \"Nhiều nhất cũng chỉ\", thường đi kèm với  というところだ.","romaji":"","vi":""},{"ja":"たかだか  (N?): \"Cùng lắm cũng chỉ\", \"chẳng qua chỉ là\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('207.  というわけだ: Đó là lý do tại sao; thảo nào; điều này có nghĩa là; là trường hợp ~', 'N1', 'Dùng để đưa ra một kết luận logic hoặc giải thích một sự việc dựa trên những thông tin, tình huống đã được nêu hoặc ngầm hiểu trước đó.', '(Mệnh đề giải thích/thông tin nền) +  というわけだ', '[{"ja":"電車が遅れたんです。それで遅刻したというわけです。","romaji":"→ Xe điện bị chậm ạ. Thành ra là tôi đã đến muộn.","vi":""},{"ja":"彼は日本の大学に留学したいそうだ。だから日本語を勉強しているというわけだ。","romaji":"→ Nghe nói anh ấy muốn du học đại học Nhật. Thảo nào mà anh ấy học tiếng Nhật.","vi":"──────────"},{"ja":"つまり  (N3): \"Tóm lại\", \"nói cách khác\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('208.  というわけではない: Không phải là; không có nghĩa là ~', 'N1', 'Dùng để phủ định một phần hoặc hoàn toàn một kết luận hoặc suy diễn logic mà người khác có thể nghĩ đến, hoặc làm mềm một khẳng định.', '(Thể thông thường) +  というわけではない /  というわけでもない', '[{"ja":"嫌いというわけではないが、あまり好きではない。","romaji":"→ Không phải là ghét, nhưng cũng không thích lắm.","vi":""},{"ja":"誰でもできるというわけではない。","romaji":"→ Không phải là ai cũng làm được.","vi":"──────────"},{"ja":"必ずしも～ない  (N3): \"Không hẳn là\", \"không nhất thiết là\".","romaji":"","vi":""},{"ja":"～とは限らない  (N3): \"Không hẳn là\", \"không phải lúc nào cũng\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('209.  といわず～といわず: Cả; không chỉ A hay B, mà (tổng thể) ~', 'N1', 'Dùng để liệt kê hai hoặc nhiều danh từ (N1, N2...) và nhấn mạnh rằng không chỉ N1, N2 mà toàn bộ các phần, các khía cạnh của sự vật/sự việc đó đều ở trong một trạng thái nào đó hoặc bị ảnh hưởng.', 'N1 +  といわず + N2 +  といわず', '[{"ja":"平日といわず週末といわず、この店はいつも混んでいる。","romaji":"→ Bất kể là ngày thường hay cuối tuần, quán này lúc nào cũng đông.","vi":""},{"ja":"彼は顔といわず手といわず、泥だらけだ。","romaji":"→ Anh ta dính đầy bùn, cả mặt lẫn tay (và các bộ phận khác nữa).","vi":"──────────"},{"ja":"～であれ～であれ  (N1): \"Dù là... hay...\", nhấn mạnh sự không phân biệt đối với hành động/kết quả ở vế sau.","romaji":"","vi":""},{"ja":"至る所（いたるところ）(N?): \"Khắp mọi nơi\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('210.  ときている: Bởi vì ~', 'N1', 'Dùng để nêu ra một đặc điểm hoặc tình huống (thường là nổi bật hoặc đã biết) như một lý do hiển nhiên hoặc một yếu tố cộng thêm để giải thích cho một kết quả hoặc đánh giá nào đó (thường ở vế sau).', 'N / (Thể thông thường) +  ときている /  ときてる (から /  ので)', '[{"ja":"あの人は美人で頭もいいときているから、モテるのも当然だ。","romaji":"→ Người đó vì vừa đẹp lại vừa thông minh (thêm cả yếu tố đó nữa), nên được yêu thích cũng là đương nhiên.","vi":""},{"ja":"値段も安いし、味もいいときている。この店が人気なのも頷ける。","romaji":"→ Giá vừa rẻ, vị lại ngon (thêm cả yếu tố đó nữa). Quán này nổi tiếng cũng là điều dễ hiểu.","vi":"──────────"},{"ja":"～上に  (N2): \"Thêm vào đó\", dùng để bổ sung.  ときている có sắc thái như một lý do hiển nhiên.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('211.  とみると: Ngay khi nhận ra ..., thì ~', 'N1', 'Diễn tả rằng ngay khi nhận ra hoặc thấy một dấu hiệu, một tình huống nào đó, thì lập tức thực hiện một hành động, thường là phản ứng nhanh.', '(Mệnh đề chỉ sự nhận biết/dấu hiệu) +  とみると、～', '[{"ja":"子供は母親の姿とみると、駆け寄ってきた。","romaji":"→ Đứa bé ngay khi thấy bóng mẹ thì liền chạy lại.","vi":""},{"ja":"店員がいないとみると、彼は商品を盗んだ。","romaji":"→ Ngay khi nhận ra không có nhân viên, hắn ta đã trộm đồ.","vi":"──────────"},{"ja":"～と見るや  (N1): Gần như đồng nghĩa, cũng nhấn mạnh sự nhanh nhạy khi nhận ra.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('212.  と見るや（とみるや）: Vừa nhìn thấy; khi nhìn thấy; sau khi xác nhận ~', 'N1', 'Diễn tả rằng ngay sau khi nhìn thấy hoặc xác nhận được một tình huống, một cơ hội nào đó, một hành động khác xảy ra ngay lập tức, thường là hành động nhanh chóng, quyết đoán.', 'N / V-る/V-た +  と見るや', '[{"ja":"警官の姿と見るや、犯人は逃げ出した。","romaji":"→ Vừa thấy bóng cảnh sát, kẻ phạm tội đã bỏ chạy.","vi":""},{"ja":"チャンスと見るや、彼はすぐに行動した。","romaji":"→ Ngay khi thấy cơ hội, anh ta đã hành động ngay lập tức.","vi":"──────────"},{"ja":"～なり  (N2): \"Ngay khi\", cũng diễn tả hành động tức thời.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('213.  となると  /  となれば: Khi nói đến; trong trường hợp đó; nếu điều đó xảy ra', 'N1', 'Dùng để đưa ra một giả định hoặc một tình huống cụ thể, và sau đó nói về những điều sẽ xảy ra, những cân nhắc, hoặc những phản ứng khác biệt khi tình huống đó trở thành hiện thực hoặc được xem xét nghiêm túc.', 'N +  となると /  となれば / (Thể thông thường) +  となると /  となれば', '[{"ja":"留学するとなると、いろいろ準備が必要だ。","romaji":"→ Nếu mà đi du học (khi việc đó trở nên cụ thể) thì cần phải chuẩn bị nhiều thứ.","vi":""},{"ja":"彼が来ないとなれば、計画を変更しなければならない。","romaji":"→ Nếu anh ta không đến (khi tình huống đó xảy ra) thì phải thay đổi kế hoạch thôi.","vi":"──────────"},{"ja":"～場合は  (N4): \"Trong trường hợp\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('214.  とされる: Được coi là; người ta nói rằng ~', 'N1', 'Dùng để trình bày một thông tin, nhận định, hoặc đánh giá được nhiều người công nhận hoặc được cho là đúng theo một nguồn nào đó, nhưng không phải là sự khẳng định tuyệt đối của người nói. Mang tính khách quan.', '(Thể thông thường) +  とされる / N +  とされる', '[{"ja":"この地域は、日本で最も美しい場所の一つとされる。","romaji":"→ Vùng này được xem là một trong những nơi đẹp nhất Nhật Bản.","vi":""},{"ja":"地球温暖化の原因は、二酸化炭素の増加とされる。","romaji":"→ Nguyên nhân của nóng lên toàn cầu được cho là do sự gia tăng CO2.","vi":"──────────"},{"ja":"～と考えられている  (N2): \"Người ta nghĩ rằng\", \"được cho là\".","romaji":"","vi":""},{"ja":"～と見られている  (N1): \"Được xem là\", \"được dự đoán là\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('215.  ときたら: Khi nói đến; liên quan đến ~', 'N1', 'Dùng để nêu ra một chủ đề (N) và sau đó đưa ra lời phàn nàn, chỉ trích, hoặc nhận xét tiêu cực, bất mãn về chủ đề đó.', 'N +  ときたら', '[{"ja":"うちの息子ときたら、毎日ゲームばかりしている。","romaji":"→ Nói đến thằng con trai nhà tôi thì nó suốt ngày chỉ chơi game (phàn nàn).","vi":""},{"ja":"最近の天気ときたら、暑かったり寒かったり、変だ。","romaji":"→ Nói đến thời tiết dạo này thì lúc nóng lúc lạnh, thật kỳ lạ (bất mãn).","vi":"──────────"},{"ja":"～といえば  (N3): \"Nếu nói đến\", dùng để gợi ra một liên tưởng hoặc thông tin liên quan, không nhất thiết tiêu cực.","romaji":"","vi":""},{"ja":"～なんて  (N3): Có thể dùng để bày tỏ sự ngạc nhiên hoặc bất mãn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('216.  ところを: Mặc dù (đó là một thời gian/điều kiện nhất định); mặc dù bình thường', 'N1', 'Dùng để diễn tả một hành động xảy ra vào đúng lúc ai đó đang trong một tình huống/trạng thái nhất định, thường là tình huống khó khăn, bận rộn, không thuận tiện, hoặc một khoảnh khắc riêng tư. Thường dùng trong lời cảm ơn, xin lỗi, hoặc khi bị bắt gặp làm gì đó.', 'N +  の +  ところを / A-い +  ところを / V-ている/V-た +  ところを', '[{"ja":"お忙しいところを、わざわざお越しいただきありがとうございます。 - Cảm ơn anh đã cất công đến đây dù đang bận rộn.","romaji":"","vi":""},{"ja":"寝ているところを起こされて、機嫌が悪い。","romaji":"→ Bị đánh thức đúng lúc đang ngủ nên tôi bực mình.","vi":""},{"ja":"犯行の現場ところを警察に押さえられた。","romaji":"→ Bị cảnh sát bắt giữ tại hiện trường (đúng lúc đang thực hiện) vụ án.","vi":"──────────"},{"ja":"～最中に  (N3): \"Đúng vào lúc đang...\", nhấn mạnh sự việc xảy ra giữa chừng một hành động khác, thường là hành động gây gián đoạn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('217.  ともあろうものが: Trong tất cả mọi người (biểu hiện sự ngạc nhiên trước hành vi sai trái của một người có địa vị cao)', 'N1', 'Dùng để diễn tả sự ngạc nhiên, thất vọng, hoặc chỉ trích mạnh mẽ khi một người có địa vị cao, có trách nhiệm, hoặc đáng lẽ phải làm gương (N) lại có hành vi sai trái, không phù hợp với địa vị của mình.', 'N (Người có địa vị/trách nhiệm cao) +  ともあろうものが', '[{"ja":"国会議員ともあろうものが、賄賂を受け取るとは許せない。","romaji":"→ Người như nghị sĩ quốc hội mà lại nhận hối lộ thì không thể tha thứ được.","vi":""},{"ja":"教師ともあろうものが、生徒を騙すなんて信じられない。","romaji":"→ Người là giáo viên mà lại đi lừa học sinh thì thật không thể tin nổi.","vi":"──────────"},{"ja":"としたことが  (N1): \"Ai chứ N mà lại...\", cũng thể hiện sự ngạc nhiên, thất vọng trước lỗi lầm của người đáng tin cậy, có thể dùng cho cả bản thân.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('218.  ともなく  /  ともなしに: Bằng cách nào đó; không biết; không nghĩ; vô thức ~', 'N1', 'Diễn tả một hành động được thực hiện mà không có ý định, mục đích rõ ràng; làm một cách vô thức, bâng quơ, không chủ ý, không có sự tập trung cụ thể.', 'V-る +  ともなく /  ともなしに (Thường lặp lại động từ: V るともなくV る)', '[{"ja":"テレビを見るともなく見ていたら、面白い番組が始まった。","romaji":"→ Đang xem TV một cách bâng quơ thì có chương trình thú vị bắt đầu.","vi":""},{"ja":"何をするともなく、一日が過ぎてしまった。","romaji":"→ Một ngày đã trôi qua mà chẳng làm gì cụ thể cả (không có mục đích rõ ràng).","vi":""},{"ja":"誰言うともなしに、その噂は広まった。","romaji":"→ Chẳng biết ai nói mà tin đồn đó đã lan rộng.","vi":"──────────"},{"ja":"なんとなく  (N3): \"Không hiểu sao\", \"bằng cách nào đó\", thường chỉ cảm giác hoặc lý do không rõ ràng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('219.  ともすれば: Dễ; có xu hướng; dễ bị; có khả năng ~', 'N1', 'Dùng để diễn tả rằng một người hoặc vật có khuynh hướng dễ dàng rơi vào một trạng thái hoặc thực hiện một hành động nào đó (thường là không tốt hoặc không mong muốn) nếu không cẩn thận hoặc trong một số điều kiện nhất định.', 'ともすれば +  ～がちだ /  ～やすい / (Mệnh đề chỉ xu hướng)', '[{"ja":"人はともすれば楽な方に流れがちだ。","romaji":"→ Con người ta có xu hướng dễ nghiêng về phía dễ dàng.","vi":""},{"ja":"彼はともすれば悲観的に考えすぎる。","romaji":"→ Anh ta có xu hướng dễ suy nghĩ quá bi quan (chỉ cần có chút gì là lại...).","vi":"──────────"},{"ja":"～やすい  (N4): \"Dễ\" (làm gì đó), chỉ khả năng hoặc tính chất.","romaji":"","vi":""},{"ja":"とかく  (N?): \"Thường thì\", \"hay có chiều hướng\", gần nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('220.  とも～とも: Không thể đưa ra kết luận; không thể đánh giá', 'N1', 'Dùng để diễn tả sự không chắc chắn, không thể phân biệt hoặc không thể đưa ra kết luận rõ ràng giữa hai hoặc nhiều khả năng, trạng thái, hoặc tính chất.', '(Từ/Mệnh đề 1) +  とも + (Từ/Mệnh đề 2) +  とも +  つかない /  言え ない /  見分けられない /  区別できない /  判断できない', '[{"ja":"それが本当とも嘘ともつかない。","romaji":"→ Không biết đó là thật hay giả.","vi":""},{"ja":"彼の表情からは、賛成とも反対とも読み取れなかった。","romaji":"→ Từ biểu cảm của anh ấy, không thể đọc ra là tán thành hay phản đối.","vi":"──────────"},{"ja":"どちらとも言えない  (N?): \"Không thể nói là bên nào\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('221.  とりわけ: Đặc biệt; trên hết ~', 'N1', 'Dùng như một trạng từ để nhấn mạnh rằng một điều gì đó là đặc biệt nổi bật, đáng chú ý hơn hẳn, hoặc quan trọng hơn so với những thứ khác cùng loại.', 'とりわけ + (Danh từ/Mệnh đề được nhấn mạnh)', '[{"ja":"私は果物が好きだが、とりわけマンゴーが好きだ。","romaji":"→ Tôi thích trái cây, đặc biệt là xoài.","vi":""},{"ja":"今年の冬は寒いが、とりわけ今朝は冷え込んだ。","romaji":"→ Mùa đông năm nay lạnh, nhưng đặc biệt là sáng nay thì rất buốt.","vi":"──────────"},{"ja":"中でも  (N3): \"Trong số đó thì (đặc biệt là)...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('222.  としたことが: Trong tất cả mọi người, ai mà ngờ được?', 'N1', 'Dùng để diễn tả sự ngạc nhiên hoặc thất vọng lớn khi một người (N), đặc biệt là người mà mình tin tưởng hoặc kỳ vọng (hoặc chính bản thân mình, hàm ý tự trách), lại làm một việc sai lầm, ngớ ngẩn, hoặc không đáng có, trái với mong đợi.', 'N (Người, thường là người đáng tin cậy, có năng lực, hoặc bản thân người nói) +  としたことが、～', '[{"ja":"あの慎重な彼としたことが、こんなミスを犯すなんて。","romaji":"→ Ai chứ người cẩn trọng như anh ấy mà lại phạm lỗi thế này.","vi":""},{"ja":"私としたことが、大事な約束を忘れてしまうなんて。","romaji":"→ Đến cả tôi mà lại quên mất cuộc hẹn quan trọng như vậy (tự trách).","vi":"──────────"},{"ja":"～にしては  (N3): \"Vậy mà\" (so với điều kiện/dự đoán thông thường), nhưng không nhất thiết là lỗi lầm.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('223.  とっさに: Ngay lập tức; ngay tức khắc; nhanh chóng', 'N1', 'Dùng như một trạng từ để diễn tả một hành động được thực hiện ngay lập tức, theo phản xạ, không cần suy nghĩ, thường là để đối phó với một tình huống bất ngờ hoặc nguy hiểm.', 'とっさに + V', '[{"ja":"転びそうになったので、とっさに手をついた。","romaji":"→ Vì suýt ngã nên tôi đã chống tay xuống ngay lập tức.","vi":""},{"ja":"質問されて、とっさに答えが出なかった。","romaji":"→ Bị hỏi, tôi đã không thể trả lời ngay tức khắc.","vi":"──────────"},{"ja":"思わず  (N3): \"Bất giác\", \"không kìm được\", nhấn mạnh sự vô thức, không chủ ý.","romaji":"","vi":""},{"ja":"咄嗟に（とっさに）: Đây là cách viết Hán tự của nó.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('224.  とて: Ngay cả; ngay cả khi/dù ~', 'N1', 'Dùng để diễn tả ý nghĩa "ngay cả" hoặc "dù là". Là cách nói có phần cổ và trang trọng, thường dùng trong văn viết hoặc các phát biểu mang tính hình thức.', 'N +  とて / (Thể thông thường) +  からとて / (Từ để hỏi) +  とて', '[{"ja":"私とて、その問題が難しいことは分かっている。","romaji":"→ Ngay cả tôi cũng biết vấn đề đó khó.","vi":""},{"ja":"子供だからとて、許されるわけではない。","romaji":"→ Dù là trẻ con cũng không có nghĩa là được tha thứ.","vi":""},{"ja":"いかに困難だとて、諦めるわけにはいかない。","romaji":"→ Dù khó khăn đến mấy cũng không thể bỏ cuộc.","vi":"──────────"},{"ja":"～さえ  /  ～すら  (N3/N1): \"Ngay cả\".  とて cổ và trang trọng hơn.","romaji":"","vi":""},{"ja":"～といえども  (N1): \"Dù là\", \"ngay cả khi\", cũng trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('225.  とは: Tôi không biết; tôi ngạc nhiên rằng; sự thật là ~', 'N1', 'Dùng ở cuối câu hoặc trước vế sau để diễn tả sự ngạc nhiên, bất ngờ, hoặc khó tin của người nói trước một sự thật hoặc tình huống nào đó vừa mới biết hoặc nhận ra.', '(Thể thông thường) +  とは ( +  知らなかった /  思わなかった /  驚いた など)', '[{"ja":"彼が結婚していたとは、知らなかった。","romaji":"→ Anh ta đã kết hôn rồi, tôi thật không biết (ngạc nhiên).","vi":""},{"ja":"こんなに美味しいとは、思わなかった。","romaji":"→ Thật không ngờ lại ngon đến thế này.","vi":"──────────"},{"ja":"～というのは  (N4): Dùng để định nghĩa hoặc giải thích, khác với  とは chỉ sự ngạc nhiên.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('226.  とはいえ: Dù; mặc dù; dù vậy; tuy nhiên', 'N1', 'Dùng để thừa nhận một sự thật hoặc một tình huống (vế trước), nhưng sau đó đưa ra một ý kiến hoặc sự thật khác có phần trái ngược, hạn chế, hoặc làm giảm nhẹ ý nghĩa của vế trước.', 'N / (Thể thông thường) +  とはいえ', '[{"ja":"まだ４月とはいえ、今日は暑いですね。","romaji":"→ Tuy nói là vẫn tháng 4 nhưng hôm nay nóng nhỉ.","vi":""},{"ja":"彼は成功したとはいえ、多くのものを失った。","romaji":"→ Mặc dù anh ấy đã thành công nhưng cũng đã mất rất nhiều thứ.","vi":"──────────"},{"ja":"～といっても  (N3): \"Dù nói là... nhưng...\", gần nghĩa, cũng dùng để làm rõ hoặc hạn chế một phát biểu.","romaji":"","vi":""},{"ja":"～ものの  (N2): \"Mặc dù... nhưng...\", cũng diễn tả sự tương phản.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('227.  とは比べものにならない: Không thể so sánh với ~', 'N1', 'Dùng để nhấn mạnh sự khác biệt rất lớn về mức độ, chất lượng giữa hai sự vật/sự việc (N1 và N2, hoặc N1 và một tiêu chuẩn ngầm hiểu), cho rằng một cái vượt trội hơn hoặc tệ hơn hẳn cái kia đến mức không thể đặt lên bàn cân so sánh.', 'N1 +  とは + N2 + (と)  は比べものにならない (ほど～)', '[{"ja":"今年の暑さは、去年とは比べものにならない。","romaji":"→ Cái nóng năm nay không thể so sánh được với năm ngoái (nóng hơn nhiều đến mức không thể so sánh).","vi":""},{"ja":"彼の才能は、凡人とは比べものにならない。","romaji":"→ Tài năng của anh ấy không thể so sánh với người thường (vượt trội hơn hẳn).","vi":"──────────"},{"ja":"比較にならない  (N?): \"Không thể so sánh\", \"không đáng để so sánh\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('228.  とは打って変わって  /  とは打って変わり（とはうってかわって  /  と はうってかわり）: Không giống như; hoàn toàn khác; rất khác với ~', 'N1', 'Dùng để nhấn mạnh sự thay đổi hoàn toàn, 180 độ của một tình trạng, thái độ, hoặc sự việc so với trước đó (N hoặc tình trạng đã đề cập).', 'N / (Tình trạng trước đó) +  とは打って変わって /  とは打って変わり', '[{"ja":"昨日の嵐とは打って変わって、今日は快晴だ。","romaji":"→ Khác hẳn với cơn bão hôm qua, hôm nay trời nắng đẹp.","vi":""},{"ja":"彼は以前の無口な態度とは打って変わり、よく話すようになった。","romaji":"→ Anh ấy đã thay đổi hoàn toàn so với thái độ ít nói trước đây, trở nên nói nhiều hơn.","vi":"──────────"},{"ja":"一変して  (N?): \"Thay đổi hoàn toàn\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('229.  つ～つ: Và ~ (chỉ hai hành động tương phản)', 'N1', 'Dùng để diễn tả hai hành động hoặc trạng thái trái ngược nhau đang diễn ra xen kẽ, lặp đi lặp lại, hoặc trong một mối quan hệ qua lại.', 'V1-ます (bỏ  ます) +  つ + V2-ます (bỏ  ます) +  つ', '[{"ja":"彼はドアの前を行きつ戻りつしている。","romaji":"→ Anh ta cứ đi đi lại lại trước cửa.","vi":""},{"ja":"抜きつ抜かれつの激しいレースだった。","romaji":"→ Đó là một cuộc đua khốc liệt lúc vượt lên, lúc bị vượt qua.","vi":"──────────"},{"ja":"～たり～なかったり  (N4): \"Lúc thì... lúc thì không...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('230.  尽くす（つくす）: Sử dụng hết (hoàn toàn không còn lại gì); cạn kiệt; hết ~ / Cố hết sức; phục vụ', 'N1', '1.   Gắn vào sau động từ để diễn tả ý nghĩa "làm hết", "làm đến cùng", "sử dụng hết" hành động đó đến mức không còn gì. 2.   Như một động từ độc lập có nghĩa "cống hiến hết mình", "phục vụ tận tụy". 3.   Trong cụm từ cố định "力を尽くす" nghĩa là "dốc hết sức lực".', '1.   V-ます (bỏ  ます) +  尽くす (Nghĩa: làm hết, làm cạn kiệt) 2.   N +  に尽くす / N +  のために尽くす (Nghĩa: cống hiến, phục vụ) 3.   力を尽くす (Nghĩa: cố gắng hết sức)', '[{"ja":"冷蔵庫にあるものを食べ尽くした。","romaji":"→ Tôi đã ăn hết mọi thứ trong tủ lạnh. (Nghĩa 1)","vi":""},{"ja":"国のために力を尽くす。","romaji":"→ Cống hiến hết sức mình cho đất nước. (Nghĩa 2 & 3)","vi":"──────────"},{"ja":"～果たす  (N2): \"Hoàn thành\" (nhiệm vụ, vai trò).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('231.  ってば  /  ったら: Nói về; tôi đã nói với bạn rồi; thôi nào (bực mình / không hài lòng)', 'N1', 'Dùng trong văn nói thân mật để:   Nhắc lại một chủ đề đã nói hoặc gọi tên ai đó khi người đó không chú ý.   Thể hiện sự bực mình, không hài lòng, hoặc sốt ruột khi người nghe không chú ý hoặc không làm theo.', 'N (Thường là tên người) +  ってば /  ったら', '[{"ja":"もう行くよってば！早くして！ - Đã bảo là đi rồi mà! Nhanh lên! (Bực mình)","romaji":"","vi":""},{"ja":"太郎ったら、また宿題忘れたの？ - Taro này, lại quên bài tập à? (Chê trách nhẹ)","romaji":"──────────","vi":"So sánh:"},{"ja":"～よ  (N5): Nhấn mạnh.  ってば/ったら mang thêm sắc thái cảm xúc (thường là bực mình, sốt ruột, hoặc thân mật pha chút trách móc).","romaji":"","vi":""},{"ja":"ねえ  (N?): \"Này\" (gọi, thu hút sự chú ý).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('232.  うちに入らない（うちにはいらない）: Không thực sự; không thể coi là ~', 'N1', 'Dùng để diễn tả rằng một việc gì đó quá nhỏ bé, không đáng kể, không đủ tiêu chuẩn, hoặc không quan trọng để có thể được coi là hoặc được tính là một cái gì đó thực sự.', 'N / V-る/V-た + (の) +  うちに入らない', '[{"ja":"これくらいの怪我は、怪我のうちに入らないよ。","romaji":"→ Vết thương cỡ này thì không được tính là bị thương đâu.","vi":""},{"ja":"趣味で描いているだけで、絵を描くとは言えるうちに入らない。","romaji":"→ Chỉ là vẽ cho vui thôi, không thể gọi là biết vẽ được.","vi":"──────────"},{"ja":"取るに足りない  (N1 - thành ngữ): \"Không đáng để nhắc tới/quan tâm\", gần nghĩa.","romaji":"","vi":""},{"ja":"大したことない  (N?): \"Chẳng có gì to tát\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('233.  わ: Hậu tố cuối câu nữ tính', 'N1', 'Dùng ở cuối câu, chủ yếu do phụ nữ sử dụng trong văn nói (đặc biệt là thế hệ trước hoặc trong một số vai trò nhân vật), để làm mềm câu nói, thể hiện cảm xúc nhẹ nhàng (ngạc nhiên, cảm thán, khẳng định nhẹ, đồng tình).', '(Mệnh đề) +  わ', '[{"ja":"今日はいい天気ですわね。","romaji":"→ Hôm nay trời đẹp nhỉ.","vi":""},{"ja":"私、もう帰るわ。","romaji":"→ Tớ về đây.","vi":"──────────"},{"ja":"～の  (N4 - cuối câu, nữ tính): \"ấy\", \"à\", cũng là một hậu tố nữ tính.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('234.  はどうであれ: Tuy nhiên; bất cứ điều gì ~', 'N1', 'Dùng để nói rằng bất kể tình trạng, nội dung, hoặc kết quả của N là như thế nào (tốt hay xấu, đúng hay sai...), thì vế sau vẫn không thay đổi, vẫn giữ nguyên, hoặc vẫn là điều quan trọng cần được ưu tiên.', 'N +  はどうであれ', '[{"ja":"結果はどうであれ、全力を尽くすことが大切だ。","romaji":"→ Bất kể kết quả thế nào, việc cố gắng hết sức là quan trọng.","vi":""},{"ja":"理由はどうであれ、人を傷つけることは許されない。","romaji":"→ Dù lý do ra sao, việc làm tổn thương người khác là không thể tha thứ.","vi":"──────────"},{"ja":"～がどうあろうと  (N?): \"Dù N có thế nào đi nữa\", gần như đồng nghĩa.","romaji":"","vi":""},{"ja":"いずれにしても  (N1): \"Dù sao đi nữa\", thường dùng để kết luận.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('235.  はおろか: Chưa kể đến; đừng nói đến; không cần phải nói ~', 'N1', 'Dùng để nhấn mạnh một tình trạng tiêu cực, rằng ngay cả một điều cơ bản, dễ dàng, hoặc ít hơn (N2) cũng không làm được/không có, chứ đừng nói đến một điều cao hơn, khó hơn, hoặc nhiều hơn (N1).', 'N1 +  はおろか + N2 +  も /  さえ +  ～ない', '[{"ja":"彼は漢字はおろか、ひらがなさえ書けない。","romaji":"→ Anh ta đừng nói đến Kanji, ngay cả Hiragana cũng không viết được.","vi":""},{"ja":"彼は家はおろか、車も持っていない。","romaji":"→ Anh ta đừng nói đến nhà, ngay cả xe cũng không có.","vi":"──────────"},{"ja":"～はもちろん  (N3): \"Đương nhiên là\" (dùng cho trường hợp tích cực hoặc điều hiển nhiên).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('236.  はさておき: Gác lại ~', 'N1', 'Dùng để tạm thời gác lại một chủ đề (N) để nói về một chủ đề khác được cho là quan trọng hơn hoặc cần được ưu tiên hơn vào lúc đó.', 'N +  はさておき', '[{"ja":"冗談はさておき、本題に入りましょう。","romaji":"→ Tạm gác chuyện đùa sang một bên, chúng ta hãy vào vấn đề chính.","vi":""},{"ja":"見た目はさておき、味は保証します。","romaji":"→ Khoan nói đến vẻ ngoài (gác chuyện đó lại), tôi đảm bảo mùi vị.","vi":"──────────"},{"ja":"～はともかくとして  (N2): Dạng nhấn mạnh của  ～はともかく.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('237.  はそっちのけで  /  をそっちのけで: Bỏ qua (một việc) để (việc khác); thay vì ~', 'N1', 'Diễn tả việc ai đó quá mải mê vào một việc mà bỏ bê, lơ là một việc khác quan trọng hơn hoặc đáng lẽ phải làm (N), không thèm để ý đến N.', 'N +  はそっちのけで /  をそっちのけで', '[{"ja":"彼は勉強はそっちのけで、毎日遊んでばかりいる。","romaji":"→ Anh ta bỏ bê việc học hành mà ngày nào cũng chỉ lo chơi bời.","vi":""},{"ja":"彼女は仕事をそっちのけで、おしゃべりに夢中だ。","romaji":"→ Cô ấy bỏ bê công việc mà mải mê buôn chuyện.","vi":"──────────"},{"ja":"～を怠ける  (N?): \"Lười biếng/bỏ bê việc...\".","romaji":"","vi":""},{"ja":"～を後回しにする  (N?): \"Để việc... lại sau\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('238.  わ〜わで: Và (liệt kê những điều tiêu cực xảy ra cùng lúc)', 'N1', 'Dùng để liệt kê hai hoặc nhiều sự việc, tình huống (thường là tiêu cực hoặc khó khăn) xảy ra cùng lúc hoặc chồng chất lên nhau, dẫn đến một tình trạng vất vả, khó xử, hoặc bối rối.', 'N1 +  は + V1-る +  わ、N2 +  は + V2-る +  わで、～ (thường là  大 変だ、困った)', '[{"ja":"雨は降るわ、風は吹くわで、大変な一日だった。","romaji":"→ Nào là mưa rơi, nào là gió thổi, thật là một ngày vất vả.","vi":""},{"ja":"子供は泣くわ、電話は鳴るわで、全然集中できない。","romaji":"→ Nào là con khóc, nào là điện thoại reo, tôi hoàn toàn không thể tập trung được.","vi":"──────────"},{"ja":"～だの～だの  (N1): Liệt kê (thường là phàn nàn hoặc những thứ lộn xộn). わ～わで thường mô tả tình huống khó khăn do nhiều việc xảy ra cùng lúc.","romaji":"","vi":""},{"ja":"踏んだり蹴ったり  (Thành ngữ): \"Họa vô đơn chí\", \"đã đen còn gặp lắm chuyện\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('239.  や否や（やいなや）: Ngay sau khi; khoảnh khắc ~', 'N1', 'Diễn tả rằng một hành động xảy ra gần như đồng thời hoặc ngay lập tức sau một hành động khác, gần như không có khoảng cách thời gian. Nhấn mạnh sự tức thời.', 'V-る +  や否や', '[{"ja":"彼はベルが鳴るや否や、受話器を取った。","romaji":"→ Anh ấy vừa nghe tiếng chuông reo là nhấc ngay ống nghe.","vi":""},{"ja":"空が暗くなるや否や、大粒の雨が降り始めた。","romaji":"→ Trời vừa tối sầm lại là những hạt mưa lớn bắt đầu rơi.","vi":"──────────"},{"ja":"～たとたん(に) (N3): Gần nghĩa, nhấn mạnh sự bất ngờ của vế sau.  や否や trang trọng hơn.","romaji":"","vi":""},{"ja":"～なり  (N2): Gần nghĩa, nhưng  なり thường dùng với hành động bất thường hơn hoặc phản xạ tự nhiên.","romaji":"","vi":""},{"ja":"～と同時に  (N3): \"Đồng thời với\", có thể chỉ hai hành động diễn ra cùng lúc chứ không nhất thiết là ngay sau.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('240.  やしない: Nên làm, nhưng không làm; tuyệt đối không; không có cách nào ~', 'N1', 'Dùng trong văn nói, thường là để thể hiện sự bất mãn, phàn nàn, hoặc nhấn mạnh một cách suồng sã rằng ai đó hoàn toàn không làm một việc gì đó (dù nên làm hoặc được kỳ vọng), hoặc một việc gì đó tuyệt đối không xảy ra.', 'V-ます (bỏ  ます) +  やしない (Thường ở cuối câu)', '[{"ja":"あいつは、何度言っても分かりやしない。","romaji":"→ Cái gã đó, nói bao nhiêu lần cũng chẳng thèm hiểu.","vi":""},{"ja":"宿題なんて、やりやしないよ。","romaji":"→ Bài tập về nhà ấy à, tớ chẳng thèm làm đâu.","vi":""},{"ja":"そんなこと、分かりやしない。","romaji":"→ Chuyện đó, làm sao mà hiểu được.","vi":"──────────"},{"ja":"～ものか  /  ～もんか  (N3): \"Tuyệt đối không\", cũng thể hiện sự phủ định mạnh mẽ, nhưng thường mang tính quyết tâm hơn.","romaji":"","vi":""},{"ja":"～っこない  (N2): \"Tuyệt đối không thể\" (khả năng).","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('241.  やれ～やれ: Mẫu đưa ra hai ví dụ đại diện (thường là tiêu cực)', 'N1', 'Dùng để liệt kê hai hoặc nhiều ví dụ (thường là những yêu cầu, phàn nàn, hoặc những thứ lộn xộn, phiền phức) để thể hiện sự mệt mỏi, chán ngán, hoặc bối rối trước tình hình đó.', 'やれ + N1/V1-る +  だの、 やれ + N2/V2-る +  だの (と) /  やれ + N1 +  やら + N2 +  やら', '[{"ja":"子供たちは、やれお菓子が食べたいだの、やれおもちゃが欲しいだの 、いつもわがままばかり言う。","romaji":"→ Bọn trẻ lúc nào cũng ích kỷ, nào là muốn ăn kẹo, nào là muốn đồ chơi.","vi":""},{"ja":"引っ越しの準備で、やれ荷造りだの、やれ手続きだの、大忙しだ。","romaji":"→ Chuẩn bị chuyển nhà, nào là đóng gói đồ đạc, nào là làm thủ tục, bận tối mắt.","vi":"──────────"},{"ja":"～とか～とか  (N4): Liệt kê ví dụ, trung tính hơn.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('242.  ようが  /  ようと: Ngay cả khi; dù thế nào/gì ~', 'N1', 'Dùng để diễn tả sự nhượng bộ, rằng dù có làm V (với ý chí, cố gắng) đi nữa, thì kết quả ở vế sau vẫn không thay đổi hoặc không bị ảnh hưởng.', 'V-よう (Thể ý chí) +  が /  と', '[{"ja":"どんなに反対されようが、私は自分の道を進む。","romaji":"→ Dù có bị phản đối thế nào đi nữa, tôi vẫn sẽ đi con đường của mình.","vi":""},{"ja":"たとえ彼が謝らようと、私は許さない。","romaji":"→ Dù anh ta có xin lỗi đi nữa, tôi cũng sẽ không tha thứ.","vi":"──────────"},{"ja":"～たところで  (N1): \"Dù có... thì cũng (vô ích)\", nhấn mạnh sự vô ích.","romaji":"","vi":""},{"ja":"～といえども  (N1): \"Dù là\", cũng mang tính nhượng bộ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('243.  ようが～ようが  /  ようと～ようと: Dù; cho dù; ngay cả khi [A] hay [B]', 'N1', 'Dùng để liệt kê hai hành động hoặc khả năng (thường là đối lập hoặc bao hàm mọi trường hợp) và khẳng định rằng dù thực hiện hành động nào đi nữa, hoặc dù tình huống nào xảy ra, kết quả ở vế sau vẫn không đổi.', 'V1-よう +  が/と + V2-よう +  が/と (V1 và V2 có thể giống hoặc khác nhau, hoặc V2 là V1-まい)', '[{"ja":"雨が降ろうが雪が降ろうが、試合は行われる。","romaji":"→ Dù mưa hay tuyết rơi, trận đấu vẫn sẽ diễn ra.","vi":""},{"ja":"行こうと行くまいと、それは君の自由だ。","romaji":"→ Dù đi hay không đi, đó là tự do của cậu.","vi":"──────────"},{"ja":"～であれ～であれ  (N1): \"Dù là... hay...\", thường dùng với danh từ.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('244.  ようによっては  /  ようでは: Tùy theo cách; tùy thuộc vào cách ~', 'N1', 'Diễn tả rằng kết quả, đánh giá, hoặc ý nghĩa của một sự việc có thể thay đổi tùy thuộc vào cách thức thực hiện hành động (V), cách nhìn nhận, hoặc cách xử lý.', 'V-ます (bỏ  ます) +  ようによっては /  ようでは', '[{"ja":"考えようによっては、失敗もいい経験になる。","romaji":"→ Tùy vào cách suy nghĩ mà thất bại cũng có thể trở thành kinh nghiệm tốt.","vi":""},{"ja":"やりようによっては、もっと時間を短縮できるはずだ。","romaji":"→ Tùy vào cách làm mà đáng lẽ có thể rút ngắn thời gian hơn nữa.","vi":""},{"ja":"そんなやりようでは、成功はおぼつかない。","romaji":"→ Nếu làm theo cách đó thì khó mà thành công được.","vi":"──────────"},{"ja":"～次第で  (N2): \"Tùy thuộc vào\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('245.  ようにも～ない: Ngay cả khi tôi muốn… tôi cũng không thể ~', 'N1', 'Diễn tả rằng mặc dù rất muốn làm hành động V, nhưng vì một lý do hoặc hoàn cảnh nào đó (thường là khách quan) mà không thể làm được, không có cách nào làm được.', 'V-よう (Thể ý chí) +  にも + V-ない (Thể khả năng phủ định)', '[{"ja":"歯が痛くて、食べようにも食べられない。","romaji":"→ Răng đau quá, muốn ăn cũng không ăn được.","vi":""},{"ja":"眠くて起きようにも起きられない。","romaji":"→ Buồn ngủ quá, muốn dậy cũng không dậy nổi.","vi":"──────────"},{"ja":"V-たくても V-れない  (N?): Gần như đồng nghĩa.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('246.  ようと～まいと  /  ようが～まいが: Dù có hay không; bất kể', 'N1', 'Dùng để diễn tả rằng dù có thực hiện hành động V hay không, thì kết quả hoặc tình hình ở vế sau vẫn không thay đổi, không bị ảnh hưởng.', 'V1-よう (Thể ý chí) +  と/が + V1-まい (Thể phủ định ý chí/suy đoán) +  と/が', '[{"ja":"君が来ようと来るまいと、会議は時間通りに始まる。","romaji":"→ Dù cậu có đến hay không, cuộc họp vẫn sẽ bắt đầu đúng giờ.","vi":""},{"ja":"雨が降ろうが降るまいが、私は出かけます。","romaji":"→ Dù trời có mưa hay không, tôi vẫn sẽ ra ngoài.","vi":"──────────"},{"ja":"～であろうとなかろうと  (N?): \"Dù có là... hay không...\", trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('247.  ゆえに: Do đó; vì vậy; bởi vì; do ~', 'N1', 'Dùng để chỉ nguyên nhân, lý do. Là cách nói trang trọng, có phần cổ, thường dùng trong văn viết, lý luận, hoặc diễn văn, mang tính hình thức.', 'N +  の +  ゆえに / (Thể thông thường) +  ゆえに', '[{"ja":"悪天候ゆえに、飛行機は欠航となった。","romaji":"→ Do thời tiết xấu nên chuyến bay đã bị hủy.","vi":""},{"ja":"人間は考える葦である。ゆえに尊い。","romaji":"→ Con người là cây sậy biết suy nghĩ. Do đó mà đáng quý.","vi":"──────────"},{"ja":"～ため  (N4): \"Vì\", trang trọng hơn.  ゆえに trang trọng nhất và có phần cổ điển, thường dùng trong các văn bản mang tính học thuật, triết lý.","romaji":"","vi":""},{"ja":"～が故に  (N?): Gần như đồng nghĩa với  ゆえに, cũng rất trang trọng.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('248.  ぞ・ぜ: Hậu tố cuối câu; thêm sức mạnh hoặc chỉ thị lệnh', 'N1', 'Dùng ở cuối câu trong văn nói, chủ yếu do nam giới sử dụng (hoặc trong một số vai diễn nhân vật), để:   ぞ: Nhấn mạnh sự khẳng định, cảnh báo, quyết tâm, hoặc tự nhủ một cách mạnh mẽ.   ぜ: Nhấn mạnh, rủ rê, hoặc ra lệnh một cách thân mật, suồng sã, đôi khi hơi ngang tàng.', '(Mệnh đề) +  ぞ /  ぜ', '[{"ja":"行くぞ！ - Đi thôi! (Quyết tâm)","romaji":"","vi":""},{"ja":"忘れるなぞ。","romaji":"→ Đừng quên đấy! (Cảnh báo)","vi":""},{"ja":"そろそろ行こうぜ。","romaji":"→ Chuẩn bị đi thôi nào! (Rủ rê thân mật)","vi":""},{"ja":"やるぜ！ - Làm thôi! (Thể hiện sự sẵn sàng)","romaji":"──────────","vi":"Ngữ pháp tương tự:"},{"ja":"～わ  (N1 - nữ tính): Hậu tố cuối câu nữ tính.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('249.  ずじまい: Cuối cùng không làm ~', 'N1', 'Diễn tả rằng một hành động mà mình đã định làm, mong muốn làm, hoặc đáng lẽ nên làm cuối cùng lại không thể thực hiện được, và cảm thấy tiếc nuối hoặc chưa hoàn thành về điều đó.', 'V-ない (bỏ  ない) +  ずじまい (だ/だった)', '[{"ja":"彼に本当の気持ちを言えずじまいだった。","romaji":"→ Rốt cuộc tôi đã không thể nói ra tình cảm thật của mình với anh ấy.","vi":""},{"ja":"京都に行ったのに、金閣寺を見ずじまいで帰ってきた。","romaji":"→ Đã đến Kyoto vậy mà tôi lại về mà chưa kịp xem chùa Vàng.","vi":"──────────"},{"ja":"～そびれる  (N1): \"Bỏ lỡ cơ hội làm...\", cũng có sự tiếc nuối.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('250.  ずにはおかない  /  ないではおかない: Nhất định/chắc chắn sẽ làm gì đó; không thể không ~', 'N1', 'Diễn tả rằng một tác nhân nào đó (người, sự vật, sự việc) chắc chắn sẽ gây ra một hành động hoặc một cảm xúc nào đó ở người khác, không thể nào khác được, hoặc là người nói có ý chí mạnh mẽ nhất định sẽ làm gì đó và không để yên.', 'V-ない (bỏ  ない) +  ずにはおかない / V-ない +  ないではおかない', '[{"ja":"あの映画は見る人を感動させずにはおかないだろう。","romaji":"→ Bộ phim đó chắc chắn sẽ khiến người xem cảm động.","vi":""},{"ja":"この不正を知った以上、黙ってはいないではおかない。","romaji":"→ Một khi đã biết sự bất chính này, tôi nhất định sẽ không im lặng (sẽ làm gì đó).","vi":"──────────"},{"ja":"必ず～する  (N4): \"Nhất định sẽ làm\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('251.  ずには済まない  /  ないでは済まない: Phải; nhất định sẽ; không thể không ~', 'N1', 'Diễn tả rằng dựa trên tình hình, quy tắc xã hội, hoặc trách nhiệm đạo đức, một hành động nào đó là bắt buộc phải làm, không thể tránh khỏi, nếu không sẽ không ổn thỏa.', 'V-ない (bỏ  ない) +  ずには済まない / V-ない +  ないでは済まない', '[{"ja":"多大な損害を与えたのだから、謝らずには済まない。","romaji":"→ Vì đã gây ra thiệt hại lớn nên không thể không xin lỗi (nếu không xin lỗi thì không xong).","vi":""},{"ja":"人の物を盗んだのだから、罰を受けないでは済まないだろう。","romaji":"→ Vì đã trộm đồ của người khác nên chắc chắn sẽ phải chịu phạt (không chịu phạt thì không được).","vi":"──────────"},{"ja":"～ざるを得ない  (N1): \"Buộc phải\", thường do hoàn cảnh bên ngoài ép buộc, không còn lựa chọn khác.","romaji":"","vi":""},{"ja":"～ないわけにはいかない  (N2): \"Không thể không\", do áp lực xã hội hoặc tình thế.","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('252.  ずとも: Ngay cả khi không làm; ngay cả khi không là ~', 'N1', 'Dùng để diễn tả ý nghĩa "dù không..." hoặc "không cần...". Là cách nói cổ và trang trọng, ít dùng trong văn nói hiện đại.', 'V-ない (bỏ  ない) +  ずとも', '[{"ja":"言わずとも、彼の気持ちは分かっている。","romaji":"→ Dù không nói ra, tôi cũng hiểu cảm xúc của anh ấy.","vi":""},{"ja":"わざわざ行かずとも、電話で済むことだ。","romaji":"→ Không cần cất công đi, việc đó có thể giải quyết bằng điện thoại.","vi":"──────────"},{"ja":"～ないでも  (N?): \"Dù không...\".","romaji":"","vi":""}]') ON CONFLICT DO NOTHING;
INSERT INTO grammar_points (pattern_ja, jlpt_level, explanation_vi, structure_vi, example_sentences) VALUES ('253.  ずくめ: Hoàn toàn; toàn là; chỉ toàn là ~', 'N1', 'Diễn tả rằng một thứ gì đó được bao phủ hoặc bao gồm hoàn toàn bởi N, không có gì khác, toàn bộ đều là N.', 'N +  ずくめ', '[{"ja":"彼女はいつも黒ずくめの服装をしている。","romaji":"→ Cô ấy lúc nào cũng mặc đồ toàn màu đen.","vi":""},{"ja":"最近、いいことずくめで嬉しい。","romaji":"→ Gần đây toàn chuyện tốt nên tôi rất vui.","vi":"──────────"}]') ON CONFLICT DO NOTHING;
